-- TAB: REMAINING
------------------------------------------------------------

UI.RegisterTab{
    name  = "Remaining",
    order = 27,

    build = function(panel)
        panel.header = panel:CreateFontString(nil, "ARTWORK", "GameFontNormal")
        panel.header:SetPoint("TOPLEFT", 8, -8)
        panel.header:SetPoint("TOPRIGHT", -8, -8)
        panel.header:SetJustifyH("LEFT")

        panel.list = UI.CreateList(panel)
        panel.list:ClearAllPoints()
        panel.list:SetPoint("TOPLEFT", 4, -32)
        panel.list:SetPoint("BOTTOMRIGHT", -8, 38)

        panel.refresh = AddButton(panel, "Refresh", 110, function()
            UI.Refresh()
        end)
        panel.refresh:SetPoint("BOTTOMLEFT", 8, 8)
    end,

    refresh = function(panel)
        local module = CN:GetModule("Breakdown")

        if not module then
            panel.header:SetText("Breakdown module not loaded.")
            panel.list:SetEntries({})
            return
        end

        panel.header:SetText("What is left, and why")

        local entries = {}

        for _, row in ipairs(module.Report()) do
            local headline

            if row.total and row.total > 0 then
                headline = string.format("|cffffd100%-14s|r %6d / %-6d  |cff999999%.1f%%|r",
                    row.name, row.collected or 0, row.total,
                    (row.collected or 0) / row.total * 100)
            else
                headline = string.format("|cffffd100%-14s|r %6d collected",
                    row.name, row.collected or 0)
            end

            table.insert(entries, {
                text    = headline,
                tooltip = row.unknownTotal
                    and ("No percentage is shown because " .. row.unknownTotal .. ".")
                    or nil,
            })

            if row.unknownTotal then
                table.insert(entries, {
                    text = "      |cff808080no percentage: " .. row.unknownTotal .. "|r",
                })
            end

            for _, reason in ipairs(row.reasons or {}) do
                table.insert(entries, { text = "      " .. reason })
            end

            if row.action then
                table.insert(entries, {
                    text = "      |cffffff00-> " .. row.action .. "|r",
                })
            end
        end

        if #entries == 0 then
            table.insert(entries, { text = "Nothing to report yet. Run the scans first." })
        end

        panel.list:SetEntries(entries)
    end,
}

------------------------------------------------------------
-- TAB: COLLECTIONS
------------------------------------------------------------

-- The account dashboard. Every row is "collected / known" -- and the
-- percentage beside it is that ratio and nothing wider.
--
-- The comment here used to say "never a fabricated percentage of some total
-- the addon cannot verify" and the code fifty lines below formatted `%.1f%%`.
-- Both halves were defensible on their own: the denominator IS the addon's
-- own scan snapshot, which is exactly what the row says. What was missing was
-- anything on screen saying WHEN that snapshot was taken, so a figure that
-- silently goes stale the day the game adds collectibles read as current.
-- The header now says so, and each row carries its scan age.
UI.RegisterTab{
    name  = "Collections",
    order = 25,

    build = function(panel)
        panel.header = panel:CreateFontString(nil, "ARTWORK", "GameFontNormal")
        panel.header:SetPoint("TOPLEFT", 8, -8)
        panel.header:SetPoint("TOPRIGHT", -8, -8)
        panel.header:SetJustifyH("LEFT")

        panel.list = UI.CreateList(panel)
        panel.list:ClearAllPoints()
        panel.list:SetPoint("TOPLEFT", 4, -32)
        panel.list:SetPoint("BOTTOMRIGHT", -8, 38)

        panel.scanAll = AddButton(panel, "Scan everything", 140, function()
            Print("Scanning all collections; this takes a moment.")

            for _, moduleName in ipairs({ "Pets", "Mounts", "Toys", "Appearances",
                                          "Titles", "Professions" }) do
                local module = CN:GetModule(moduleName)

                if module and module.Scan then
                    pcall(module.Scan)
                end
            end

            Print("Collection scan complete.")
            UI.Refresh()
        end)
        panel.scanAll:SetPoint("BOTTOMLEFT", 8, 8)

        panel.achieve = AddButton(panel, "Scan achievements", 150, function()
            local module = CN:GetModule("Achievements")

            if module then
                Print("Scanning achievements; this takes a moment.")

                local scanned, completed = module.Scan()

                Print("Scanned " .. scanned .. ", completed " .. completed .. ".")
            end

            UI.Refresh()
        end)
        panel.achieve:SetPoint("LEFT", panel.scanAll, "RIGHT", 6, 0)
    end,

    refresh = function(panel)
        local entries = {}

        local function row(label, collected, total, note)
            local text

            if total and total > 0 then
                text = string.format("%-16s %6d / %-6d  |cff999999%.1f%%|r",
                    label, collected, total, collected / total * 100)
            else
                text = string.format("%-16s %6s        |cff999999%s|r",
                    label, "-", note or "not scanned")
            end

            table.insert(entries, { text = text })
        end

        local pets = CN:GetModule("Pets")

        if pets then
            local counts = pets.Summary()
            row("Pets", counts.collected, counts.known)
        end

        local mounts = CN:GetModule("Mounts")

        if mounts then
            local counts = mounts.Summary()
            row("Mounts", counts.collected, counts.known)
        end

        local toys = CN:GetModule("Toys")

        if toys then
            local counts = toys.Summary()
            row("Toys", counts.collected, counts.known)
        end

        local appearances = CN:GetModule("Appearances")

        if appearances then
            local counts = appearances.Summary()
            row("Appearances", counts.collected, counts.total)
        end

        local titles = CN:GetModule("Titles")

        if titles then
            local counts = titles.Summary()
            row("Titles", counts.onAccount, counts.known)
        end

        local achievements = CN:GetModule("Achievements")

        if achievements then
            local counts = achievements.Summary()
            row("Achievements", counts.completed, counts.total)
        end

        local reputations = CN:GetModule("Reputations")

        if reputations then
            local counts = reputations.Summary()

            table.insert(entries, {
                text = string.format("%-16s %6d account-wide, %d character-specific",
                    "Reputations", counts.account, counts.character),
            })
        end

        table.insert(entries, { text = " " })

        local quests = CN:GetModule("Quests")

        if quests then
            table.insert(entries, {
                text = string.format("%-16s %6d discovered",
                    "Quests", CN.CountKeys(CN.Account("discoveredQuests"))),
            })
        end

        local professions = CN:GetModule("Professions")

        if professions then
            for _, record in ipairs(professions.Summary()) do
                local note = record.recipesSeen
                    and (record.recipeKnown .. " of " .. record.recipeTotal .. " recipes")
                    or "|cffffff00open its window once|r"

                table.insert(entries, {
                    text = string.format("%-16s %6s / %-6s  |cff999999%s|r",
                        record.name or "?", tostring(record.rank),
                        tostring(record.maxRank), note),
                })
            end

            local waiting = professions.AwaitingRecipeCapture()

            if #waiting > 0 then
                table.insert(entries, { text = " " })
                table.insert(entries, {
                    text = "|cffffff00Recipes need the profession window open: "
                        .. table.concat(waiting, ", ") .. "|r",
                    tooltip = "The client only exposes a recipe list while that "
                        .. "profession's window is open. Open each one once and "
                        .. "the addon captures it automatically.",
                })
            end
        end

        panel.header:SetText("Account completion  |cff999999(collected / "
            .. "known at the last scan -- not of everything in the game)|r")
        panel.list:SetEntries(entries)
    end,
}

------------------------------------------------------------
-- TAB: SETTINGS
------------------------------------------------------------

UI.RegisterTab{
    name  = "Settings",
    order = 40,

    build = function(panel)
        panel.modeLabel = panel:CreateFontString(nil, "ARTWORK", "GameFontNormal")
        panel.modeLabel:SetPoint("TOPLEFT", 8, -12)

        -- A cycling button instead of a dropdown: dropdown templates have
        -- been renamed twice in recent expansions, this has not.
        panel.modeButton = AddButton(panel, "balanced", 160, function()
            local settings = CN.Settings()
            local modes    = CN.priorityModes

            local currentIndex = 1

            for index, mode in ipairs(modes) do
                if mode == settings.priorityMode then
                    currentIndex = index
                    break
                end
            end

            settings.priorityMode = modes[(currentIndex % #modes) + 1]

            UI.Refresh()
        end)
        panel.modeButton:SetPoint("TOPLEFT", panel.modeLabel, "BOTTOMLEFT", 0, -6)

        panel.modeHelp = panel:CreateFontString(nil, "ARTWORK", "GameFontDisableSmall")
        panel.modeHelp:SetPoint("LEFT", panel.modeButton, "RIGHT", 8, 0)
        panel.modeHelp:SetText("Click to cycle")

        panel.debug = AddCheckbox(panel, "Debug output",
            function() return CN.Settings().debug end,
            function(value) CN.Settings().debug = value end)
        panel.debug:SetPoint("TOPLEFT", panel.modeButton, "BOTTOMLEFT", 0, -16)

        panel.auto = AddCheckbox(panel, "Auto-advance waypoint as I finish things",
            function() return CN.IsAutoWaypointEnabled() end,
            function(value)
                CN.Settings().autoWaypoint = value

                if value then
                    CN.StartAutoWaypointTicker()
                    CN.AutoAdvance("settings", true)
                else
                    CN.StopAutoWaypointTicker()
                end
            end)
        panel.auto:SetPoint("TOPLEFT", panel.debug, "BOTTOMLEFT", 0, -6)

        panel.minimap = AddCheckbox(panel, "Show minimap button",
            function() return not CN.Settings().minimap.hide end,
            function(value)
                CN.Settings().minimap.hide = not value
                UI.UpdateMinimapButton()
            end)
        panel.minimap:SetPoint("TOPLEFT", panel.auto, "BOTTOMLEFT", 0, -6)

        panel.tooltips = AddCheckbox(panel, "Add lines to item and unit tooltips",
            function() return CN.Settings().tooltips ~= false end,
            function(value) CN.Settings().tooltips = value end)
        panel.tooltips:SetPoint("TOPLEFT", panel.minimap, "BOTTOMLEFT", 0, -6)

        panel.arrow = AddCheckbox(panel, "Show the navigation arrow",
            function()
                local nav = CN:GetModule("Navigation")
                return nav and nav.IsArrowEnabled()
            end,
            function(value)
                CN.Settings().arrow = value

                local nav = CN:GetModule("Navigation")

                if nav then
                    if value then
                        nav.BuildArrow()
                        nav.Refresh()
                    else
                        nav.Clear()
                    end
                end
            end)
        panel.arrow:SetPoint("TOPLEFT", panel.tooltips, "BOTTOMLEFT", 0, -6)

        panel.pins = AddCheckbox(panel, "Show route pins on the world map",
            function()
                local pins = CN:GetModule("MapPins")
                return pins and pins.IsEnabled()
            end,
            function(value)
                local pins = CN:GetModule("MapPins")

                if pins then
                    pins.SetEnabled(value)
                end
            end)
        panel.pins:SetPoint("TOPLEFT", panel.arrow, "BOTTOMLEFT", 0, -6)

        panel.setup = AddButton(panel, "Scan everything now", 180, function()
            local setup = CN:GetModule("Setup")

            if setup then
                setup.Run()
            end
        end)
        panel.setup:SetPoint("TOPLEFT", panel.pins, "BOTTOMLEFT", 0, -12)

        panel.reset = AddButton(panel, "Reset window position", 180, function()
            CN.Settings().window = nil

            if window then
                window:ClearAllPoints()
                window:SetPoint("CENTER")
            end
        end)
        panel.reset:SetPoint("BOTTOMLEFT", 8, 8)

        panel.about = panel:CreateFontString(nil, "ARTWORK", "GameFontDisableSmall")
        panel.about:SetPoint("BOTTOMRIGHT", -8, 14)
    end,

    refresh = function(panel)
        local settings = CN.Settings()

        panel.modeLabel:SetText("Priority mode")
        panel.modeButton:SetText(tostring(settings.priorityMode))

        panel.debug.Refresh()
        panel.auto.Refresh()
        panel.minimap.Refresh()
        panel.tooltips.Refresh()
        panel.arrow.Refresh()
        panel.pins.Refresh()

        panel.about:SetText("Completion Navigator v" .. CN.version)
    end,
}

------------------------------------------------------------
-- MINIMAP BUTTON
------------------------------------------------------------

local function UpdateMinimapPosition()
    if not minimapButton then
        return
    end

    local angle  = math.rad(CN.Settings().minimap.angle or 225)
    local radius = 80

    minimapButton:SetPoint("CENTER", Minimap, "CENTER",
        math.cos(angle) * radius, math.sin(angle) * radius)
end

local function BuildMinimapButton()
    if minimapButton or not Minimap then
        return minimapButton
    end

    minimapButton = CreateFrame("Button", "CompletionNavigatorMinimapButton", Minimap)

    minimapButton:SetSize(31, 31)
    minimapButton:SetFrameStrata("MEDIUM")
    minimapButton:SetFrameLevel(8)
    -- Middle-click added in 0.45.0. Three buttons, three of the things a
    -- player does most: open it, navigate, and start following.
    minimapButton:RegisterForClicks("LeftButtonUp", "RightButtonUp",
        "MiddleButtonUp")
    minimapButton:RegisterForDrag("LeftButton")
    minimapButton:SetMovable(true)

    local overlay = minimapButton:CreateTexture(nil, "OVERLAY")
    overlay:SetSize(53, 53)
    overlay:SetTexture("Interface\\Minimap\\MiniMap-TrackingBorder")
    overlay:SetPoint("TOPLEFT")

    local icon = minimapButton:CreateTexture(nil, "ARTWORK")
    icon:SetSize(20, 20)
    icon:SetPoint("CENTER", -1, 1)

    -- Prefer the addon's own artwork. SetTexture fails silently on a missing
    -- file and leaves the texture blank, so verify it took and fall back to
    -- a stock icon rather than shipping an invisible button.
    icon:SetTexture(CN.MEDIA_PATH .. "Logo")

    if not icon:GetTexture() then
        icon:SetTexture("Interface\\Icons\\INV_Misc_Map_01")
        icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
    else
        -- The supplied art is a circular badge already; trimming the corners
        -- keeps it round inside the minimap ring.
        icon:SetTexCoord(0.06, 0.94, 0.06, 0.94)
    end

    minimapButton:SetScript("OnClick", function(self, button)
        if button == "MiddleButton" then
            -- Follow mode is the addon's hands-free state and it was three
            -- keystrokes or a scroll through the window away. It is the thing
            -- somebody with the button on their minimap most wants one click
            -- from.
            CN.HandleSlashCommand("follow")

            return
        end

        if button == "RightButton" then
            local results = CN.Recommend(1)

            if #results > 0 then
                CN.currentRecommendation = results[1]

                local objective = results[1]

                Print("Recommended: " .. tostring(objective.name))
                CN.NavigateToObjective(objective)
            else
                Print("Nothing actionable is known yet.")
            end

            return
        end

        UI.Toggle()
    end)

    -- Drag around the minimap edge; the angle is what gets persisted.
    minimapButton:SetScript("OnDragStart", function(self)
        self:SetScript("OnUpdate", function()
            local mx, my = Minimap:GetCenter()
            local px, py = GetCursorPosition()
            local scale  = Minimap:GetEffectiveScale()

            px, py = px / scale, py / scale

            CN.Settings().minimap.angle = math.deg(CN.Atan2(py - my, px - mx))

            UpdateMinimapPosition()
        end)
    end)

    minimapButton:SetScript("OnDragStop", function(self)
        self:SetScript("OnUpdate", nil)
    end)

    minimapButton:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_LEFT")
        GameTooltip:AddLine("Completion Navigator")

        -- The recommendation is the whole point of the addon, so put it where
        -- it costs nothing to read. This is cheap now: candidates are cached,
        -- so hovering the button does not rebuild fourteen providers.
        local ok, results = pcall(CN.Recommend, 1)

        if ok and results and results[1] then
            local objective = results[1]

            GameTooltip:AddLine("Next: " .. tostring(objective.name or objective.id),
                0.2, 1.0, 0.6)

            local reasons = CN.ExplainRecommendation(objective)

            for index, reason in ipairs(reasons) do
                if index > 2 then
                    break
                end

                GameTooltip:AddLine(reason, 0.6, 0.6, 0.6)
            end
        elseif not ok then
            -- An engine that threw is not an empty list, and telling the
            -- player to run setup again when the real answer is "something
            -- broke" sends them to the wrong place.
            GameTooltip:AddLine("Something went wrong; /cn errors has it.",
                0.96, 0.42, 0.38)
        else
            GameTooltip:AddLine("Nothing actionable is known yet.", 0.6, 0.6, 0.6)

            -- The shared explanation rather than an unconditional "run
            -- setup", which was shown to players who had run it and then
            -- hidden every type with /cn show.
            for index, line in ipairs(CN.ExplainEmptyList()) do
                if index > 2 then
                    break
                end

                GameTooltip:AddLine(line, 0.6, 0.6, 0.6)
            end
        end

        GameTooltip:AddLine(" ")
        GameTooltip:AddLine("|cffffffffLeft-click|r open the window", 1, 1, 1)
        GameTooltip:AddLine("|cffffffffRight-click|r navigate to the next objective", 1, 1, 1)
        -- Middle-click has started follow mode since 0.44.0 and the tooltip
        -- -- the feature's only discovery surface -- did not mention it.
        GameTooltip:AddLine("|cffffffffMiddle-click|r start follow mode", 1, 1, 1)
        GameTooltip:AddLine("|cffffffffDrag|r reposition this button", 1, 1, 1)
        GameTooltip:Show()
    end)

    minimapButton:SetScript("OnLeave", function()
        GameTooltip:Hide()
    end)

    UpdateMinimapPosition()

    return minimapButton
end

function UI.UpdateMinimapButton()
    BuildMinimapButton()

    if not minimapButton then
        return
    end

    if CN.Settings().minimap.hide then
        minimapButton:Hide()
    else
        minimapButton:Show()
        UpdateMinimapPosition()
    end
end

------------------------------------------------------------
-- KEYBINDING ENTRY POINTS
------------------------------------------------------------

function CompletionNavigator_ToggleUI()
    UI.Toggle()
end

function CompletionNavigator_NextObjective()
    local handler = SlashCmdList and SlashCmdList.COMPLETIONNAVIGATOR

    if handler then
        handler("next")
    end
end

function CompletionNavigator_Navigate()
    local handler = SlashCmdList and SlashCmdList.COMPLETIONNAVIGATOR

    if handler then
        handler("go")
    end
end

-- One helper rather than three copies of the same four lines. The slash
-- handler is the single entry point every command already goes through, so a
-- binding is a keystroke that types for you.
local function RunCommand(text)
    local handler = SlashCmdList and SlashCmdList.COMPLETIONNAVIGATOR

    if handler then
        handler(text)
    end
end

function CompletionNavigator_ToggleFollow()
    RunCommand("follow")
end

function CompletionNavigator_Plan()
    -- No argument: /cn plan now defaults to however long this character
    -- usually plays, which is exactly the right behaviour for a key you press
    -- without thinking about it.
    RunCommand("plan")
end

function CompletionNavigator_ToggleHud()
    RunCommand("hud")
end

BINDING_HEADER_COMPLETIONNAVIGATOR       = "Completion Navigator"
BINDING_NAME_COMPLETIONNAVIGATOR_TOGGLE  = "Toggle window"
BINDING_NAME_COMPLETIONNAVIGATOR_NEXT    = "Recommend next objective"
BINDING_NAME_COMPLETIONNAVIGATOR_GO      = "Navigate to recommendation"
BINDING_NAME_COMPLETIONNAVIGATOR_FOLLOW  = "Start or stop follow mode"
BINDING_NAME_COMPLETIONNAVIGATOR_PLAN    = "Plan a session"
BINDING_NAME_COMPLETIONNAVIGATOR_HUD     = "Toggle the heads-up line"

------------------------------------------------------------
-- LIFECYCLE
------------------------------------------------------------

CN:OnLogin(function()
    UI.UpdateMinimapButton()

    -- Say once where the interface actually is. A minimap button nobody
    -- notices is the same as no interface at all.
    local settings = CN.Settings()

    if not settings.seenWelcome then
        settings.seenWelcome = true

        Print("Click the |cffffff00map icon on your minimap|r to open the window, "
            .. "or type |cffffff00/cn ui|r.")
        Print("Right-click that icon to navigate straight to the next objective.")
    end
end)

-- Keep an open window current without polling.
for _, event in ipairs({
    "QUEST_TURNED_IN",
    "QUEST_ACCEPTED",
    "QUEST_REMOVED",
    "UPDATE_FACTION",
    "ZONE_CHANGED_NEW_AREA",
    "MAJOR_FACTION_RENOWN_LEVEL_CHANGED",
}) do
    CN:RegisterEvent(event, function()
        UI.RequestRefresh()
    end)
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "ui",
    -- "show" REMOVED. Filters registers `/cn show` and loads later in the
    -- .toc, so this alias was already dead -- and `/cn show` being the filter
    -- command is what the documentation says. A dead alias that reads as a
    -- live one is a collision waiting for a load-order change.
    aliases = { "window" },
    order   = 5,
    help    = "Open the main window.",
    handler = function()
        UI.Toggle()
    end,
}

CN:RegisterCommand{
    name    = "uistatus",
    order   = 7,
    help    = "Diagnose the window and minimap button.",
    handler = function()
        Print("UI diagnostics:")
        Print("Window object: " .. (CompletionNavigatorFrame and "created" or "|cffff4444not created|r"))

        if CompletionNavigatorFrame then
            Print("  shown: " .. tostring(CompletionNavigatorFrame:IsShown()))
            Print("  size: " .. math.floor(CompletionNavigatorFrame:GetWidth() or 0)
                .. " x " .. math.floor(CompletionNavigatorFrame:GetHeight() or 0))
            Print("  strata: " .. tostring(CompletionNavigatorFrame:GetFrameStrata()))

            local point, _, _, x, y = CompletionNavigatorFrame:GetPoint()

            Print("  anchored: " .. tostring(point)
                .. " at " .. math.floor(x or 0) .. ", " .. math.floor(y or 0))
        end

        Print("Minimap button: "
            .. (CompletionNavigatorMinimapButton and "created" or "|cffff4444not created|r"))

        if CompletionNavigatorMinimapButton then
            Print("  shown: " .. tostring(CompletionNavigatorMinimapButton:IsShown()))
            Print("  hidden by setting: " .. tostring(CN.Settings().minimap.hide))
            Print("  angle: " .. tostring(CN.Settings().minimap.angle))
        end

        Print("Registered tabs: " .. #UI.tabs)
        Print("Minimap frame exists: " .. tostring(Minimap ~= nil))

        if CompletionNavigatorFrame and not CompletionNavigatorFrame:IsShown() then
            Print("Forcing the window open and centering it.")

            CN.Settings().window = nil

            CompletionNavigatorFrame:ClearAllPoints()
            CompletionNavigatorFrame:SetPoint("CENTER")
            CompletionNavigatorFrame:Show()
        end
    end,
}

CN:RegisterCommand{
    name    = "minimap",
    order   = 6,
    help    = "Toggle the minimap button.",
    handler = function()
        local settings = CN.Settings()

        settings.minimap.hide = not settings.minimap.hide

        UI.UpdateMinimapButton()

        Print("Minimap button " .. (settings.minimap.hide and "hidden." or "shown."))
    end,
}
'@

$Embedded['UI\List.lua'] = @'
-- UI/List.lua
-- Completion Navigator :: the scrolling list every tab is built out of.
--
-- SPLIT OUT OF UI.lua IN 0.45.0.
--
-- UI.lua had reached 2,550 lines holding a window, eleven tabs, a minimap
-- button, keybinding entry points and this. The list is the piece with the
-- least to do with the rest: it knows about rows, pooling, filtering and
-- sorting, and nothing about what is in them.
--
-- Only this piece moved. The tabs stayed where they are, because each one
-- reaches into window-local helpers and moving them would be a refactor with
-- real regression risk in a release that already carries a great deal --
-- which is a judgement about timing rather than about the value of doing it.

local ADDON_NAME, CN = ...

local UI = CN.UI

-- Shared with UI.lua, which owns the chrome these rows sit inside.
local WINDOW_WIDTH = UI.WINDOW_WIDTH or 560
local ROW_HEIGHT   = UI.ROW_HEIGHT or 20

local SafeCreateFrame = UI.SafeCreateFrame

-- Creates a reusable row list. Rows are pooled; SetRows swaps the data.
local function CreateList(parent)
    local list = CreateFrame("Frame", nil, parent)

    list:SetPoint("TOPLEFT", 8, -8)
    list:SetPoint("BOTTOMRIGHT", -8, 8)

    local scroll = SafeCreateFrame("ScrollFrame", nil, list, "UIPanelScrollFrameTemplate")

    scroll:SetPoint("TOPLEFT")
    scroll:SetPoint("BOTTOMRIGHT", -26, 0)

    local content = CreateFrame("Frame", nil, scroll)

    content:SetSize(1, 1)
    scroll:SetScrollChild(content)

    list.rows = {}

    function list:GetRow(index)
        if self.rows[index] then
            return self.rows[index]
        end

        local row = CreateFrame("Button", nil, content)

        row:SetHeight(ROW_HEIGHT)
        row:SetPoint("TOPLEFT", 0, -((index - 1) * ROW_HEIGHT))
        row:SetPoint("TOPRIGHT", 0, -((index - 1) * ROW_HEIGHT))

        row.highlight = row:CreateTexture(nil, "HIGHLIGHT")
        row.highlight:SetAllPoints()
        row.highlight:SetColorTexture(1, 1, 1, 0.10)

        row.label = row:CreateFontString(nil, "ARTWORK", "GameFontHighlightLeft")
        row.label:SetPoint("LEFT", 4, 0)
        row.label:SetPoint("RIGHT", -4, 0)
        row.label:SetJustifyH("LEFT")

        -- HANDLERS ARE BOUND ONCE, HERE.
        --
        -- They used to be created inside SetEntries, which meant three fresh
        -- closures per row on every redraw -- three hundred of them for a
        -- hundred-row list, every time the window refreshed, each one
        -- capturing a table it did not need to capture. In this game that is
        -- not an abstract cost: allocation churn is what garbage collection
        -- pauses are made of, and a pause is a stutter.
        --
        -- Bound once and reading `row.entry`, which SetEntries already sets,
        -- a redraw now allocates nothing at all.
        row:SetScript("OnClick", function(clicked)
            local entry = clicked.entry

            if entry and entry.onClick then
                entry.onClick()
            end
        end)

        row:SetScript("OnEnter", function(hovered)
            local entry = hovered.entry

            if not entry or not entry.tooltip or not GameTooltip then
                return
            end

            GameTooltip:SetOwner(hovered, "ANCHOR_RIGHT")
            GameTooltip:SetText(entry.tooltip, nil, nil, nil, nil, true)
            GameTooltip:Show()
        end)

        row:SetScript("OnLeave", function()
            if GameTooltip then
                GameTooltip:Hide()
            end
        end)

        self.rows[index] = row

        return row
    end

    -- A CEILING ON ROWS.
    --
    -- Every row is a frame, and frames cannot be destroyed in this game --
    -- only hidden and reused. A list that renders one entry per row therefore
    -- grows its frame pool to the size of the largest list it has ever been
    -- shown, permanently, for the rest of the session. Nothing capped that.
    --
    -- Two hundred rows is far more than anyone reads before scrolling and
    -- more than any tab currently produces; the point is that the number
    -- exists at all. When it bites, the list says so rather than silently
    -- ending -- a truncated list that looks complete is worse than a long one.
    list.maxRows = 200

    -- A FILTER OVER WHATEVER IS BEING SHOWN.
    --
    -- Not a search across everything the addon knows -- that is what the
    -- commands are for, and a search box that quietly queries a different
    -- data set than the list under it is a lie about what you are looking at.
    -- This narrows the rows already on screen, which is what people reach for
    -- a box for.
    -- STATE IN A LOCAL, NOT ON THE FRAME.
    --
    -- A frame is not a plain table: templates and mixins put a metatable on
    -- it, and reading an unset field can return something other than nil.
    -- The first version of this kept `list.filterText` on the frame and
    -- relied on "unset means nil" -- which held in the game and did not hold
    -- against the test harness's stub, whose __index answers every key. The
    -- test caught it; a player with a different UI library might have found
    -- it instead.
    local filterText = nil

    -- THE SAME TRAP, TWO FIELDS ALONG.
    --
    -- `lastEntries` was kept on the frame while `filterText` was moved off it
    -- for exactly the reason above, which is the shape of a fix applied to
    -- the instance that was noticed rather than to the class. Reading an
    -- unset field on a frame is not guaranteed to give nil -- a mixin's
    -- __index can answer every key -- and here that turns `if
    -- self.lastEntries then` into an infinite ipairs over a table that
    -- answers every index.
    --
    -- Found in 0.47.0 when a new test made the first call to SetFilter
    -- happen before anything had set entries. It hung the suite outright.
    local lastEntries = nil

    -- Readable, because a filter nobody can read is a filter nobody can test,
    -- and the one defect this widget has shipped was a filter that was set
    -- and never applied.
    function list:GetFilter()
        return filterText
    end

    function list:SetFilter(text)
        -- A stub EditBox, or a template whose GetText returns something
        -- surprising, must not be able to poison the filter with a value that
        -- string.find will throw on later -- three frames away from here,
        -- where the cause is not obvious.
        if type(text) ~= "string" then
            text = ""
        end

        text = CN.Trim(text)

        filterText = (text ~= "") and string.lower(text) or nil

        if lastEntries then
            self:SetEntries(lastEntries)
        end
    end

    -- SORTING.
    --
    -- Every list in this window has been in whatever order its tab produced,
    -- which is the right default -- the ranking IS the product -- and the
    -- wrong only option. Somebody looking for a specific mount wants
    -- alphabetical; somebody auditing progress wants it grouped.
    --
    -- Three orders, cycled by clicking the header, and "as ranked" is first
    -- so the default never changes for anybody who does not go looking.
    list.sortModes = { "ranked", "name", "reverse" }
    list.sortIndex = 1

    function list:SortMode()
        return self.sortModes[self.sortIndex] or "ranked"
    end

    function list:CycleSort()
        self.sortIndex = (self.sortIndex % #self.sortModes) + 1

        if lastEntries then
            self:SetEntries(lastEntries)
        end

        return self:SortMode()
    end

    function list:ApplySort(entries)
        local mode = self:SortMode()

        if mode == "ranked" then
            return entries
        end

        local sorted = {}

        for _, entry in ipairs(entries) do
            table.insert(sorted, entry)
        end

        -- A stable-enough comparison on the visible text: the rows are what
        -- the player is reading, so the order they asked for is an order over
        -- what they can see, not over an id they cannot.
        table.sort(sorted, function(a, b)
            local left  = string.lower(tostring(a.text or ""))
            local right = string.lower(tostring(b.text or ""))

            if mode == "reverse" then
                return left > right
            end

            return left < right
        end)

        return sorted
    end

    function list:Matches(entry)
        if not filterText then
            return true
        end

        local haystack = string.lower(tostring(entry.text or ""))

        -- Plain find, not a pattern: somebody typing "mount (2)" is typing a
        -- name, not a regular expression, and a stray bracket must not throw.
        return haystack:find(filterText, 1, true) ~= nil
    end

    -- entries = { { text = , onClick = , tooltip = }, ... }
    function list:SetEntries(entries)
        lastEntries = entries

        if filterText then
            local kept = {}

            for _, entry in ipairs(entries) do
                if self:Matches(entry) then
                    table.insert(kept, entry)
                end
            end

            entries = kept
        end

        entries = self:ApplySort(entries)

        local width = scroll:GetWidth() or (WINDOW_WIDTH - 60)

        local shown = math.min(#entries, self.maxRows)

        local truncated = #entries - shown

        if truncated > 0 then
            -- Room for the line that explains the truncation.
            shown = shown - 1
            truncated = truncated + 1
        end

        content:SetSize(width, math.max(1, (shown + (truncated > 0 and 1 or 0)) * ROW_HEIGHT))

        for index = 1, shown do
            local entry = entries[index]

            local row = self:GetRow(index)

            row.label:SetText(entry.text or "")

            -- The only thing a redraw changes. The handlers were bound when
            -- the row was created and read this.
            row.entry = entry

            row:Show()
        end

        local used = shown

        if truncated > 0 then
            used = shown + 1

            local row = self:GetRow(used)

            row.label:SetText("|cff999999... and " .. truncated
                .. " more not shown|r")

            row.entry = nil

            row:Show()
        end

        for index = used + 1, #self.rows do
            self.rows[index]:Hide()
        end

        return used
    end

    return list
end

UI.CreateList = CreateList
'@

$Embedded['Data\Quests.lua'] = @'
-- Data/Quests.lua
-- Completion Navigator :: curated static quest data.
--
-- Blizzard does not reliably return metadata for historical quests, so
-- anything the client cannot answer lives here. Keys are quest IDs.
--
-- Fields:
--   name       (string)  quest title
--   mapID      (number)  UiMapID the quest is picked up or completed in
--   x, y       (number)  0-1 normalized map coordinates
--   expansion  (string)  short expansion tag
--   requires   (table)   array of prerequisite quest IDs
--   unlocks    (table)   array of quest IDs this one opens
--   breadcrumb (boolean) skippable and permanently missable
--   obsolete   (boolean) no longer obtainable
--
-- Added in 0.43.0, all optional, all for saying WHY something is not
-- available rather than leaving the player to work it out:
--
--   classes    (table)   class file names that can take it, e.g. { "DRUID" }
--   races      (table)   race file names, e.g. { "NIGHTELF" }
--   faction    (string)  "Alliance" or "Horde"
--   minLevel   (number)  character level required
--   turnInMapID(number)  where it is handed IN, when that differs from where
--   turnInX,               it is picked up -- the client's own waypoint moves
--   turnInY                as you progress, so it cannot answer this
--
-- Add rows with:  .\cn.ps1 data quest <id> -Name "<title>"

local ADDON_NAME, CN = ...

CN.Static.RegisterQuests({

    [8237] = {
        name      = "Vanquish the Invaders!",
        expansion = "Classic",
    },

    -- CN:DATA:QUESTS -- new rows are inserted above this marker.
})
'@

$Embedded['Data\Community.lua'] = @'
-- Data/Community.lua
-- Completion Navigator :: quest chains contributed by players.
--
-- SEPARATE FROM Data/Quests.lua, DELIBERATELY.
--
-- Quests.lua is curated: somebody checked each row. This file is not. Rows
-- here arrived as `/cn contribute` exports, were reviewed for shape rather
-- than for truth, and are believed because several independent installs
-- watched the same ordering hold.
--
-- Keeping the two apart is what lets /cn why say which kind of claim it is
-- making. Merging them would be a one-line convenience that permanently
-- destroyed the distinction between "this is known" and "this has been
-- observed a lot", and there is no getting it back afterwards.
--
-- Rows are registered as OBSERVED prerequisites, so nothing in here can ever
-- present itself as curated fact.

local ADDON_NAME, CN = ...

CN.Static.RegisterCommunity({

    -- [questID] = { requires = { questID, ... }, sources = 3 },
    --
    -- `sources` is how many independent contributions agreed. Two is thin,
    -- five is solid; below two a row does not belong in this file.

    -- CN:DATA:COMMUNITY -- new rows are inserted above this marker.
})
'@

$Embedded['Data\ApiSurface.lua'] = @'
-- Data/ApiSurface.lua
-- GENERATED. Do not edit; gen.py rewrites this file from the source.
--
-- Every client API name the addon actually references. Each call site
-- guards on the name existing, which is right -- and which also means a
-- misspelled or renamed one is indistinguishable from a feature the
-- client does not support: the guard is false and the branch is dead
-- forever, silently.
--
-- /cn capture asks the live client which of these exist. The offline
-- suite fails on any it refused, and /cn selftest reports them in game.

local ADDON_NAME, CN = ...

CN.apiSurface = {
    "C_Calendar.GetDayEvent",
    "C_Calendar.GetNumDayEvents",
    "C_Calendar.OpenCalendar",
    "C_CampaignInfo.GetCampaignID",
    "C_CampaignInfo.GetCampaignInfo",
    "C_CampaignInfo.GetChapterIDs",
    "C_ChallengeMode.GetMapUIInfo",
    "C_Container.GetContainerItemInfo",
    "C_Container.GetContainerItemQuestInfo",
    "C_Container.GetContainerNumSlots",
    "C_CraftingOrders.GetClaimedOrder",
    "C_CraftingOrders.GetMyOrders",
    "C_CurrencyInfo.ExpandCurrencyList",
    "C_CurrencyInfo.GetCurrencyInfo",
    "C_CurrencyInfo.GetCurrencyListInfo",
    "C_CurrencyInfo.GetCurrencyListLink",
    "C_CurrencyInfo.GetCurrencyListSize",
    "C_DateAndTime.GetCurrentCalendarTime",
    "C_DateAndTime.GetSecondsUntilWeeklyReset",
    "C_DeathInfo.GetCorpseMapPosition",
