------------------------------------------------------------
-- GREAT VAULT
------------------------------------------------------------

-- The weekly reward chest. Three rows -- raid, dungeons, world -- each with
-- three thresholds, and you pick ONE item from everything unlocked.
--
-- This is the only system in the game that hands the addon all three things
-- it normally has to guess at: a hard deadline, a known denominator, and a
-- known reward. Everywhere else the addon reports counts because a percentage
-- would need a denominator the client will not supply; here the thresholds
-- are fixed and the client reports progress against them, so "3 of 4" is a
-- fact rather than an estimate.
--
-- The enum has been renamed across expansions, so the row type is resolved by
-- probing rather than assumed.
local function ThresholdEnum()
    if not Enum then
        return {}
    end

    return Enum.WeeklyRewardChestThresholdType
        or Enum.WeeklyRewardChestThreshold
        or {}
end

function Blizzard.HasWeeklyRewards()
    return C_WeeklyRewards ~= nil and C_WeeklyRewards.GetActivities ~= nil
end

-- Maps the client's row enum onto stable names of our own, so nothing
-- downstream depends on Blizzard's numbering.
function Blizzard.WeeklyRewardRowName(activityType)
    local enum = ThresholdEnum()

    if enum.Raid and activityType == enum.Raid then
        return "RAID"
    end

    -- Mythic+ is called "Activities" in the enum, which is uselessly generic.
    if enum.Activities and activityType == enum.Activities then
        return "DUNGEON"
    end

    if enum.World and activityType == enum.World then
        return "WORLD"
    end

    -- Older builds exposed a PvP row; treat it as world content rather than
    -- dropping it, so nothing silently disappears.
    if enum.RankedPvP and activityType == enum.RankedPvP then
        return "PVP"
    end

    return "UNKNOWN"
end

-- Returns an array of rows:
--   { row, index, threshold, progress, level, unlocked, rewardID }
function Blizzard.GetWeeklyRewardActivities()
    if not Blizzard.HasWeeklyRewards() then
        return {}
    end

    local ok, activities = pcall(C_WeeklyRewards.GetActivities)

    if not ok or type(activities) ~= "table" then
        return {}
    end

    local rows = {}

    for _, activity in ipairs(activities) do
        if type(activity) == "table" then
            local threshold = activity.threshold or 0
            local progress  = activity.progress or 0

            table.insert(rows, {
                row       = Blizzard.WeeklyRewardRowName(activity.type),
                index     = activity.index,
                threshold = threshold,
                progress  = progress,
                level     = activity.level,
                unlocked  = threshold > 0 and progress >= threshold,
                rewardID  = activity.id,
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.row ~= b.row then
            return a.row < b.row
        end

        return (a.threshold or 0) < (b.threshold or 0)
    end)

    return rows
end

function Blizzard.HasAvailableWeeklyRewards()
    if not C_WeeklyRewards then
        return false
    end

    if C_WeeklyRewards.HasAvailableRewards then
        local ok, available = pcall(C_WeeklyRewards.HasAvailableRewards)

        if ok then
            return available and true or false
        end
    end

    return false
end

function Blizzard.IsWorldQuest(questID)
    if C_QuestLog and C_QuestLog.IsWorldQuest then
        local ok, result = pcall(C_QuestLog.IsWorldQuest, questID)

        return ok and result and true or false
    end

    return false
end

-- Seconds remaining on a world quest, or nil when it is not time-limited.
function Blizzard.GetQuestTimeLeft(questID)
    if not C_TaskQuest then
        return nil
    end

    if C_TaskQuest.GetQuestTimeLeftSeconds then
        local ok, seconds = pcall(C_TaskQuest.GetQuestTimeLeftSeconds, questID)

        if ok and type(seconds) == "number" and seconds > 0 then
            return seconds
        end
    end

    if C_TaskQuest.GetQuestTimeLeftMinutes then
        local ok, minutes = pcall(C_TaskQuest.GetQuestTimeLeftMinutes, questID)

        if ok and type(minutes) == "number" and minutes > 0 then
            return minutes * 60
        end
    end

    return nil
end

-- World quests currently up on a map. The field naming has changed between
-- versions (questId vs questID), so both are accepted.
function Blizzard.GetWorldQuestsOnMap(uiMapID)
    local results = {}

    if not uiMapID or not C_TaskQuest or not C_TaskQuest.GetQuestsForPlayerByMapID then
        return results
    end

    local ok, tasks = pcall(C_TaskQuest.GetQuestsForPlayerByMapID, uiMapID)

    if not ok or type(tasks) ~= "table" then
        return results
    end

    for _, task in ipairs(tasks) do
        local questID = task.questID or task.questId

        if questID then
            table.insert(results, {
                questID = questID,
                mapID   = task.mapID or uiMapID,
                x       = task.x,
                y       = task.y,
                inArea  = task.inProgress,
            })
        end
    end

    return results
end

function Blizzard.GetWorldQuestInfo(questID)
    local info = {}

    if C_TaskQuest and C_TaskQuest.GetQuestInfoByQuestID then
        local ok, title, factionID = pcall(C_TaskQuest.GetQuestInfoByQuestID, questID)

        if ok then
            info.title     = title
            info.factionID = factionID
        end
    end

    if C_QuestLog and C_QuestLog.GetQuestTagInfo then
        local ok, tag = pcall(C_QuestLog.GetQuestTagInfo, questID)

        if ok and type(tag) == "table" then
            info.tagName        = tag.tagName
            info.worldQuestType = tag.worldQuestType
            info.quality        = tag.quality
            info.isElite        = tag.isElite
        end
    end

    return info
end

-- Calendar events happening today. Requires the calendar to have been
-- opened at least once; the call is cheap and safe to repeat.
function Blizzard.GetTodaysEvents()
    local events = {}

    if not C_Calendar or not C_DateAndTime then
        return events
    end

    pcall(function()
        if C_Calendar.OpenCalendar then
            C_Calendar.OpenCalendar()
        end
    end)

    local ok, today = pcall(C_DateAndTime.GetCurrentCalendarTime)

    if not ok or type(today) ~= "table" or not today.monthDay then
        return events
    end

    local gotCount, count = pcall(C_Calendar.GetNumDayEvents, 0, today.monthDay)

    if not gotCount or type(count) ~= "number" then
        return events
    end

    for index = 1, count do
        local gotEvent, event = pcall(C_Calendar.GetDayEvent, 0, today.monthDay, index)

        if gotEvent and type(event) == "table" and event.title then
            -- sequenceType is "ONGOING" or "START" while an event is live.
            local ongoing = event.sequenceType == "ONGOING"
                or event.sequenceType == "START"
                or event.sequenceType == ""

            -- WHEN IT ENDS, where the calendar says so.
            --
            -- Without this an active event is just a name, and the ranking
            -- has nothing to weigh: "Timewalking is on" and "Timewalking ends
            -- in four hours" are different pieces of advice. Some builds omit
            -- the end time entirely, and nil is then the right answer rather
            -- than a guessed week.
            local endsIn

            -- Gated on the end time itself, which is all this block reads.
            -- It used to also require C_DateAndTime.GetSecondsUntilWeeklyReset
            -- -- a function it never calls -- so on any build lacking that
            -- unrelated API every calendar event silently lost its deadline,
            -- and with it the urgency weighting and the "ends in" line.
            if type(event.endTime) == "table" and event.endTime.monthDay then

                local finish = event.endTime

                local nowStamp = time()

                local okStamp, stamp = pcall(time, {
                    year  = finish.year   or 0,
                    month = finish.month  or 1,
                    day   = finish.monthDay,
                    hour  = finish.hour   or 0,
                    min   = finish.minute or 0,
                })

                if okStamp and stamp and stamp > nowStamp then
                    endsIn = stamp - nowStamp
                end
            end

            table.insert(events, {
                title        = event.title,
                eventType    = event.eventType,
                calendarType = event.calendarType,
                sequenceType = event.sequenceType,
                ongoing      = ongoing,
                endsIn       = endsIn,
            })
        end
    end

    return events
end

------------------------------------------------------------
-- VIGNETTES (RARES AND TREASURES)
------------------------------------------------------------

-- Vignettes are the skull and chest icons the client puts on the minimap.
-- They are the only live signal that a rare is actually up right now, which
-- is what makes them worth more than any static rare database.
function Blizzard.GetVignettes(uiMapID)
    local results = {}

    if not C_VignetteInfo or not C_VignetteInfo.GetVignettes then
        return results
    end

    local ok, guids = pcall(C_VignetteInfo.GetVignettes)

    if not ok or type(guids) ~= "table" then
        return results
    end

    for _, guid in ipairs(guids) do
        local gotInfo, info = pcall(C_VignetteInfo.GetVignetteInfo, guid)

        if gotInfo and type(info) == "table" and info.name then
            local entry = {
                guid        = guid,
                vignetteID  = info.vignetteID,
                name        = info.name,
                atlas       = info.atlasName,
                objectGUID  = info.objectGUID,
                isDead      = info.isDead and true or false,
                onMinimap   = info.onMinimap,
                inFogOfWar  = info.inFogOfWar,
            }

            if uiMapID and C_VignetteInfo.GetVignettePosition then
                local gotPosition, position =
                    pcall(C_VignetteInfo.GetVignettePosition, guid, uiMapID)

                if gotPosition and position and position.GetXY then
                    local x, y = position:GetXY()

                    entry.mapID = uiMapID
                    entry.x     = x
                    entry.y     = y
                end
            end

            table.insert(results, entry)
        end
    end

    return results
end

-- Treasure chests and rare creatures use different atlas art. The atlas
-- name is the only reliable discriminator the client exposes.
function Blizzard.ClassifyVignette(atlasName)
    if type(atlasName) ~= "string" then
        return "UNKNOWN"
    end

    local lower = string.lower(atlasName)

    if string.find(lower, "chest", 1, true)
        or string.find(lower, "treasure", 1, true)
        or string.find(lower, "lootcontainer", 1, true) then
        return "TREASURE"
    end

    if string.find(lower, "vignetteskull", 1, true)
        or string.find(lower, "vignetteboss", 1, true)
        or string.find(lower, "elite", 1, true) then
        return "RARE"
    end

    if string.find(lower, "vignette", 1, true) then
        return "RARE"
    end

    return "UNKNOWN"
end

------------------------------------------------------------
-- CURRENCIES
------------------------------------------------------------

function Blizzard.GetCurrencyList()
    local results = {}

-- The currency id for a row of the currency list.
--
-- GetCurrencyListInfo returns a display record with no id in it. The link is
-- the only thing that carries one, and it has to be dug out of the hyperlink
-- -- `|Hcurrency:2245|h[Flightstones]|h` -- because the client offers no
-- direct accessor. Guarded and pcall'd at every step: this runs once per
-- currency on every scan, and a client that will not produce a link should
-- cost the row, not the scan.
local function CurrencyIDFromList(index)
    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyListLink then
        return nil
    end

    local ok, link = pcall(C_CurrencyInfo.GetCurrencyListLink, index)

    if not ok or type(link) ~= "string" then
        return nil
    end

    return tonumber(string.match(link, "currency:(%d+)"))
end

    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyListSize then
        return results
    end

    -- A COLLAPSED HEADER HIDES ITS ROWS FROM THE COUNT.
    --
    -- `GetCurrencyListSize` counts only rows under EXPANDED headers, exactly
    -- like the faction list. The reputation path has handled this since
    -- 0.30.0 with `WithAllFactionsExpanded`; the currency path never did, and
    -- there was no `ExpandCurrencyList` call anywhere in the addon. A player
    -- who had collapsed an expansion group in their Currency tab lost every
    -- currency underneath it from `/cn currencies`, from `/cn clock` and from
    -- the weekly-cap warnings, with nothing on screen saying so.
    --
    -- Expanded, scanned, put back -- the same shape, and the same obligation:
    -- what this addon changes to read, it changes back.
    local collapsed = {}

    if C_CurrencyInfo.ExpandCurrencyList then
        local counted, initial = pcall(C_CurrencyInfo.GetCurrencyListSize)

        if counted and type(initial) == "number" then
            for index = initial, 1, -1 do
                local asked, row = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)

                if asked and type(row) == "table" and row.isHeader
                    and row.isHeaderExpanded == false then

                    table.insert(collapsed, row.name)

                    pcall(C_CurrencyInfo.ExpandCurrencyList, index, true)
                end
            end
        end
    end

    local ok, size = pcall(C_CurrencyInfo.GetCurrencyListSize)

    if not ok or type(size) ~= "number" then
        return results
    end

    for index = 1, size do
        local gotInfo, info = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)


        if gotInfo and type(info) == "table" and not info.isHeader and info.name then
            -- THE LIST ROW DOES NOT CARRY AN ID.
            --
            -- CurrencyDisplayInfo -- what GetCurrencyListInfo returns -- has
            -- a name, quantities and flags and NO currencyID. Reading one
            -- gave nil for every row, and Currencies.Scan drops any row
            -- without an id, so the character currency store has always been
            -- empty and `/cn currencies` has always said "no currency data
            -- yet". The stub returned fixture tables that did carry the
            -- field, so the suite never saw it.
            --
            -- The id comes from the list LINK. Kept tolerant of a client that
            -- does supply it directly, because being wrong in that direction
            -- costs nothing.
            local currencyID = info.currencyID or CurrencyIDFromList(index)

            table.insert(results, {
                currencyID   = currencyID,
                name         = info.name,
                quantity     = info.quantity or 0,
                maxQuantity  = info.maxQuantity or 0,
                totalEarned  = info.totalEarned or 0,
                quality      = info.quality,
                discovered   = info.discovered ~= false,

                -- Weekly caps are the actionable part: a capped currency is
                -- earning potential being thrown away every week it sits.
                canEarnPerWeek     = info.canEarnPerWeek and true or false,
                earnedThisWeek     = info.quantityEarnedThisWeek or 0,
                maxWeeklyQuantity  = info.maxWeeklyQuantity or 0,

                useTotalEarnedForMaxQty = info.useTotalEarnedForMaxQty and true or false,

                -- Warband currencies. The client flags them and the addon
                -- ignored the flag until 0.43.0, so one capped on your main
                -- was recommended again on every alt.
                accountWide = (info.isAccountWide
                    or info.isAccountTransferable) and true or false,
            })
        end
    end

    -- Put the headers back the way the player had them.
    if #collapsed > 0 and C_CurrencyInfo.ExpandCurrencyList then
        local wanted = {}

        for _, name in ipairs(collapsed) do
            wanted[name] = true
        end

        local counted, final = pcall(C_CurrencyInfo.GetCurrencyListSize)

        if counted and type(final) == "number" then
            for index = final, 1, -1 do
                local asked, row = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)

                if asked and type(row) == "table" and row.isHeader
                    and row.name and wanted[row.name] then

                    pcall(C_CurrencyInfo.ExpandCurrencyList, index, false)
                end
            end
        end
    end

    return results
end

function Blizzard.GetCurrency(currencyID)
    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyInfo then
        return nil
    end

    local ok, info = pcall(C_CurrencyInfo.GetCurrencyInfo, currencyID)

    if not ok or type(info) ~= "table" then
        return nil
    end

    return info
end

------------------------------------------------------------
-- EXPLORATION
------------------------------------------------------------

-- Blizzard exposes explored overlay textures but never a total, so a raw
-- "percent explored" cannot be computed from the map API. The Exploration
-- achievement category does carry per-subzone criteria, which is the only
-- countable exploration data the client offers.
CN_EXPLORATION_CATEGORY = 97

function Blizzard.GetExplorationAchievements()
    local results = {}

    if not GetCategoryNumAchievements then
        return results
    end

    local total = Blizzard.GetCategoryCounts(CN_EXPLORATION_CATEGORY)

    for index = 1, total do
        local achievement =
            Blizzard.GetAchievementInCategory(CN_EXPLORATION_CATEGORY, index)

        if achievement then
            local done, criteria =
                Blizzard.GetAchievementProgress(achievement.achievementID)

            table.insert(results, {
                achievementID = achievement.achievementID,
                name          = achievement.name,
                completed     = achievement.completed,
                done          = done,
                criteria      = criteria,
            })
        end
    end

    return results
end

-- The unfinished criteria of one achievement, by name. For exploration
-- achievements these are the subzone names still undiscovered.
function Blizzard.GetIncompleteCriteria(achievementID, limit)
    local missing = {}

    if not GetAchievementNumCriteria or not GetAchievementCriteriaInfo then
        return missing
    end

    local total = GetAchievementNumCriteria(achievementID) or 0

    for index = 1, total do
        local ok, description, _, completed =
            pcall(GetAchievementCriteriaInfo, achievementID, index)

        if ok and not completed and description and description ~= "" then
            table.insert(missing, description)

            if limit and #missing >= limit then
                break
            end
        end
    end

    return missing
end

-- Every criterion, with its state, not only the missing ones.
--
-- GetIncompleteCriteria answers "what is left". A chain needs "what is the
-- whole path, and where on it am I" -- the done ones are what make progress
-- legible, and dropping them means the player sees five things left and no
-- sense of whether that is five out of six or five out of fifty.
function Blizzard.GetAchievementCriteriaList(achievementID, limit)
    local criteria = {}

    if not GetAchievementNumCriteria or not GetAchievementCriteriaInfo then
        return criteria
    end

    local total = GetAchievementNumCriteria(achievementID) or 0

    for index = 1, total do
        local ok, description, _, completed, quantity, required =
            pcall(GetAchievementCriteriaInfo, achievementID, index)

        if ok and description and description ~= "" then
            table.insert(criteria, {
                index       = index,
                description = description,
                completed   = completed and true or false,
                quantity    = quantity,
                required    = required,
            })

            if limit and #criteria >= limit then
                break
            end
        end
    end

    return criteria
end

-- How much standing remains before the next rank, and what that rank is.
--
-- Reputation is one of the few things in the game with a denominator the
-- client will actually vouch for, which is why it gets a real number here
-- while most of this addon refuses to invent one.
function Blizzard.GetReputationRemaining(factionID)
    local data = Blizzard.GetFactionByID(factionID)

    if not data then
        return nil
    end

    local current   = data.currentStanding or data.currentReactionThreshold
    local threshold = data.nextReactionThreshold
    local floor     = data.currentReactionThreshold

    if not current or not threshold or not floor then
        return nil
    end

    local earned = current - floor
    local needed = threshold - floor

    if needed <= 0 then
        return nil
    end

    return {
        earned    = earned,
        needed    = needed,
        remaining = math.max(0, needed - earned),
        standing  = data.reaction,
        name      = data.name,

        -- The rank being worked toward, so a band can be reported as a band
        -- -- "11,999 of 12,000 to Revered" -- rather than as a fraction of a
        -- goal the client will not vouch for.
        nextRankName = data.nextReactionName or data.nextRank,
    }
end

-- Every way the game knows of to obtain an appearance.
--
-- An appearance is not one item. It is a set of sources -- a drop here, a
-- vendor there, a quest reward -- and "which of these can I actually still
-- get" is the question a transmog hunter is asking.
function Blizzard.GetAppearanceSources(appearanceID)
    local sources = {}

    if not C_TransmogCollection or not C_TransmogCollection.GetAppearanceSources then
        return sources
    end

    local ok, results = pcall(C_TransmogCollection.GetAppearanceSources, appearanceID)

    if not ok or type(results) ~= "table" then
        return sources
    end

    for _, source in ipairs(results) do
        table.insert(sources, {
            sourceID    = source.sourceID,
            name        = source.name,
            collected   = source.isCollected and true or false,
            sourceType  = source.sourceType,
            itemID      = source.itemID,
        })
    end

    return sources
end

------------------------------------------------------------
-- MAP TOPOLOGY
------------------------------------------------------------

-- The map you are standing on is not necessarily the map a quest giver is
-- registered against.
--
-- GetBestMapForUnit answers with the most SPECIFIC map containing you, which
-- in a city or a cave is a small child map. Quest starts belonging to the
-- surrounding zone are registered on the PARENT, so a player standing in
-- front of an exclamation mark in a city can be told there is nothing here.
-- Reported from live play, exactly that way.
function Blizzard.GetMapInfo(mapID)
    if not mapID or not C_Map or not C_Map.GetMapInfo then
        return nil
    end

    local ok, info = pcall(C_Map.GetMapInfo, mapID)

    return ok and info or nil
end

function Blizzard.GetMapChildren(mapID)
    if not mapID or not C_Map or not C_Map.GetMapChildrenInfo then
        return {}
    end

    local ok, children = pcall(C_Map.GetMapChildrenInfo, mapID)

    if not ok or type(children) ~= "table" then
        return {}
    end

    return children
end

-- Every map worth asking about when the question is "what is around me":
-- the map itself, its parent, and the parent's other children. Ordered
-- nearest-first and deduplicated.
function Blizzard.RelatedMapIDs(mapID)
    local ordered, seen = {}, {}

    local function add(id)
        if id and not seen[id] then
            seen[id] = true
            table.insert(ordered, id)
        end
    end

    add(mapID)

    local info = Blizzard.GetMapInfo(mapID)

    local parentID = info and info.parentMapID

    -- A continent or world map has thousands of descendants; walking those
    -- would be a scan, not a lookup. Zone and below only.
    if parentID and parentID > 0 then
        local parent = Blizzard.GetMapInfo(parentID)

        -- 3 = zone, 4 = dungeon/micro. Anything broader is a continent.
        if parent and (parent.mapType or 0) >= 3 then
            add(parentID)

            for _, child in ipairs(Blizzard.GetMapChildren(parentID)) do
                add(child.mapID)
            end
        end
    end

    for _, child in ipairs(Blizzard.GetMapChildren(mapID)) do
        add(child.mapID)
    end

    return ordered
end

------------------------------------------------------------
-- QUEST COMPLETION HISTORY
------------------------------------------------------------

-- Every quest this character has ever completed.
--
-- This is a real number the client will vouch for, unlike anything the addon
-- counts about itself, and it is the number a player who has done three
-- hundred quests in a weekend actually wants to see.
function Blizzard.GetAllCompletedQuestIDs()
    if not C_QuestLog or not C_QuestLog.GetAllCompletedQuestIDs then
        return nil
    end

    local ok, ids = pcall(C_QuestLog.GetAllCompletedQuestIDs)

    if ok and type(ids) == "table" then
        return ids
    end

    return nil
end

-- Quests offered by the NPC currently being spoken to.
--
-- The most reliable "there is a quest right here" signal there is: the player
-- is standing in the conversation. Map data can be missing or registered
-- against a map we did not think to ask about; this cannot be wrong.
function Blizzard.GetGossipAvailableQuests()
    local offered = {}

    if not C_GossipInfo then
        return offered
    end

    local sources = {}

    if C_GossipInfo.GetAvailableQuests then
        table.insert(sources, C_GossipInfo.GetAvailableQuests)
    end

    for _, source in ipairs(sources) do
        local ok, quests = pcall(source)

        if ok and type(quests) == "table" then
            for _, quest in ipairs(quests) do
                if type(quest) == "table" and quest.questID then
                    table.insert(offered, {
                        questID   = quest.questID,
                        title     = quest.title,
                        isDaily   = quest.frequency == 2 or quest.isDaily,
                        isRepeatable = quest.repeatable and true or false,
                    })
                end
            end
        end
    end

    return offered
end

-- Quests the questgiver window is offering right now (the non-gossip case:
-- an NPC with a single quest opens the detail frame directly).
function Blizzard.GetActiveQuestOffer()
    if not GetQuestID then
        return nil
    end

    local ok, questID = pcall(GetQuestID)

    if ok and questID and questID > 0 then
        return questID
    end

    return nil
end

-- Bonus objectives and world quests keyed to a map. These are "available"
-- in every sense a player means, and they are not quest starts.
function Blizzard.GetTaskQuestsOnMap(uiMapID)
    local tasks = {}

    if not uiMapID or not C_TaskQuest or not C_TaskQuest.GetQuestsForPlayerByMapID then
        return tasks
    end

    local ok, results = pcall(C_TaskQuest.GetQuestsForPlayerByMapID, uiMapID)

    if not ok or type(results) ~= "table" then
        return tasks
    end

    for _, task in ipairs(results) do
        if type(task) == "table" and task.questId then
            table.insert(tasks, {
                questID = task.questId,
                x       = task.x,
                y       = task.y,
                mapID   = task.mapID or uiMapID,
                inProgress = task.inProgress and true or false,
            })
        end
    end

    return tasks
end

------------------------------------------------------------
-- CAMPAIGNS
------------------------------------------------------------

-- The main story, as distinct from everything else.
--
-- A player working through an expansion says "the story" and "the side
-- quests" and means two genuinely different things; the client knows which
-- is which and the addon should stop pretending they are one pile.
function Blizzard.GetCampaignID(questID)
    if not questID or not C_CampaignInfo or not C_CampaignInfo.GetCampaignID then
        return nil
    end

    local ok, campaignID = pcall(C_CampaignInfo.GetCampaignID, questID)

    if ok and campaignID and campaignID > 0 then
        return campaignID
    end

    return nil
end

function Blizzard.GetCampaignInfo(campaignID)
    if not campaignID or not C_CampaignInfo or not C_CampaignInfo.GetCampaignInfo then
        return nil
    end

    local ok, info = pcall(C_CampaignInfo.GetCampaignInfo, campaignID)

    return ok and info or nil
end

function Blizzard.GetCampaignChapters(campaignID)
    if not campaignID or not C_CampaignInfo or not C_CampaignInfo.GetChapterIDs then
        return {}
    end

    local ok, chapters = pcall(C_CampaignInfo.GetChapterIDs, campaignID)

    return (ok and type(chapters) == "table") and chapters or {}
end

function Blizzard.IsQuestCampaign(questID)
    return Blizzard.GetCampaignID(questID) ~= nil
end

------------------------------------------------------------
-- MERCHANTS
------------------------------------------------------------

-- Vendor inventories are only readable while the merchant window is open,
-- exactly like trade skill recipes. Everything here is opportunistic.
function Blizzard.GetMerchantItems()
    local items = {}

    if not GetMerchantNumItems then
        return items
    end

    local ok, count = pcall(GetMerchantNumItems)

    if not ok or type(count) ~= "number" then
        return items
    end

    for index = 1, count do
        local gotInfo, name, texture, price, quantity, numAvailable,
              isPurchasable, isUsable, extendedCost =
              pcall(GetMerchantItemInfo, index)

        if gotInfo and name then
            local itemID

            if C_MerchantFrame and C_MerchantFrame.GetItemInfo then
                local gotItem, info = pcall(C_MerchantFrame.GetItemInfo, index)

                if gotItem and type(info) == "table" then
                    itemID = info.itemID
                end
            end

            if not itemID and GetMerchantItemLink then
                local gotLink, link = pcall(GetMerchantItemLink, index)

                if gotLink and type(link) == "string" then
                    itemID = tonumber(link:match("item:(%d+)"))
                end
            end

            table.insert(items, {
                index         = index,
                itemID        = itemID,
                name          = name,
                price         = price,
                available     = numAvailable,
                isPurchasable = isPurchasable and true or false,
                extendedCost  = extendedCost and true or false,
            })
        end
    end

    return items
end

-- The creature ID behind any unit token. The GUID carries it, and it is the
-- only stable identifier for an NPC.
function Blizzard.GetUnitNPCID(unit)
    if not unit or not UnitExists or not UnitExists(unit) then
        return nil, nil
    end

    local name = UnitName and UnitName(unit) or nil

    local guid = UnitGUID and UnitGUID(unit)

    if not guid then
        return nil, name
    end

    -- GUID form: Creature-0-serverID-instanceID-zoneUID-npcID-spawnUID
    --
    -- The extra parentheses matter: select(6, ...) returns every value from
    -- position 6 onward, so without them tonumber receives the spawn UID as
    -- its `base` argument and throws.
    local npcID = tonumber((select(6, strsplit("-", guid))))

    return npcID, name
end

-- The NPC currently being interacted with.
function Blizzard.GetInteractingNPC()
    return Blizzard.GetUnitNPCID("npc")
end

------------------------------------------------------------
-- ITEM IDENTITY
------------------------------------------------------------

-- Items that teach a collectible do not announce themselves as such; each
-- collection API has its own item lookup. All three are optional and all
-- three have changed shape before, so each is probed rather than assumed.

function Blizzard.GetMountFromItem(itemID)
    if not itemID or not C_MountJournal or not C_MountJournal.GetMountFromItem then
        return nil
    end

    return C_MountJournal.GetMountFromItem(itemID)
end

function Blizzard.GetPetSpeciesFromItem(itemID)
    if not itemID or not C_PetJournal or not C_PetJournal.GetPetInfoByItemID then
        return nil, nil
    end

    local name, icon, petType, companionID, tooltipSource, description,
          isWild, canBattle, isTradeable, isUnique, obtainable, creatureDisplayID,
          speciesID = C_PetJournal.GetPetInfoByItemID(itemID)

    -- The species ID has moved position in this return list before. Falling
    -- back to the companion ID keeps the lookup working either way.
    return speciesID or companionID, name
end

-- Returns true/false only for items that actually have an appearance, and nil
-- for everything else.
--
-- The gate matters. PlayerHasTransmogByItemInfo answers false for a stack of
-- ore just as readily as for an unlearned tabard, so using it alone would
-- stamp "appearance not yet known" on every trade good in the game.
function Blizzard.HasTransmogByItem(itemID)
    if not itemID or not C_TransmogCollection then
        return nil
    end

    if not C_TransmogCollection.GetItemInfo then
        return nil
    end

    local ok, appearanceID = pcall(C_TransmogCollection.GetItemInfo, itemID)

    if not ok or not appearanceID then
        return nil
    end

    if C_TransmogCollection.PlayerHasTransmogByItemInfo then
        local hasOk, has = pcall(C_TransmogCollection.PlayerHasTransmogByItemInfo, itemID)

        if hasOk then
            return has and true or false
        end
    end

    return nil
end

function Blizzard.GetItemName(itemID)
    if not itemID then
        return nil
    end

    if C_Item and C_Item.GetItemNameByID then
        return C_Item.GetItemNameByID(itemID)
    end

    if GetItemInfo then
        return (GetItemInfo(itemID))
    end

    return nil
end

------------------------------------------------------------
-- SAVED INSTANCES
------------------------------------------------------------

-- What you are locked to this week, straight from the client.
--
-- NEVER PERSISTED. A lockout is a fact with an expiry on it, the client
-- always knows it, and a stale copy on disk would be worse than no copy at
-- all: "you have 6 of 8 bosses down in there" is actively harmful advice
-- after the reset it did not know about.
--
-- Returns an array of:
--   { name, id, reset, difficultyID, difficulty, defeated, encounters,
--     locked, extended, raid }
function Blizzard.GetSavedInstances()
    local results = {}

    if not GetNumSavedInstances or not GetSavedInstanceInfo then
        return results
    end

    local ok, count = pcall(GetNumSavedInstances)

    if not ok or not count then
        return results
    end

    for index = 1, count do
        -- POSITION 11 IS THE TOTAL AND 12 IS THE PROGRESS, NOT THE REVERSE.
        --
        -- The client returns ... difficultyName, numEncounters,
        -- encounterProgress. This read them the other way round, so a raid
        -- with six of eight bosses down came back as defeated=8, encounters=6
        -- -- which made `remaining` clamp to zero, `complete` true, and the
        -- provider return NOTHING. The Instances module's whole stated purpose
        -- is that a part-finished lockout is the cheapest progress in the
        -- game, and it has never once produced a candidate.
        --
        -- The stub had the same belief written into its fixture comment, so
        -- the suite agreed. Eighth time in this project that a stub and the
        -- code shared one wrong assumption.
        -- TWO DIFFERENT ID SPACES, AND THE ADDON USED THE WRONG ONE.
        --
        -- Return #2 is the LOCKOUT id -- a large opaque save identifier. The
        -- Encounter Journal's instance id is return #14. The addon stored #2
        -- as `id` and then handed it to `EJ_SelectInstance` and
        -- `EJ_GetEncounterInfoByIndex`, which have never heard of it: in game
        -- the boss list came back empty on the first iteration and
        -- `RemainingBosses` always answered "the Adventure Guide has no boss
        -- list for this instance".
        --
        -- The fixture put Encounter Journal instance ids in slot 2, so the
        -- stub and the code shared one wrong belief and the self-test asserted
        -- against it. Ninth time in this project.
        --
        -- Both are kept now, under names that say which is which, and the
        -- journal is asked with the journal's id.
        local gotInfo, name, lockoutID, reset, difficultyID, locked, extended,
            _, isRaid, _, difficultyName, encounters, defeated, _,
            journalInstanceID =
                pcall(GetSavedInstanceInfo, index)

        if gotInfo and name then
            table.insert(results, {
                name         = name,
                id           = lockoutID,
                instanceID   = journalInstanceID,
                reset        = reset,
                difficultyID = difficultyID,
                difficulty   = difficultyName,
                locked       = locked and true or false,
                extended     = extended and true or false,
                raid         = isRaid and true or false,
                defeated     = defeated or 0,
                encounters   = encounters or 0,
            })
        end
    end

    return results
end

------------------------------------------------------------
-- THE ENCOUNTER JOURNAL
------------------------------------------------------------

-- READING THIS API CHANGES WHAT THE PLAYER IS LOOKING AT.
--
-- EJ_SelectInstance and EJ_SelectEncounter are not queries. They set the
-- journal's current selection, which is the same selection the Adventure
-- Guide window is displaying. Scanning it while that window is open would
-- move the player's view out from under them -- an addon reaching into the
-- interface and changing what somebody is reading, which is exactly the kind
-- of thing this addon does not do.
--
-- So: refuse while the journal is visible, and put the selection back
-- afterwards when it is not.
function Blizzard.HasEncounterJournal()
    return EJ_SelectInstance ~= nil
        and EJ_GetEncounterInfoByIndex ~= nil
        and EJ_GetInstanceInfo ~= nil
end

function Blizzard.IsEncounterJournalOpen()
    return EncounterJournal ~= nil
        and EncounterJournal.IsShown ~= nil
        and EncounterJournal:IsShown() and true or false
end

local function WithJournal(work)
    if not Blizzard.HasEncounterJournal() then
        return nil, "the Adventure Guide is not available"
    end

    if Blizzard.IsEncounterJournalOpen() then
        return nil, "the Adventure Guide is open -- close it and try again"
    end

    local restoreInstance

    if EJ_GetCurrentInstance then
        local gotCurrent, current = pcall(EJ_GetCurrentInstance)

        if gotCurrent then
            restoreInstance = current
        end
    end

    local ok, result = pcall(work)

    -- Put it back even when the work threw, or the player's next visit to
    -- the Adventure Guide opens on whatever this addon was reading last.
    --
    -- AND "NOTHING WAS SELECTED" IS A STATE TO RESTORE.
    --
    -- The restore was guarded on `restoreInstance`, and
    -- `EJ_GetCurrentInstance` returns nil whenever the player has not opened
    -- the Adventure Guide this session -- which is the ordinary case, since
    -- this function refuses to run at all while the window is up. So on
    -- virtually every real invocation nothing was restored and the player's
    -- next visit opened on whatever this addon read last: exactly the outcome
    -- the comment above says it exists to prevent.
    if restoreInstance then
        if EJ_SelectInstance then
            pcall(EJ_SelectInstance, restoreInstance)
        end
    elseif EJ_ClearSearch then
        -- Nothing was selected before, so nothing should be selected after.
        -- Clearing the search is the only lever the client offers for that,
        -- and it also drops the search string this addon may have set.
        pcall(EJ_ClearSearch)
    end

    if not ok then
        return nil, tostring(result)
    end

    return result
end

Blizzard.WithEncounterJournal = WithJournal

-- Bosses in an instance, in the order the journal lists them:
--   { encounterID, name, order }
function Blizzard.GetInstanceEncounters(instanceID)
    if not instanceID then
        return {}
    end

    local encounters = WithJournal(function()
        EJ_SelectInstance(instanceID)

        local list = {}

        local index = 1

        while true do
            local name, _, encounterID = EJ_GetEncounterInfoByIndex(index, instanceID)

            if not name then
                break
            end

            table.insert(list, {
                encounterID = encounterID,
                name        = name,
                order       = index,
            })

            index = index + 1

            -- No instance in the game has anything like this many bosses.
            -- The guard is against an API that returns a name forever.
            if index > 40 then
                break
            end
        end

        return list
    end)

    return encounters or {}
end

-- Where does this drop?
--
-- Uses the journal's own search rather than building a reverse index of every
-- item in the game. An index would be tens of thousands of rows to answer a
-- question the player asks a handful of times a session, and it would be
-- stale the day a patch changed a loot table. The search is what the
-- Adventure Guide itself uses.
--
-- Returns an array of { instanceID, instance, encounterID, encounter }.
function Blizzard.SearchEncounterJournal(text, limit)
    if not text or text == "" then
        return {}
    end

    if not EJ_SetSearch or not EJ_GetSearchResult or not EJ_GetNumSearchResults then
        return {}
    end

    limit = limit or 8

    local results = WithJournal(function()
        EJ_SetSearch(text)

        local found = {}

        -- THE SEARCH IS ASYNCHRONOUS.
        --
        -- `EJ_SEARCH_RESULT_UPDATE` exists because `EJ_SetSearch` does not
        -- finish before it returns; Blizzard's own Encounter Journal listens
        -- for it. Read in the same frame, `EJ_GetNumSearchResults` answers
        -- zero on a cold search. The caller then memoised that zero for the
        -- session, so a second query after the results arrived still got
        -- nothing back.
        --
        -- There is no synchronous form to switch to, so the fix is on the
        -- caching side: a zero here is "not yet", not "nothing", and is
        -- reported as such rather than remembered. The stub answered
        -- synchronously, so no test could reach this.
        local total = EJ_GetNumSearchResults() or 0

        for index = 1, math.min(total, limit) do
            local id, stype, _, _, _, instanceID = EJ_GetSearchResult(index)

            -- Type 1 is an encounter in every build that has exposed this.
            if stype == 1 and id then
                local instanceName

                if instanceID and EJ_GetInstanceInfo then
                    instanceName = EJ_GetInstanceInfo(instanceID)
                end

                local encounterName = EJ_GetEncounterInfo and EJ_GetEncounterInfo(id)

                -- The journal's current difficulty, where the build exposes
                -- it. Reported rather than assumed: a nil here means the
                -- client did not say, which is different from "any".
                local difficulty

                if EJ_GetDifficulty and GetDifficultyInfo then
                    local gotDifficulty, difficultyID = pcall(EJ_GetDifficulty)

                    if gotDifficulty and difficultyID then
                        local gotName, name = pcall(GetDifficultyInfo, difficultyID)

                        if gotName then
                            difficulty = name
                        end
                    end
                end

                table.insert(found, {
                    encounterID = id,
                    encounter   = encounterName,
                    instanceID  = instanceID,
                    instance    = instanceName,
                    difficulty  = difficulty,
                })
            end
        end

        if EJ_ClearSearch then
            EJ_ClearSearch()
        end

        return found
    end)

    return results or {}
end

function Blizzard.GetInstanceName(instanceID)
    if not instanceID or not EJ_GetInstanceInfo then
        return nil
    end

    local ok, name = pcall(EJ_GetInstanceInfo, instanceID)

    return ok and name or nil
end
'@

$Embedded['Providers\StaticData.lua'] = @'
-- Providers/StaticData.lua
-- Completion Navigator :: access layer for the curated static database.
--
-- Data/*.lua files call CN.Static.Register* to contribute rows. Nothing
-- reads those tables directly; everything goes through the accessors here
-- so the storage shape can change without touching consumers.

local ADDON_NAME, CN = ...

local Static = {}

CN.Static = Static

Static.quests    = {}
Static.recipes   = {}
Static.vendors   = {}
Static.rares     = {}
Static.treasures = {}

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

-- record = { name =, mapID =, x =, y =, expansion =, requires = {}, unlocks = {} }
function Static.RegisterQuest(questID, record)
    if not questID or type(record) ~= "table" then
        return
    end

    Static.quests[questID] = record
end

function Static.RegisterQuests(records)
    for questID, record in pairs(records) do
        Static.RegisterQuest(questID, record)
    end
end

function Static.RegisterRecipe(itemID, record)
    Static.recipes[itemID] = record
end

function Static.RegisterVendor(npcID, record)
    Static.vendors[npcID] = record
end

function Static.RegisterRare(npcID, record)
    Static.rares[npcID] = record
end

function Static.RegisterTreasure(id, record)
    Static.treasures[id] = record
end

------------------------------------------------------------
-- ACCESS
------------------------------------------------------------

-- CONTRIBUTED CHAINS.
--
-- Held apart from the curated table so that the difference between "checked"
-- and "widely observed" survives being written to disk, and so /cn why can
-- say which one it is quoting.
Static.community = Static.community or {}

function Static.RegisterCommunity(records)
    if type(records) ~= "table" then
        return 0
    end

    local added = 0

    for questID, record in pairs(records) do
        if type(record) == "table" and type(record.requires) == "table" then
            Static.community[questID] = record

            added = added + 1
        end
    end

    return added
end

function Static.GetCommunity(questID)
    return Static.community[questID]
end

function Static.CommunityCount()
    local count = 0

    for _ in pairs(Static.community) do
        count = count + 1
    end

    return count
end

function Static.GetQuest(questID)
    return Static.quests[questID]
end

-- ELIGIBILITY, from curated data.
--
-- The client only draws quest pins the character qualifies for, so gating is
-- normally handled by simply not seeing it. That is fine while the player is
-- standing there and useless the moment they ask "why can nobody in my
-- Warband do this?" -- which is exactly what /cn why and /cn alts are for.
--
-- Returns eligible, reason. A record with no gating fields is eligible, and
-- says so with a nil reason rather than an empty claim.
function Static.QuestEligibility(questID, character)
    local record = Static.quests[questID]

    if not record then
        return true, nil
    end

    character = character or CN.character or {}

    if record.faction and character.faction
        and record.faction ~= character.faction then

        return false, record.faction .. " only"
    end

    if record.minLevel and character.level
        and character.level < record.minLevel then

        return false, "level " .. record.minLevel .. " required"
    end

    local function allowed(list, value, label)
        if type(list) ~= "table" or #list == 0 or not value then
            return true
        end

        for _, entry in ipairs(list) do
            if entry == value then
                return true
            end
        end

        return false, label .. " only: " .. table.concat(list, ", ")
    end

    local okClass, classReason = allowed(record.classes, character.class, "class")

    if not okClass then
        return false, classReason
    end

    local okRace, raceReason = allowed(record.races, character.race, "race")

    if not okRace then
        return false, raceReason
    end

    return true, nil
end

-- Where a quest is HANDED IN, which is not where it is picked up and is not
-- what the client's moving "next waypoint" reports once you are part-way
-- through it.
function Static.GetQuestTurnIn(questID)
    local record = Static.quests[questID]

    if not record or not record.turnInMapID then
        return nil
    end

    return record.turnInMapID, record.turnInX, record.turnInY
end

function Static.GetQuestName(questID)
    local record = Static.quests[questID]

    return record and record.name or nil
end

function Static.GetQuestLocation(questID)
    local record = Static.quests[questID]

    if not record then
        return nil, nil, nil
    end

    return record.mapID, record.x, record.y
end

function Static.Count()
    return CN.CountKeys(Static.quests),
           CN.CountKeys(Static.recipes),
           CN.CountKeys(Static.vendors),
           CN.CountKeys(Static.rares),
           CN.CountKeys(Static.treasures)
end
'@

$Embedded['Providers\TomTom.lua'] = @'
-- Providers/TomTom.lua
-- Completion Navigator :: TomTom waypoint provider.
--
-- TomTom stays the navigation engine. Completion Navigator only decides
-- which waypoint is worth setting.

local ADDON_NAME, CN = ...

local provider = {}

local active = {}

function provider.IsAvailable()
    return _G.TomTom ~= nil and _G.TomTom.AddWaypoint ~= nil
end

-- Returns true and the uid, or false and why not -- the same contract as the
-- Blizzard provider below, so `CN.SetWaypoint` can tell the player the truth
-- whichever one is in use.
function provider.SetWaypoint(mapID, x, y, title)
    if not provider.IsAvailable() then
        return false, "TomTom is not loaded"
    end

    local uid = _G.TomTom:AddWaypoint(mapID, x, y, {
        title       = title or "Completion Navigator",
        persistent  = false,
        minimap     = true,
        world       = true,
        crazy       = true,
    })

    if not uid then
        return false, "TomTom refused the waypoint"
    end

    table.insert(active, uid)

    return true, uid
end

function provider.ClearAll()
    if not provider.IsAvailable() then
        return false
    end

    local removed = #active

    for _, uid in ipairs(active) do
        pcall(_G.TomTom.RemoveWaypoint, _G.TomTom, uid)
    end

    active = {}

    return removed > 0
end

CN.RegisterWaypointProvider("TomTom", provider, 10)

------------------------------------------------------------
-- BLIZZARD MAP PIN FALLBACK
------------------------------------------------------------

local blizzardProvider = {}

function blizzardProvider.IsAvailable()
    return C_Map ~= nil and C_Map.SetUserWaypoint ~= nil
end

-- WHETHER THIS ACTUALLY WORKED IS NOW REPORTED.
--
-- This returned nothing at all, and every early return was silent -- so
-- `CN.SetWaypoint` discarded the result, returned `true` unconditionally, and
-- `/cn go` printed "Waypoint set: <name>" whether or not a pin appeared.
--
-- And the client refuses more often than the addon assumed. User waypoints
-- cannot be placed on dungeon and raid maps, on the cosmic and continent
-- maps, or on several instanced maps -- `C_Map.CanSetUserWaypointOnMap`
-- exists to say so and was called nowhere in this addon. In every one of
-- those cases the player was told a waypoint had been set and then sent to
-- look for an arrow that was never there.
function blizzardProvider.SetWaypoint(mapID, x, y)
    if not blizzardProvider.IsAvailable() then
        return false
    end

    if C_Map.CanSetUserWaypointOnMap then
        local asked, allowed = pcall(C_Map.CanSetUserWaypointOnMap, mapID)

        if asked and not allowed then
            return false, "the game does not allow a waypoint on this map"
        end
    end

    local point = UiMapPoint and UiMapPoint.CreateFromCoordinates(mapID, x, y)

    if not point then
        return false, "the client would not build a map point"
    end

    -- Guarded, as the identical call in Navigation.lua already was. Same API,
    -- and it was pcall'd in one place and bare in the other.
    local placed = pcall(C_Map.SetUserWaypoint, point)

    if not placed then
        return false, "the client refused the waypoint"
    end

    -- WHOSE PIN THIS IS.
    --
    -- There is exactly one user waypoint, and it belongs to the player unless
    -- this addon put it there. Remembering that is what lets ClearAll below
    -- refuse to delete a pin somebody placed by hand.
    blizzardProvider.owned = { mapID = mapID, x = x, y = y }

    if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
        C_SuperTrack.SetSuperTrackedUserWaypoint(true)
    end

    return true
end

function blizzardProvider.ClearAll()
    if not C_Map or not C_Map.ClearUserWaypoint then
        return false
    end

    -- ONLY IF IT IS OURS.
    --
    -- `ClearUserWaypoint` removes THE user waypoint -- there is one, and it
    -- is the player's. `/cn clearway`, stopping follow mode and every
    -- provider switch called it unconditionally, so an addon whose standing
    -- rule is that it does not act deleted a pin the player had placed by
    -- hand. The TomTom provider next door has always done this correctly: it
    -- tracks the UIDs it created and removes only those.
    if not blizzardProvider.owned then
        return false
    end

    -- And only if it is still the one we set. A player who has moved the pin
    -- since owns it again.
    if C_Map.GetUserWaypoint then
        local asked, current = pcall(C_Map.GetUserWaypoint)

        if asked and current then
            local sameMap = current.uiMapID == blizzardProvider.owned.mapID

            if not sameMap then
                blizzardProvider.owned = nil

                return false
            end
        end
    end

    pcall(C_Map.ClearUserWaypoint)

    blizzardProvider.owned = nil

    return true
end

CN.RegisterWaypointProvider("Blizzard", blizzardProvider, 20)
'@

$Embedded['Providers\ATT.lua'] = @'
-- Providers/ATT.lua
-- Completion Navigator :: AllTheThings interoperability.
--
-- ATT is the largest completion data corpus in the ecosystem. Duplicating it
-- would be pointless and rude; reading it when the player already has it
-- installed is the right relationship. Completion Navigator stays the
-- decision layer.
--
-- IMPORTANT: third-party addon APIs are not stable and are not documented as
-- public contracts. Every entry point below is probed at runtime and wrapped
-- in pcall. If ATT changes shape, this provider reports itself unavailable
-- and the addon carries on with its own data. It must never take the addon
-- down with it.
--
-- Run /cn providers in game to see exactly which entry points resolved.

local ADDON_NAME, CN = ...

local ATT = {}

CN.ATT = ATT

-- Candidate globals, newest naming first.
local GLOBALS = { "AllTheThings", "ATTC", "ATT" }

local resolved   = nil
local probeNotes = {}

local function Root()
    if resolved then
        return resolved
    end

    for _, name in ipairs(GLOBALS) do
        local candidate = _G[name]

        if type(candidate) == "table" then
            resolved = candidate

            table.insert(probeNotes, "global: " .. name)

            return resolved
        end
    end

    return nil
end

function ATT.IsAvailable()
    return Root() ~= nil
end

------------------------------------------------------------
-- SEARCH
------------------------------------------------------------

-- ATT's field search is the one entry point that has survived several
-- rewrites. It returns an array of "groups" describing everything ATT knows
-- about that ID.
local function Search(field, id)
    local root = Root()

    if not root or not id then
        return nil
    end

    local search = root.SearchForField or root.SearchForFieldContainer

    if type(search) ~= "function" then
        return nil
    end

    local ok, results = pcall(search, field, id)

    if not ok or type(results) ~= "table" then
        return nil
    end

    return results
end

ATT.Search = Search

------------------------------------------------------------
-- QUEST DATA
------------------------------------------------------------

-- Walks the groups ATT returns for a quest and pulls out whatever is useful.
-- Every field is optional; ATT groups are heterogeneous.
function ATT.GetQuestData(questID)
    local groups = Search("questID", questID)

    if not groups or #groups == 0 then
        return nil
    end

    local data = { source = "ATT" }

    for _, group in ipairs(groups) do
        if type(group) == "table" then
            if not data.name and type(group.name) == "string" and group.name ~= "" then
                data.name = group.name
            end

            if not data.mapID then
                data.mapID = group.mapID or group.coord and group.coord[3] or nil
            end

            -- ATT stores coordinates as {x, y, mapID} in `coord`, or a list
            -- of those in `coords`. Values are 0-100.
            local coord = group.coord

            if not coord and type(group.coords) == "table" then
                coord = group.coords[1]
            end

            if not data.x and type(coord) == "table" and coord[1] and coord[2] then
                data.x     = coord[1] / 100
                data.y     = coord[2] / 100
                data.mapID = coord[3] or data.mapID
            end

            if not data.requires and type(group.sourceQuests) == "table"
                and #group.sourceQuests > 0 then

                data.requires = {}

                for _, prerequisiteID in ipairs(group.sourceQuests) do
                    if type(prerequisiteID) == "number" then
                        table.insert(data.requires, prerequisiteID)
                    end
                end

                if #data.requires == 0 then
                    data.requires = nil
                end
            end

            -- FIRST WINS, like every other field in this loop.
            --
            -- The guard tested `data.lvl`, which nothing in this file ever
            -- assigns, so it was always true and the LAST matching group won
            -- -- alone among the six fields merged here, all of which use
            -- `if not data.<field>`. Two ATT groups with different level
            -- requirements produced whichever happened to be iterated last,
            -- and that feeds the "too low level" block reason.
            if data.requiresLevel == nil and type(group.lvl) == "number" then
                data.requiresLevel = group.lvl
            end
        end
    end

    if not (data.name or data.requires or data.x) then
        return nil
    end

    return data
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function ATT.Describe()
    local root = Root()

    if not root then
        return "not installed"
    end

    local entries = {}

    for _, note in ipairs(probeNotes) do
        table.insert(entries, note)
    end

    table.insert(entries, "SearchForField: "
        .. (type(root.SearchForField) == "function" and "yes" or "no"))

    return table.concat(entries, ", ")
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

CN.RegisterQuestDataProvider("ATT", {
    IsAvailable  = ATT.IsAvailable,
    GetQuestData = ATT.GetQuestData,
    Describe     = ATT.Describe,
    priority     = 20,
})
'@

$Embedded['Providers\BtWQuests.lua'] = @'
-- Providers/BtWQuests.lua
-- Completion Navigator :: BtWQuests interoperability.
--
-- BtWQuests knows quest chains. Completion Navigator knows what you have
-- done and where you are. The useful combination is: given the chain, which
-- link is the next one you can actually act on.
--
-- Same caution as the ATT provider: this reads another addon's internals,
-- which are not a published contract. Every access is probed and wrapped, so
-- a BtWQuests update can make this provider go quiet but cannot break
-- Completion Navigator.
--
-- /cn providers reports exactly what resolved.

local ADDON_NAME, CN = ...

local BtW = {}

CN.BtWQuests = BtW

local probeNotes = {}

local function Database()
    -- The database has lived in a couple of places across versions.
    local candidates = {
        _G.BtWQuestsDatabase,
        _G.BtWQuests and _G.BtWQuests.Database,
        _G.BtWQuests and _G.BtWQuests.database,
    }

    -- A NUMERIC LOOP, NOT ipairs.
    --
    -- The first slot is nil whenever the global is absent -- which the
    -- comment above says is the normal case on recent versions -- and ipairs
    -- stops at the first nil. So the two fallbacks this list exists to
    -- provide were unreachable in exactly the situation they were written
    -- for, and the provider reported BtWQuests as unavailable to anyone
    -- running a version that had moved it.
    --
    -- The interpreters do not even agree on how long the list is: 5.4 says
    -- two, the game's 5.1 says zero. BlizzardWorld.lua already avoids this
    -- with a numeric loop and a comment naming "the same nil-hole problem".
    for index = 1, 3 do
        local candidate = candidates[index]

        if type(candidate) == "table" then
            if #probeNotes == 0 then
                table.insert(probeNotes, "database slot " .. index)
            end

            return candidate
        end
    end

    return nil
end

function BtW.IsAvailable()
    return _G.BtWQuests ~= nil and Database() ~= nil
end

------------------------------------------------------------
-- QUEST LOOKUP
------------------------------------------------------------

local function GetQuestItem(questID)
    local database = Database()

    if not database or not questID then
        return nil
    end

    local getter = database.GetQuestByID or database.GetQuest

    if type(getter) ~= "function" then
        return nil
    end

    local ok, item = pcall(getter, database, questID)

    if not ok or type(item) ~= "table" then
        return nil
    end

    return item
end

BtW.GetQuestItem = GetQuestItem

-- Normalizes whatever shape prerequisites come back in into a flat array of
-- quest IDs. BtWQuests expresses them as condition tables, which may nest.
local function CollectQuestIDs(node, out, depth)
    if type(node) ~= "table" or depth > 4 then
        return
    end

    if type(node.questID) == "number" then
        out[node.questID] = true
    end

    if type(node.id) == "number" and node.type == "quest" then
        out[node.id] = true
    end

    for _, child in pairs(node) do
        if type(child) == "table" then
            CollectQuestIDs(child, out, depth + 1)
        end
    end
end

function BtW.GetQuestData(questID)
    local item = GetQuestItem(questID)

    if not item then
        return nil
    end

    local data = { source = "BtWQuests" }

    -- Name.
    local nameGetter = item.GetName

    if type(nameGetter) == "function" then
        local ok, name = pcall(nameGetter, item)

        if ok and type(name) == "string" and name ~= "" then
            data.name = name
        end
    elseif type(item.name) == "string" then
        data.name = item.name
    end

    -- Prerequisites.
    local prerequisites = item.prerequisites or item.restrictions

    local getter = item.GetPrerequisites

    if type(getter) == "function" then
        local ok, result = pcall(getter, item)

        if ok and type(result) == "table" then
            prerequisites = result
        end
    end

    if type(prerequisites) == "table" then
        local ids = {}

        CollectQuestIDs(prerequisites, ids, 0)

        ids[questID] = nil   -- never list a quest as its own prerequisite

        local list = {}

        for id in pairs(ids) do
            table.insert(list, id)
        end

        table.sort(list)

        if #list > 0 then
            data.requires = list
        end
    end

    if not (data.name or data.requires) then
        return nil
    end

    return data
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function BtW.Describe()
    if not _G.BtWQuests then
        return "not installed"
    end

    local database = Database()

    if not database then
        return "loaded, but no database found"
    end

    local entries = {}

    for _, note in ipairs(probeNotes) do
        table.insert(entries, note)
    end

    table.insert(entries, "GetQuestByID: "
        .. (type(database.GetQuestByID) == "function" and "yes" or "no"))

    return table.concat(entries, ", ")
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

CN.RegisterQuestDataProvider("BtWQuests", {
    IsAvailable  = BtW.IsAvailable,
    GetQuestData = BtW.GetQuestData,
    Describe     = BtW.Describe,
    priority     = 30,
})
'@

$Embedded['Providers\HandyNotes.lua'] = @'
-- Providers/HandyNotes.lua
-- Completion Navigator :: HandyNotes interoperability.
--
-- HandyNotes and its plugins hold coordinates for treasures, rares, vendors
-- and collectibles that no Blizzard API reports. Where vignettes only tell
-- you about something in range, HandyNotes knows where things are before you
-- get near them.
--
-- Same caution as the other external providers: this reads another addon's
-- internals, which are not a published contract. Every access is probed and
-- wrapped, so a HandyNotes update can make this go quiet but cannot break
-- Completion Navigator. /cn providers reports what resolved.

local ADDON_NAME, CN = ...

local Print = CN.Print

local HandyNotes = {}

CN.HandyNotes = HandyNotes

local function Root()
    local candidate = _G.HandyNotes

    if type(candidate) == "table" then
        return candidate
    end

    return nil
end

function HandyNotes.IsAvailable()
    return Root() ~= nil
end

------------------------------------------------------------
-- PLUGINS
------------------------------------------------------------

-- HandyNotes itself holds almost no data. The plugins do, and they register
-- with the parent under names like "HandyNotes_Treasures".
function HandyNotes.GetPlugins()
    local root = Root()

    if not root then
        return {}
    end

    local names = {}

    -- Ace-style addon with a plugin registry.
    local iterate = root.IteratePlugins

    if type(iterate) == "function" then
        -- THE WHOLE TRIPLET, NOT JUST THE FIRST RETURN.
        --
        -- `IteratePlugins` is a `pairs`-style stateful iterator: it returns
        -- `next`, the table, and the control value. Capturing only the first
        -- and writing `for name in iterator` calls `next(nil, nil)`, which
        -- throws "bad argument #1 to 'next' (table expected, got nil)" -- so
        -- this integration could not work for any player who actually has
        -- HandyNotes installed.
        --
        -- The stub in the test suite was a single self-contained closure,
        -- which is the one shape that makes the broken form work. Stub more
        -- forgiving than the client, again.
        local ok, step, state, control = pcall(iterate, root)

        if ok and type(step) == "function" then
            local safe = 0

            for name in step, state, control do
                table.insert(names, name)

                safe = safe + 1

                if safe > 200 then
                    break
                end
            end
        end
    end

    if #names == 0 and type(root.plugins) == "table" then
        for name in pairs(root.plugins) do
            table.insert(names, name)
        end
    end

    table.sort(names)

    return names
end

------------------------------------------------------------
-- NODE LOOKUP
------------------------------------------------------------

-- Asks every registered plugin what it knows about a map. Plugin node
-- iterators are HandyNotes' documented extension point, so this is the most
-- stable surface available -- but it is still another addon's internals.
function HandyNotes.GetNodesOnMap(uiMapID)
    local root = Root()

    if not root or not uiMapID then
        return {}
    end

    local nodes = {}

    local iterate = root.IteratePlugins

    if type(iterate) ~= "function" then
        return nodes
    end

    local ok, step, state, control = pcall(iterate, root)

    if not ok or type(step) ~= "function" then
        return nodes
    end

    local pluginCount = 0

    for name, handler in step, state, control do
        pluginCount = pluginCount + 1

        if pluginCount > 50 then
            break
        end

        if type(handler) == "table" and type(handler.GetNodes2) == "function" then
            -- Same triplet, same reason: a plugin's node iterator is also
            -- a `pairs`-style return. This one was inside a pcall, so it
            -- failed to a debug line instead of an error -- silently, which
            -- is how a whole feature can be broken and look empty.
            local gotNodes, nodeStep, nodeState, nodeControl =
                pcall(handler.GetNodes2, handler, uiMapID, false)

            if gotNodes and type(nodeStep) == "function" then
                local safe = 0

                -- HandyNotes coords pack x and y into one integer.
                local success = pcall(function()
                    for coord, node in nodeStep, nodeState, nodeControl do
                        safe = safe + 1

                        if safe > 500 then
                            break
                        end

                        if type(coord) == "number" then
                            local x = math.floor(coord / 10000) / 10000
                            local y = (coord % 10000) / 10000

                            table.insert(nodes, {
                                plugin = name,
                                x      = x,
                                y      = y,
                                mapID  = uiMapID,
                                label  = type(node) == "table" and node.label or nil,
                            })
                        end
                    end
                end)

                if not success then
                    CN.DebugPrint("HandyNotes plugin " .. tostring(name)
                        .. " node iteration failed.")
                end
            end
        end
    end

    return nodes
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function HandyNotes.Describe()
    local root = Root()

    if not root then
        return "not installed"
    end

    local plugins = HandyNotes.GetPlugins()

    if #plugins == 0 then
        return "loaded, no plugins registered"
    end

    local noun = (#plugins == 1) and " plugin" or " plugins"

    if #plugins <= 3 then
        return #plugins .. noun .. ": " .. table.concat(plugins, ", ")
    end

    return #plugins .. noun
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

-- Registered as a quest data provider so it appears in /cn providers, even
-- though it answers about locations rather than quests. It never claims to
-- know a quest, so it can never contribute wrong prerequisite data.
CN.RegisterQuestDataProvider("HandyNotes", {
    IsAvailable  = HandyNotes.IsAvailable,
    GetQuestData = function() return nil end,
    Describe     = HandyNotes.Describe,
    priority     = 90,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

-- `GetNodesOnMap` is seventy lines and the stated reason this file exists,
-- and until 0.53.0 nothing called it: no provider, no command, no test. It
-- was written, documented, shipped, and never run -- and because it sat
-- behind a broken iterator it could not have worked if it had been.
--
-- Read-only and on request. HandyNotes nodes are another addon's data about
-- the same world, so they are shown rather than folded into the ranking:
-- this addon does not know how that plugin decides what to draw, and
-- inheriting somebody else's opinion silently is not the same as having one.
CN:RegisterCommand{
    name    = "handynotes",
    aliases = { "hn" },
    order   = 78,
    help    = "What HandyNotes plugins are drawing on this map.",
    handler = function()
        if not HandyNotes.IsAvailable() then
            Print("HandyNotes is not installed, or has not loaded.")
            return
        end

        Print("HandyNotes: " .. HandyNotes.Describe())

        local mapID = CN.GetPlayerPosition()

        if not mapID then
            Print("|cff999999The client will not say which map you are on.|r")
            return
        end

        local nodes = HandyNotes.GetNodesOnMap(mapID)

        if #nodes == 0 then
            Print("|cff999999No plugin is drawing anything on this map.|r")
            return
        end

        Print(#nodes .. " node(s) on this map:")

        for index, node in ipairs(nodes) do
            if index > 20 then
                Print("  |cff999999and " .. (#nodes - 20) .. " more|r")
                break
            end

            Print(string.format("  %d. %s |cff999999%s at %.1f, %.1f|r",
                index, tostring(node.label or "unnamed"),
                tostring(node.plugin), (node.x or 0) * 100, (node.y or 0) * 100))
        end

        Print("|cff999999Shown, not scored: this is another addon's view of "
            .. "the same world.|r")
    end,
}
'@

$Embedded['Modules\Quests.lua'] = @'
-- Modules/Quests.lua
-- Completion Navigator :: quest subsystem.
--
-- Roadmap position: automatic discovery, event-driven refresh, persistent
-- metadata and status, source-ranked metadata writes.

local ADDON_NAME, CN = ...

local Quests = CN:RegisterModule("Quests")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

CN.pendingQuestLoads = CN.pendingQuestLoads or {}

------------------------------------------------------------
-- COMPLETION STATE
------------------------------------------------------------

function Quests.IsCompletedByCharacter(questID)
    return Blizzard.IsQuestCompletedByCharacter(questID)
end

function Quests.IsCompletedOnAccount(questID)
    return Blizzard.IsQuestCompletedOnAccount(questID)
end

-- Kept for backwards compatibility with the single-file prototype.
CN.IsQuestCompletedByCharacter = Quests.IsCompletedByCharacter
CN.IsQuestCompletedOnAccount   = Quests.IsCompletedOnAccount

------------------------------------------------------------
-- METADATA
------------------------------------------------------------

-- Writes a name only when the incoming source is at least as
-- authoritative as the stored one. Manual entries never clobber Blizzard.
function Quests.SetMetadata(questID, name, source)
    if not questID or not name or name == "" then
        return false
    end

    local metadata = CN.Account("questMetadata")
    local existing = metadata[questID]

    source = source or "manual"

    if existing and existing.name and not CN.IsBetterSource(source, existing.source) then
        DebugPrint("Kept existing " .. tostring(existing.source)
            .. " name for quest " .. questID .. "; rejected " .. source .. ".")
        return false
    end

    metadata[questID] = {
        questID  = questID,
        name     = name,
        lastSeen = time(),
        source   = source,
    }

    return true
end

function Quests.GetMetadata(questID)
    return CN.Account("questMetadata")[questID]
end

-- Resolution order: cache -> live client -> static data -> async request.
function Quests.GetName(questID, requestIfMissing)
    if not questID then
        return nil
    end

    local cached = Quests.GetMetadata(questID)

    if cached and cached.name then
        return cached.name
    end

    local title = Blizzard.GetQuestTitle(questID, false)

    if title then
        Quests.SetMetadata(questID, title, "blizzard")
        return title
    end

    local static = CN.Static.GetQuestName(questID)

    if static then
        Quests.SetMetadata(questID, static, "static")
        return static
    end

    if requestIfMissing then
        Blizzard.GetQuestTitle(questID, true)
    end

    return nil
end

CN.GetQuestName = Quests.GetName

------------------------------------------------------------
-- DISCOVERY
------------------------------------------------------------

function Quests.RecordDiscovered(questID, source)
    questID = CN.ToID(questID)

    if not questID then
        return false
    end

    local discovered = CN.Account("discoveredQuests")
    local existing   = discovered[questID]

    discovered[questID] = {
        firstSeen = existing and existing.firstSeen or time(),
        lastSeen  = time(),
        source    = source or (existing and existing.source) or "manual",
    }

    if not existing then
        DebugPrint("Discovered quest " .. questID .. " (" .. tostring(source or "manual") .. ").")
    end

    return existing == nil
end

CN.RecordDiscoveredQuest = Quests.RecordDiscovered

-- Quests you could walk up to and accept right now, on one map.
--
-- These are the exclamation marks. Until 0.23.0 the addon could not see them
-- at all: it read the quest LOG, which by definition contains only quests you
-- have already taken. "What should I do next?" cannot be answered honestly
-- while the answer "pick up that quest twenty yards away" is invisible.
------------------------------------------------------------
-- LIFECYCLE PHASE
------------------------------------------------------------

-- A quest is not one place. It is three, in order:
--
--   PICKUP  -- the exclamation mark, where you accept it
--   ACTIVE  -- wherever its objectives actually are
--   TURNIN  -- the question mark, where you hand it back
--
-- Treating a quest as a single point is why an addon sends you back and forth:
-- it cannot tell that two quests share a giver, or that four you are carrying
-- all hand in at the same NPC. Naming the phase is what makes batching
-- possible at all.
CN.questPhases = {
    PICKUP = "PICKUP",
    ACTIVE = "ACTIVE",
    TURNIN = "TURNIN",
}

CN.questPhaseVerbs = {
    PICKUP = "pick up",
    ACTIVE = "work on",
    TURNIN = "turn in",
}

function Quests.Phase(questID)
    if not questID then
        return nil
    end

    if Blizzard.IsQuestReadyForTurnIn(questID) then
        return CN.questPhases.TURNIN
    end

    if Blizzard.IsQuestInLog(questID) then
        return CN.questPhases.ACTIVE
    end

    if Quests.IsCompletedByCharacter(questID) then
        return nil
    end

    return CN.questPhases.PICKUP
end

function Quests.PhaseVerb(phase)
    return CN.questPhaseVerbs[phase] or "do"
end

-- Quests offered near you that you have not taken.
--
-- REPORTED FROM LIVE PLAY: "I'm literally standing in front of one to pick
-- up" while this returned zero. Three separate reasons that can happen, and
-- the old version was vulnerable to all three:
--
--   1. WRONG MAP. GetBestMapForUnit answers with the most specific map you
--      are standing on -- a city, a cave, a building interior. Quest starts
--      belonging to the surrounding zone are registered against the PARENT
--      map, so asking only about your own map misses them. This is the most
--      likely cause and the cheapest to fix: ask the neighbourhood.
--   2. THE MAP SIMPLY DOES NOT SAY. A giver whose pin the client has not
--      loaded is invisible to every map query. The only thing that cannot be
--      wrong is the conversation itself, so talking to an NPC now records
--      what they offered.
--
-- Sources are unioned and each result says where it came from, because when
-- this is wrong again the first question will be "which source found it".
function Quests.AvailableOnMap(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local found, seen = {}, {}

    local function consider(poi, source)
        if not poi or not poi.questID or seen[poi.questID] then
            return
        end

        if Blizzard.IsQuestInLog(poi.questID) then
            return
        end

        if Quests.IsCompletedByCharacter(poi.questID) then
            return
        end

        seen[poi.questID] = true

        poi.source = source

        table.insert(found, poi)
    end

    -- 1. Every map in the neighbourhood, not just the one under your feet.
    for _, relatedID in ipairs(Blizzard.RelatedMapIDs(mapID)) do
        for _, poi in ipairs(Blizzard.GetQuestPOIsOnMap(relatedID)) do
            if poi.isQuestStart and not poi.inProgress then
                consider(poi, "map")

                Quests.RememberOffer(poi)
            end
        end
    end

    -- 2. Anything an NPC has actually offered us, remembered from the
    --    conversation. Only kept while it is still plausibly nearby.
    for questID, record in pairs(Quests.RecentOffers()) do
        consider({
            questID = questID,
            mapID   = record.mapID,
            x       = record.x,
            y       = record.y,
        }, "offered")
    end

    table.sort(found, function(a, b) return a.questID < b.questID end)

    return found
end

-- QUESTS THREE ZONES AWAY.
--
-- The client's POI list only answers for a map, and only for the map the
-- player is looking at -- so "what is waiting for me in Azj-Kahet?" was
-- structurally unanswerable and the addon said so in its own scope-limits
-- note. It still cannot enumerate a zone it has never seen; what it can do
-- is remember what it HAS seen.
--
-- Every quest start observed on any map is recorded, so a zone the player
-- walked through last week can still be reported on. Bounded, and pruned
-- when a quest is completed or picked up, because a remembered pin for a
-- quest already in the log is worse than no pin.
Quests.rememberedCap = 600

local function Remembered()
    return CN.Account("questPins")
end

Quests.Remembered = Remembered

function Quests.RememberOffer(poi)
    if not poi or not poi.questID or not poi.mapID then
        return false
    end

    local store = Remembered()

    -- Only what the client cannot re-derive instantly: no names, no
    -- timestamps beyond the one that makes pruning possible.
    store[poi.questID] = {
        mapID = poi.mapID,
        x     = poi.x and math.floor(poi.x * 1000 + 0.5) / 1000 or nil,
        y     = poi.y and math.floor(poi.y * 1000 + 0.5) / 1000 or nil,
    }

    if CN.CountKeys(store) > Quests.rememberedCap then
        Quests.PruneRemembered()
    end

    return true
end

-- Drops anything no longer worth remembering: completed, in the log, or --
-- if still over the cap after that -- the lowest quest IDs, which are the
-- oldest content and the least likely to be what the player is working on.
function Quests.PruneRemembered()
    local store = Remembered()

    local dropped = 0

    -- ACCOUNT COMPLETION, NOT THIS CHARACTER'S.
    --
    -- `Remembered()` is an account-wide store of WHERE a quest is, and where
    -- a quest is does not depend on who is asking. Pruning it on
    -- `IsCompletedByCharacter` meant one character finishing a zone deleted
    -- the remembered locations for every other character who still had it to
    -- do -- the same wrong-scope defect as the quest-status store, in the
    -- other direction.
    for questID in pairs(store) do
        if Quests.IsCompletedOnAccount(questID)
            or Blizzard.IsQuestInLog(questID) then

            store[questID] = nil
            dropped = dropped + 1
        end
    end

    local remaining = CN.CountKeys(store)

    if remaining > Quests.rememberedCap then
        local ids = {}

        for questID in pairs(store) do
            table.insert(ids, questID)
        end

        table.sort(ids)

        for index = 1, remaining - Quests.rememberedCap do
            store[ids[index]] = nil
            dropped = dropped + 1
        end
    end

    return dropped
end

-- What is waiting in a zone the player is not standing in.
function Quests.RememberedInZone(mapID)
    local waiting = {}

    if not mapID then
        return waiting
    end

    for questID, record in pairs(Remembered()) do
        if record.mapID == mapID
            and not Quests.IsCompletedByCharacter(questID)
            and not Blizzard.IsQuestInLog(questID) then

            table.insert(waiting, {
                questID = questID,
                mapID   = record.mapID,
                x       = record.x,
                y       = record.y,
            })
        end
    end

    table.sort(waiting, function(a, b) return a.questID < b.questID end)

    return waiting
end

-- Every zone with something remembered in it, most first.
function Quests.RememberedZones()
    local byZone = {}

    for questID, record in pairs(Remembered()) do
        if not Quests.IsCompletedByCharacter(questID)
            and not Blizzard.IsQuestInLog(questID) then

            byZone[record.mapID] = (byZone[record.mapID] or 0) + 1
        end
    end

    local zones = {}

    for zoneID, count in pairs(byZone) do
        table.insert(zones, {
            mapID = zoneID,
            name  = Blizzard.GetMapName(zoneID),
            count = count,
        })
    end

    table.sort(zones, function(a, b)
        if a.count ~= b.count then
            return a.count > b.count
        end

        return (a.mapID or 0) < (b.mapID or 0)
    end)

    return zones
end

CN:RegisterEvent("QUEST_TURNED_IN", function()
    Quests.PruneRemembered()
end)

CN:RegisterCommand{
    name    = "waiting",
    args    = "[zone name]",
    order   = 23,
    help    = "Quests you have walked past and never picked up, by zone.",
    handler = function(args)
        args = CN.Trim(args or "")

        local zones = Quests.RememberedZones()

        if #zones == 0 then
            Print("Nothing remembered yet.")
            Print("|cff999999The addon records quest starts as it sees them. "
                .. "Walk through a zone once and it can tell you what you "
                .. "left behind in it.|r")
            return
        end

        if args ~= "" then
            for _, zone in ipairs(zones) do
                if zone.name and string.lower(zone.name):find(string.lower(args), 1, true) then
                    Print(zone.name .. ": " .. zone.count .. " left behind")

                    for index, entry in ipairs(Quests.RememberedInZone(zone.mapID)) do
                        if index > 20 then
                            Print("  |cff999999... and more|r")
                            break
                        end

                        Print("  " .. (Quests.GetName(entry.questID)
                            or ("quest " .. entry.questID)))
                    end

                    return
                end
            end

            Print("Nothing remembered in a zone matching \"" .. args .. "\".")
            return
        end

        Print("Quests you have seen and not taken:")

        for index, zone in ipairs(zones) do
            if index > 12 then
                Print("  |cff999999... and " .. (#zones - 12) .. " more zones|r")
                break
            end

            Print(string.format("  %-28s %d",
                tostring(zone.name or zone.mapID), zone.count))
        end

        Print("|cff999999This is what the addon has actually seen, not every "
            .. "quest in the game -- the client only lists pins for the map "
            .. "you are looking at.|r")
    end,
}

-- HOW FAR IS "HERE".
--
-- Searching the parent map and its siblings is what fixed a player being told
-- zero while standing in front of a quest giver. It also means the answer now
-- spans a whole zone, so calling it "here" overstates it -- the addon would
-- be pointing at something a four-minute ride away and using a word that
-- means arm's reach.
--
-- Split by distance where coordinates exist, and say the honest word for
-- each. Anything without coordinates is reported as "in this zone", because
-- that is the strongest claim the data supports.
CN.nearbyYards = 300

function Quests.SplitAvailableByDistance(available, mapID)
    local near, zone = {}, {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    local nav = CN:GetModule("Navigation")

    for _, poi in ipairs(available or {}) do
        local yards

        if nav and nav.DistanceYards and playerX and playerY
            and poi.x and poi.y and (poi.mapID or mapID) == playerMap then

            yards = nav.DistanceYards(playerMap, playerX, playerY, poi.x, poi.y)
        end

        poi.yards = yards

        if yards and yards <= CN.nearbyYards then
            table.insert(near, poi)
        else
            table.insert(zone, poi)
        end
    end

    return near, zone
end

-- World quests and bonus objectives, deliberately counted SEPARATELY.
--
-- They are available in the dictionary sense, and they are not what a player
-- means by "quests I can pick up here" -- there is no exclamation mark and
-- nobody to talk to. Folding them into that number makes it stop matching
-- what is on the screen, which is the entire complaint this code exists to
-- answer.
function Quests.TasksOnMap(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local tasks = {}

    for _, task in ipairs(Blizzard.GetTaskQuestsOnMap(mapID)) do
        if not Quests.IsCompletedByCharacter(task.questID) then
            table.insert(tasks, task)
        end
    end

    return tasks
end

------------------------------------------------------------
-- WHAT AN NPC ACTUALLY OFFERED
------------------------------------------------------------

-- A conversation cannot be wrong about what it is offering. Map data can.
local recentOffers = {}

Quests.offerMemorySeconds = 900

function Quests.RecentOffers()
    local now = time()

    for questID, record in pairs(recentOffers) do
        if now - (record.at or 0) > Quests.offerMemorySeconds then
            recentOffers[questID] = nil
        end
    end

    return recentOffers
end

function Quests.NoteOffered(questID, title)
    if not questID or Quests.IsCompletedByCharacter(questID) then
        return false
    end

    if Blizzard.IsQuestInLog(questID) then
        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    recentOffers[questID] = {
        at    = time(),
        mapID = mapID,
        x     = x,
        y     = y,
    }

    if title and title ~= "" then
        Quests.SetMetadata(questID, title, "offered")
    end

    if mapID and x and y then
        Quests.SetLocation(questID, mapID, x, y, "offered")
    end

    Quests.RecordDiscovered(questID, "offered")

    DebugPrint("Noted quest " .. questID .. " offered by an NPC here.")

    return true
end

function Quests.ForgetOffer(questID)
    if questID then
        recentOffers[questID] = nil
    end
end

-- Talking to someone is the single most reliable moment to learn that a
-- quest exists here, so take it every time.
CN:RegisterEvent("GOSSIP_SHOW", function()
    for _, offer in ipairs(Blizzard.GetGossipAvailableQuests()) do
        Quests.NoteOffered(offer.questID, offer.title)
    end
end)

CN:RegisterEvent("QUEST_DETAIL", function()
    Quests.NoteOffered(Blizzard.GetActiveQuestOffer(), GetTitleText and GetTitleText())
end)

CN:RegisterEvent("QUEST_ACCEPTED", function(_, questID)
    Quests.ForgetOffer(questID)
end)

------------------------------------------------------------
-- DIAGNOSIS
------------------------------------------------------------

-- When a player says "it says zero and I am standing in front of one", the
-- useful reply is not a guess. It is a listing of every map that was asked,
-- what each one answered, and why each answer was rejected.
function Quests.AvailableDiagnostic(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    local report = {
        mapID  = mapID,
        maps   = {},
        counts = { start = 0, inLog = 0, completed = 0, notStart = 0, task = 0, offered = 0 },
    }

    if not mapID then
        return report
    end

    for _, relatedID in ipairs(Blizzard.RelatedMapIDs(mapID)) do
        local pois = Blizzard.GetQuestPOIsOnMap(relatedID)

        local row = {
            mapID = relatedID,
            name  = Blizzard.GetMapName(relatedID),
            pois  = #pois,
            starts = 0,
            usable = 0,
        }

        for _, poi in ipairs(pois) do
            if poi.isQuestStart and not poi.inProgress then
                row.starts = row.starts + 1

                if Blizzard.IsQuestInLog(poi.questID) then
                    report.counts.inLog = report.counts.inLog + 1
                elseif Quests.IsCompletedByCharacter(poi.questID) then
                    report.counts.completed = report.counts.completed + 1
                else
                    row.usable = row.usable + 1
                    report.counts.start = report.counts.start + 1
                end
            else
                report.counts.notStart = report.counts.notStart + 1
            end
        end

        table.insert(report.maps, row)
    end

    report.counts.task    = #Blizzard.GetTaskQuestsOnMap(mapID)
    report.counts.offered = CN.CountKeys(Quests.RecentOffers())

    return report
end

-- How many quests are on offer here that you have not taken.
--
-- This is the number a player means by "new", and it took a fourteen-year-old
-- to say so plainly. The addon used to report how many quests it had written
-- into its own database for the first time -- a scanner statistic, correct and
-- useless, which drops to zero forever once a zone has been walked. He read
-- "0 new" in a zone with exclamation marks visible on his screen and
-- concluded, reasonably, that the addon was broken.
--
-- A number shown to a player has to be about the player's world. If it is
-- about the addon's bookkeeping it belongs in debug output.
function Quests.AvailableCount(mapID)
    return #Quests.AvailableOnMap(mapID)
end

function Quests.DiscoverActive()
    local entries = Blizzard.GetQuestLogEntries()

    if #entries == 0 and not C_QuestLog then
        Print("Quest Log API is unavailable.")
        return 0, 0
    end

    local seen = 0
    local new  = 0

    for _, info in ipairs(entries) do
        if Quests.RecordDiscovered(info.questID, "questlog") then
            new = new + 1
        end

        if info.title and info.title ~= "" then
            Quests.SetMetadata(info.questID, info.title, "questlog")
        end

        seen = seen + 1
    end

    -- Quests offered in this zone but not yet accepted.
    --
    -- Without these, "new" settled at zero permanently after the first scan:
    -- the only thing being discovered was your own quest log, which stops
    -- changing the moment you have scanned it once.
    for _, poi in ipairs(Quests.AvailableOnMap()) do
        if Quests.RecordDiscovered(poi.questID, "available") then
            new = new + 1
        end

        local title = Blizzard.GetQuestTitle(poi.questID, true)

        if title and title ~= "" then
            Quests.SetMetadata(poi.questID, title, "available")
        end

        if poi.x and poi.y then
            Quests.SetLocation(poi.questID, poi.mapID, poi.x, poi.y, "available")
        end

        seen = seen + 1
    end

    return seen, new
end

------------------------------------------------------------
-- STATUS
------------------------------------------------------------

-- ASKED, NOT REMEMBERED.
--
-- This used to write the answer into an account-wide `questStatus` table.
-- Both fields come from a free synchronous client call, so there was nothing
-- to gain by storing them -- and `IsQuestFlaggedCompleted` answers for the
-- character asking, so storing it account-wide meant a main's four thousand
-- completions were read back as every alt's. `/cn breakdown` on a fresh alt
-- reported the main's progress, and scanning on the alt destroyed the main's
-- record.
--
-- Migration 7 drops the store. The name is kept because callers want the pair
-- of answers, and asking through one function keeps the two questions
-- together.
function Quests.RecordStatus(questID)
    return Quests.IsCompletedByCharacter(questID),
        Quests.IsCompletedOnAccount(questID)
end

function Quests.ScanKnown()
    local scanned, byCharacter, onAccount = 0, 0, 0

    for questID in pairs(CN.Account("discoveredQuests")) do
        local characterCompleted, accountCompleted = Quests.RecordStatus(questID)

        scanned = scanned + 1

        if characterCompleted then
            byCharacter = byCharacter + 1
        end

        if accountCompleted then
            onAccount = onAccount + 1
        end
    end

    return scanned, byCharacter, onAccount
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

-- Curated static data first, then whatever external addons know, then
-- anything harvested from this account's own play. Static wins because it is
-- the only source this addon controls and ships.
function Quests.GetRecord(questID)
    local static = CN.Static.GetQuest(questID)

    if static and (static.requires or static.obsolete or static.requiresLevel) then
        return static, "static"
    end

    local external = CN.QueryQuestDataProviders(questID)

    if external and (external.requires or external.requiresLevel) then
        return external, table.concat(external.providers or { "external" }, "+")
    end

    local harvested = CN.Account("questHarvest")[questID]

    if harvested and harvested.requires then
        return harvested, "harvested"
    end

    return static, static and "static" or nil
end

CN.RegisterEligibilityChecker(CN.objectiveTypes.QUEST, function(questID)
    local states = CN.objectiveStates

    if Quests.IsCompletedByCharacter(questID) then
        return states.COMPLETED, "Already completed by this character", nil
    end

    local static = Quests.GetRecord(questID)

    if static then
        if static.obsolete then
            return states.UNOBTAINABLE, CN.blockReasons.OBSOLETE, nil
        end

        if static.requires then
            for _, prerequisiteID in ipairs(static.requires) do
                if not Quests.IsCompletedByCharacter(prerequisiteID) then
                    return states.LOCKED,
                           CN.blockReasons.PREREQUISITE_QUEST,
                           Quests.GetName(prerequisiteID) or ("quest " .. prerequisiteID)
                end
            end
        end



        if static.requiresLevel and UnitLevel("player") < static.requiresLevel then
            return states.LOCKED, CN.blockReasons.LEVEL_TOO_LOW, tostring(static.requiresLevel)
        end

        if static.requiresFaction and CN.character
            and CN.character.faction ~= static.requiresFaction then
            return states.INELIGIBLE, CN.blockReasons.WRONG_FACTION, static.requiresFaction
        end
    end

    -- CURATED GATING (0.43.0).
    --
    -- Class, race, faction and level, from the static database. The client
    -- handles this implicitly by not drawing a pin you do not qualify for,
    -- which works while you are standing there and answers nothing when you
    -- ask "could any of my characters do this?" -- which is precisely what
    -- /cn alts is for.
    local eligible, gateReason = CN.Static.QuestEligibility(questID)

    if not eligible then
        local reason = CN.blockReasons.WRONG_CLASS

        if gateReason:find("^race") then
            reason = CN.blockReasons.WRONG_RACE
        elseif gateReason:find("^level") then
            reason = CN.blockReasons.LEVEL_TOO_LOW
        elseif gateReason:find("Alliance") or gateReason:find("Horde") then
            reason = CN.blockReasons.WRONG_FACTION
        end

        return states.INELIGIBLE, reason, gateReason
    end

    -- Prerequisites nobody curated, inferred from repeated observation
    -- across characters.
    --
    -- Reported as LIKELY_PREREQUISITE, never as PREREQUISITE_QUEST. The
    -- addon has watched an ordering hold on several characters; that is
    -- strong evidence and it is still not the same claim as knowing. It
    -- must not be possible to mistake one for the other in the output.
    local dependency = CN.GetDependency(
        CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID))

    if dependency and dependency.observedRequires then
        local harvest = CN:GetModule("Harvest")

        for _, prerequisiteID in ipairs(dependency.observedRequires) do
            if not Quests.IsCompletedByCharacter(prerequisiteID) then
                local name = Quests.GetName(prerequisiteID)
                    or ("quest " .. prerequisiteID)

                -- WHERE THE EDGE CAME FROM DECIDES WHAT THE LINE CAN CLAIM.
                --
                -- An imported chain was never observed by this player, so
                -- the harvest store has nothing for it and the character
                -- count came back zero -- "seen first on 0 characters",
                -- printed as evidence. Say which kind of edge it is.
                if dependency.origin == "contributed" then
                    return states.LOCKED,
                           CN.blockReasons.LIKELY_PREREQUISITE,
                           name .. " (from an imported chain, not from your "
                               .. "own play)"
                end

                local characters = harvest
                    and harvest.Confidence(harvest.Store()[questID], prerequisiteID)
                    or 0

                return states.LOCKED,
                       CN.blockReasons.LIKELY_PREREQUISITE,
                       name .. " (seen first on " .. characters
                           .. " characters)"
            end
        end
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- LOCATION
------------------------------------------------------------

-- Coordinates the player supplied by hand, for quests the client will not
-- answer for. Persisted account-wide: a location is a fact about the world,
-- not about one character.
local function Overrides()
    return CN.Account("questLocations")
end

Quests.Overrides = Overrides

-- `source` says where the coordinates came from: nil or "manual" for a
-- player typing them, "offered" for a quest giver's gossip, "available" for a
-- map pin. Two callers have always passed it and this function has always
-- ignored it -- the parameter was not even declared -- so `/cn where`
-- attributed machine-learned coordinates to the player, and the block comment
-- above describing this store as "coordinates the player supplied by hand"
-- was false in both directions.
function Quests.SetLocation(questID, mapID, x, y, source)
    if not questID or not mapID or not x or not y then
        return false
    end

    -- Accept either 0-1 or 0-100; the map API wants 0-1.
    if x > 1 then x = x / 100 end
    if y > 1 then y = y / 100 end

    if x <= 0 or x >= 1 or y <= 0 or y >= 1 then
        return false
    end

    Overrides()[questID] = {
        mapID  = mapID,
        x      = x,
        y      = y,
        setAt  = time(),
        source = source,
    }

    return true
end

-- Live client data first, then the player's own override, then curated
-- static data. Live wins because it tracks the quest's *current* step.
function Quests.GetLocation(questID)
    local mapID, x, y = Blizzard.GetQuestWaypoint(questID)

    -- A CURATED TURN-IN BEATS THE CLIENT'S MOVING WAYPOINT.
    --
    -- `Static.GetQuestTurnIn` has existed since the three-phase quest model
    -- was designed -- "a quest is a pick up, a do, and a turn in" -- with a
    -- documented schema, and was called by nothing at all: the harness's dead
    -- code check listed it by name. So the third phase, the one the design
    -- rests on, has always used the client's waypoint, which points at
    -- whatever the quest currently wants rather than at the person who takes
    -- it back.
    --
    -- Only when the quest is actually ready to hand in. Before that the
    -- client's waypoint is the better answer, because it moves with the work.
    if CN.Static and CN.Static.GetQuestTurnIn
        and Blizzard.IsQuestReadyForTurnIn
        and Blizzard.IsQuestReadyForTurnIn(questID) then

        local turnMap, turnX, turnY = CN.Static.GetQuestTurnIn(questID)

        if turnMap and turnX and turnY then
            return turnMap, turnX, turnY, "turn-in"
        end
    end

    if mapID and x and y then
        return mapID, x, y, "blizzard"
    end

    local override = Overrides()[questID]

    if override and override.mapID and override.x and override.y then
        return override.mapID, override.x, override.y, override.source or "manual"
    end

    local staticMap, staticX, staticY = CN.Static.GetQuestLocation(questID)

    if staticMap and staticX and staticY then
        return staticMap, staticX, staticY, "static"
    end

    return mapID or staticMap, nil, nil, nil
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Quests", function()
    local candidates = {}

    -- The coordinates are no longer needed here: travel cost is asked for
    -- by map and point, and CN.TravelCost reads the player's position itself
    -- so that every provider costs a journey the same way.
    local playerMap = CN.GetPlayerPosition()

    local seen = {}

    local function add(questID, name, isActive, availablePOI)
        if not questID or seen[questID] then
            return
        end

        if CN.IsIgnored(CN.objectiveTypes.QUEST, questID)
            or CN.IsDeferred(CN.objectiveTypes.QUEST, questID) then
            return
        end

        seen[questID] = true

        local mapID, x, y, source = Quests.GetLocation(questID)

        local reasons = {}
        local value   = 1
        local travel  = 0

        -- An available quest carries its own pin, which is more current than
        -- anything recorded earlier.
        if availablePOI then
            mapID  = availablePOI.mapID or mapID
            x      = availablePOI.x or x
            y      = availablePOI.y or y
            source = "available"

            -- Weighted above an accepted quest you have not started: going to
            -- get a quest is cheap, it is right here, and it unlocks
            -- everything that quest leads to.
            value = value + 2

            table.insert(reasons, "available to pick up in this zone")

            if availablePOI.isDaily then
                table.insert(reasons, "daily")
            end
        end

        -- A DEADLINE THE ADDON ALREADY KNEW AND WAS NOT ATTACHING.
        --
        -- 0.28.0 added an urgency curve that weights anything carrying
        -- `expiresIn`, and then only world quests and the Vault set it. A
        -- daily disappears at the daily reset and a weekly at the weekly one;
        -- both are knowable to the minute, and neither was being said. The
        -- headline feature of that release was close to inert.
        local expiry

        if availablePOI and availablePOI.isDaily then
            expiry = Blizzard.GetSecondsUntilDailyReset()
        elseif isActive and Blizzard.IsQuestInLog(questID) then
            local timeLeft = Blizzard.GetQuestTimeLeft(questID)

            if timeLeft and timeLeft > 0 then
                expiry = timeLeft
            end
        end

        if isActive then
            if Blizzard.IsQuestReadyForTurnIn(questID) then
                value = value + 3
                table.insert(reasons, "ready to turn in")
            else
                local done, total = Blizzard.GetQuestObjectiveProgress(questID)

                if total > 0 and done > 0 then
                    value = value + 1
                    table.insert(reasons, done .. " of " .. total .. " objectives already done")
                end
            end
        end

        local static = CN.Static.GetQuest(questID)

        if static and static.unlocks and #static.unlocks > 0 then
            value = value + #static.unlocks
            table.insert(reasons, "unlocks " .. #static.unlocks .. " further quest(s)")
        end

        if mapID and playerMap then
            if mapID == playerMap then
                table.insert(reasons, "in your current zone")
            end

            -- COSTED AS THE JOURNEY YOU WOULD ACTUALLY MAKE.
            --
            -- Before 0.42.0 this was a straight line within the zone and a
            -- flat 25 for anywhere else -- so the zone over the ridge and the
            -- far side of the continent cost exactly the same, and a zone
            -- with a flight master in it cost the same as one without.
            local measured, fromTravel = CN.TravelCost(mapID, x, y)

            travel = measured or travel

            if fromTravel and mapID ~= playerMap then
                table.insert(reasons, "another zone, costed by how long the "
                    .. "journey actually takes")
            end
        elseif not mapID then
            -- Unknown location: usable as a suggestion, useless for routing.
            travel = 5
        end

        table.insert(candidates, CN.NewObjective({
            id                = questID,
            type              = CN.objectiveTypes.QUEST,
            name              = name or Quests.GetName(questID) or ("Quest " .. questID),
            mapID             = mapID,
            x                 = x,
            y                 = y,
            source            = source,
            phase             = Quests.Phase(questID),
            state             = CN.objectiveStates.AVAILABLE,
            completionValue   = value,
            travelCost        = travel,
            expiresIn         = expiry,
            reasons           = reasons,
        }))
    end

    for _, info in ipairs(Blizzard.GetQuestLogEntries()) do
        add(info.questID, info.title, true)
    end

    -- Quests standing in this zone waiting to be picked up.
    --
    -- This is the fix for the most basic possible complaint: the addon showed
    -- only quests you had already accepted, so it could never tell you to go
    -- and get one. Picking up a quest twenty yards away is often the single
    -- best next action available, and it was invisible.
    for _, poi in ipairs(Quests.AvailableOnMap(playerMap)) do
        local name = Quests.GetName(poi.questID)
            or Blizzard.GetQuestTitle(poi.questID, true)
            or ("Quest " .. poi.questID)

        add(poi.questID, name, false, poi)
    end

    -- Curated quests that are not in the log and not yet completed.
    for questID, record in pairs(CN.Static.quests) do
        if not record.obsolete and not Quests.IsCompletedByCharacter(questID) then
            local state = CN.Explain(CN.objectiveTypes.QUEST, questID)

            if state == CN.objectiveStates.AVAILABLE then
                add(questID, record.name, false)
            end
        end
    end

    return candidates
end, { events = { "QUEST_ACCEPTED", "QUEST_TURNED_IN", "QUEST_REMOVED", "QUEST_LOG_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 2 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_DATA_LOAD_RESULT", function(event, questID, success)
    if not CN.pendingQuestLoads[questID] then
        return
    end

    CN.pendingQuestLoads[questID] = nil

    if not success then
        DebugPrint("Quest " .. tostring(questID) .. " metadata was unavailable from Blizzard.")
        return
    end

    local title = Blizzard.GetQuestTitle(questID, false)

    if title then
        Quests.SetMetadata(questID, title, "blizzard")
        Print("Quest " .. questID .. " - " .. title)
    else
        DebugPrint("Quest " .. questID .. " loaded, but no title was returned.")
    end
end)

CN:RegisterEvent("QUEST_ACCEPTED", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordDiscovered(questID, "questlog")

    local title = Blizzard.GetQuestTitle(questID, true)

    if title then
        Quests.SetMetadata(questID, title, "questlog")
    end

    Quests.RecordStatus(questID)

    DebugPrint("Quest accepted: " .. questID)
end)

CN:RegisterEvent("QUEST_TURNED_IN", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordDiscovered(questID, "questlog")
    Quests.RecordStatus(questID)

    DebugPrint("Quest turned in: " .. questID)
end)

CN:RegisterEvent("QUEST_REMOVED", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordStatus(questID)

    DebugPrint("Quest removed from log: " .. questID)
end)

-- QUEST_LOG_UPDATE fires constantly; throttle a full rescan.
local lastLogScan = 0

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    local now = time()

    if now - lastLogScan < 10 then
        return
    end

    lastLogScan = now

    local seen, new = Quests.DiscoverActive()

    if new > 0 then
        DebugPrint("Quest Log scan discovered " .. new .. " new quests (" .. seen .. " active).")
    end
end)

CN:OnLogin(function()
    local seen, new = Quests.DiscoverActive()

    DebugPrint("Login quest scan: " .. seen .. " active, "
        .. new .. " newly recorded.")
end)

