$Embedded['Modules\Opportunities.lua'] = @'
-- Modules/Opportunities.lua
-- Completion Navigator :: things that expire.
--
-- The scoring formula gives limitedTimeBonus the heaviest weight of any
-- term (3.0), and until this module existed nothing ever set it. The engine
-- was built to prioritise content that disappears and had no idea what
-- disappears.
--
-- That is the whole point of the module: a world quest with two hours left
-- and a permanent quest in the same zone are not equally urgent, and the
-- recommendation should say so.

local ADDON_NAME, CN = ...

local Opportunities = CN:RegisterModule("Opportunities")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local HOUR = 3600
local DAY  = 86400

------------------------------------------------------------
-- URGENCY
------------------------------------------------------------

-- Converts "seconds remaining" into the bonus the scorer multiplies by 3.0.
-- Deliberately steep: something with an hour left should dominate, something
-- with three days left should barely register.
function Opportunities.Urgency(secondsLeft)
    if not secondsLeft or secondsLeft <= 0 then
        return 0
    end

    if secondsLeft <= HOUR then
        return 3
    elseif secondsLeft <= 6 * HOUR then
        return 2
    elseif secondsLeft <= DAY then
        return 1.25
    elseif secondsLeft <= 3 * DAY then
        return 0.5
    end

    return 0.25
end

function Opportunities.FormatTimeLeft(seconds)
    -- "UNKNOWN" AND "EXPIRED" ARE DIFFERENT ANSWERS.
    --
    -- `Blizzard.GetQuestTimeLeft` returns nil when the client will not say,
    -- and this collapsed that into "expired". The sort puts unknowns LAST
    -- using `or math.huge`, so a live world quest appeared at the bottom of a
    -- list headed "soonest to expire", labelled expired -- contradicting
    -- itself on the same screen.
    --
    -- The addon has a convention for exactly this and it is used here now.
    if not seconds then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time left"
    end

    if seconds <= 0 then
        return "expired"
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m left"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h left"
    end

    return math.floor(seconds / DAY) .. "d left"
end

------------------------------------------------------------
-- WORLD QUESTS
------------------------------------------------------------

-- World quests are the largest source of expiring content and the addon
-- could not see a single one before this.
function Opportunities.GetWorldQuests(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local results = {}

    for _, task in ipairs(Blizzard.GetWorldQuestsOnMap(mapID)) do
        local questID = task.questID

        if not Blizzard.IsQuestCompletedByCharacter(questID)
            and not CN.IsIgnored(CN.objectiveTypes.QUEST, questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, questID) then

            local secondsLeft = Blizzard.GetQuestTimeLeft(questID)
            local info        = Blizzard.GetWorldQuestInfo(questID)

            table.insert(results, {
                questID     = questID,
                mapID       = task.mapID,
                x           = task.x,
                y           = task.y,
                name        = info.title or CN.GetQuestName(questID) or ("World quest " .. questID),
                tagName     = info.tagName,
                isElite     = info.isElite,
                secondsLeft = secondsLeft,
            })
        end
    end

    table.sort(results, function(a, b)
        return (a.secondsLeft or math.huge) < (b.secondsLeft or math.huge)
    end)

    return results
end

------------------------------------------------------------
-- RESETS
------------------------------------------------------------

function Opportunities.GetResets()
    return {
        daily  = Blizzard.GetSecondsUntilDailyReset(),
        weekly = Blizzard.GetSecondsUntilWeeklyReset(),
    }
end

------------------------------------------------------------
-- WORLD EVENTS
------------------------------------------------------------

-- Calendar reads are relatively expensive and the answer changes daily, not
-- minute to minute.
local eventCache, eventCachedAt = nil, 0

function Opportunities.GetActiveEvents(force)
    if not force and eventCache and (time() - eventCachedAt) < 1800 then
        return eventCache
    end

    local active = {}

    for _, event in ipairs(Blizzard.GetTodaysEvents()) do
        if event.ongoing then
            table.insert(active, event)
        end
    end

    eventCache    = active
    eventCachedAt = time()

    return active
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Opportunities", function()
    local candidates = {}

    -- Only the map is needed now: travel cost is computed by CN.TravelCost,
    -- which reads the player's position itself so every provider costs a
    -- journey the same way.
    local playerMap = CN.GetPlayerPosition()

    for _, worldQuest in ipairs(Opportunities.GetWorldQuests(playerMap)) do
        local reasons = {}

        local urgency = Opportunities.Urgency(worldQuest.secondsLeft)

        if worldQuest.secondsLeft then
            table.insert(reasons, "world quest, "
                .. Opportunities.FormatTimeLeft(worldQuest.secondsLeft))
        else
            table.insert(reasons, "world quest")
        end

        if worldQuest.tagName then
            table.insert(reasons, worldQuest.tagName)
        end

        -- Costed through the real travel model rather than a straight line
        -- and a flat out-of-zone penalty, the same way quests have been
        -- since 0.42.0. World quests are exactly where this matters: they
        -- are scattered across a continent and they expire.
        local travel = CN.TravelCost(worldQuest.mapID, worldQuest.x, worldQuest.y)

        if worldQuest.mapID == playerMap then
            table.insert(reasons, "in your current zone")
        end

        table.insert(candidates, CN.NewObjective({
            id               = worldQuest.questID,
            type             = CN.objectiveTypes.QUEST,
            name             = worldQuest.name,
            mapID            = worldQuest.mapID,
            x                = worldQuest.x,
            y                = worldQuest.y,
            state            = CN.objectiveStates.AVAILABLE,
            completionValue  = 1,
            limitedTimeBonus = urgency,
            travelCost       = travel,
            expiresIn        = worldQuest.secondsLeft,
            reasons          = reasons,
        }))
    end

    -- ACTIVE EVENTS (0.43.0).
    --
    -- The calendar has been read since 0.20.0 and its answers went into
    -- `/cn events` and nowhere else. A holiday or a Timewalking week is a
    -- deadline in exactly the sense the ranking already understands -- it is
    -- gone on a known date and it is not coming back for a year -- so it
    -- belongs in the list rather than in a separate command.
    for _, event in ipairs(Opportunities.GetActiveEvents()) do
        if not CN.IsIgnored(CN.objectiveTypes.CURRENCY, event.title)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, event.title) then

            local reasons = { "world event, on now" }

            if event.endsIn then
                table.insert(reasons, "ends in "
                    .. Opportunities.FormatTimeLeft(event.endsIn))
            end

            -- Deliberately modest. The addon knows the event is running; it
            -- does not know which of its quests you have done, so claiming
            -- this is your most valuable next action would be a guess.
            table.insert(candidates, CN.NewObjective({
                id               = event.title,
                type             = CN.objectiveTypes.CURRENCY,
                name             = event.title,
                completionValue  = 2,
                limitedTimeBonus = event.endsIn
                    and Opportunities.Urgency(event.endsIn) or 1,
                travelCost       = CN.unknownLocationCost,
                expiresIn        = event.endsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "QUEST_LOG_UPDATE", "ZONE_CHANGED_NEW_AREA" }, volatile = true })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    -- World quest availability changes constantly; nothing to persist, the
    -- candidate provider reads live each time it is asked.
end)

CN:OnLogin(function()
    -- Warm the calendar so the first /cn events call has data.
    Opportunities.GetActiveEvents(true)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "now",
    aliases = { "opportunities" },
    order   = 15,
    help    = "Show everything expiring soon.",
    handler = function()
        local resets = Opportunities.GetResets()

        if resets.daily then
            Print("Daily reset: " .. Opportunities.FormatTimeLeft(resets.daily))
        end

        if resets.weekly then
            Print("Weekly reset: " .. Opportunities.FormatTimeLeft(resets.weekly))
        end

        local events = Opportunities.GetActiveEvents()

        if #events > 0 then
            Print("Active events:")

            for _, event in ipairs(events) do
                Print("  " .. event.title)
            end
        end

        local worldQuests = Opportunities.GetWorldQuests()

        if #worldQuests == 0 then
            Print("No world quests available on your current map.")
            return
        end

        Print("World quests here (" .. #worldQuests .. "), soonest to expire:")

        for index = 1, math.min(#worldQuests, 10) do
            local worldQuest = worldQuests[index]

            Print("  " .. index .. ". " .. worldQuest.name
                .. " |cff999999(" .. Opportunities.FormatTimeLeft(worldQuest.secondsLeft)
                .. (worldQuest.tagName and (", " .. worldQuest.tagName) or "") .. ")|r")
        end

        if #worldQuests > 10 then
            Print("  |cff999999... and " .. (#worldQuests - 10) .. " more.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "events",
    order   = 16,
    help    = "List world events active today.",
    handler = function()
        local events = Opportunities.GetActiveEvents(true)

        if #events == 0 then
            Print("No world events detected as active today.")
            Print("|cff999999The calendar may not have loaded yet; open it once and retry.|r")
            return
        end

        for _, event in ipairs(events) do
            Print("  " .. event.title
                .. " |cff999999(" .. tostring(event.sequenceType) .. ")|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Warband.lua'] = @'
-- Modules/Warband.lua
-- Completion Navigator :: which character should do this.
--
-- The per-character data already exists: reputations, titles, professions
-- and recipes are stored on the character that owns them. What was missing
-- is anything that reads across all of them and answers the question the
-- whole design was built around.
--
-- This module also feeds `characterSuitability`, the second scoring term
-- that was weighted in the formula but never set by anything. An objective
-- your current character is poorly suited to should rank below one they can
-- act on now, and the reason should say why.

local ADDON_NAME, CN = ...

local Warband = CN:RegisterModule("Warband")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- ROSTER
------------------------------------------------------------

function Warband.Roster()
    local rows = {}

    for key, character in CN.Characters() do
        table.insert(rows, {
            key      = key,
            name     = character.name,
            realm    = character.realm,
            class    = character.class,
            race     = character.race,
            level    = character.level,
            faction  = character.faction,
            spec     = character.specName,
            lastSeen = character.lastSeen,
            isCurrent = (key == CN.characterKey),

            professions  = CN.CountKeys(character.professions),
            recipes      = CN.CountKeys(character.recipes),
            titles       = CN.CountKeys(character.titles),
            reputations  = CN.CountKeys(character.reputations),
        })
    end

    table.sort(rows, function(a, b)
        if (a.level or 0) ~= (b.level or 0) then
            return (a.level or 0) > (b.level or 0)
        end

        return (a.key or "") < (b.key or "")
    end)

    return rows
end

------------------------------------------------------------
-- WHO SHOULD DO THIS
------------------------------------------------------------

-- Answers for any objective type that has per-character state. Returns
-- bestKey, detail, scope -- where scope explains why the answer is what it
-- is, including "account-wide" meaning the question does not apply.
function Warband.WhoShould(objectiveType, id)
    local types = CN.objectiveTypes

    if objectiveType == types.REPUTATION then
        local module = CN:GetModule("Reputations")

        if not module then
            return nil, nil, "no reputation data"
        end

        local bestKey, bestRecord, accountWide = module.BestCharacterFor(id)

        if accountWide then
            return nil, nil, "account-wide"
        end

        if bestKey then
            return bestKey, tostring(bestRecord and bestRecord.standing), "highest standing"
        end

        return nil, nil, "no character has this faction recorded"
    end

    if objectiveType == types.RECIPE then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local holders = module.WhoKnows(id)

        if #holders > 0 then
            return holders[1], table.concat(holders, ", "), "already knows it"
        end

        return nil, nil, "no character knows this recipe"
    end

    if objectiveType == types.TITLE then
        local module = CN:GetModule("Titles")

        if not module then
            return nil, nil, "no title data"
        end

        local holders = module.WhoHas(id)

        if #holders > 0 then
            return holders[1], table.concat(holders, ", "), "already earned it"
        end

        return nil, nil, "no character has this title"
    end

    if objectiveType == types.PROFESSION then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local bestKey, bestRecord = module.BestCharacterFor(id)

        if bestKey then
            return bestKey,
                   tostring(bestRecord and bestRecord.rank) .. " skill",
                   "highest skill"
        end

        return nil, nil, "no character has this profession"
    end

    if objectiveType == types.PET or objectiveType == types.MOUNT
        or objectiveType == types.TOY or objectiveType == types.ACHIEVEMENT
        or objectiveType == types.APPEARANCE then
        return nil, nil, "account-wide"
    end

    return nil, nil, "not tracked per character"
end

------------------------------------------------------------
-- SUITABILITY
------------------------------------------------------------

-- Positive when the logged-in character is the right one, negative when
-- somebody else is. Fed into the scoring formula so recommendations stop
-- pointing at work this character cannot usefully do.
function Warband.Suitability(objectiveType, id)
    local bestKey, detail, scope = Warband.WhoShould(objectiveType, id)

    if scope == "account-wide" or not bestKey then
        return 0, nil
    end

    if bestKey == CN.characterKey then
        return 1, "you are the best character for this"
    end

    return -2, bestKey .. " is better suited (" .. tostring(detail) .. ")"
end

-- Applied to every candidate before scoring, so no module has to remember
-- to do it.
function Warband.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    if objective.accountWide then
        return objective
    end

    local suitability, reason = Warband.Suitability(objective.type, objective.id)

    if suitability ~= 0 then
        objective.characterSuitability = suitability

        if reason then
            objective.reasons = objective.reasons or {}
            table.insert(objective.reasons, reason)
        end
    end

    return objective
end

CN.RegisterCandidateDecorator("Warband", Warband.Decorate)

------------------------------------------------------------
-- COVERAGE
------------------------------------------------------------

-- What the Warband collectively has, versus what any one character has.
-- This is the number that matters for account completion; a single
-- character's totals understate it.
function Warband.Coverage()
    local professions, recipes, titles = {}, {}, {}

    local characters = 0

    for _, character in CN.Characters() do
        characters = characters + 1

        for skillLineID in pairs(character.professions or {}) do
            professions[skillLineID] = true
        end

        for recipeID in pairs(character.recipes or {}) do
            recipes[recipeID] = true
        end

        for titleID in pairs(character.titles or {}) do
            titles[titleID] = true
        end
    end

    return {
        characters  = characters,
        professions = CN.CountKeys(professions),
        recipes     = CN.CountKeys(recipes),
        titles      = CN.CountKeys(titles),
    }
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "warband",
    aliases = { "roster" },
    order   = 17,
    help    = "Show every known character and what they cover.",
    handler = function()
        local rows = Warband.Roster()

        if #rows == 0 then
            Print("No characters recorded yet.")
            return
        end

        Print("Warband (" .. #rows .. " character"
            .. (#rows == 1 and "" or "s") .. "):")

        for _, row in ipairs(rows) do
            local marker = row.isCurrent and "|cff00ff00>|r " or "  "

            Print(marker .. row.key
                .. " |cff999999" .. tostring(row.level) .. " "
                .. tostring(row.class or "?")
                .. (row.faction and (" " .. row.faction) or "") .. "|r")

            Print("      professions " .. row.professions
                .. ", recipes " .. row.recipes
                .. ", titles " .. row.titles
                .. ", reputations " .. row.reputations)
        end

        local coverage = Warband.Coverage()

        -- THE CAVEAT BELONGS ON THE NUMBER, NOT ONLY ON THE ONE-CHARACTER
        -- CASE.
        --
        -- `CN.Characters()` holds the characters that have logged in with
        -- this addon installed, which for most people is a fraction of the
        -- account. With three of ten alts seen the figure was printed as
        -- plain fact and only the `#rows == 1` case was hedged.
        Print("Combined coverage across the " .. #rows .. " character"
            .. (#rows == 1 and "" or "s") .. " this addon has seen: "
            .. coverage.professions .. " professions, "
            .. coverage.recipes .. " recipes, " .. coverage.titles .. " titles.")

        if #rows == 1 then
            Print("|cffffff00Only one character has been seen. Log in on your alts "
                .. "with the addon loaded to make these comparisons useful.|r")
        else
            Print("|cff999999An alt that has never logged in with the addon "
                .. "loaded is not in this total.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "who",
    args    = "<type> <id>",
    order   = 18,
    help    = "Which character should do something. Types: rep, recipe, title, profession.",
    handler = function(args)
        local kind, value = args:match("^(%S+)%s+(.+)$")

        if not kind or not value then
            -- NAMES RESOLVE FOR TWO OF THE FOUR, AND THE USAGE LINE SAID
            -- FOUR. `RECIPE` and `PROFESSION` have no resolver, so a name
            -- there fell through to "Could not resolve" -- which reads as
            -- "that recipe does not exist" rather than "give me the id".
            Print("Usage: /cn who <rep|title> <id or name>")
            Print("|cff999999       /cn who <recipe|profession> <id>|r")
            Print("|cff999999Recipes and professions are looked up by id "
                .. "only; |cffffff00/cn recipes|r|cff999999 lists yours.|r")
            return
        end

        kind = string.lower(kind)

        local types = CN.objectiveTypes

        local map = {
            rep        = types.REPUTATION,
            reputation = types.REPUTATION,
            recipe     = types.RECIPE,
            title      = types.TITLE,
            profession = types.PROFESSION,
            prof       = types.PROFESSION,
        }

        local objectiveType = map[kind]

        if not objectiveType then
            Print("Unknown type: " .. kind)
            Print("Use one of: rep, recipe, title, profession")
            return
        end

        -- Resolve names to IDs through the owning module where possible.
        local id = CN.ToID(value)

        if not id then
            if objectiveType == types.REPUTATION then
                local module = CN:GetModule("Reputations")
                id = module and module.Resolve(value)
            elseif objectiveType == types.TITLE then
                local module = CN:GetModule("Titles")
                id = module and module.Resolve(value)
            end
        end

        if not id then
            if objectiveType == types.RECIPE
                or objectiveType == types.PROFESSION then

                Print("Recipes and professions are looked up by id, not by "
                    .. "name: " .. value)
                Print("|cff999999|cffffff00/cn recipes|r|cff999999 lists the "
                    .. "ones this addon knows about, with their ids.|r")
            else
                Print("Could not resolve: " .. value)
            end

            return
        end

        local bestKey, detail, scope = Warband.WhoShould(objectiveType, id)

        if scope == "account-wide" then
            Print("That is account-wide; any character counts.")
            return
        end

        if not bestKey then
            Print(tostring(scope) .. ".")
            return
        end

        if bestKey == CN.characterKey then
            Print("This character is the best one for it (" .. tostring(detail) .. ").")
        else
            Print("Best character: " .. bestKey .. " |cff999999(" .. tostring(detail) .. ")|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Rares.lua'] = @'
-- Modules/Rares.lua
-- Completion Navigator :: rares and treasures.
--
-- Most rare-tracking addons ship a static database of where rares spawn.
-- That answers "where is it", which is only half the question, and it goes
-- stale every patch.
--
-- This module leads with the client's vignette data instead, because a
-- vignette is the one live signal that a rare is *up right now*. Something
-- that exists this minute and may be dead in five is exactly the kind of
-- objective the opportunity scoring was built for.
--
-- Everything seen is also recorded permanently, so the addon accumulates its
-- own spawn database from play -- same approach as quest harvesting, and it
-- never goes stale because it comes from the live game.

local ADDON_NAME, CN = ...

local Rares = CN:RegisterModule("Rares")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

-- Everything ever seen, keyed by vignetteID. Account-wide: where a rare
-- spawns is a fact about the world.
local function Store()
    return CN.Account("rares")
end

-- Which vignettes this character has already dealt with. Rares are usually
-- once-per-character, so this is character state, not account state.
local function CharacterKills(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.raresKilled = character.raresKilled or {}

    return character.raresKilled
end

Rares.Store          = Store
Rares.CharacterKills = CharacterKills

------------------------------------------------------------
-- LIVE STATE
------------------------------------------------------------

-- Vignettes currently visible, classified and located.
function Rares.GetActive(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    local active = {}

    for _, vignette in ipairs(Blizzard.GetVignettes(mapID)) do
        local kind = Blizzard.ClassifyVignette(vignette.atlas)

        if not vignette.isDead then
            table.insert(active, {
                guid       = vignette.guid,
                vignetteID = vignette.vignetteID,
                name       = vignette.name,
                kind       = kind,
                mapID      = vignette.mapID,
                x          = vignette.x,
                y          = vignette.y,
                inFogOfWar = vignette.inFogOfWar,
            })
        end
    end

    table.sort(active, function(a, b)
        if a.kind ~= b.kind then
            return a.kind < b.kind
        end

        return (a.name or "") < (b.name or "")
    end)

    return active
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

function Rares.Record(vignette)
    if not vignette or not vignette.vignetteID then
        return false
    end

    local store    = Store()
    local existing = store[vignette.vignetteID]

    local record = existing or {
        vignetteID = vignette.vignetteID,
        firstSeen  = time(),
        sightings  = 0,
    }

    record.name      = vignette.name or record.name
    record.kind      = vignette.kind or record.kind
    record.lastSeen  = time()
    record.sightings = (record.sightings or 0) + 1

    -- Keep the first coordinates seen; rares roam, and the spawn point is
    -- more useful than wherever it happened to be standing.
    if vignette.mapID and vignette.x and vignette.y then
        if not record.mapID then
            record.mapID = vignette.mapID
            record.x     = math.floor(vignette.x * 10000 + 0.5) / 10000
            record.y     = math.floor(vignette.y * 10000 + 0.5) / 10000
            record.zone  = Blizzard.GetMapName(vignette.mapID)
        end
    end

    store[vignette.vignetteID] = record

    return existing == nil
end

------------------------------------------------------------
-- KILL TRACKING
------------------------------------------------------------

-- A vignette that was present and is now gone, while the player was nearby,
-- is very likely dealt with. This is inference, so it is recorded as
-- "cleared by this character" rather than presented as fact.
local lastSeenGuids = {}

-- HOW CLOSE YOU HAVE TO HAVE BEEN FOR "IT VANISHED" TO MEAN "IT DIED".
--
-- `GetVignettes` returns what is IN RANGE, and a vignette leaves that list
-- for two completely different reasons: somebody killed it, or you rode away
-- from it. The old code could not tell them apart and assumed the first, so
-- riding past a rare marked it cleared -- permanently, with no expiry and no
-- command to undo it. The addon then refused to ever offer that rare to that
-- character again, which is the worst possible failure for a module whose job
-- is to say a rare is up.
--
-- A vignette that goes out of range does so at the edge of the range. One
-- that dies does so wherever it was standing, which for a player who killed
-- it is close. This is still inference, but it is inference that distinguishes
-- the two cases instead of collapsing them.
Rares.clearedWithinYards = 150

-- AND THE INFERENCE EXPIRES.
--
-- Some rares are once per character and some are daily or weekly, and the
-- client does not say which. Remembering forever is right for the first group
-- and permanently wrong for the second; remembering until the weekly reset is
-- approximately right for both, and self-corrects either way.
Rares.rememberSeconds = 7 * 24 * 60 * 60

local function ClearedUntil()
    local seconds = Blizzard.GetSecondsUntilWeeklyReset
        and Blizzard.GetSecondsUntilWeeklyReset()

    if type(seconds) == "number" and seconds > 0 then
        return time() + seconds
    end

    return time() + Rares.rememberSeconds
end

-- Recorded when the client itself says the vignette is dead, which needs no
-- inference at all, and when one vanishes from close range.
function Rares.NoteCleared(vignetteID, name)
    local kills = CharacterKills()

    if not kills or not vignetteID then
        return false
    end

    kills[vignetteID] = ClearedUntil()

    DebugPrint("Marking cleared: " .. tostring(name or vignetteID))

    return true
end

-- The sighting set, so a test can put the module in the state a real
-- VIGNETTE_MINIMAP_UPDATED would have left it in and then drive the real
-- comparison. Writing to `lastSeenGuids` from outside is the alternative, and
-- a test that reaches around the module proves nothing about the module.
function Rares.SetLastSeen(seen)
    lastSeenGuids = seen or {}
end

function Rares.NoteDisappearances(currentGuids)
    local kills = CharacterKills()

    if not kills then
        return
    end

    for guid, entry in pairs(lastSeenGuids) do
        if not currentGuids[guid] and entry.vignetteID then
            if entry.wasDead then
                Rares.NoteCleared(entry.vignetteID, entry.name)
            elseif entry.yards and entry.yards <= Rares.clearedWithinYards then
                Rares.NoteCleared(entry.vignetteID, entry.name)
            else
                DebugPrint("Vignette out of range, not marking cleared: "
                    .. tostring(entry.name))
            end
        end
    end
end

function Rares.IsClearedByCharacter(vignetteID)
    local kills = CharacterKills()

    if not kills then
        return false
    end

    local entry = kills[vignetteID]

    if entry == nil then
        return false
    end

    -- MIGRATED IN PLACE. Entries written before 0.53.0 hold the time the
    -- vignette vanished rather than the time the memory expires, and most of
    -- them are the false positives described above. Treating a bare timestamp
    -- as "expires one week after it was written" retires them without a
    -- migration step and without discarding a genuine recent kill.
    local expires = type(entry) == "number" and entry or 0

    if expires < time() then
        kills[vignetteID] = nil

        return false
    end

    return true
end

-- The player's own escape hatch, because inference that cannot be corrected
-- is just a wrong answer with a longer life.
function Rares.ForgetCleared()
    local kills = CharacterKills()

    if not kills then
        return 0
    end

    local count = CN.CountKeys(kills)

    for key in pairs(kills) do
        kills[key] = nil
    end

    return count
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Rares.Summary()
    local counts = {
        known     = 0,
        rares     = 0,
        treasures = 0,
        located   = 0,
        cleared   = 0,
    }

    local kills = CharacterKills() or {}

    for vignetteID, record in pairs(Store()) do
        counts.known = counts.known + 1

        if record.kind == "TREASURE" then
            counts.treasures = counts.treasures + 1
        else
            counts.rares = counts.rares + 1
        end

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        if kills[vignetteID] then
            counts.cleared = counts.cleared + 1
        end
    end

    return counts
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.RARE, function(vignetteID)
    local states = CN.objectiveStates
    local record = Store()[vignetteID]

    if not record then
        return states.UNKNOWN, "Never seen this rare", nil
    end

    if Rares.IsClearedByCharacter(vignetteID) then
        return states.COMPLETED, "Cleared by this character", record.name
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only what is actually up right now becomes a candidate. A rare that is
-- not spawned is not a next action, and the whole point of using vignettes
-- is knowing the difference.
CN.RegisterCandidateProvider("Rares", function()
    local candidates = {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    for _, vignette in ipairs(Rares.GetActive(playerMap)) do
        local objectiveType = vignette.kind == "TREASURE"
            and CN.objectiveTypes.TREASURE
            or CN.objectiveTypes.RARE

        local id = vignette.vignetteID

        if id
            and not Rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(objectiveType, id)
            and not CN.IsDeferred(objectiveType, id) then

            local reasons = {}
            local travel  = 0

            table.insert(reasons, vignette.kind == "TREASURE"
                and "treasure is up right now"
                or "rare is up right now")

            if vignette.x and vignette.y and playerX and playerY then
                local dx = vignette.x - playerX
                local dy = vignette.y - playerY

                travel = math.sqrt((dx * dx) + (dy * dy)) * 10

                table.insert(reasons, "in your current zone")
            end

            table.insert(candidates, CN.NewObjective({
                id               = id,
                type             = objectiveType,
                name             = vignette.name,
                mapID            = vignette.mapID,
                x                = vignette.x,
                y                = vignette.y,
                accountWide      = false,
                state            = CN.objectiveStates.AVAILABLE,
                completionValue  = 2,

                -- Up now, gone when someone else kills it. That is exactly
                -- what the limited-time term is for.
                limitedTimeBonus = 1.5,

                travelCost       = travel,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED", "ZONE_CHANGED_NEW_AREA" }, volatile = true })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

local function OnVignetteUpdate()
    local mapID = select(1, CN.GetPlayerPosition())

    local currentGuids = {}

    for _, vignette in ipairs(Rares.GetActive(mapID)) do
        currentGuids[vignette.guid] = true

        Rares.Record(vignette)
    end

    Rares.NoteDisappearances(currentGuids)

    -- Rebuild the seen set for the next comparison, carrying the two facts
    -- that let the next comparison tell a kill from a departure: whether the
    -- client had already flagged it dead, and how far away it was.
    local nextSeen = {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    local travel = CN:GetModule("Travel")

    for _, vignette in ipairs(Blizzard.GetVignettes(mapID)) do
        local yards

        if travel and travel.YardsBetween and playerMap and playerX
            and vignette.mapID and vignette.x then

            yards = travel.YardsBetween(playerMap, playerX, playerY,
                vignette.mapID, vignette.x, vignette.y)
        end

        nextSeen[vignette.guid] = {
            vignetteID = vignette.vignetteID,
            name       = vignette.name,
            wasDead    = vignette.isDead and true or false,
            yards      = yards,
        }
    end

    lastSeenGuids = nextSeen
end

CN:RegisterEvent("VIGNETTE_MINIMAP_UPDATED", OnVignetteUpdate)
CN:RegisterEvent("VIGNETTES_UPDATED", OnVignetteUpdate)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Vignettes from the previous zone are meaningless now.
    lastSeenGuids = {}
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "rares",
    order   = 74,
    help    = "Show rares and treasures up right now.",
    handler = function()
        local active = Rares.GetActive()

        if #active == 0 then
            Print("Nothing is up nearby.")
            Print("|cff999999Vignettes only appear for content in range; "
                .. "move around the zone.|r")
            return
        end

        Print("Up right now (" .. #active .. "):")

        for index, vignette in ipairs(active) do
            local cleared = vignette.vignetteID
                and Rares.IsClearedByCharacter(vignette.vignetteID)

            Print("  " .. index .. ". " .. tostring(vignette.name)
                .. " |cff999999[" .. tostring(vignette.kind) .. "]|r"
                .. (cleared and " |cff999999(already cleared)|r" or "")
                .. (vignette.x and string.format(" |cff999999%.1f, %.1f|r",
                    vignette.x * 100, vignette.y * 100) or ""))
        end

        Print("|cffffff00/cn rare <number>|r to set a waypoint.")
        Print("|cff999999\"already cleared\" is inferred from a vignette that "
            .. "vanished while you were next to it, and it expires at the "
            .. "weekly reset. /cn rareforget clears it now.|r")
    end,
}

CN:RegisterCommand{
    name    = "rareforget",
    order   = 77,
    help    = "Forget which rares this character is assumed to have cleared.",
    handler = function()
        local count = Rares.ForgetCleared()

        if count == 0 then
            Print("Nothing was being treated as cleared on this character.")
            return
        end

        Print(count .. " cleared for this character, forgotten. They will be "
            .. "offered again.")

        CN.InvalidateCandidates()
    end,
}

CN:RegisterCommand{
    name    = "rare",
    args    = "<number>",
    order   = 75,
    help    = "Navigate to something that is up right now.",
    handler = function(args)
        local index = CN.ToID(args)

        if not index then
            Print("Usage: /cn rare <number from /cn rares>")
            return
        end

        local active = Rares.GetActive()
        local vignette = active[index]

        if not vignette then
            Print("There is no number " .. index .. " in the current list.")
            return
        end

        CN.NavigateToObjective({
            id    = vignette.vignetteID,
            type  = vignette.kind == "TREASURE"
                and CN.objectiveTypes.TREASURE
                or CN.objectiveTypes.RARE,
            name  = vignette.name,
            mapID = vignette.mapID,
            x     = vignette.x,
            y     = vignette.y,
        })
    end,
}

CN:RegisterCommand{
    name    = "raredb",
    order   = 76,
    help    = "Summarize every rare and treasure recorded from play.",
    handler = function()
        local counts = Rares.Summary()

        if counts.known == 0 then
            Print("Nothing recorded yet. Rares and treasures are captured "
                .. "automatically as you encounter them.")
            return
        end

        Print("Recorded: " .. counts.known
            .. " (" .. counts.rares .. " rares, " .. counts.treasures .. " treasures)")
        Print("With coordinates: " .. counts.located)
        Print("Cleared by this character: " .. counts.cleared)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Currencies.lua'] = @'
-- Modules/Currencies.lua
-- Completion Navigator :: currencies, caps, and wasted earning potential.
--
-- A currency total on its own is not a decision. What matters is whether you
-- are at a cap, because a capped currency is earning potential you are
-- throwing away, and a weekly cap you have not filled resets in a few days
-- whether you use it or not.
--
-- Both of those are time-sensitive, which is why this module contributes to
-- the opportunity side of the scoring rather than sitting in a list.

local ADDON_NAME, CN = ...

local Currencies = CN:RegisterModule("Currencies")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- Currency quantities are character state; which currencies exist is not.
local function NameStore()
    return CN.Account("currencyNames")
end

local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.currencies = character.currencies or {}

    return character.currencies
end

Currencies.NameStore      = NameStore
Currencies.CharacterStore = CharacterStore

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Currencies.Scan()
    local names = NameStore()
    local mine  = CharacterStore()

    if not mine then
        return 0, 0, 0
    end

    local seen, atCap, weeklyRemaining = 0, 0, 0

    for _, currency in ipairs(Blizzard.GetCurrencyList()) do
        if currency.currencyID then
            names[currency.currencyID] = currency.name

            local capped = currency.maxQuantity > 0
                and currency.quantity >= currency.maxQuantity

            local weeklyLeft = 0

            if currency.maxWeeklyQuantity > 0 then
                weeklyLeft = math.max(0,
                    currency.maxWeeklyQuantity - currency.earnedThisWeek)
            end

            mine[currency.currencyID] = {
                currencyID        = currency.currencyID,
                quantity          = currency.quantity,
                maxQuantity       = currency.maxQuantity,
                totalEarned       = currency.totalEarned,
                earnedThisWeek    = currency.earnedThisWeek,
                maxWeeklyQuantity = currency.maxWeeklyQuantity,
                capped            = capped,
                accountWide       = currency.accountWide or nil,
                weeklyRemaining   = weeklyLeft,
                lastSeen          = time(),
            }

            seen = seen + 1

            if capped then
                atCap = atCap + 1
            end

            if weeklyLeft > 0 then
                weeklyRemaining = weeklyRemaining + 1
            end
        end
    end

    CN.MarkScanned("currencies")

    return seen, atCap, weeklyRemaining
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Currencies.Capped(character)
    local capped = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.capped then
            table.insert(capped, {
                currencyID = currencyID,
                name       = NameStore()[currencyID],
                quantity   = record.quantity,
                maximum    = record.maxQuantity,

                -- CARRIED THROUGH, WHICH IT WAS NOT.
                --
                -- The candidate provider reads `accountWide` off these rows
                -- under a long comment explaining that ignoring the flag was
                -- "the exact mistake the Warband work exists to prevent" --
                -- and this function, the only thing that builds those rows,
                -- never copied it. The flag was read from the client
                -- correctly, stored correctly, and dropped here. So a
                -- Warband currency capped on your main was still recommended
                -- on every alt, which is precisely the behaviour 0.43.0
                -- claimed to have fixed.
                accountWide = record.accountWide and true or false,
            })
        end
    end

    table.sort(capped, function(a, b) return (a.name or "") < (b.name or "") end)

    return capped
end

function Currencies.WeeklyUnfilled(character)
    local rows = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.weeklyRemaining and record.weeklyRemaining > 0 then
            table.insert(rows, {
                currencyID = currencyID,
                name       = NameStore()[currencyID],
                remaining  = record.weeklyRemaining,
                earned     = record.earnedThisWeek,
                maximum    = record.maxWeeklyQuantity,
            })
        end
    end

    table.sort(rows, function(a, b) return (a.remaining or 0) > (b.remaining or 0) end)

    return rows
end

function Currencies.Summary(character)
    local store = CharacterStore(character) or {}

    return {
        known           = CN.CountKeys(store),
        capped          = #Currencies.Capped(character),
        weeklyUnfilled  = #Currencies.WeeklyUnfilled(character),
    }
end

function Currencies.Resolve(text)
    local currencyID = CN.ToID(text)

    if currencyID and NameStore()[currencyID] then
        return currencyID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, name in pairs(NameStore()) do
        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A capped currency is not a place to travel to, so these carry no
-- coordinates. They surface as high-priority advisories: stop earning this
-- and go spend it.
CN.RegisterCandidateProvider("Currencies", function()
    local candidates = {}

    for _, currency in ipairs(Currencies.Capped()) do
        if not CN.IsIgnored(CN.objectiveTypes.CURRENCY, currency.currencyID)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, currency.currencyID) then

            -- ACCOUNT-WIDE CURRENCIES ARE ACCOUNT-WIDE (0.43.0).
            --
            -- The client flags these and the addon ignored the flag, so a
            -- Warband currency capped on one character was recommended again
            -- on every other one -- the exact mistake the Warband work exists
            -- to prevent, in the one store that had not been told about it.
            local shared = currency.accountWide

            table.insert(candidates, CN.NewObjective({
                id               = currency.currencyID,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Spend " .. tostring(currency.name)
                    .. (shared and " (Warband)" or ""),
                accountWide      = shared and true or false,
                completionValue  = 2,
                limitedTimeBonus = 1,
                travelCost       = 0,

                -- A capped currency is not "expiring", but every hour spent
                -- at cap is earning thrown away, and the weekly reset is when
                -- that waste is realised. Treating the reset as its deadline
                -- makes the urgency curve say the true thing: this matters
                -- more on Monday night than on Wednesday morning.
                expiresIn        = CN.Blizzard.GetSecondsUntilWeeklyReset(),

                reasons          = {
                    "at cap: " .. tostring(currency.quantity)
                        .. " / " .. tostring(currency.maximum),
                    "further earning is wasted until you spend it",
                },
            }))
        end
    end

    return candidates
end, { events = { "CURRENCY_DISPLAY_UPDATE" }, volatile = true })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

local lastScan = 0

CN:RegisterEvent("CURRENCY_DISPLAY_UPDATE", function()
    local now = time()

    if now - lastScan < 10 then
        return
    end

    lastScan = now

    Currencies.Scan()
end)

CN:OnLogin(function()
    Currencies.Scan()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "currencies",
    aliases = { "currency" },
    order   = 77,
    help    = "Show currency caps and unfilled weekly earning.",
    handler = function()
        local counts = Currencies.Summary()

        if counts.known == 0 then
            Print("No currency data yet. Run /cn currencyscan.")
            return
        end

        Print("Currencies tracked: " .. counts.known)

        local capped = Currencies.Capped()

        if #capped > 0 then
            Print("|cffff4444At cap (" .. #capped .. ") - spend these:|r")

            for _, currency in ipairs(capped) do
                Print("  " .. tostring(currency.name)
                    .. " |cff999999" .. currency.quantity
                    .. " / " .. currency.maximum .. "|r")
            end
        end

        local weekly = Currencies.WeeklyUnfilled()

        if #weekly > 0 then
            Print("Weekly earning still available (" .. #weekly .. "):")

            for index = 1, math.min(#weekly, 8) do
                local currency = weekly[index]

                Print("  " .. tostring(currency.name)
                    .. " |cff999999" .. currency.earned .. " / " .. currency.maximum
                    .. ", " .. currency.remaining .. " left this week|r")
            end
        end

        if #capped == 0 and #weekly == 0 then
            Print("Nothing capped, nothing left to earn this week.")
        end
    end,
}

CN:RegisterCommand{
    name    = "currencyscan",
    order   = 78,
    help    = "Rescan currencies for this character.",
    handler = function()
        local seen, atCap, weekly = Currencies.Scan()

        Print("Scanned " .. seen .. " currencies.")
        Print("At cap: " .. atCap .. "   With weekly earning left: " .. weekly)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Breakdown.lua'] = @'
-- Modules/Breakdown.lua
-- Completion Navigator :: "why isn't this 100%?"
--
-- Every other module answers what it tracks. None of them answer the
-- question a completionist actually asks, which is why a category is not
-- finished and what specifically is in the way.
--
-- Two rules shape this module.
--
-- 1. A percentage is only shown where the denominator is trustworthy. The
--    client knows exactly how many mounts exist; nobody knows how many
--    quests exist. Where the denominator is unknown, counts are shown and
--    the reason is stated, rather than inventing a number that looks
--    authoritative and is not.
--
-- 2. Every line says what to do next, not just what is missing. "4 vendor
--    recipes" is trivia; "4 recipes, open the profession window to see
--    which" is an instruction.

local ADDON_NAME, CN = ...

local Breakdown = CN:RegisterModule("Breakdown")

local Print = CN.Print

-- "1 are locked" reads as a bug even when the number is right.
local function Are(count)
    return count == 1 and "is" or "are"
end

local function Plural(count, singular, plural)
    return count == 1 and singular or (plural or (singular .. "s"))
end

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

-- Each category reports: collected, total (or nil when unknowable),
-- remaining lines, and the next action.
Breakdown.categories = {}

function Breakdown.Register(definition)
    if type(definition) ~= "table" or not definition.name then
        return
    end

    definition.order = definition.order or 100

    table.insert(Breakdown.categories, definition)

    table.sort(Breakdown.categories, function(a, b)
        if a.order == b.order then
            return a.name < b.name
        end

        return a.order < b.order
    end)
end

------------------------------------------------------------
-- REPORT
------------------------------------------------------------

local function Percentage(collected, total)
    if not total or total <= 0 then
        return nil
    end

    return collected / total * 100
end

function Breakdown.Report(categoryName)
    local rows = {}

    for _, category in ipairs(Breakdown.categories) do
        if not categoryName
            or string.lower(category.name) == string.lower(categoryName) then

            local ok, result = pcall(category.report)

            if ok and type(result) == "table" then
                result.name  = category.name
                result.order = category.order

                table.insert(rows, result)
            elseif not ok then
                -- A category that throws was dropped with no trace, so if
                -- every one of them threw the report said "Nothing to report
                -- yet. Run the scans first." -- which sends the player to do
                -- work that will not help.
                local errors = CN:GetModule("Errors")

                if errors and errors.Record then
                    pcall(errors.Record, "breakdown:" .. tostring(category.name),
                        tostring(result))
                end
            end
        end
    end

    return rows
end

------------------------------------------------------------
-- BUILT-IN CATEGORIES
------------------------------------------------------------

Breakdown.Register{
    name  = "Mounts",
    order = 10,
    report = function()
        local module = CN:GetModule("Mounts")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.wrongFaction > 0 then
            table.insert(reasons, counts.wrongFaction .. " " .. Are(counts.wrongFaction)
                .. " locked to the opposite faction")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn mountscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Pets",
    order = 11,
    report = function()
        local module = CN:GetModule("Pets")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.unobtainable > 0 then
            table.insert(reasons, counts.unobtainable .. " " .. Are(counts.unobtainable)
                .. " no longer obtainable and can never be collected")
        end

        if counts.wildMissing > 0 then
            table.insert(reasons, counts.wildMissing .. " " .. Are(counts.wildMissing) .. " "
                .. Plural(counts.wildMissing, "a wild pet", "wild pets")
                .. " you can catch in the world")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn petscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Toys",
    order = 12,
    report = function()
        local module = CN:GetModule("Toys")

        if not module then return nil end

        local counts = module.Summary()

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            action    = counts.known == 0 and "/cn toyscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Appearances",
    order = 13,
    report = function()
        local module = CN:GetModule("Appearances")

        if not module then return nil end

        local counts = module.Summary()
        local rows   = module.Remaining()

        local reasons = {}

        for index = 1, math.min(3, #rows) do
            table.insert(reasons, rows[index].name .. ": "
                .. rows[index].remaining .. " left")
        end

        return {
            collected = counts.collected,
            total     = counts.total,
            remaining = counts.total - counts.collected,
            reasons   = reasons,
            action    = counts.categories == 0 and "/cn appearancescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Achievements",
    order = 14,
    report = function()
        local module = CN:GetModule("Achievements")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.nearlyDone > 0 then
            table.insert(reasons, counts.nearlyDone .. " " .. Are(counts.nearlyDone)
                .. " within two criteria of finishing")
        end

        return {
            collected = counts.completed,
            total     = counts.total,
            remaining = counts.total - counts.completed,
            reasons   = reasons,
            -- SCAN STATE IS NOT THE LIVE TOTAL.
            --
            -- `counts.total` comes from the client, so it is never zero and
            -- this branch could never fire: a player who has never scanned
            -- saw a healthy "1200 / 3400 (35.3%)" with no in-progress rows and
            -- no prompt to scan. The scan is what fills `inProgress`, so that
            -- is what says whether it has run.
            action    = counts.inProgress == 0 and "/cn achievescan"
                or (counts.nearlyDone > 0 and "/cn closest" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Titles",
    order = 15,
    report = function()
        local module = CN:GetModule("Titles")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.onAccount > counts.onThisOne then
            local elsewhere = counts.onAccount - counts.onThisOne

            table.insert(reasons, elsewhere .. " " .. Are(elsewhere)
                .. " held by another character, not this one")
        end

        return {
            collected = counts.onAccount,
            total     = counts.known,
            remaining = counts.known - counts.onAccount,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn titlescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Reputations",
    order = 16,
    report = function()
        local module = CN:GetModule("Reputations")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.paragonPending > 0 then
            table.insert(reasons, counts.paragonPending .. " " .. Plural(counts.paragonPending, "has", "have")
                .. " a Paragon reward waiting to be collected")
        end

        if counts.character > 0 then
            table.insert(reasons, counts.character .. " " .. Are(counts.character)
                .. " character-specific, so an alt may be further ahead")
        end

        -- Total factions in the game is not knowable from the client.
        return {
            collected = counts.exalted + counts.maxedRenown,
            total     = nil,
            remaining = nil,
            unknownTotal = "the client does not expose how many factions exist",
            reasons   = reasons,
            action    = (counts.account + counts.character) == 0
                and "/cn repscan"
                or (counts.paragonPending > 0 and "/cn paragon" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Recipes",
    order = 17,
    report = function()
        local module = CN:GetModule("Professions")

        if not module then return nil end

        local waiting = module.AwaitingRecipeCapture()

        local reasons = {}

        if #waiting > 0 then
            table.insert(reasons, "recipe lists not captured for: "
                .. table.concat(waiting, ", "))
        end

        local known = 0

        for _, record in ipairs(module.Summary()) do
            known = known + (record.recipeKnown or 0)
        end

        return {
            collected    = known,
            total        = nil,
            unknownTotal = "recipes are only countable while a profession window is open",
            reasons      = reasons,
            action       = #waiting > 0 and "open each profession window once" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Quests",
    order = 18,
    report = function()
        local discovered = CN.CountKeys(CN.Account("discoveredQuests"))

        -- ASKED OF THE CLIENT, FOR THIS CHARACTER.
        --
        -- This counted an account-wide `questStatus` store whose
        -- `characterCompleted` flag belonged to whichever character last
        -- scanned, so a fresh alt was shown the main's progress. The client
        -- answers per character, for free, and `discoveredQuests` is the set
        -- worth asking about.
        local quests = CN:GetModule("Quests")

        local completed = 0

        if quests and quests.IsCompletedByCharacter then
            for questID in pairs(CN.Account("discoveredQuests")) do
                if quests.IsCompletedByCharacter(questID) then
                    completed = completed + 1
                end
            end
        end

        return {
            collected    = completed,
            total        = nil,
            unknownTotal = "no API reports how many quests exist; "
                .. "only quests this addon has seen can be counted",
            reasons      = {
                discovered .. " quests discovered so far",
                CN.CountKeys(CN.Account("questHarvest")) .. " harvested with location data",
            },
            action = "/cn harvest",
        }
    end,
}

Breakdown.Register{
    name  = "Currencies",
    order = 19,
    report = function()
        local module = CN:GetModule("Currencies")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.capped > 0 then
            table.insert(reasons, counts.capped .. " " .. Are(counts.capped)
                .. " at cap; further earning is wasted")
        end

        if counts.weeklyUnfilled > 0 then
            table.insert(reasons, counts.weeklyUnfilled .. " still " .. Plural(counts.weeklyUnfilled, "has", "have")
                .. " weekly earning available")
        end

        return {
            collected    = counts.known - counts.capped,
            total        = nil,
            unknownTotal = "currencies are a state to manage, not a set to complete",
            reasons      = reasons,
            action       = counts.capped > 0 and "/cn currencies" or nil,
        }
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintRow(row)
    local percentage = Percentage(row.collected, row.total)

    if percentage then
        Print(string.format("|cffffd100%s|r  %d / %d  (%.1f%%)",
            row.name, row.collected, row.total, percentage))
    else
        Print(string.format("|cffffd100%s|r  %d collected",
            row.name, row.collected or 0))

        if row.unknownTotal then
            Print("    |cff999999no percentage: " .. row.unknownTotal .. "|r")
        end
    end

    for _, reason in ipairs(row.reasons or {}) do
        Print("    " .. reason)
    end

    if row.action then
        Print("    |cffffff00-> " .. row.action .. "|r")
    end
end

CN:RegisterCommand{
    name    = "breakdown",
    aliases = { "remaining" },
    args    = "[category]",
    order   = 19,
    help    = "Explain what is left in each category, and why.",
    handler = function(args)
        local requested = args ~= "" and args or nil

        local rows = Breakdown.Report(requested)

        if #rows == 0 then
            if requested then
                Print("No category matches: " .. requested)

                local names = {}

                for _, category in ipairs(Breakdown.categories) do
                    table.insert(names, category.name)
                end

                Print("Try: " .. table.concat(names, ", "))
            else
                Print("Nothing to report yet. Run the scans first.")
            end

            return
        end

        Print("What is left, and why:")

        for _, row in ipairs(rows) do
            PrintRow(row)
        end

        if not requested then
            Print("|cff999999/cn breakdown <category> for one at a time.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Exploration.lua'] = @'
-- Modules/Exploration.lua
-- Completion Navigator :: map exploration.
--
-- The map API exposes which overlay textures you have revealed but never how
-- many exist, so a genuine "percent explored" cannot be computed from it.
-- The Exploration achievement category does carry one criterion per subzone,
-- which is the only countable exploration data the client offers -- and each
-- unfinished criterion is the literal name of a place you have not been.
--
-- That turns out to be the more useful shape anyway: "Eversong Woods, 3 of
-- 12 subzones, missing Sunsail Anchorage" is actionable. "78% explored" is
-- not.

local ADDON_NAME, CN = ...

local Exploration = CN:RegisterModule("Exploration")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("exploration")
end

Exploration.Store = Store

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Exploration.Scan()
    local store = Store()

    local seen, complete = 0, 0

    for _, achievement in ipairs(Blizzard.GetExplorationAchievements()) do
        store[achievement.achievementID] = {
            achievementID = achievement.achievementID,
            name          = achievement.name,
            completed     = achievement.completed,
            done          = achievement.done,
            criteria      = achievement.criteria,
            lastSeen      = time(),
        }

        seen = seen + 1

        if achievement.completed then
            complete = complete + 1
        end
    end

    CN.MarkScanned("exploration")

    return seen, complete
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Exploration.Summary()
    local counts = {
        zones     = 0,
        complete  = 0,
        criteria  = 0,
        done      = 0,
    }

    for _, record in pairs(Store()) do
        counts.zones    = counts.zones + 1
        counts.criteria = counts.criteria + (record.criteria or 0)
        counts.done     = counts.done + (record.done or 0)

        if record.completed then
            counts.complete = counts.complete + 1
        end
    end

    return counts
end

-- Zones with the fewest subzones left, so the cheapest wins come first.
function Exploration.Closest(limit)
    local rows = {}

    for _, record in pairs(Store()) do
        if not record.completed and (record.criteria or 0) > 0 then
            table.insert(rows, {
                achievementID = record.achievementID,
                name          = record.name,
                done          = record.done,
                criteria      = record.criteria,
                remaining     = record.criteria - record.done,
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.remaining == b.remaining then
            return (a.name or "") < (b.name or "")
        end

        return a.remaining < b.remaining
    end)

    local results = {}

    for index = 1, math.min(limit or 10, #rows) do
        table.insert(results, rows[index])
    end

    return results
end

-- The exploration achievement matching the zone the player is standing in,
-- matched on name because no API maps a UiMapID to its achievement.
function Exploration.ForCurrentZone()
    local zone = GetZoneText and GetZoneText()

    if not zone or zone == "" then
        return nil
    end

    local needle = string.lower(zone)

    for _, record in pairs(Store()) do
        if record.name and string.find(string.lower(record.name), needle, 1, true) then
            return record
        end
    end

    return nil
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only the zone the player is already in. Exploration elsewhere is a
-- project, and the criteria carry no coordinates to route to.
CN.RegisterCandidateProvider("Exploration", function()
    local candidates = {}

    local record = Exploration.ForCurrentZone()

    if record and not record.completed and (record.criteria or 0) > 0 then
        local remaining = record.criteria - record.done

        if remaining > 0
            and not CN.IsIgnored(CN.objectiveTypes.EXPLORATION, record.achievementID)
            and not CN.IsDeferred(CN.objectiveTypes.EXPLORATION, record.achievementID) then

            local reasons = {
                remaining .. " subzone" .. (remaining == 1 and "" or "s")
                    .. " left in this zone",
            }

            local missing = Blizzard.GetIncompleteCriteria(record.achievementID, 3)

            if #missing > 0 then
                table.insert(reasons, "missing: " .. table.concat(missing, ", "))
            end

            table.insert(candidates, CN.NewObjective({
                id              = record.achievementID,
                type            = CN.objectiveTypes.EXPLORATION,
                name            = record.name,
                accountWide     = true,
                completionValue = math.max(1, 4 - remaining),
                travelCost      = 0,
                reasons         = reasons,
            }))
        end
    end

    return candidates
end, { events = { "CRITERIA_UPDATE", "ZONE_CHANGED_NEW_AREA" } })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Discovering a subzone fires criteria updates; the Achievements module
    -- already throttles those, so only refresh the exploration view.
    local record = Exploration.ForCurrentZone()

    if record then
        local done, criteria = Blizzard.GetAchievementProgress(record.achievementID)

        record.done     = done
        record.criteria = criteria
    end
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "explorescan",
    order   = 67,
    help    = "Scan exploration achievements.",
    handler = function()
        local seen, complete = Exploration.Scan()

        Print("Scanned " .. seen .. " exploration achievements.")
        Print("Complete: " .. complete)
    end,
}

CN:RegisterCommand{
    name    = "exploration",
    aliases = { "explore" },
    args    = "[count]",
    order   = 68,
    help    = "Show zones with the least exploration left.",
    handler = function(args)
        local counts = Exploration.Summary()

        if counts.zones == 0 then
            Print("No exploration data yet. Run /cn explorescan.")
            return
        end

        Print("Exploration: " .. counts.complete .. " / " .. counts.zones .. " zones")

        if counts.criteria > 0 then
            -- NO PERCENTAGE. This file's own header says a genuine "percent
            -- explored" is uncomputable and that "78% explored is not
            -- [useful]" -- and then printed one, computed against the sum of
            -- criteria in the achievements this addon happens to have stored.
            -- Not the world; not even every zone, since a zone with no
            -- exploration achievement contributes nothing to either side.
            -- A player reads "73.0%" as the world.
            --
            -- The raw counts are honest and are what remains.
            Print(string.format("Subzones discovered: %d of %d in the "
                .. "exploration achievements this addon has scanned",
                counts.done, counts.criteria))
        end

        local here = Exploration.ForCurrentZone()

        if here then
            if here.completed then
                Print("This zone: |cff00ff00fully explored|r")
            else
                Print("This zone: " .. here.done .. " / " .. here.criteria)

                local missing = Blizzard.GetIncompleteCriteria(here.achievementID, 6)

                for _, name in ipairs(missing) do
                    Print("  missing: " .. name)
                end
            end
        end

        local closest = Exploration.Closest(CN.ToID(args) or 5)

        if #closest > 0 then
            Print("Closest to finishing:")

            for _, row in ipairs(closest) do
                Print("  " .. row.name .. " |cff999999("
                    .. row.done .. "/" .. row.criteria .. ")|r")
            end
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Filters.lua'] = @'
-- Modules/Filters.lua
-- Completion Navigator :: managing what you told the addon to hide.
--
-- Ignore and defer have existed since the first build, and until now there
-- was no way to see either list or undo anything in them. Ignoring something
-- by accident meant it was gone permanently with no recourse, which is a
-- bug wearing a feature's clothes.
--
-- Defer also only offered one hour. The spec asked for a real set of
-- durations, and "until the weekly reset" is the one that actually matches
-- how the game works.

local ADDON_NAME, CN = ...

local Filters = CN:RegisterModule("Filters")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local HOUR = 3600
local DAY  = 86400

------------------------------------------------------------
-- DURATIONS
------------------------------------------------------------

-- Ordered, because they are offered as a list in the UI.
Filters.durations = {
    { key = "hour",    label = "1 hour",        seconds = HOUR },
    { key = "day",     label = "Today",         seconds = DAY },
    { key = "tomorrow",label = "Tomorrow",      seconds = 2 * DAY },
    { key = "week",    label = "This week",     seconds = 7 * DAY },
    { key = "reset",   label = "Until reset",   seconds = nil },  -- computed
    { key = "forever", label = "Until I undo it", seconds = math.huge },
}

------------------------------------------------------------
-- TYPE FILTERING
------------------------------------------------------------

-- Which KINDS of objective the recommendation list may contain.
--
-- Distinct from ignore and defer, which hide one specific objective. This is a
-- standing preference about what you want to be told about at all: someone
-- levelling wants quests, someone finishing a collection does not.
--
-- Only DISABLED types are stored. That way a type added in a later release is
-- enabled by default rather than silently invisible to everyone who upgraded,
-- which is the failure mode of storing an allow-list.
local function HiddenTypes()
    local settings = CN.Settings()

    if not settings then
        return {}
    end

    settings.hiddenTypes = settings.hiddenTypes or {}

    return settings.hiddenTypes
end

Filters.HiddenTypes = HiddenTypes

-- Bumped whenever the filter changes, so the ranked list knows to rebuild
-- without invalidating the providers, which have not changed at all.
CN.typeFilterGeneration = 0

local function Bump()
    CN.typeFilterGeneration = (CN.typeFilterGeneration or 0) + 1
end

function Filters.IsTypeEnabled(objectiveType)
    if not objectiveType then
        return true
    end

    local hidden = HiddenTypes()

    if next(hidden) == nil then
        return true
    end

    return not hidden[objectiveType]
end

function Filters.SetTypeEnabled(objectiveType, enabled)
    if not objectiveType then
        return false
    end

    local hidden = HiddenTypes()

    if enabled then
        hidden[objectiveType] = nil
    else
        hidden[objectiveType] = true
    end

    Bump()

    return true
end

function Filters.ToggleType(objectiveType)
    local enabled = Filters.IsTypeEnabled(objectiveType)

    Filters.SetTypeEnabled(objectiveType, not enabled)

    return not enabled
end

function Filters.EnableAllTypes()
    local hidden = HiddenTypes()

    local count = CN.CountKeys(hidden)

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    Bump()

    return count
end

-- Everything except this one.
function Filters.OnlyType(objectiveType)
    local hidden = HiddenTypes()

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    for _, known in ipairs(Filters.TypeOrder()) do
        if known ~= objectiveType then
            hidden[known] = true
        end
    end

    Bump()

    return true
end

-- The types worth offering, in a stable order. Deliberately not every entry in
-- CN.objectiveTypes: VENDOR and COLLECTIBLE are internal plumbing rather than
-- things anyone would choose to be shown.
function Filters.TypeOrder()
    local types = CN.objectiveTypes

    return {
        types.QUEST,
        types.ACHIEVEMENT,
        types.REPUTATION,
        types.PET,
        types.MOUNT,
        types.TOY,
        types.APPEARANCE,
        types.RECIPE,
        types.PROFESSION,
        types.RARE,
        types.TREASURE,
        types.EXPLORATION,
        types.TITLE,
        types.CURRENCY,
        types.INSTANCE,
    }
end

-- Friendly names live in Objectives.lua now, beside the enum they name, so
-- that everything which prints a type can reach them -- most of the places
-- that do load long before this file. These two are kept as the names the
-- rest of this module already uses.
Filters.typeLabels = CN.typeLabels

Filters.TypeLabel = CN.TypeLabel

-- Accepts what a person would actually type.
function Filters.ResolveType(text)
    if not text or text == "" then
        return nil
    end

    local needle = string.lower(CN.Trim(text))

    for _, objectiveType in ipairs(Filters.TypeOrder()) do
        if string.lower(objectiveType) == needle
            or string.lower(Filters.TypeLabel(objectiveType)) == needle then
            return objectiveType
        end

        -- "quest" should match QUEST, "pet" should match PET.
        if string.lower(Filters.TypeLabel(objectiveType)):find(needle, 1, true) then
            return objectiveType
        end
    end

    return nil
end

function Filters.HiddenTypeCount()
    return CN.CountKeys(HiddenTypes())
end

-- Exposed on CN so the scoring layer can consult it without knowing that a
-- Filters module exists.
function CN.IsObjectiveTypeEnabled(objectiveType)
    return Filters.IsTypeEnabled(objectiveType)
end

------------------------------------------------------------
-- READING THE LISTS
------------------------------------------------------------

-- Objective keys are "TYPE:id". Splitting them back out is what lets the
-- lists show a name rather than an opaque string.
local function SplitKey(key)
    local objectiveType, id = string.match(tostring(key), "^(.-):(.+)$")

    return objectiveType, tonumber(id) or id
end

Filters.SplitKey = SplitKey

-- Best-effort name for anything the addon might have hidden.
function Filters.DescribeObjective(objectiveType, id)
    local types = CN.objectiveTypes

    local numericID = tonumber(id)

    if objectiveType == types.QUEST and numericID then
        return CN.GetQuestName(numericID) or ("Quest " .. numericID)
    end

    -- Cached name first, then ask the client.
    --
    -- Names used to come only from a previous scan, so pinning something the
    -- addon had not seen yet produced "Faction 2600" -- which is the addon
    -- telling the player it does not know what they just asked for. The
    -- client knows. Ask it.
    if objectiveType == types.REPUTATION and numericID then
        local cached = CN.Account("factionNames")[numericID]

        if cached then
            return cached
        end

        local data = CN.Blizzard.GetFactionByID(numericID)

        return (data and data.name) or ("Faction " .. numericID)
    end

    if objectiveType == types.PET and numericID then
        -- The client's journal first: since 0.36.0 the addon no longer keeps
        -- its own copy of every pet name on disk.
        local live = CN.Blizzard.GetPetName(numericID)

        if live then
            return live
        end

        local record = CN.Account("pets")[numericID]

        return (record and record.name) or ("Pet " .. numericID)
    end

    if objectiveType == types.MOUNT and numericID then
        local record = CN.Account("mounts")[numericID]

        if record and record.name then
            return record.name
        end

        local live = CN.Blizzard.GetMountByID(numericID)

        return (live and live.name) or ("Mount " .. numericID)
    end

    if objectiveType == types.TOY and numericID then
        local record = CN.Account("toys")[numericID]
        return record and record.name or ("Toy " .. numericID)
    end

    if (objectiveType == types.RARE or objectiveType == types.TREASURE) and numericID then
        local record = CN.Account("rares")[numericID]
        return record and record.name or (objectiveType .. " " .. numericID)
    end

    if objectiveType == types.ACHIEVEMENT and numericID then
        local record = CN.Account("achievements")[numericID]

        if record and record.name then
            return record.name
        end

        return CN.Blizzard.GetAchievementName(numericID)
            or ("Achievement " .. numericID)
    end

    if objectiveType == types.CURRENCY and numericID then
        return CN.Account("currencyNames")[numericID] or ("Currency " .. numericID)
    end

    if objectiveType == types.RECIPE and numericID then
        return CN.Account("recipeNames")[numericID] or ("Recipe " .. numericID)
    end

    if objectiveType == types.TITLE and numericID then
        return CN.Account("titleNames")[numericID] or ("Title " .. numericID)
    end

    return tostring(objectiveType) .. " " .. tostring(id)
end

function Filters.ListIgnored()
    local rows = {}

    for key, entry in pairs(CN.Account("ignoredObjectives")) do
        local objectiveType, id = SplitKey(key)

        table.insert(rows, {
            key   = key,
            type  = objectiveType,
            id    = id,
            name  = Filters.DescribeObjective(objectiveType, id),
            since = entry and entry.since,
        })
    end

    table.sort(rows, function(a, b) return (a.name or "") < (b.name or "") end)

    return rows
end

function Filters.ListDeferred()
    local rows = {}

    local now = time()

    for key, entry in pairs(CN.Account("deferredObjectives")) do
        local objectiveType, id = SplitKey(key)

        local remaining

        if entry and entry.until_ then
            remaining = entry.until_ - now
        end

        table.insert(rows, {
            key       = key,
            type      = objectiveType,
            id        = id,
            name      = Filters.DescribeObjective(objectiveType, id),
            remaining = remaining,
            expired   = remaining ~= nil and remaining <= 0,
        })
    end

    table.sort(rows, function(a, b)
        return (a.remaining or math.huge) < (b.remaining or math.huge)
    end)

    return rows
end

------------------------------------------------------------
-- UNDO
------------------------------------------------------------

function Filters.Restore(key)
    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local removed = false

    if ignored[key] then
        ignored[key] = nil
        removed = true
    end

    if deferred[key] then
        deferred[key] = nil
        removed = true
    end

    -- Same reason as CN.SetIgnored: the list a provider built is the list the
    -- player sees, and un-hiding something has to rebuild it.
    if removed and CN.InvalidateCandidates then
        CN.InvalidateCandidates()
    end

    return removed
end

function Filters.RestoreAll()
    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local count = CN.CountKeys(ignored) + CN.CountKeys(deferred)

    for key in pairs(ignored) do
        ignored[key] = nil
    end

    for key in pairs(deferred) do
        deferred[key] = nil
    end

    if count > 0 and CN.InvalidateCandidates then
        CN.InvalidateCandidates()
    end

    return count
end

-- Deferrals that have run out are dead weight in SavedVariables.
function Filters.PruneExpired()
    local deferred = CN.Account("deferredObjectives")

    local now, pruned = time(), 0

    for key, entry in pairs(deferred) do
        if entry and entry.until_ and entry.until_ <= now then
            deferred[key] = nil
            pruned = pruned + 1
        end
    end

    return pruned
end

CN:OnLogin(function()
    local pruned = Filters.PruneExpired()

    if pruned > 0 then
        DebugPrint("Pruned " .. pruned .. " expired deferrals.")
    end
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function FormatRemaining(seconds)
    if not seconds then
        return "indefinitely"
    end

    if seconds <= 0 then
        return "expired"
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h"
    end

    return math.floor(seconds / DAY) .. "d"
end

Filters.FormatRemaining = FormatRemaining

CN:RegisterCommand{
    name    = "hidden",
    aliases = { "ignored" },
    order   = 20,
    help    = "Show everything you have ignored or deferred.",
    handler = function()
        local ignored  = Filters.ListIgnored()
        local deferred = Filters.ListDeferred()

        if #ignored == 0 and #deferred == 0 then
            Print("Nothing is hidden.")
            return
        end

        if #ignored > 0 then
            Print("Ignored (" .. #ignored .. "):")

            for _, row in ipairs(ignored) do
                Print("  " .. row.name .. " |cff999999[" .. tostring(row.type)
                    .. " " .. tostring(row.id) .. "]|r")
            end
        end

        if #deferred > 0 then
            Print("Deferred (" .. #deferred .. "):")

            for _, row in ipairs(deferred) do
                Print("  " .. row.name .. " |cff999999["
                    .. FormatRemaining(row.remaining) .. " left]|r")
            end
        end

        Print("|cffffff00/cn unhide <id>|r to restore one, "
            .. "|cffffff00/cn unhide all|r for everything.")
    end,
}

CN:RegisterCommand{
    name    = "unhide",
    aliases = { "restore" },
    args    = "<id or all>",
    order   = 21,
    help    = "Undo an ignore or a deferral.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn unhide <id or all>")
            return
        end

        if string.lower(args) == "all" then
            local count = Filters.RestoreAll()

            Print("Restored " .. count .. " hidden objective"
                .. (count == 1 and "" or "s") .. ".")
            return
        end

        local wanted = tostring(CN.ToID(args) or args)

        local restored = 0

        -- Match on the id alone, since the player sees ids and not the
        -- internal TYPE:id key.
        for _, row in ipairs(Filters.ListIgnored()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    Print("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        for _, row in ipairs(Filters.ListDeferred()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    Print("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        if restored == 0 then
            Print("Nothing hidden matches: " .. args)
            Print("Run |cffffff00/cn hidden|r to see the list.")
        end
    end,
}

------------------------------------------------------------
-- MODES
------------------------------------------------------------

-- Applying a mode is two existing operations performed together, plus a
-- record of what was on before so it can be undone.
function Filters.ApplyMode(name)
    local mode = CN.modes[name]

    if not mode then
        return false, "No such mode."
    end

    local settings = CN.Settings()

    -- Remember what to go back to. One level deep on purpose: an undo stack
    -- for a display preference is a feature nobody asked for.
    --
    -- BUT ONLY IF THERE IS NOT ALREADY A MODE ON.
    --
    -- This captured unconditionally, so switching from one focus straight to
    -- another overwrote the player's real settings with the FIRST focus's
    -- settings. `/cn mode leveling`, then `/cn mode collecting`, then
    -- `/cn mode off` left you in the levelling filter -- thirteen types
    -- hidden -- while printing "Previous filters and weighting restored" and
    -- recording no active mode. There was then no single command that got you
    -- back.
    --
    -- One level deep means one level: the state before the first focus, kept
    -- until a focus is actually cleared.
    if not settings.mode then
        settings.modePrevious = {
            profile = settings.priorityMode,
            hidden  = {},
        }

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            if not Filters.IsTypeEnabled(objectiveType) then
                table.insert(settings.modePrevious.hidden, objectiveType)
            end
        end
    end

    settings.priorityMode = mode.profile or "balanced"

    Filters.EnableAllTypes()

    if mode.show then
        local wanted = {}

        for _, objectiveType in ipairs(mode.show) do
            wanted[objectiveType] = true
        end

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            if not wanted[objectiveType] then
                Filters.SetTypeEnabled(objectiveType, false)
            end
        end
    end

    settings.mode = name

    CN.InvalidateCandidates("mode")

    return true, mode
end

function Filters.CurrentMode()
    local settings = CN.Settings()

    return settings and settings.mode, settings and CN.modes[settings.mode]
end

function Filters.ClearMode()
    local settings = CN.Settings()

    local previous = settings.modePrevious

    -- NOTHING TO CLEAR MEANS NOTHING TO CHANGE.
    --
    -- This called EnableAllTypes unconditionally and only then looked for
    -- something to restore -- so `/cn mode off` with no focus active unhid
    -- everything the player had hidden by hand with `/cn show`, and then
    -- printed "Previous filters and weighting restored". Hidden types live in
    -- SavedVariables, so the loss was permanent.
    --
    -- The suite only ever called this after ApplyMode, which is the one path
    -- where there is something to restore.
    if not previous and not settings.mode then
        return false
    end

    Filters.EnableAllTypes()

    if previous then
        settings.priorityMode = previous.profile or "balanced"

        for _, objectiveType in ipairs(previous.hidden or {}) do
            Filters.SetTypeEnabled(objectiveType, false)
        end
    end

    settings.mode         = nil
    settings.modePrevious = nil

    CN.InvalidateCandidates("mode")

    return true
end

CN:RegisterCommand{
    name    = "show",
    aliases = { "types" },
    args    = "[type, only <type>, or all]",
    order   = 17,
    help    = "Choose which kinds of objective appear in recommendations.",
    handler = function(args)
        args = CN.Trim(args or "")

        local lowered = string.lower(args)

        if lowered == "all" then
            local restored = Filters.EnableAllTypes()

            Print("Showing every type again"
                .. (restored > 0 and (" (" .. restored .. " restored)") or "") .. ".")

        elseif lowered:match("^only%s+") then
            local wanted = Filters.ResolveType(lowered:gsub("^only%s+", ""))

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffff00/cn show|r lists them.")
                return
            end

            Filters.OnlyType(wanted)

            Print("Showing only " .. Filters.TypeLabel(wanted) .. ".")

        elseif args ~= "" then
            local wanted = Filters.ResolveType(args)

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffff00/cn show|r lists them.")
                return
            end

            local nowEnabled = Filters.ToggleType(wanted)

            Print(Filters.TypeLabel(wanted) .. ": " .. CN.YesNo(nowEnabled))
        end

        local hiddenCount = Filters.HiddenTypeCount()

        Print("Recommendation types"
            .. (hiddenCount > 0 and (" |cffffff00" .. hiddenCount .. " hidden|r") or ""))

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            local enabled = Filters.IsTypeEnabled(objectiveType)

            Print("  " .. CN.YesNo(enabled) .. " " .. Filters.TypeLabel(objectiveType)
                .. " |cff999999" .. string.lower(objectiveType) .. "|r")
        end

        Print("|cff999999/cn show pets|r toggles one, |cff999999/cn show only quests|r "
            .. "narrows to one, |cff999999/cn show all|r restores everything.")

        if hiddenCount > 0 then
            Print("|cff999999Hidden types still appear in /cn breakdown and the "
                .. "Collections tab; this only filters recommendations.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "percharacter",
    aliases = { "perchar" },
    args    = "[setting]",
    order   = 18,
    help    = "Make a setting apply to this character only.",
    handler = function(args)
        args = CN.Trim(args or "")

        local settings = CN.Settings()

        if args ~= "" then
            -- MATCHED WITHOUT CASE, BECAUSE THE KEYS ARE camelCase.
            --
            -- This lowercased the argument and then looked it up in a table
            -- keyed `priorityMode`, `autoWaypoint`, `mapPins` -- so those
            -- three could never be set by any input, and the command rejected
            -- the exact spelling its own help line prints. Three of the six
            -- overridable settings were unreachable, including the one the
            -- feature was built for: a levelling alt wanting a different
            -- priority mode from a max-level main.
            local key

            for name in pairs(CN.characterOverridable) do
                if string.lower(name) == string.lower(args) then
                    key = name
                    break
                end
            end

            if not key then
                Print("That setting cannot be set per character: " .. args)

                local names = {}

                for name in pairs(CN.characterOverridable) do
                    table.insert(names, name)
                end

                table.sort(names)

                Print("|cff999999Overridable: " .. table.concat(names, ", ") .. "|r")
                return
            end

            args = key

            if CN.IsOverridden(args) then
                CN.ClearOverride(args)

                Print(args .. " now follows the account setting again ("
                    .. tostring(settings[args]) .. ").")
            else
                -- Seed the override with whatever this character sees now, so
                -- taking control never changes the current behaviour.
                local ok, message = CN.SetOverride(args, settings[args])

                if not ok then
                    Print(message)
                    return
                end

                Print(args .. " is now set for this character only ("
                    .. tostring(settings[args]) .. ").")
            end
        end

        Print("Settings for " .. tostring(CN.characterKey or "this character") .. ":")

        -- EVERY OVERRIDABLE SETTING, NOT A HAND-COPIED FOUR OF THEM.
        --
        -- `CN.characterOverridable` also carries `mapPins` and `follow`, and
        -- the rejection branch above already enumerates the whole table -- so
        -- overriding `mapPins` was accepted and then never listed, and the
        -- status view gave no sign it existed.
        local overridable = {}

        for key in pairs(CN.characterOverridable or {}) do
            table.insert(overridable, key)
        end

        table.sort(overridable)

        for _, key in ipairs(overridable) do
            local overridden = CN.IsOverridden(key)

            Print("  " .. key .. " = " .. tostring(settings[key])
                .. (overridden
                    and " |cffffff00this character only|r"
                    or " |cff999999account-wide|r"))
        end

        Print("|cff999999/cn perchar priorityMode|r toggles whether a setting "
            .. "is shared or per character.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Vendors.lua'] = @'
-- Modules/Vendors.lua
-- Completion Navigator :: who sells what, and where they stand.
--
-- This is the module the flagship example in the design needs:
--
--   Recipe X is sold by Vendor A. Vendor A is in <zone> at <coords>.
--   The recipe requires Revered with Faction B. This character is Honored.
--   Another character is already Revered and has the profession.
--   -> Switch to that character and buy it.
--
-- Every other piece of that already exists. The missing link was that
-- nothing knew where anything is sold.
--
-- Vendor inventories are only readable while the merchant window is open --
-- the same client restriction as trade skill recipes. So this records every
-- vendor you talk to, permanently and account-wide, and the database grows
-- as you play rather than shipping stale.

local ADDON_NAME, CN = ...

local Vendors = CN:RegisterModule("Vendors")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("vendors")
end

-- Reverse index: itemID -> { npcID, npcID, ... }. Rebuilt from the vendor
-- store rather than persisted, so it can never drift out of sync with it.
local itemIndex = nil

Vendors.Store = Store

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

function Vendors.CaptureOpenMerchant()
    local npcID, npcName = Blizzard.GetInteractingNPC()

    if not npcID then
        return false, 0
    end

    local items = Blizzard.GetMerchantItems()

    if #items == 0 then
        return false, 0
    end

    local store  = Store()
    local record = store[npcID] or { npcID = npcID, firstSeen = time() }

    record.name     = npcName or record.name
    record.lastSeen = time()

    local mapID, x, y = CN.GetPlayerPosition()

    -- Keep the first location seen; vendors do not move, and later readings
    -- are just wherever you happened to be standing when you opened the
    -- window a second time.
    if mapID and x and y and not record.mapID then
        record.mapID = mapID
        record.x     = math.floor(x * 10000 + 0.5) / 10000
        record.y     = math.floor(y * 10000 + 0.5) / 10000
        record.zone  = Blizzard.GetMapName(mapID)
    end

    -- WHAT NOT TO WRITE TO DISK.
    --
    -- This used to store every item's NAME alongside its ID. The client
    -- already knows every item name and hands it back from its own cache in
    -- microseconds; storing them again made this the largest thing the addon
    -- wrote, at roughly twenty-four kilobytes per vendor. The whole
    -- SavedVariables file is rewritten on every logout and re-parsed on every
    -- login, so that is a cost paid twice per session for data the client was
    -- always going to give us for free.
    --
    -- The rule this establishes, and the reason it is worth writing down:
    -- persist only what the client CANNOT tell us. Names, collected states
    -- and completion flags are all re-derivable instantly. Cross-character
    -- knowledge, observations gathered over time and the player's own choices
    -- are not, and those are what this database is actually for.
    record.items = {}

    -- A NUMBER, NOT A TABLE.
    --
    -- Each item used to get a table of its own to hold two fields. A table
    -- per item costs far more in a saved-variables file than the value it
    -- carries, and a large vendor sells hundreds of items. Prices are stored
    -- directly; the handful bought with an extended cost -- tokens, currency
    -- -- are listed separately, because they are the exception.
    --
    -- Price is kept at all because the client only reports it while the
    -- merchant window is open, so unlike the item's name it genuinely cannot
    -- be recovered later.
    record.extendedCost = nil

    for _, item in ipairs(items) do
        if item.itemID then
            record.items[item.itemID] = item.price or 0

            if item.extendedCost then
                record.extendedCost = record.extendedCost or {}
                record.extendedCost[item.itemID] = true
            end
        end
    end

    record.itemCount = CN.CountKeys(record.items)

    store[npcID] = record

    -- The reverse index is now stale.
    itemIndex = nil

    CN.MarkScanned("vendors")

    return true, record.itemCount
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

local function BuildItemIndex()
    local index = {}

    for npcID, record in pairs(Store()) do
        for itemID in pairs(record.items or {}) do
            index[itemID] = index[itemID] or {}
            table.insert(index[itemID], npcID)
        end
    end

    itemIndex = index

    return index
end

-- The candidate provider asks this question thousands of times per rebuild,
-- once per known recipe, and almost always gets no answer. WhoSells allocates
-- a result array every time it is called; this does not allocate at all until
-- there is something to return.
function Vendors.FirstLocatedSeller(itemID)
    if not itemID then
        return nil
    end

    local index = itemIndex or BuildItemIndex()

    local npcIDs = index[itemID]

    if not npcIDs then
        return nil
    end

    local store = Store()

    for _, npcID in ipairs(npcIDs) do
        local record = store[npcID]

        if record and record.mapID and record.x and record.y then
            return record, npcID
        end
    end

    return nil
end

-- What a vendor charges for an item, in the shape callers expect, whichever
-- shape the store happens to be in. Old databases keep working until the
-- next merchant visit rewrites the row.
function Vendors.PriceOf(record, itemID)
    local stored = record and record.items and record.items[itemID]

    if stored == nil then
        return nil
    end

    if type(stored) == "table" then
        return stored.price, stored.extendedCost and true or false
    end

    return stored, (record.extendedCost and record.extendedCost[itemID]) or false
end

function Vendors.WhoSells(itemID)
    if not itemID then
        return {}
    end

    local index = itemIndex or BuildItemIndex()

    local sellers = {}

    for _, npcID in ipairs(index[itemID] or {}) do
        local record = Store()[npcID]

        if record then
            table.insert(sellers, {
                npcID = npcID,
                name  = record.name,
                zone  = record.zone,
                mapID = record.mapID,
                x     = record.x,
                y     = record.y,
                price = Vendors.PriceOf(record, itemID),
            })
        end
    end

    return sellers
end

-- Finds an item by name across every recorded vendor. This is what makes
-- "who sells Flask of Testing" work without knowing an item ID.
function Vendors.FindItem(text)
    if not text or text == "" then
        return nil, {}
    end

    local itemID = CN.ToID(text)

    if itemID then
        return itemID, Vendors.WhoSells(itemID)
    end

    local needle  = string.lower(text)
    local matches = {}

    for npcID, record in pairs(Store()) do
        for id in pairs(record.items or {}) do
            -- Resolved from the client's item cache rather than from a copy
            -- of it kept on disk. Unknown names are skipped rather than
            -- guessed; the client fills its cache as items are seen.
            local name = Blizzard.GetItemName(id)

            if name and string.find(string.lower(name), needle, 1, true) then
                matches[id] = name
            end
        end
    end

    local bestID, bestName

    for id, name in pairs(matches) do
        if not bestName or #name < #bestName then
            bestID, bestName = id, name
        end
    end

    if not bestID then
        return nil, {}
    end

    return bestID, Vendors.WhoSells(bestID)
end

function Vendors.Summary()
    local counts = { vendors = 0, items = 0, located = 0 }

    local uniqueItems = {}

    for _, record in pairs(Store()) do
        counts.vendors = counts.vendors + 1

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        for itemID in pairs(record.items or {}) do
            uniqueItems[itemID] = true
        end
    end

    counts.items = CN.CountKeys(uniqueItems)

    return counts
end

------------------------------------------------------------
-- RECIPE LINKING
------------------------------------------------------------

-- The payoff: a recipe this character does not know, sold by a vendor whose
-- location is recorded, becomes an objective with real coordinates.
CN.RegisterCandidateProvider("Vendors", function()
    local professions = CN:GetModule("Professions")

    if not professions then
        return {}
    end

    local known = professions.CharacterRecipes() or {}
    local names = professions.RecipeNames()

    local playerMap = select(1, CN.GetPlayerPosition())

    local candidates, considered, dropped = CN.CollectBounded(names, nil,
        function(itemID)
            if known[itemID] then
                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.RECIPE, itemID)
                or CN.IsDeferred(CN.objectiveTypes.RECIPE, itemID) then
                return nil
            end

            local seller = Vendors.FirstLocatedSeller(itemID)

            if not seller then
                return nil
            end

            -- A recipe you can walk to in this zone beats one across the
            -- continent, and that is the only distinction worth ranking here.
            return (seller.mapID == playerMap) and 3 or 2
        end,
        function(itemID, recipeName)
            local seller = Vendors.FirstLocatedSeller(itemID)

            if not seller then
                return nil
            end

            local reasons = { "sold by " .. tostring(seller.name) }

            if seller.zone then
                table.insert(reasons, "in " .. seller.zone)
            end

            return CN.NewObjective({
                id              = itemID,
                type            = CN.objectiveTypes.RECIPE,
                name            = recipeName,
                mapID           = seller.mapID,
                x               = seller.x,
                y               = seller.y,
                completionValue = 2,
                -- COSTED, NOT GUESSED. This charged a flat 25 for anything
                -- outside the current zone while holding the seller's exact
                -- coordinates -- so a vendor ninety seconds away in the next
                -- zone was charged twenty-five where a quest at the identical
                -- spot was charged three. A systematic twenty-two point
                -- penalty against exactly the collection types this file
                -- exists to surface.
                travelCost      = CN.TravelCost(seller.mapID, seller.x, seller.y),
                reasons         = reasons,
            })
        end)

    CN.providerTruncation["Vendors"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "MERCHANT_SHOW", "TRADE_SKILL_LIST_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("MERCHANT_SHOW", function()
    local captured, count = Vendors.CaptureOpenMerchant()

    if captured then
        DebugPrint("Recorded vendor with " .. count .. " items.")
    end
end)

CN:RegisterEvent("MERCHANT_UPDATE", function()
    Vendors.CaptureOpenMerchant()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vendors",
    order   = 79,
    help    = "Summarize recorded vendors.",
    handler = function()
        local counts = Vendors.Summary()

        if counts.vendors == 0 then
            Print("No vendors recorded yet.")
            Print("|cff999999Open a merchant window and the addon records "
                .. "what they sell and where they stand.|r")
            return
        end

        Print("Vendors recorded: " .. counts.vendors
            .. " (" .. counts.located .. " with coordinates)")
        Print("Distinct items seen: " .. counts.items)
    end,
}

CN:RegisterCommand{
    name    = "sells",
    aliases = { "whosells" },
    args    = "<itemID or name>",
    order   = 80,
    help    = "Find which recorded vendor sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn sells <itemID or name>")
            return
        end

        local itemID, sellers = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            Print("|cff999999Only vendors you have opened are known.|r")
            return
        end

        Print("Item " .. itemID .. " is sold by:")

        for index, seller in ipairs(sellers) do
            Print("  " .. index .. ". " .. tostring(seller.name)
                .. (seller.zone and (" |cff999999in " .. seller.zone .. "|r") or "")
                .. (seller.x and string.format(" |cff999999%.1f, %.1f|r",
                    seller.x * 100, seller.y * 100) or ""))
        end

        Print("|cffffff00/cn tovendor " .. itemID .. "|r to set a waypoint.")
    end,
}

CN:RegisterCommand{
    name    = "tovendor",
    args    = "<itemID or name>",
    order   = 81,
    help    = "Navigate to a vendor that sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn tovendor <itemID or name>")
            return
        end

        local itemID, sellers = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            return
        end

        for _, seller in ipairs(sellers) do
            if seller.mapID and seller.x and seller.y then
                CN.NavigateToObjective({
                    id    = seller.npcID,
                    type  = CN.objectiveTypes.VENDOR,
                    name  = seller.name,
                    mapID = seller.mapID,
                    x     = seller.x,
                    y     = seller.y,
                })

                return
            end
        end

        Print("No recorded seller has coordinates yet.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Tooltips.lua'] = @'
-- Modules/Tooltips.lua
-- Completion Navigator :: what the addon knows, shown where you are looking.
--
-- Everything in this addon already knows whether you own a toy, which of your
-- characters knows a recipe, and which vendor sells an item. Until now you had
-- to go and ask. A tooltip is where that question actually gets asked -- while
-- hovering the thing in a vendor list, a loot window or the auction house.
--
-- The line-building functions are deliberately separate from the hooks: the
-- lines are pure data, so they can be tested offline, and the hooks are a thin
-- adapter over whichever tooltip API the client is running.

local ADDON_NAME, CN = ...

local Tooltips = CN:RegisterModule("Tooltips")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local GREEN  = { 0.4, 1.0, 0.4 }
local RED    = { 1.0, 0.4, 0.4 }
local YELLOW = { 1.0, 0.85, 0.3 }
local GREY   = { 0.6, 0.6, 0.6 }

local HEADER = "Completion Navigator"

local function Enabled()
    local settings = CN.Settings()

    return settings and settings.tooltips ~= false
end

Tooltips.Enabled = Enabled

------------------------------------------------------------
-- LINE BUILDERS
------------------------------------------------------------

local function Add(lines, text, color)
    table.insert(lines, { text = text, color = color or GREY })
end

local function CollectedLine(lines, label, collected)
    if collected then
        Add(lines, label .. ": collected", GREEN)
    else
        Add(lines, label .. ": not collected", RED)
    end
end

-- Toys are keyed by item ID in both the toy box and our own store, so this is
-- the one collection lookup that needs no translation.
local function ToyLines(lines, itemID)
    local record = CN.Account("toys")[itemID]

    if record then
        CollectedLine(lines, "Toy", record.collected)
        return true
    end

    -- No scan yet, but the client can still answer for this one item.
    if PlayerHasToy and C_ToyBox and C_ToyBox.GetToyInfo then
        local _, name = C_ToyBox.GetToyInfo(itemID)

        if name then
            CollectedLine(lines, "Toy", PlayerHasToy(itemID))
            return true
        end
    end

    return false
end

local function MountLines(lines, itemID)
    local mountID = Blizzard.GetMountFromItem(itemID)

    if not mountID then
        return false
    end

    local record = CN.Account("mounts")[mountID]

    if record then
        CollectedLine(lines, "Mount", record.collected)

        if record.isFactionSpecific and record.faction then
            Add(lines, "Faction-locked", YELLOW)
        end

        return true
    end

    local mount = Blizzard.GetMountByID(mountID)

    if mount then
        CollectedLine(lines, "Mount", mount.isCollected)
        return true
    end

    return false
end

local function PetLines(lines, itemID)
    local speciesID = Blizzard.GetPetSpeciesFromItem(itemID)

    if not speciesID then
        return false
    end

    local record = CN.Account("pets")[speciesID]

    local count, limit

    if record then
        count, limit = record.count, record.limit
    else
        count, limit = Blizzard.GetPetCollectedCount(speciesID)
    end

    count = count or 0

    -- NO FABRICATED DENOMINATOR.
    --
    -- `limit or 3` invented the cap when neither the store nor the client
    -- supplied it, and then printed "collected 2 of 3" as though the 3 had
    -- been read from somewhere. Three is the right number today; it is still
    -- a made-up total in a module that refuses them everywhere else.
    if count > 0 and limit and limit > 0 then
        Add(lines, "Battle pet: collected " .. count .. " of " .. limit, GREEN)
    elseif count > 0 then
        Add(lines, "Battle pet: collected " .. count, GREEN)
    else
        Add(lines, "Battle pet: not collected", RED)
    end

    return true
end

local function AppearanceLines(lines, itemID)
    local has = Blizzard.HasTransmogByItem(itemID)

    if has == nil then
        return false
    end

    if has then
        Add(lines, "Appearance: already known", GREEN)
    else
        Add(lines, "Appearance: not yet known", RED)
    end

    return true
end

-- Recipes are the messy case. The trade skill API keys recipes by recipe ID
-- while a vendor sells an item ID, and the two are not the same number. The
-- ID lookup is tried first because it is exact; the name match is the fallback
-- that actually fires most of the time, and it is reported as a match on name
-- rather than dressed up as certainty.
local function RecipeLines(lines, itemID, itemName)
    local professions = CN:GetModule("Professions")

    if not professions then
        return false
    end

    local mine = professions.CharacterRecipes() or {}

    -- ONE INDEXED LOOKUP, NOT A SCAN.
    --
    -- This used to walk every recipe name the addon knew -- lowercasing each
    -- one and searching it -- on every single item tooltip. At retail scale
    -- that is twenty-five hundred iterations and five thousand string
    -- allocations to answer a question about one item, measured at 0.54ms:
    -- three per cent of a frame, per mouseover, and a bag sweep fires dozens
    -- a second.
    local recipeID, matchedOnName =
        professions.RecipeForItem(itemID, itemName)

    if not recipeID then
        return false
    end

    if mine[recipeID] then
        Add(lines, "Recipe: known by this character", GREEN)
    else
        Add(lines, "Recipe: not known by this character", RED)

        local holders = professions.WhoKnows(recipeID) or {}

        if #holders > 0 then
            Add(lines, "Known by: " .. table.concat(holders, ", "), YELLOW)
        end
    end

    if matchedOnName then
        Add(lines, "matched by name", GREY)
    end

    return true
end

local function VendorLines(lines, itemID)
    local vendors = CN:GetModule("Vendors")

    if not vendors then
        return false
    end

    local sellers = vendors.WhoSells(itemID)

    if #sellers == 0 then
        return false
    end

    for index, seller in ipairs(sellers) do
        if index > 3 then
            Add(lines, "and " .. (#sellers - 3) .. " more recorded seller"
                .. ((#sellers - 3) == 1 and "" or "s"), GREY)
            break
        end

        local text = "Sold by " .. tostring(seller.name or seller.npcID)

        if seller.zone then
            text = text .. " in " .. seller.zone
        end

        if seller.x and seller.y then
            text = text .. string.format(" (%.1f, %.1f)", seller.x * 100, seller.y * 100)
        end

        Add(lines, text, YELLOW)
    end

    return true
end

-- The whole item block, as data. Returns an array of { text, color }.
function Tooltips.ItemLines(itemID, itemName)
    local lines = {}

    if not itemID or not CN.db then
        return lines
    end

    itemName = itemName or Blizzard.GetItemName(itemID)

    local collectible = false

    collectible = ToyLines(lines, itemID)         or collectible
    collectible = MountLines(lines, itemID)       or collectible
    collectible = PetLines(lines, itemID)         or collectible
    collectible = RecipeLines(lines, itemID, itemName) or collectible

    -- Appearance state is noise on something that is not gear, so it is only
    -- consulted when nothing else claimed the item.
    if not collectible then
        AppearanceLines(lines, itemID)
    end

    VendorLines(lines, itemID)

    -- WHY IT MATTERS, not only that it is tracked (0.43.0).
    --
    -- Every line above answers "do I have this?". None of them answered the
    -- question a player actually hovers an item to ask, which is "should I
    -- care?" -- and the addon knows, because it has already ranked the thing
    -- and written down its reasons.
    --
    -- One line, the top reason only. A tooltip that grows a paragraph is a
    -- tooltip people turn off.
    if collectible then
        local goals = CN:GetModule("Goals")

        local mountID = Blizzard.GetMountFromItem(itemID)
        local speciesID = Blizzard.GetPetSpeciesFromItem(itemID)

        local goalType = mountID and CN.objectiveTypes.MOUNT
            or (speciesID and CN.objectiveTypes.PET)

        local goalID = mountID or speciesID

        if goals and goalType and goalID and goals.IsGoal
            and goals.IsGoal(goalType, goalID) then

            Add(lines, "You are chasing this.", { 0.365, 0.824, 0.984 })
        else
            local candidate = CN.FindCandidate and goalType
                and CN.FindCandidate(goalType, goalID)

            local reason = candidate and candidate.reasons
                and candidate.reasons[1]

            if reason then
                Add(lines, reason, { 0.6, 0.6, 0.6 })
            end

            -- ONE MORE LINE, WHERE IT SAYS SOMETHING THE FIRST DID NOT.
            --
            -- 0.43.0 added the top reason, which answers "should I care?".
            -- The second question a player asks of a collectible is "where
            -- does it come from?", and the addon has known that since 0.41.0
            -- without ever putting it where the mouse already is.
            local instances = CN:GetModule("Instances")

            if instances and itemName then
                local ok, source = pcall(instances.DescribeSource, itemName)

                if ok and source then
                    Add(lines, "Drops from " .. source, { 0.6, 0.6, 0.6 })
                end
            end
        end
    end

    return lines
end

-- Unit tooltips answer a narrower question: have I shopped here, and is this
-- creature one the addon is tracking as a rare.
function Tooltips.UnitLines(npcID)
    local lines = {}

    if not npcID or not CN.db then
        return lines
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local record = vendors.Store()[npcID]

        if record then
            Add(lines, "Recorded vendor: " .. (record.itemCount or 0) .. " items", YELLOW)

            if not record.mapID then
                Add(lines, "no coordinates recorded yet", GREY)
            end
        end
    end

    -- The rare database is keyed by vignette ID, not creature ID, so there is
    -- deliberately nothing to say here about rares. Adding a guess would be
    -- worse than the silence.

    return lines
end

------------------------------------------------------------
-- RENDERING
------------------------------------------------------------

function Tooltips.Render(tooltip, lines)
    if not tooltip or not tooltip.AddLine or #lines == 0 then
        return 0
    end

    tooltip:AddLine(" ")
    tooltip:AddLine(HEADER, 0.2, 1.0, 0.6)

    for _, line in ipairs(lines) do
        tooltip:AddLine(line.text, line.color[1], line.color[2], line.color[3])
    end

    if tooltip.Show then
        tooltip:Show()
    end

    return #lines
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

-- Which tooltip API resolved, reported by /cn tooltips so a silent hook is
-- diagnosable rather than mysterious.
Tooltips.backend = "none"

local function OnItemTooltip(tooltip, itemID, itemName)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        Tooltips.Render(tooltip, Tooltips.ItemLines(itemID, itemName))
    end)

    if not ok then
        DebugPrint("Item tooltip failed: " .. tostring(err))
    end
end

local function OnUnitTooltip(tooltip, unit)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        local npcID = Blizzard.GetUnitNPCID(unit or "mouseover")

        Tooltips.Render(tooltip, Tooltips.UnitLines(npcID))
    end)

    if not ok then
        DebugPrint("Unit tooltip failed: " .. tostring(err))
    end
end

Tooltips.OnItemTooltip = OnItemTooltip
Tooltips.OnUnitTooltip = OnUnitTooltip

function Tooltips.Install()
    if Tooltips.installed then
        return Tooltips.backend
    end

    -- Modern retail: every tooltip is data-driven and post-processed. Post
    -- calls run after the tooltip is rebuilt, so lines are added once per
    -- render rather than accumulating.
    if TooltipDataProcessor
        and TooltipDataProcessor.AddTooltipPostCall
        and Enum and Enum.TooltipDataType then

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item,
            function(tooltip, data)
                local itemID, itemName

                if data then
                    itemID = data.id
                end

                if TooltipUtil and TooltipUtil.GetDisplayedItem then
                    local name, _, id = TooltipUtil.GetDisplayedItem(tooltip)

                    itemName = name
                    itemID   = itemID or id
                end

                OnItemTooltip(tooltip, itemID, itemName)
            end)

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Unit,
            function(tooltip, data)
                local unit

                if TooltipUtil and TooltipUtil.GetDisplayedUnit then
                    unit = select(2, TooltipUtil.GetDisplayedUnit(tooltip))
                end

                OnUnitTooltip(tooltip, unit)
            end)

        Tooltips.installed = true
        Tooltips.backend   = "TooltipDataProcessor"

        return Tooltips.backend
    end

    -- Older clients. Kept because the addon is expected to load on more than
    -- one flavour, and a missing hook here is silent otherwise.
    if GameTooltip and GameTooltip.HookScript then
        GameTooltip:HookScript("OnTooltipSetItem", function(self)
            local name, link = self:GetItem()

            local itemID = link and tonumber(link:match("item:(%d+)"))

            OnItemTooltip(self, itemID, name)
        end)

        GameTooltip:HookScript("OnTooltipSetUnit", function(self)
            local _, unit = self:GetUnit()

            OnUnitTooltip(self, unit)
        end)

        Tooltips.installed = true
        Tooltips.backend   = "OnTooltipSet"

        return Tooltips.backend
    end

    Tooltips.backend = "none"

    return Tooltips.backend
end

CN:OnLogin(function()
    Tooltips.Install()

    DebugPrint("Tooltip backend: " .. tostring(Tooltips.backend))
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "tooltips",
    args    = "[on or off]",
    order   = 82,
    help    = "Toggle addon lines on item and unit tooltips.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args))

        if args == "on" then
            settings.tooltips = true
        elseif args == "off" then
            settings.tooltips = false
        elseif args ~= "" then
            Print("Usage: /cn tooltips [on or off]")
            return
        else
            -- Default is on, so nil counts as enabled.
            settings.tooltips = (settings.tooltips == false)
        end

        Print("Tooltip lines: " .. CN.YesNo(settings.tooltips ~= false))
        Print("|cff999999Backend: " .. tostring(Tooltips.backend) .. "|r")

        if Tooltips.backend == "none" then
            Print("|cff999999No tooltip API resolved, so nothing will be added.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Setup.lua'] = @'
-- Modules/Setup.lua
-- Completion Navigator :: the first five minutes.
--
-- Every recommendation this addon makes is only as good as what it has
-- scanned, and until now a new install had to discover eleven separate scan
-- commands to get there. Worse, it looked broken in the meantime: an empty
-- database and a confident "nothing actionable is known yet" read as a bug
-- rather than as a first run.
--
-- /cn setup runs every scan in order, one per frame, and then reports what
-- the client genuinely could not answer -- recipes and vendors, which are
-- readable only while their windows are open, and so can never be batched.

local ADDON_NAME, CN = ...

local Setup = CN:RegisterModule("Setup")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- STEPS
------------------------------------------------------------

-- Ordered so the cheap scans report first and the journal scans -- which
-- open and filter collection UIs -- come last.
Setup.steps = {
    { key = "reputations", label = "Reputations", module = "Reputations", fn = "Scan" },
    { key = "currencies",  label = "Currencies",  module = "Currencies",  fn = "Scan" },
    { key = "titles",      label = "Titles",      module = "Titles",      fn = "Scan" },
    { key = "professions", label = "Professions", module = "Professions", fn = "Scan" },
    { key = "exploration", label = "Exploration", module = "Exploration", fn = "Scan" },
    { key = "quests",      label = "Quests",      module = "Quests",      fn = "ScanKnown" },
    { key = "achievements",label = "Achievements",module = "Achievements",fn = "Scan" },
    { key = "toys",        label = "Toys",        module = "Toys",        fn = "Scan" },
    { key = "mounts",      label = "Mounts",      module = "Mounts",      fn = "Scan" },
    { key = "pets",        label = "Battle pets", module = "Pets",        fn = "Scan" },
    { key = "appearances", label = "Appearances", module = "Appearances", fn = "Scan" },
}

function Setup.RunStep(step)
    local module = CN:GetModule(step.module)

    if not module or type(module[step.fn]) ~= "function" then
        return false, "module not loaded"
    end

    local ok, first = pcall(module[step.fn])

    if not ok then
        return false, tostring(first)
    end

    return true, first
end

------------------------------------------------------------
-- RUN
------------------------------------------------------------

Setup.running = false

-- Spreading the steps across frames matters: several of these walk the entire
-- pet journal or achievement tree, and doing all eleven inside one frame is a
-- visible stutter on a login that is already busy.
function Setup.Run(onComplete)
    if Setup.running then
        Print("Setup is already running.")
        return false
    end

    Setup.running = true

    local results = {}
    local index   = 0

    -- THE WHOLE BODY IS GUARDED, NOT JUST THE STEP.
    --
    -- `RunStep` was pcall'd and nothing else was -- and steps two onward run
    -- inside `C_Timer.After` callbacks, outside the slash command's own
    -- pcall. So a throw in the bookkeeping, in `Setup.Report`, or in
    -- `Setup.Outstanding` stopped the chain dead AND left `Setup.running`
    -- true, which makes `/cn setup` answer "Setup is already running." for
    -- the rest of the session with no way back short of a reload.
    local function step()
        local ran, err = pcall(function()
            index = index + 1

            local entry = Setup.steps[index]

            if not entry then
                Setup.running = false

                -- COMPLETION IS RECORDED ONLY IF SOMETHING COMPLETED.
                --
                -- This was stamped unconditionally, so a run in which every
                -- scan failed was remembered as a successful setup: the login
                -- reminder stopped, `Setup.HasRun()` went true forever, and
                -- `/cn setup check` answered "Everything the addon can read
                -- on its own is scanned."
                local failed = 0

                for _, row in ipairs(results) do
                    if not row.ok then
                        failed = failed + 1
                    end
                end

                if failed < #results then
                    CN.Account("setup").completedAt = time()
                end

                Setup.Report(results)

                if onComplete then
                    pcall(onComplete, results)
                end

                return
            end

            local ok, value = Setup.RunStep(entry)

            table.insert(results, {
                label = entry.label,
                ok    = ok,
                value = ok and value or nil,
                error = (not ok) and value or nil,
            })

            if C_Timer and C_Timer.After then
                C_Timer.After(0, step)
            else
                step()
            end
        end)

        if not ran then
            Setup.running = false

            local errors = CN:GetModule("Errors")

            if errors and errors.Record then
                pcall(errors.Record, "Setup.Run", tostring(err))
            end

            Print("Setup stopped after " .. index .. " of "
                .. #Setup.steps .. " scans: " .. tostring(err))
            Print("|cff999999/cn setup runs it again from the start.|r")
        end
    end

    Print("Running setup: " .. #Setup.steps .. " scans.")

    step()

    return true
end

function Setup.Report(results)
    local scanned, absent, broke = 0, 0, 0

    for _, result in ipairs(results) do
        if result.ok then
            scanned = scanned + 1

            Print("  " .. result.label .. ": "
                .. (type(result.value) == "number" and result.value or "done"))
        elseif result.error == "module not loaded" then
            -- "UNAVAILABLE" AND "IT THREW" ARE DIFFERENT STATEMENTS.
            --
            -- Every failure was reported with the word "unavailable", so a
            -- module that raised a Lua error was presented to the player as a
            -- subsystem this client does not have -- nothing to look into,
            -- nothing to report.
            absent = absent + 1

            Print("  " .. result.label
                .. ": |cff999999not available on this client|r")
        else
            broke = broke + 1

            Print("  " .. result.label .. ": |cffff4444failed: "
                .. tostring(result.error) .. "|r")
        end
    end

    Print("Setup complete: " .. scanned .. " scanned"
        .. (absent > 0 and (", " .. absent .. " unavailable") or "")
        .. (broke > 0 and (", " .. broke .. " failed") or "") .. ".")

    if broke > 0 then
        Print("|cff999999A failure is a defect, not a missing feature. "
            .. "|cffffff00/cn errors|r has the detail.|r")
    end

    for _, line in ipairs(Setup.Outstanding()) do
        Print("|cffffff00" .. line .. "|r")
    end

    Print("Now try |cffffff00/cn next|r.")
end

------------------------------------------------------------
-- WHAT SETUP CANNOT DO
------------------------------------------------------------

-- Two subsystems are readable only while their window is open. Saying so is
-- the difference between "this addon does not track recipes" and "open your
-- profession window once".
function Setup.Outstanding()
    local lines = {}

    local professions = CN:GetModule("Professions")

    if professions and professions.AwaitingRecipeCapture then
        local awaiting = professions.AwaitingRecipeCapture()

        if awaiting and #awaiting > 0 then
            local names = {}

            for _, entry in ipairs(awaiting) do
                table.insert(names, tostring(entry))
            end

            table.insert(lines, "Open each profession window once to record recipes: "
                .. table.concat(names, ", "))
        end
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local counts = vendors.Summary()

        if counts.vendors == 0 then
            table.insert(lines,
                "No vendors recorded yet; they are captured as you open merchant windows.")
        end
    end

    return lines
end

function Setup.HasRun()
    local record = CN.Account("setup")

    return (record and record.completedAt) and true or false
end

------------------------------------------------------------
-- FIRST-RUN PROMPT
------------------------------------------------------------

-- Prompt, never act. Running eleven scans uninvited on someone's login is the
-- same discourtesy as seizing their waypoint.
--
-- BUT: the prompt used to fire once, ever. It was recorded as "prompted" the
-- first time and never spoken again, so a player who missed that single line
-- in a busy login -- which is most of them -- had an addon that quietly knew
-- nothing about their collections for the rest of its installed life, and no
-- way to find out why it seemed thin.
--
-- A required first step is worth saying every login until it has been done.
-- Once done, it is never mentioned again. That is the difference between a
-- reminder and nagging: a reminder stops when the thing is finished.
Setup.remindSeconds = 8

function Setup.RemindIfNeeded()
    if Setup.HasRun() then
        return false
    end

    Print("Completion Navigator has not scanned your collections yet.")
    Print("Type |cffffff00/cn setup|r once and it will know what you have.")

    local account = CN.Account("setup")

    account.prompts = (account.prompts or 0) + 1

    return true
end

------------------------------------------------------------
-- WHEN THE ADDON CANNOT SEE SOMETHING
------------------------------------------------------------

-- Two subsystems are readable only while their window is open, so the addon
-- can be fully set up and still blind to a profession the player levelled
-- last week. It knew that and only said so immediately after a manual scan,
-- which is the one moment the player is least likely to need telling.
--
-- Said again periodically, and never more than this often, because the fix
-- is "open a window some time" rather than anything urgent.
Setup.outstandingIntervalDays = 7

function Setup.RemindOutstanding()
    if not Setup.HasRun() then
        return false
    end

    local lines = Setup.Outstanding()

    if #lines == 0 then
        return false
    end

    local account = CN.Account("setup")

    local last = account.outstandingRemindedAt or 0

    if (time() - last) < (Setup.outstandingIntervalDays * 86400) then
        return false
    end

    account.outstandingRemindedAt = time()

    Print("Completion Navigator cannot see everything yet:")

    for _, line in ipairs(lines) do
        Print("  |cffffff00" .. line .. "|r")
    end

    return true
end

CN:OnLogin(function()
    local function speak()
        if Setup.RemindIfNeeded() then
            return
        end

        Setup.RemindOutstanding()
    end

    -- Delayed, so it lands after the login chatter rather than inside it.
    if C_Timer and C_Timer.After then
        C_Timer.After(Setup.remindSeconds, speak)
    else
        speak()
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "setup",
    aliases = { "scanall" },
    args    = "[check]",
    order   = 5,
    help    = "Scan every subsystem once. Run this first.",
    handler = function(args)
        if string.lower(CN.Trim(args or "")) == "check" then
            -- Report without scanning. "What can you not see?" is a
            -- different question from "go and look again", and answering the
            -- first by doing the second is why people stop asking.
            if not Setup.HasRun() then
                Print("Not scanned yet. Type |cffffff00/cn setup|r.")
                return
            end

            local lines = Setup.Outstanding()

            if #lines == 0 then
                Print("Everything the addon can read on its own is scanned.")
                return
            end

            Print("Still outside what the addon can read on its own:")

            for _, line in ipairs(lines) do
                Print("  |cffffff00" .. line .. "|r")
            end

            return
        end

        Setup.Run()
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Goals.lua'] = @'
-- Modules/Goals.lua
-- Completion Navigator :: what you are actually working toward.
--
-- Everything else in this addon answers "what should I do next?" from the
-- whole field of what is available. That is the right default, and it is the
-- wrong answer when you have decided you want one specific thing.
--
-- A goal is a target you pin. Once pinned:
--
--   * it becomes a candidate in its own right, even when nothing else would
--     have surfaced it -- an uncollected mount is not normally actionable,
--     but if you have decided you want it, it is;
--   * anything that plausibly leads to it is weighted up, and says so;
--   * /cn goal prints what is actually known about getting it -- the source,
--     where it is, which of your characters is best placed, and what the
--     next concrete step is.
--
-- Goals are account-wide. Deciding you want a mount is not a fact about the
-- character you happened to be playing when you decided it.

local ADDON_NAME, CN = ...

local Goals = CN:RegisterModule("Goals")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("goals")
end

Goals.Store = Store

-- How many goals are worth having at once. Beyond a handful, "goal" stops
-- meaning anything and the weighting stops discriminating.
Goals.limit = 10

------------------------------------------------------------
-- TYPES
------------------------------------------------------------

-- Which objective types can be pinned, and what the user types for each.
Goals.types = {
    quest       = CN.objectiveTypes.QUEST,
    achievement = CN.objectiveTypes.ACHIEVEMENT,
    mount       = CN.objectiveTypes.MOUNT,
    pet         = CN.objectiveTypes.PET,
    toy         = CN.objectiveTypes.TOY,
    recipe      = CN.objectiveTypes.RECIPE,
    title       = CN.objectiveTypes.TITLE,
    rep         = CN.objectiveTypes.REPUTATION,
    reputation  = CN.objectiveTypes.REPUTATION,
    rare        = CN.objectiveTypes.RARE,
    currency    = CN.objectiveTypes.CURRENCY,
}

local function ResolveType(text)
    if not text then
        return nil
    end

    return Goals.types[string.lower(text)]
end

Goals.ResolveType = ResolveType

Goals.ResolveType = ResolveType

local function Key(objectiveType, id)
    return CN.ObjectiveKey(objectiveType, id)
end

------------------------------------------------------------
-- MANAGING GOALS
------------------------------------------------------------

function Goals.IsGoal(objectiveType, id)
    if not objectiveType or not id then
        return false
    end

    local store = Store()

    if not store or next(store) == nil then
        return false
    end

    return store[Key(objectiveType, id)] ~= nil
end

function Goals.Add(objectiveType, id)
    if not objectiveType or not id then
        return false, "A goal needs a type and an ID."
    end

    local store = Store()

    local key = Key(objectiveType, id)

    if store[key] then
        return false, "That is already a goal."
    end

    if CN.CountKeys(store) >= Goals.limit then
        return false, "You already have " .. Goals.limit
            .. " goals. Clear one first."
    end

    local filters = CN:GetModule("Filters")

    local name = filters and filters.DescribeObjective(objectiveType, id)
        or (objectiveType .. " " .. tostring(id))

    store[key] = {
        type  = objectiveType,
        id    = id,
        name  = name,
        since = time(),
    }

    -- A goal changes the weight of everything, and objectives are decorated
    -- when their provider builds them. Force a full rebuild so the new
    -- weighting takes effect immediately rather than whenever something
    -- happens to go stale.
    Goals.zoneGeneration = (Goals.zoneGeneration or 0) + 1

    CN.InvalidateCandidates()

    return true, name
end

function Goals.Remove(objectiveType, id)
    local store = Store()

    local key = Key(objectiveType, id)

    if not store[key] then
        return false
    end

    local name = store[key].name

    store[key] = nil

    Goals.zoneGeneration = (Goals.zoneGeneration or 0) + 1

    CN.InvalidateCandidates()

    return true, name
end

function Goals.Clear()
    local store = Store()

    local count = CN.CountKeys(store)

    for key in pairs(store) do
        store[key] = nil
    end

    Goals.zoneGeneration = (Goals.zoneGeneration or 0) + 1

    CN.InvalidateCandidates()

    return count
end

-- Ordered oldest first, so the list is stable and numbering means something
-- between calls.
function Goals.List()
    local list = {}

    local filters = CN:GetModule("Filters")

    for key, goal in pairs(Store()) do
        -- RE-RESOLVED, NOT FROZEN.
        --
        -- The name was worked out once when the goal was pinned and then
        -- persisted -- and for currencies, recipes, titles, toys and rares
        -- the describer can only answer from a cache the scans fill. Pin one
        -- before the relevant scan and the placeholder was kept forever:
        -- "Currency 3008" in `/cn goals`, in `/cn chase`, and after every
        -- future login, even once the client could name it.
        --
        -- `/cn chase <type> <id>` pins automatically, so hitting this needs
        -- no unusual sequence at all. It undoes, for exactly the cache-only
        -- types, the fix recorded in Filters.lua: "The client knows. Ask it."
        local name = goal.name

        if filters and filters.DescribeObjective then
            local ok, described = pcall(filters.DescribeObjective,
                goal.type, goal.id)

            if ok and described and described ~= "" then
                local placeholder = tostring(goal.type):sub(1, 1)
                    .. tostring(goal.type):sub(2):lower() .. " " .. tostring(goal.id)

                -- Only when the describer has learned something real: a
                -- second placeholder is not an improvement on the first.
                if described ~= placeholder or not name then
                    name = described
                end
            end
        end

        table.insert(list, {
            key   = key,
            type  = goal.type,
            id    = goal.id,
            name  = name,
            since = goal.since or 0,
        })
    end

    table.sort(list, function(a, b)
        if a.since ~= b.since then
            return a.since < b.since
        end

        return tostring(a.key) < tostring(b.key)
    end)

    return list
end

------------------------------------------------------------
-- WHAT IS KNOWN ABOUT GETTING IT
------------------------------------------------------------

-- Everything the addon can say about how to obtain one goal. Deliberately
-- honest: where nothing is known, it says so and names what would make it
-- knowable, rather than inventing a route.
--
-- Returns a table:
--   name, source, mapID, x, y, zone, steps (array of strings),
--   done (boolean), character (string or nil)
function Goals.Plan(goal)
    local plan = {
        name  = goal.name,
        steps = {},
    }

    local types = CN.objectiveTypes

    local function step(text)
        table.insert(plan.steps, text)
    end

    ------------------------------------------------------------
    -- Is it already done?
    ------------------------------------------------------------

    local state, reason = CN.Explain(goal.type, goal.id)

    if state == CN.objectiveStates.COMPLETED then
        plan.done = true

        step(reason or "Already complete.")

        return plan
    end

    ------------------------------------------------------------
    -- Where is it?
    ------------------------------------------------------------

    if goal.type == types.QUEST then
        local quests = CN:GetModule("Quests")

        if quests then
            local mapID, x, y, source = quests.GetLocation(goal.id)

            plan.mapID, plan.x, plan.y = mapID, x, y
            plan.source = source

            if mapID then
                plan.zone = Blizzard.GetMapName(mapID)
            end
        end

        if state == CN.objectiveStates.LOCKED and reason then
            step(reason)
        end
    end

    if goal.type == types.MOUNT then
        local record = CN.Account("mounts")[goal.id]

        if record then
            plan.source = record.source

            if record.isFactionSpecific then
                step("Faction-locked. Only obtainable on one faction.")
            end
        end
    end

    if goal.type == types.PET then
        local record = CN.Account("pets")[goal.id]

        if record and record.isWild then
            step("Wild pet: find and capture it in the world.")
        end
    end

    if goal.type == types.RECIPE then
        local vendors = CN:GetModule("Vendors")

        if vendors then
            local seller = vendors.FirstLocatedSeller(goal.id)

            if seller then
                plan.source = "Sold by " .. tostring(seller.name)
                plan.mapID, plan.x, plan.y = seller.mapID, seller.x, seller.y
                plan.zone = seller.zone

                step("Buy it from " .. tostring(seller.name)
                    .. (seller.zone and (" in " .. seller.zone) or "") .. ".")
            else
                step("No recorded vendor sells this. Open merchants to record them.")
            end
        end
    end

    if goal.type == types.RARE or goal.type == types.TREASURE then
        local record = CN.Account("rares")[goal.id]

        if record then
            plan.mapID, plan.x, plan.y = record.mapID, record.x, record.y
            plan.zone = record.zone

            step("Seen " .. (record.sightings or 1) .. " time"
                .. ((record.sightings or 1) == 1 and "" or "s") .. " here.")
        end
    end

    if goal.type == types.ACHIEVEMENT then
        local record = CN.Account("achievements")[goal.id]

        if record and record.criteria then
            local remaining = (record.criteria or 0) - (record.done or 0)

            step(remaining .. " of " .. record.criteria .. " criteria left.")

            for _, criterion in ipairs(Blizzard.GetIncompleteCriteria(goal.id, 5) or {}) do
                step("Missing: " .. criterion)
            end
        end
    end

    if goal.type == types.REPUTATION then
        local record = CN.Account("reputations")[goal.id]

        if record then
            if record.accountWide then
                step("Account-wide: any character's progress counts.")
            else
                step("Character-specific: progress does not carry across your Warband.")
            end
        end
    end

    ------------------------------------------------------------
    -- Who should do it?
    ------------------------------------------------------------

    local warband = CN:GetModule("Warband")

    if warband then
        local ok, best, _, why = pcall(warband.WhoShould, goal.type, goal.id)

        if ok and best then
            plan.character = best

            step("Best character: " .. tostring(best)
                .. (why and (" (" .. why .. ")") or ""))
        end
    end

    ------------------------------------------------------------
    -- Fall back to honesty.
    ------------------------------------------------------------

    if plan.mapID and plan.x and plan.y then
        step("Location known: " .. (plan.zone or ("map " .. plan.mapID))
            .. string.format(" (%.1f, %.1f)", plan.x * 100, plan.y * 100))
    elseif #plan.steps == 0 then
        step("Nothing is known about how to obtain this yet.")
        step("The addon learns sources from play: open vendors, scan "
            .. "collections, and travel.")
    end

    return plan
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A goal is actionable by definition. Most goals would never surface on their
-- own -- an uncollected mount is not a next action for most people -- which is
-- exactly the point of having said you want it.
CN.RegisterCandidateProvider("Goals", function()
    local candidates = {}

    for _, goal in ipairs(Goals.List()) do
        if not CN.IsIgnored(goal.type, goal.id)
            and not CN.IsDeferred(goal.type, goal.id) then

            local plan = Goals.Plan(goal)

            if not plan.done then
                local reasons = { "you set this as a goal" }

                if plan.source then
                    table.insert(reasons, plan.source)
                end

                local travel

                if plan.mapID then
                    -- Costed like everything else, rather than a flat
                    -- penalty for "not here" while holding the coordinates.
                    travel = CN.TravelCost(plan.mapID, plan.x, plan.y)
                end

                table.insert(candidates, CN.NewObjective({
                    id              = goal.id,
                    type            = goal.type,
                    name            = goal.name,
                    mapID           = plan.mapID,
                    x               = plan.x,
                    y               = plan.y,
                    zone            = plan.zone,
                    accountWide     = true,
                    completionValue = 6,
                    travelCost      = travel,
                    isGoal          = true,
                    reasons         = reasons,
                }))
            end
        end
    end

    return candidates
end, { events = { "ZONE_CHANGED_NEW_AREA" }, cooldown = 2 })

------------------------------------------------------------
-- WEIGHTING
------------------------------------------------------------

-- Anything that leads to a goal is worth more than it would be otherwise.
-- "Leads to" is deliberately narrow -- three relationships the addon can
-- actually establish, rather than a guess dressed up as a plan.
-- Which maps hold an unfinished goal. Rebuilt when the goal list changes,
-- not when a candidate asks.
local goalZones, goalZoneGeneration = nil, -1

local function GoalZones()
    local generation = Goals.zoneGeneration or 0

    if goalZones and goalZoneGeneration == generation then
        return goalZones
    end

    local zones = {}

    for _, goal in ipairs(Goals.List()) do
        local ok, plan = pcall(Goals.Plan, goal)

        if ok and plan and plan.mapID and not plan.done then
            zones[plan.mapID] = true
        end
    end

    goalZones           = zones
    goalZoneGeneration  = generation

    return zones
end

Goals.zoneGeneration = 0

function Goals.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    local store = Store()

    if not store or next(store) == nil then
        return objective
    end

    -- 1. It IS a goal.
    if Goals.IsGoal(objective.type, objective.id) then
        objective.userPreference = (objective.userPreference or 0) + 8

        if not objective.isGoal then
            objective.isGoal  = true
            objective.reasons = objective.reasons or {}
            table.insert(objective.reasons, "this is one of your goals")
        end

        return objective
    end

    -- 2. It unlocks a goal, per the dependency graph.
    if objective.type == CN.objectiveTypes.QUEST then
        local dependency = CN.GetDependency(CN.ObjectiveKey(objective.type, objective.id))

        if dependency and dependency.unlocks then
            for _, unlocked in ipairs(dependency.unlocks) do
                -- Dependency edges are stored as keys, but static data writes
                -- plain quest IDs. Accept both.
                local unlockedID = tonumber(unlocked)
                    or tonumber(tostring(unlocked):match(":(%d+)$"))

                if unlockedID and Goals.IsGoal(CN.objectiveTypes.QUEST, unlockedID) then
                    objective.userPreference = (objective.userPreference or 0) + 5
                    objective.reasons = objective.reasons or {}
                    table.insert(objective.reasons, "unlocks a goal")

                    return objective
                end
            end
        end
    end

    -- 3. It is in the same zone as a located goal. Weak, and weighted weakly:
    --    being in the right place is worth something, but it is not progress.
    --
    -- THE ZONES ARE WORKED OUT ONCE, NOT ONCE PER OBJECTIVE.
    --
    -- This looped every pinned goal and called Goals.Plan inside the
    -- decorator, and the decorator runs once per candidate. Goals.Plan asks
    -- the client for a map name, a vendor location, incomplete criteria and a
    -- Warband verdict -- so ten goals against a few hundred candidates was
    -- thousands of client calls per rebuild, on the path a 0.4x refactor
    -- restructured specifically to stop doing work per objective.
    --
    -- The answer only changes when the goals do, which the invalidation
    -- below already announces.
    if objective.mapID then
        local zones = GoalZones()

        if zones[objective.mapID] then
            objective.userPreference = (objective.userPreference or 0) + 2
            objective.reasons = objective.reasons or {}
            table.insert(objective.reasons, "in the same zone as a goal")

            return objective
        end
    end

    return objective
end

CN.RegisterCandidateDecorator("Goals", Goals.Decorate)

------------------------------------------------------------
-- OUTPUT
------------------------------------------------------------

local function PrintPlan(index, goal)
    local plan = Goals.Plan(goal)

    Print(index .. ". |cffffff00" .. tostring(plan.name) .. "|r"
        .. " |cff999999(" .. tostring(goal.type) .. " " .. tostring(goal.id) .. ")|r"
        .. (plan.done and " |cff00ff00done|r" or ""))

    if plan.source then
        Print("   Source: " .. tostring(plan.source))
    end

    for _, step in ipairs(plan.steps) do
        Print("   - " .. step)
    end

    if plan.character then
        Print("   Best character: |cffffff00" .. tostring(plan.character) .. "|r")
    end

    if plan.mapID and plan.x and plan.y then
        Print("   |cffffff00/cn gogoal " .. index .. "|r to set a waypoint.")
    end
end

Goals.PrintPlan = PrintPlan

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "goal",
    args    = "<type> <id>",
    order   = 12,
    help    = "Pin something as a goal. Types: quest, achievement, mount, pet, toy, recipe, title, rep, rare, currency.",
    handler = function(args)
        local typeText, idText = string.match(CN.Trim(args or ""), "^(%S+)%s+(%S+)$")

        if not typeText then
            Print("Usage: /cn goal <type> <id>")
            Print("|cff999999Types: quest, achievement, mount, pet, toy, recipe, "
                .. "title, rep, rare, currency|r")
            Print("|cffffff00/cn goals|r lists what you have pinned.")
            return
        end

        local objectiveType = ResolveType(typeText)

        if not objectiveType then
            Print("Not a goal type: " .. typeText)
            Print("|cff999999Types: quest, achievement, mount, pet, toy, recipe, "
                .. "title, rep, rare, currency|r")
            return
        end

        local id = CN.ToID(idText)

        if not id then
            Print("Not an ID: " .. idText)
            return
        end

        local added, message = Goals.Add(objectiveType, id)

        if not added then
            Print(message)
            return
        end

        Print("Goal set: |cffffff00" .. tostring(message) .. "|r")
        Print("|cff999999See the path with |cffffff00/cn chase " .. typeText
            .. " " .. idText .. "|r")

        local list = Goals.List()

        for index, goal in ipairs(list) do
            if goal.type == objectiveType and goal.id == id then
                PrintPlan(index, goal)
                break
            end
        end
    end,
}

CN:RegisterCommand{
    name    = "goals",
    order   = 13,
    help    = "List your goals and what is known about reaching them.",
    handler = function()
        local list = Goals.List()

        if #list == 0 then
            Print("No goals set.")
            Print("|cffffff00/cn goal mount 1234|r pins something to work toward.")
            Print("|cff999999A goal becomes actionable even when nothing else "
                .. "would have surfaced it, and anything leading to it ranks higher.|r")
            return
        end

        Print("Goals (" .. #list .. " of " .. Goals.limit .. "):")

        for index, goal in ipairs(list) do
            PrintPlan(index, goal)
        end
    end,
}

CN:RegisterCommand{
    name    = "ungoal",
    args    = "<number or all>",
    order   = 14,
    help    = "Remove a goal.",
    handler = function(args)
        args = CN.Trim(args or "")

        if string.lower(args) == "all" then
            local count = Goals.Clear()

            Print("Cleared " .. count .. " goal" .. (count == 1 and "" or "s") .. ".")
            return
        end

        local index = CN.ToID(args)

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn ungoal <number or all>")

            if #list > 0 then
                Print("|cff999999Numbers come from |cffffff00/cn goals|r.|r")
            end

            return
        end

        local goal = list[index]

        local removed, name = Goals.Remove(goal.type, goal.id)

        if removed then
            Print("Goal removed: " .. tostring(name))
        end
    end,
}

CN:RegisterCommand{
    name    = "gogoal",
    args    = "<number>",
    order   = 15,
    help    = "Navigate to a goal.",
    handler = function(args)
        local index = CN.ToID(CN.Trim(args or ""))

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn gogoal <number>")
            return
        end

        local goal = list[index]
        local plan = Goals.Plan(goal)

        if not (plan.mapID and plan.x and plan.y) then
            Print("No location is known for " .. tostring(plan.name) .. ".")

            for _, step in ipairs(plan.steps) do
                Print("  - " .. step)
            end

            return
        end

        CN.NavigateToObjective({
            id    = goal.id,
            type  = goal.type,
            name  = plan.name,
            mapID = plan.mapID,
            x     = plan.x,
            y     = plan.y,
        })
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Chase.lua'] = @'
-- Modules/Chase.lua
-- Completion Navigator :: what stands between you and the thing you want.
--
-- `/cn goal` has always been able to say "I want that" and re-weight the
-- list accordingly. What it could never say is what the PATH is. A player
-- chasing a mount got a line saying the mount was a goal, and nothing about
-- which four things had to happen first, how many of them were already done,
-- or which one to go and do now.
--
-- This is that path. Chase turns a goal into an ordered chain of steps, each
-- one carrying a state -- done, next, blocked, or simply outstanding -- and,
-- where the game will tell us, a real count.
--
-- ON NUMBERS. The addon's standing rule is that it does not invent a
-- denominator. That rule is doing real work here, because a progress bar is
-- exactly the kind of thing that begs to be faked. So:
--
--   * Achievement criteria, appearance sources, and reputation standing have
--     denominators the client vouches for. Those get a fraction.
--   * A mount whose source is a sentence of English does not. It gets the
--     sentence, and no bar.
--
-- Showing "1 of 1 steps" for something we know nothing about would be a lie
-- told in a font that looks like a fact.

local ADDON_NAME, CN = ...

local Chase = CN:RegisterModule("Chase")

local Print = CN.Print

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STEP STATES
------------------------------------------------------------

-- Ordered by how much the player needs to look at them.
Chase.states = {
    NEXT    = "NEXT",     -- go and do this one
    TODO    = "TODO",     -- outstanding, but not the immediate move
    BLOCKED = "BLOCKED",  -- cannot be done yet, and we know why
    DONE    = "DONE",     -- already behind you
    NOTE    = "NOTE",     -- context, not a step
}

Chase.stateLabels = {
    NEXT    = "next",
    TODO    = "to do",
    BLOCKED = "blocked",
    DONE    = "done",
    NOTE    = "",
}

Chase.stateColors = {
    NEXT    = { 0.365, 0.824, 0.984 },
    TODO    = { 0.85, 0.85, 0.85 },
    BLOCKED = { 0.96, 0.42, 0.38 },
    DONE    = { 0.45, 0.72, 0.45 },
    NOTE    = { 0.6, 0.6, 0.6 },
}

local function NewStep(state, text, extra)
    local step = extra or {}

    step.state = state
    step.text  = text

    return step
end

------------------------------------------------------------
-- PER-TYPE CHAINS
------------------------------------------------------------

-- Each builder returns steps and, optionally, a progress table:
--   { done = n, total = m, unit = "criteria" }
--
-- Returning no progress table is a positive statement -- "the game does not
-- give me a trustworthy count here" -- not an oversight.

local builders = {}

builders.ACHIEVEMENT = function(goal)
    local steps = {}

    local criteria = Blizzard.GetAchievementCriteriaList(goal.id, 25) or {}

    if #criteria == 0 then
        return steps, nil
    end

    local done = 0
    local first = true

    for _, criterion in ipairs(criteria) do
        local text = criterion.description

        -- Some criteria carry their own counter. Where they do, it is the
        -- most useful thing on the line.
        if criterion.required and criterion.required > 1 and criterion.quantity then
            text = string.format("%s (%d/%d)",
                text, criterion.quantity, criterion.required)
        end

        if criterion.completed then
            done = done + 1

            table.insert(steps, NewStep(Chase.states.DONE, text))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, text))
        end
    end

    return steps, { done = done, total = #criteria, unit = "criteria" }
end

builders.REPUTATION = function(goal)
    local steps = {}

    local standing = Blizzard.GetReputationRemaining(goal.id)

    if not standing then
        return steps, nil
    end

    if Blizzard.IsAccountWideReputation(goal.id) then
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Account-wide: any character's progress counts."))
    else
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Character-specific: progress does not carry across your Warband."))
    end

    table.insert(steps, NewStep(Chase.states.NEXT, string.format(
        "%s reputation to the next rank", CN.Comma(standing.remaining))))

    -- NO FRACTION, BECAUSE THIS ONE IS NOT A FRACTION OF THE GOAL.
    --
    -- `earned` and `needed` describe the CURRENT RANK ONLY -- how far into
    -- Honored you are, not how far along the ladder to Exalted. Returning
    -- them as done/total made `/cn chase` draw a full bar and print "100%"
    -- for somebody standing at 21,000 of the 42,000 the ladder needs, and
    -- made `Chase.All` -- which sorts by exactly that fraction -- rank a
    -- faction one point short of Honored above an appearance genuinely eighty
    -- percent collected.
    --
    -- The client will vouch for progress inside a band and not for progress
    -- across the ladder, so the band is reported as a count, with the rank
    -- named, and no denominator is invented for the rest. That is this
    -- addon's standing rule, applied to the one place that was breaking it
    -- most visibly.
    return steps, {
        done         = nil,
        total        = nil,
        unit         = "reputation",
        bandEarned   = standing.earned,
        bandNeeded   = standing.needed,
        nextRank     = standing.nextRankName,
        unknownTotal = "the client reports progress inside a rank, not "
            .. "across the whole standing",
    }
end

builders.APPEARANCE = function(goal)
    local steps = {}

    local sources = Blizzard.GetAppearanceSources(goal.id) or {}

    if #sources == 0 then
        return steps, nil
    end

    local collected = 0
    local first = true

    for _, source in ipairs(sources) do
        local name = source.name or ("item " .. tostring(source.itemID or "?"))

        if source.collected then
            collected = collected + 1

            table.insert(steps, NewStep(Chase.states.DONE, name))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, name, { itemID = source.itemID }))
        end
    end

    -- An appearance needs ONE of its sources, not all of them, so the count
    -- is deliberately not offered as progress toward the appearance. Saying
    -- "1 of 9" would suggest eight more to go when in fact you are finished.
    table.insert(steps, 1, NewStep(Chase.states.NOTE,
        collected > 0
            and "Collected. Any one source is enough."
            or string.format("Any ONE of these %d sources unlocks it.", #sources)))

    return steps, nil
end

builders.QUEST = function(goal)
    local steps = {}

    local dependencies = CN.GetPrerequisites and CN.GetPrerequisites(goal.id)

    if type(dependencies) ~= "table" or #dependencies == 0 then
        return steps, nil
    end

    local done = 0
    local first = true

    for _, questID in ipairs(dependencies) do
        local name = Blizzard.GetQuestTitle(questID, true)
            or ("Quest " .. tostring(questID))

        if CN.IsQuestComplete and CN.IsQuestComplete(questID) then
            done = done + 1

            table.insert(steps, NewStep(Chase.states.DONE, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        end
    end

    return steps, { done = done, total = #dependencies, unit = "prerequisites" }
end

Chase.builders = builders

-- Which goals are worth asking the Adventure Guide about. A reputation does
-- not drop from a boss, and searching for one costs a journal round-trip to
-- learn nothing.
Chase.instanceSourceTypes = {
    [CN.objectiveTypes.MOUNT]      = true,
    [CN.objectiveTypes.PET]        = true,
    [CN.objectiveTypes.TOY]        = true,
    [CN.objectiveTypes.APPEARANCE] = true,
    [CN.objectiveTypes.TITLE]      = true,
}

------------------------------------------------------------
-- THE CHAIN
------------------------------------------------------------

-- The full picture for one goal: where it is, what remains, how far along
-- you are, and which single step to go and do.
function Chase.Chain(goal)
    local chain = {
        name  = goal and goal.name,
        type  = goal and goal.type,
        id    = goal and goal.id,
        steps = {},
    }

    if type(goal) ~= "table" or not goal.type or not goal.id then
        return chain
    end

    local goals = CN:GetModule("Goals")

    -- Location, source and "who should do it" already exist. Reuse them
    -- rather than growing a second, subtly different answer.
    local plan = goals and goals.Plan(goal) or {}

    chain.done      = plan.done
    chain.source    = plan.source
    chain.mapID     = plan.mapID
    chain.x         = plan.x
    chain.y         = plan.y
    chain.zone      = plan.zone
    chain.character = plan.character

    if chain.done then
        table.insert(chain.steps, NewStep(Chase.states.DONE, "Already complete."))

        chain.progress = { done = 1, total = 1, unit = "steps" }

        return chain
    end

    local builder = builders[goal.type]

    if builder then
        local ok, steps, progress = pcall(builder, goal)

        if ok and type(steps) == "table" then
            chain.steps    = steps
            chain.progress = progress
        end
    end

    -- IF IT DROPS FROM A BOSS, SAY WHICH BOSS.
    --
    -- Before this, a raid mount produced a chain whose only content was the
    -- mount journal's source line -- prose, no boss, no instance, and no idea
    -- whether the player was already locked out of the thing this week. That
    -- is the one failure this feature exists to prevent: a goal with no path
    -- to it.
    --
    -- Deliberately additive. The step is appended to whatever the builder
    -- produced rather than replacing it, because the journal's answer is a
    -- location and the builder's answer is the requirement, and a player
    -- needs both.
    local instances = CN:GetModule("Instances")

    if instances and chain.name and Chase.instanceSourceTypes[goal.type] then
        local ok, description, first = pcall(instances.DescribeSource, chain.name)

        if ok and description and first then
            local lockout = first.instance and instances.LockoutFor(first.instance)

            if lockout and lockout.complete then
                table.insert(chain.steps, NewStep(Chase.states.BLOCKED,
                    "Drops from " .. description,
                    {
                        note = "you are saved to " .. first.instance
                            .. " and it is cleared -- resets in "
                            .. instances.FormatReset(lockout.resetsIn),
                    }))
            else
                local state = Chase.states.TODO

                -- Only claim the immediate move if nothing else has.
                if not Chase.NextStep(chain) then
                    state = Chase.states.NEXT
                end

                local step = NewStep(state, "Kill " .. description, {
                    encounterID = first.encounterID,
                    instanceID  = first.instanceID,
                })

                if lockout then
                    step.note = lockout.remaining .. " of " .. lockout.encounters
                        .. " left on your lockout"
                end

                table.insert(chain.steps, step)
            end
        end
    end

    -- Nothing structured? Fall back to what the existing planner knows, which
    -- is prose rather than a chain -- and say so, rather than dressing a
    -- sentence up as a step.
    if #chain.steps == 0 then
        for _, text in ipairs(plan.steps or {}) do
            table.insert(chain.steps, NewStep(Chase.states.NOTE, text))
        end

        if chain.mapID and chain.x and chain.y then
            table.insert(chain.steps, 1,
                NewStep(Chase.states.NEXT, "Travel to " ..
                    (chain.zone or ("map " .. tostring(chain.mapID))), {
                    mapID = chain.mapID,
                    x     = chain.x,
                    y     = chain.y,
                }))
        end
    end

    chain.next = Chase.NextStep(chain)

    return chain
end

-- The one step to go and do. Nil when everything outstanding is blocked or
-- unknown, which is itself worth saying out loud.
function Chase.NextStep(chain)
    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.NEXT then
            return step
        end
    end

    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.TODO then
            return step
        end
    end

    return nil
end

-- A single line for chat: where you are, and what to do about it.
function Chase.Summarize(chain)
    if not chain or not chain.name then
        return "Nothing to chase."
    end

    if chain.done then
        return tostring(chain.name) .. " is complete."
    end

    local parts = {}

    if chain.progress and chain.progress.total and chain.progress.total > 0 then
        table.insert(parts, string.format("%s of %s %s",
            CN.Comma(chain.progress.done or 0),
            CN.Comma(chain.progress.total),
            chain.progress.unit or "steps"))

    elseif chain.progress and chain.progress.bandNeeded then
        -- A band with the rank named, rather than a fraction of the goal
        -- that the client will not vouch for. "11,999 of 12,000 to Revered"
        -- is a fact; "100%" of a half-finished ladder is not.
        table.insert(parts, string.format("%s of %s %s%s",
            CN.Comma(chain.progress.bandEarned or 0),
            CN.Comma(chain.progress.bandNeeded),
            chain.progress.unit or "steps",
            chain.progress.nextRank
                and (" to " .. tostring(chain.progress.nextRank)) or ""))
    end

    local nextStep = chain.next or Chase.NextStep(chain)

    if nextStep then
        table.insert(parts, "next: " .. tostring(nextStep.text))
    elseif #parts == 0 then
        return tostring(chain.name)
            .. " -- the game does not say how this is obtained."
    end

    return tostring(chain.name) .. " -- " .. table.concat(parts, ", ")
end

-- Percent complete, or nil. Nil is a real answer and callers must render it
-- as "unknown" rather than as zero.
function Chase.Fraction(chain)
    local progress = chain and chain.progress

    if not progress or not progress.total or progress.total <= 0 then
        return nil
    end

    local fraction = (progress.done or 0) / progress.total

    if fraction < 0 then return 0 end
    if fraction > 1 then return 1 end

    return fraction
end

-- Every goal, chained, with the NEAREST-FINISHED first.
--
-- The header used to say the opposite -- "least-finished first: the thing you
-- are furthest from is the thing most in need of a plan" -- while the
-- comparator eight lines below, and its own inline comment, did and described
-- the reverse. Two comments in one function, disagreeing.
--
-- The code is right and the header was wrong. Everything else in this addon
-- ranks the nearly-finished thing above the barely-begun one: a set two
-- pieces short, a quest three kills from done, a lockout part-way through.
-- A goal you are eighty percent through is the one worth an evening; one you
-- have not started is a decision, not a next action.
function Chase.All()
    local goals = CN:GetModule("Goals")

    if not goals then
        return {}
    end

    local chains = {}

    for _, goal in ipairs(goals.List()) do
        table.insert(chains, Chase.Chain(goal))
    end

    table.sort(chains, function(a, b)
        local left  = Chase.Fraction(a)
        local right = Chase.Fraction(b)

        -- Finished goals sink. Unmeasurable ones sit between measurable
        -- progress and completion, because "no idea" is more actionable than
        -- "done" and less actionable than "you are 80% there".
        local leftDone  = a.done and 1 or 0
        local rightDone = b.done and 1 or 0

        if leftDone ~= rightDone then
            return leftDone < rightDone
        end

        if left and right then
            return left > right
        end

        if left or right then
            return left ~= nil
        end

        return tostring(a.name) < tostring(b.name)
    end)

    return chains
end

------------------------------------------------------------
-- NAVIGATION
------------------------------------------------------------

-- Go to the next step of a chain, not to the goal itself.
--
-- Those differ, and the difference is the whole point: the mount is in a
-- dungeon you cannot enter yet, but the attunement quest is forty yards away.
function Chase.NavigateNext(chain)
    local step = chain and (chain.next or Chase.NextStep(chain))

    if step and step.objectiveType and step.objectiveID then
        local located = CN.FindCandidate
            and CN.FindCandidate(step.objectiveType, step.objectiveID)

        if located then
            return CN.NavigateToObjective(located)
        end
    end

    if step and step.mapID and step.x and step.y then
        return CN.SetWaypoint(step.mapID, step.x, step.y, step.text)
    end

    if chain and chain.mapID and chain.x and chain.y then
        return CN.SetWaypoint(chain.mapID, chain.x, chain.y, chain.name)
    end

    Print("No location is known for the next step of "
        .. tostring(chain and chain.name or "that goal") .. ".")

    return false
end

------------------------------------------------------------
-- HOW LONG IS THIS GOING TO TAKE
------------------------------------------------------------

-- The addon already measures two things and never multiplied them together:
-- how long each kind of objective takes this player (Session, from watching)
-- and how long it takes to get anywhere (Travel, from flight paths and
-- measured speed). A chain is a list of steps of known types in known places.
--
-- RULES, WHICH ARE THE SAME RULES AS EVERYWHERE ELSE IN THIS ADDON.
--
--   * A step whose type has never been timed is COUNTED as unknown, reported
--     as such, and charged at the average of the steps that have been timed
--     -- because it still has to happen, and pretending it is free would
--     understate the chain rather than widen the range.
--   * The result is a RANGE, not a figure. Anybody who has played knows that
--     "four hours" is a claim nobody can make; "three to six hours" is one
--     the data actually supports.
--   * If more steps are unknown than known, no estimate is offered at all.
--     Half an answer stated confidently is worse than "not enough to say".

-- How wide the range is either side of the estimate. Chosen to be honest
-- rather than flattering: task times in this game vary by more than a third
-- depending on competition for mobs, group size and luck.
Chase.estimateSpread = 0.4

-- Below this proportion of steps timed, say nothing.
Chase.estimateCoverage = 0.5

function Chase.Estimate(chain)
    if type(chain) ~= "table" or #(chain.steps or {}) == 0 then
        return nil
    end

    local session = CN:GetModule("Session")

    if not session or not session.TypicalSeconds then
        return nil
    end

    local seconds, timed, unknown = 0, 0, 0

    for _, step in ipairs(chain.steps) do
        -- Notes are context and done steps are behind you; neither is work.
        if step.state ~= Chase.states.DONE and step.state ~= Chase.states.NOTE then
            local objectiveType = step.objectiveType or chain.type

            local typical = objectiveType and session.TypicalSeconds(objectiveType)

            if typical then
                seconds = seconds + typical
                timed   = timed + 1
            else
                unknown = unknown + 1
            end
        end
    end

    local outstanding = timed + unknown

    if outstanding == 0 then
        return nil
    end

    -- TRAVEL, LEG BY LEG (0.43.0).
    --
    -- The first version costed one journey -- player to the next step -- and
    -- said so. That understated any chain whose steps are in different
    -- places, which is most of them: a chain across three zones is three
    -- journeys, and pretending it is one makes the estimate confidently short
    -- in exactly the cases where the player most needs it to be right.
    --
    -- Walked in the order the steps are listed, which is the order the addon
    -- would route them, starting from where the player actually is. Steps
    -- with no location contribute no travel rather than a guessed hop.
    local travelSeconds = 0

    local travel = CN:GetModule("Travel")

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    if travel and playerMap then
        -- NEAREST-FIRST, not listed-order.
        --
        -- 0.42.0 costed one journey; 0.43.0 costed every leg but walked them
        -- in the order the steps happened to be listed, which is the order a
        -- criteria list came back in -- no relation to geography. On a chain
        -- whose steps are scattered that overstates the total badly.
        --
        -- This is the same greedy nearest-neighbour walk the zone router
        -- uses, and it is an ESTIMATE either way: the point is not to find
        -- the optimal tour, it is to stop pretending the player will walk a
        -- deliberately silly one.
        local pending = {}

        for _, step in ipairs(chain.steps) do
            if step.state ~= Chase.states.DONE
                and step.state ~= Chase.states.NOTE then

                local toMap = step.mapID or chain.mapID
                local toX   = step.x or chain.x
                local toY   = step.y or chain.y

                if toMap and toX and toY then
                    table.insert(pending, { mapID = toMap, x = toX, y = toY })
                end
            end
        end

        local fromMap, fromX, fromY = playerMap, playerX, playerY

        while #pending > 0 and fromX do
            local bestIndex, bestSeconds

            for index, target in ipairs(pending) do
                local leg = travel.EstimateSeconds(
                    fromMap, fromX, fromY, target.mapID, target.x, target.y)

                if leg and (not bestSeconds or leg < bestSeconds) then
                    bestIndex, bestSeconds = index, leg
                end
            end

            if not bestIndex then
                break
            end

            local chosen = table.remove(pending, bestIndex)

            travelSeconds = travelSeconds + bestSeconds

            fromMap, fromX, fromY = chosen.mapID, chosen.x, chosen.y
        end
    end

    if timed == 0 or (timed / outstanding) < Chase.estimateCoverage then
        return {
            seconds     = nil,
            timed       = timed,
            unknown     = unknown,
            travel      = travelSeconds,
            enough      = false,
        }
    end

    -- Steps that have never been timed still have to happen. Charging them at
    -- the average of the ones that have is the least-wrong option available,
    -- and it widens the range rather than hiding in it.
    --
    -- The RULES block at the top of this section used to say the opposite --
    -- that an untimed step "contributes nothing" -- which would have meant
    -- quoting four hours for a chain whose second half the addon has simply
    -- never watched. The guard that makes this honest is the one above: no
    -- estimate at all is offered unless more steps are timed than are not,
    -- and the count of untimed ones is reported alongside the number.
    local perStep = seconds / timed

    local total = seconds + (unknown * perStep) + travelSeconds

    return {
        seconds = total,
        low     = total * (1 - Chase.estimateSpread),
        high    = total * (1 + Chase.estimateSpread),
        timed   = timed,
        unknown = unknown,
        travel  = travelSeconds,
        enough  = true,
    }
end

function Chase.DescribeEstimate(chain)
    local estimate = Chase.Estimate(chain)

    if not estimate then
        return nil
    end

    local session = CN:GetModule("Session")

    local function format(seconds)
        return session and session.FormatDuration
            and session.FormatDuration(seconds)
            or (math.floor((seconds or 0) / 60) .. "m")
    end

    if not estimate.enough then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time |cff999999-- "
            .. estimate.unknown .. " of "
            .. (estimate.timed + estimate.unknown)
            .. " steps are kinds of thing this addon has not watched you do "
            .. "often enough to time|r"
    end

    local text = "roughly " .. format(estimate.low) .. " to " .. format(estimate.high)

    if estimate.travel > 60 then
        text = text .. " |cff999999including " .. format(estimate.travel)
            .. " to get there|r"
    end

    if estimate.unknown > 0 then
        text = text .. " |cff999999(" .. estimate.unknown
            .. " step(s) untimed, charged at the rate of the rest)|r"
    end

    return text
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintChain(chain)
    Print(Chase.Summarize(chain))

    local fraction = Chase.Fraction(chain)

    if fraction then
        Print(string.format("  |cff5dd2fb%s|r %d%%",
            CN.ProgressBar and CN.ProgressBar(fraction, 20) or "",
            math.floor(fraction * 100 + 0.5)))
    end

    local shown = 0

    for _, step in ipairs(chain.steps) do
        if shown >= 12 then
            Print("  |cff999999... and " .. (#chain.steps - shown) .. " more|r")
            break
        end

        local label = Chase.stateLabels[step.state] or ""

        local colour = "|cffcccccc"

        if step.state == Chase.states.DONE then
            colour = "|cff73b873"
        elseif step.state == Chase.states.NEXT then
            colour = "|cff5dd2fb"
        elseif step.state == Chase.states.BLOCKED then
            colour = "|cfff56b61"
        elseif step.state == Chase.states.NOTE then
            colour = "|cff999999"
        end

        Print(string.format("  %s%s%s|r",
            colour,
            label ~= "" and ("[" .. label .. "] ") or "",
            step.text))

        shown = shown + 1
    end

    local estimate = Chase.DescribeEstimate(chain)

    if estimate then
        Print("  |cffffd100Time:|r " .. estimate)
    end

    if chain.character then
        Print("  |cff999999Best character: " .. tostring(chain.character) .. "|r")
    end
end

Chase.PrintChain = PrintChain

CN:RegisterCommand{
    name    = "chase",
    aliases = { "chain", "path" },
    args    = "[type id, or nothing for all goals]",
    order   = 16,
    help    = "Show what stands between you and a goal, step by step.",
    handler = function(args)
        args = CN.Trim(args or "")

        local goals = CN:GetModule("Goals")

        if not goals then
            Print("The Goals module is not loaded.")
            return
        end

        if args ~= "" then
            local typeText, idText = string.match(args, "^(%S+)%s+(%S+)$")

            local objectiveType = typeText and goals.ResolveType(typeText)
            local id            = idText and CN.ToID(idText)

            if not objectiveType or not id then
                Print("Usage: |cffffff00/cn chase <type> <id>|r"
                    .. "   e.g. /cn chase mount 1234")
                Print("|cff999999Types: quest, achievement, mount, pet, toy, "
                    .. "recipe, title, rep, rare, currency|r")
                return
            end

            -- Chasing something you have not pinned pins it. Asking for the
            -- path to a thing is the clearest possible statement that you
            -- want it, and making the player run two commands to say so once
            -- is the addon being pedantic at the player's expense.
            if not goals.IsGoal(objectiveType, id) then
                goals.Add(objectiveType, id)
            end

            for _, goal in ipairs(goals.List()) do
                if goal.type == objectiveType and goal.id == id then
                    PrintChain(Chase.Chain(goal))
                    return
                end
            end

            Print("Could not pin that as a goal.")
            return
        end

        local chains = Chase.All()

        if #chains == 0 then
            Print("Nothing pinned. Try |cffffff00/cn chase mount 1234|r, or")
            Print("|cffffff00/cn goal <type> <id>|r to pin something first.")
            return
        end

        for _, chain in ipairs(chains) do
            PrintChain(chain)
        end
    end,
}

return Chase
'@

$Embedded['Modules\Progress.lua'] = @'
-- Modules/Progress.lua
-- Completion Navigator :: how much you have actually done.
--
-- REPORTED FROM LIVE PLAY: "It doesn't show how many quests I've completed
-- anymore, which I kinda liked seeing. But my first weekend, I did 350+
-- quests, so I think I can definitely do even more."
--
-- That is the whole design brief in two sentences, and the second one is the
-- important half. He is not asking for a statistic. He is asking for the
-- thing that made him want to beat his own number -- and 0.26.1 took it away
-- while fixing something else, which is a fair trade only if it comes back
-- better.
--
-- Better means: a number the client will vouch for, rather than a count of
-- rows this addon happened to write. `C_QuestLog.GetAllCompletedQuestIDs`
-- returns every quest this character has ever finished. That is the real
-- lifetime total, it is correct on a fresh install with no scan history, and
-- it does not saturate.
--
-- On top of it, the numbers that make a session feel like progress: what you
-- have done since you logged in, what you have done today, and the rate.
-- Those the addon does have to keep itself, so they are stored per character
-- and reset on the game's own clock rather than on a timer of our invention.

local ADDON_NAME, CN = ...

local Progress = CN:RegisterModule("Progress")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function Store()
    local character = CN.character

    if not character then
        return nil
    end

    character.progress = character.progress or {}

    return character.progress
end

Progress.Store = Store

-- Where the session began. Held in memory only: a session is by definition
-- the thing that ends when you log out.
local sessionStart = {
    completed = nil,
    at        = nil,
}

------------------------------------------------------------
-- THE REAL TOTAL
------------------------------------------------------------

-- Lifetime quests completed by this character, straight from the client.
-- Nil, not zero, when the client will not say -- an unknown total and a
-- total of none are different facts.
--
-- CACHED, and it needed to be.
--
-- `C_QuestLog.GetAllCompletedQuestIDs` does not hand back a number. It builds
-- and returns a table containing every quest the character has ever finished
-- -- tens of thousands of entries for anyone who has played a while, and this
-- addon is aimed squarely at people who have. The Journey tab called it on
-- every refresh to display one integer, allocating and discarding the
-- player's entire quest history to count it.
--
-- The count only changes when a quest is turned in, and the addon already
-- gets told when that happens. So: read it once, keep the number, and throw
-- the cache away on the event that can change it.
-- INVALIDATION, and a trap I walked into while writing it.
--
-- The obvious event list is "anything that could change the count", which
-- includes QUEST_LOG_UPDATE. That event fires many times a second during
-- normal play, so hooking it handed the entire saving straight back -- the
-- benchmark went from 0.000ms to 0.244ms, which is to say back to uncached.
-- A cache invalidated by a firehose is not a cache.
--
-- So: invalidate precisely on the events that certainly change the number,
-- and bound the staleness for anything that slips through. A count that is
-- at most a minute out of date is not a problem; a count that costs the
-- player's entire quest history to display is.
local lifetimeCache = { value = nil, valid = false, at = 0 }

Progress.lifetimeMaxAgeSeconds = 60

function Progress.InvalidateLifetime()
    lifetimeCache.valid = false
    lifetimeCache.value = nil
end

function Progress.LifetimeCompleted()
    if lifetimeCache.valid
        and (time() - lifetimeCache.at) < Progress.lifetimeMaxAgeSeconds then

        return lifetimeCache.value
    end

    local ids = Blizzard.GetAllCompletedQuestIDs()

    -- A nil answer is cached too. The client refusing to say is a stable
    -- fact for the moment, and re-asking on every refresh in the hope of a
    -- different answer is the same waste with extra steps.
    lifetimeCache.value = ids and #ids or nil
    lifetimeCache.valid = true
    lifetimeCache.at    = time()

    return lifetimeCache.value
end

------------------------------------------------------------
-- DAY BOUNDARIES
------------------------------------------------------------

-- "Today" means the game's day, which turns over at the daily reset rather
-- than at your local midnight. Using local midnight would show a player a
-- number that disagrees with everything else the game tells them.
function Progress.CurrentDayKey()
    local seconds = Blizzard.GetSecondsUntilDailyReset()

    -- BOTH BRANCHES ON THE SAME SCALE.
    --
    -- The fallback returned `20260822` where the primary returns about
    -- `20687` -- a day index and a calendar number, two different kinds of
    -- integer. One nil answer from the client, which happens during a loading
    -- screen or early in a login, read as a day rollover: the player's count
    -- for today was moved into "yesterday" mid-session and today restarted at
    -- one. The next genuine reset then compared against a key on the wrong
    -- scale and did it again.
    --
    -- Without the reset time the day boundary is unknowable, so the fallback
    -- uses the same day-index arithmetic with no offset. It can be off by
    -- one against the game's day; it cannot be off by six orders of
    -- magnitude.
    if not seconds then
        return math.floor(time() / 86400)
    end

    -- The reset that is coming, as an absolute time, identifies the day
    -- unambiguously without needing to know the server's timezone.
    return math.floor((time() + seconds) / 86400)
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

-- Called when the client tells us a quest was turned in.
function Progress.NoteCompleted(questID)
    local store = Store()

    if not store then
        return
    end

    local today = Progress.CurrentDayKey()

    if store.dayKey ~= today then
        -- A new day. Keep yesterday so "yesterday you did 84" is possible
        -- later, but do not accumulate an unbounded history.
        store.previousDay      = store.today or 0
        store.previousDayKey   = store.dayKey
        store.today            = 0
        store.dayKey           = today
    end

    store.today   = (store.today or 0) + 1
    store.session = (store.session or 0) + 1
    store.total   = (store.total or 0) + 1

    if (store.best or 0) < store.today then
        store.best    = store.today
        store.bestDay = today
    end

    DebugPrint("Quest " .. tostring(questID) .. " completed; "
        .. store.today .. " today.")
end

function Progress.BeginSession()
    local store = Store()

    if store then
        store.session = 0

        -- Roll the day over at login too, so a player who logs in the next
        -- morning does not see yesterday's number labelled "today".
        local today = Progress.CurrentDayKey()

        if store.dayKey ~= today then
            store.previousDay    = store.today or 0
            store.previousDayKey = store.dayKey
            store.today          = 0
            store.dayKey         = today
        end
    end

    sessionStart.completed = Progress.LifetimeCompleted()
    sessionStart.at        = time()
end

------------------------------------------------------------
-- THE NUMBERS
------------------------------------------------------------

-- Everything worth showing, in one table. Fields are nil rather than zero
-- when the client has not answered, so callers can tell the difference.
function Progress.Summary()
    local store = Store() or {}

    local summary = {
        lifetime = Progress.LifetimeCompleted(),
        today    = store.today or 0,
        session  = store.session or 0,
        best     = store.best or 0,
        previous = store.previousDay,
    }

    -- Prefer the client's own delta for the session where we have it: it
    -- counts quests completed by any means, including ones the addon did not
    -- see an event for.
    if sessionStart.completed and summary.lifetime then
        local delta = summary.lifetime - sessionStart.completed

        if delta >= 0 then
            summary.session = math.max(summary.session, delta)
        end
    end

    if sessionStart.at then
        summary.sessionSeconds = time() - sessionStart.at

        -- A rate needs enough time behind it to mean anything. Five minutes
        -- in, "240 quests per hour" is arithmetic, not information.
        if summary.sessionSeconds >= 600 and summary.session > 0 then
            summary.perHour = summary.session / (summary.sessionSeconds / 3600)
        end
    end

    return summary
end

function Progress.Describe()
    local summary = Progress.Summary()

    local parts = {}

    if summary.lifetime then
        table.insert(parts, CN.Comma(summary.lifetime) .. " quests completed")
    end

    table.insert(parts, summary.today .. " today")

    if summary.session > 0 and summary.session ~= summary.today then
        table.insert(parts, summary.session .. " this session")
    end

    if summary.perHour then
        table.insert(parts, string.format("%.0f/hour", summary.perHour))
    end

    return table.concat(parts, ", ")
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Progress.InvalidateLifetime()

    Progress.NoteCompleted(questID)
end)

-- Abandoning a quest cannot lower the completed count, but a fresh login on
-- a different character certainly changes it, and so does the client
-- finishing its initial data load.
CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    Progress.InvalidateLifetime()
end)

-- Deliberately NOT hooked to QUEST_LOG_UPDATE. See the note on the cache:
-- that event fires constantly and hooking it removed the entire benefit.
-- Anything completed by a route the addon cannot see is picked up by the
-- staleness bound instead.

CN:OnLogin(function()
    Progress.BeginSession()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "progress",
    aliases = { "done", "stats" },
    order   = 11,
    help    = "How many quests you have completed: lifetime, today, this session.",
    handler = function()
        local summary = Progress.Summary()

        if summary.lifetime then
            Print("|cffffd100" .. CN.Comma(summary.lifetime)
                .. "|r quests completed on this character.")
        else
            Print("The client will not report a lifetime total right now.")
        end

        Print("Today: |cffffff00" .. summary.today .. "|r"
            .. (summary.best > 0 and ("   |cff999999best day: "
                .. summary.best .. "|r") or ""))

        if summary.session > 0 then
            local line = "This session: |cffffff00" .. summary.session .. "|r"

            if summary.perHour then
                line = line .. string.format(
                    "   |cff999999%.0f per hour|r", summary.perHour)
            end

            Print(line)
        end

        if summary.previous then
            Print("|cff999999Previous day: " .. summary.previous .. "|r")
        end
    end,
}

return Progress
'@

$Embedded['Modules\Loremaster.lua'] = @'
-- Modules/Loremaster.lua
-- Completion Navigator :: finishing zones, continents and expansions.
--
-- FROM A PLAYER'S OWN STATED PLAN:
--
--   "Once I finish the story this weekend, I'm gonna do all the side quests
--    on the continent I'm currently on. Then I'll move from one continent to
--    another. After that, I'm gonna switch timelines and work backwards to
--    the previous expansion... Basically, I'm gonna try to complete every
--    main quest and side quest in the entire game."
--
-- That is a two-year project measured in zones and continents, and the addon
-- had nothing to say about it. It could tell him what to do in the next
-- hundred yards and nothing about where he was in the campaign.
--
-- THE DENOMINATOR PROBLEM, AND WHY THIS WORKS ANYWAY.
--
-- The client will not tell you how many quests exist in a zone. Counting
-- "quests I know about" would produce a denominator that grows as you play,
-- so your percentage would go DOWN as you did more -- which is worse than no
-- percentage at all, and this addon has a standing rule against inventing
-- one.
--
-- But the game already ships the exact tracker this player needs: the quest
-- achievements. "Loremaster of Khaz Algar", the per-zone story achievements,
-- the exploration-style quest counts. Those have criteria the client
-- enumerates and vouches for. So the progress here is real, and it is real
-- because we did not compute it -- we read it.

local ADDON_NAME, CN = ...

local Loremaster = CN:RegisterModule("Loremaster")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

-- Blizzard's "Quests" achievement category. A stable constant for many
-- years, and everything below degrades to "nothing found" rather than to an
-- error if it ever moves.
Loremaster.questCategoryID = 96

------------------------------------------------------------
-- THE CATEGORY TREE
------------------------------------------------------------

-- Every category descending from Quests: one per expansion, and below those,
-- per continent. Walked rather than hardcoded, so a new expansion needs no
-- code.
function Loremaster.QuestCategories()
    local categories = {}

    if not GetCategoryList or not GetCategoryInfo then
        return categories
    end

    local ok, list = pcall(GetCategoryList)

    if not ok or type(list) ~= "table" then
        return categories
    end

    -- Parentage is only one level per lookup, so resolve to a root by
    -- walking upward. Cheap: the tree is three deep at most.
    local function rootOf(categoryID)
        local guard = 0
        local current = categoryID

        while current and guard < 8 do
            local name, parent = GetCategoryInfo(current)

            if not name then
                return nil
            end

            if current == Loremaster.questCategoryID then
                return current
            end

            if not parent or parent <= 0 then
                return nil
            end

            current = parent
            guard   = guard + 1
        end

        return nil
    end

    for _, categoryID in ipairs(list) do
        if rootOf(categoryID) == Loremaster.questCategoryID then
            local name, parent = GetCategoryInfo(categoryID)

            table.insert(categories, {
                categoryID = categoryID,
                name       = name,
                parentID   = parent,
            })
        end
    end

    return categories
end

------------------------------------------------------------
-- SCANNING
------------------------------------------------------------

local function Records()
    return CN.Account("loremaster")
end

Loremaster.Records = Records

-- Reads every quest achievement and stores what the client says about it.
-- Stored rather than recomputed because walking the achievement tree is not
-- something to do on every frame, and because it lets the Warband view show
-- what other characters have finished.
function Loremaster.Scan()
    local store = Records()

    local scanned = 0

    for _, category in ipairs(Loremaster.QuestCategories()) do
        local total = select(1, Blizzard.GetCategoryCounts(category.categoryID))

        for index = 1, (total or 0) do
            local achievement = Blizzard.GetAchievementInCategory(
                category.categoryID, index)

            if achievement and achievement.achievementID then
                local id = achievement.achievementID

                local done, criteria = Blizzard.GetAchievementProgress(id)

                store[id] = {
                    name      = achievement.name,
                    category  = category.name,
                    completed = achievement.completed and true or false,
                    done      = done,
                    criteria  = criteria,
                }

                scanned = scanned + 1
            end
        end
    end

    CN.MarkScanned("loremaster")

    DebugPrint("Loremaster scan: " .. scanned .. " quest achievements.")

    return scanned
end

------------------------------------------------------------
-- GROUPING
------------------------------------------------------------

-- Quest achievements grouped by the category they live in -- which is to say,
-- by expansion and continent, because that is how Blizzard files them and
-- how the player thinks about them.
function Loremaster.ByCategory(includeCompleted)
    local groups, order = {}, {}

    for id, record in pairs(Records()) do
        if includeCompleted or not record.completed then
            local key = record.category or "Other"

            if not groups[key] then
                groups[key] = {}
                table.insert(order, key)
            end

            table.insert(groups[key], {
                id        = id,
                name      = record.name,
                completed = record.completed,
                done      = record.done or 0,
                criteria  = record.criteria or 0,
            })
        end
    end

    table.sort(order)

    for _, key in pairs(order) do
        table.sort(groups[key], function(a, b)
            local left  = (a.criteria or 0) > 0 and (a.done / a.criteria) or -1
            local right = (b.criteria or 0) > 0 and (b.done / b.criteria) or -1

            if left ~= right then
                return left > right
            end

            return tostring(a.name) < tostring(b.name)
        end)
    end

    return groups, order
end

-- The ones worth finishing next: started, not finished, closest first.
-- An untouched zone is not "nearly done", so it sorts below one you have
-- already put an evening into.
-- The zones nearest to finished.
--
-- TWO BUGS LIVED HERE.
--
-- The first: this sorted candidates carefully by completion fraction and then
-- handed the list to CN.CapCandidates, which re-sorts by `completionValue` --
-- a field these rows do not have. Every row therefore compared equal and the
-- tie-break took over, silently reordering the whole list alphabetically by
-- achievement ID whenever there were more rows than the limit. The careful
-- ordering above it was thrown away exactly when it mattered.
--
-- The second was worse for anyone actually working through content: rows with
-- `done == 0` were excluded, so a zone you had never set foot in could never
-- be recommended. For a player sweeping a continent, the untouched zones are
-- precisely the ones they need to be pointed at.
--
-- Untouched zones are now included and ranked separately, because "you are
-- 90% through this one" and "you have not started this one" are different
-- suggestions and blending them by fraction would bury every fresh zone under
-- every half-finished one forever.
function Loremaster.Closest(limit)
    local started, untouched = {}, {}

    for id, record in pairs(Records()) do
        if not record.completed and (record.criteria or 0) > 0 then
            local row = {
                id       = id,
                name     = record.name,
                category = record.category,
                done     = record.done or 0,
                criteria = record.criteria,
                fraction = (record.done or 0) / record.criteria,
            }

            if row.done > 0 then
                table.insert(started, row)
            else
                table.insert(untouched, row)
            end
        end
    end

    local function byProgress(a, b)
        if a.fraction ~= b.fraction then
            return a.fraction > b.fraction
        end

        return (a.criteria - a.done) < (b.criteria - b.done)
    end

    table.sort(started, byProgress)

    -- Smallest first among the untouched: a fresh zone with twenty quests is
    -- a better next step than one with ninety.
    table.sort(untouched, function(a, b)
        if a.criteria ~= b.criteria then
            return a.criteria < b.criteria
        end

        return tostring(a.name) < tostring(b.name)
    end)

    local ordered = {}

    for _, row in ipairs(started) do
        table.insert(ordered, row)
    end

    for _, row in ipairs(untouched) do
        table.insert(ordered, row)
    end

    -- Truncate. Deliberately NOT CN.CapCandidates: that re-sorts, and the
    -- ordering above is the entire product of this function.
    limit = limit or 10

    while #ordered > limit do
        table.remove(ordered)
    end

    return ordered, #started, #untouched
end

-- The quest achievement that matches the zone you are standing in.
--
-- Matched by name, which is imperfect and honest about being so: the client
-- does not link an achievement to a map. "Loremaster of Khaz Algar" will not
-- match "Isle of Dorn", and it is not supposed to -- the per-zone achievement
-- is the one that will.
function Loremaster.ForZone(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return nil
    end

    local zoneName = Blizzard.GetMapName(mapID)

    if not zoneName or zoneName == "" then
        return nil
    end

    local best

    for id, record in pairs(Records()) do
        if record.name and string.find(record.name, zoneName, 1, true) then
            -- Prefer an unfinished one; a completed zone achievement is not
            -- the thing you want to be shown while standing in it.
            if not best or (best.completed and not record.completed) then
                best = {
                    id        = id,
                    name      = record.name,
                    completed = record.completed,
                    done      = record.done or 0,
                    criteria  = record.criteria or 0,
                }
            end
        end
    end

    return best
end

------------------------------------------------------------
-- WHICH ZONE NEXT
------------------------------------------------------------

-- The addon could answer "what next" and "where in this zone", and had
-- nothing at all to say about "which zone".
--
-- That is the question somebody working through a continent asks every time
-- they finish one, and answering it badly is worse than not answering: the
-- wrong zone is twenty minutes of flying and a level range that wastes the
-- quests. So it is built from things the client will actually vouch for --
-- how much of each zone's quest achievement is done, how big what remains
-- is, and whether the zone feeds something you said you were chasing -- and
-- it says which of those reasons applied.

-- A zone you are most of the way through beats a fresh one, because
-- finishing is cheaper than starting and leaves fewer loose ends behind.
Loremaster.nearlyDoneFraction = 0.6

function Loremaster.NextZones(limit)
    local rows = Loremaster.Closest(50)

    local chased = {}

    -- Anything pinned as a goal makes the zone that serves it worth more.
    local goals = CN:GetModule("Goals")

    if goals then
        for _, goal in ipairs(goals.List()) do
            if goal.type == CN.objectiveTypes.ACHIEVEMENT then
                chased[goal.id] = true
            end
        end
    end

    local currentZone = Loremaster.ForZone()

    local scored = {}

    for _, row in ipairs(rows) do
        local reasons = {}

        local value = 0

        if row.fraction >= Loremaster.nearlyDoneFraction then
            value = value + 3
            table.insert(reasons, string.format(
                "%d%% done -- finishing is cheaper than starting",
                math.floor(row.fraction * 100)))
        elseif row.done > 0 then
            value = value + 1
            table.insert(reasons, string.format("%d of %d done",
                row.done, row.criteria))
        else
            table.insert(reasons, string.format(
                "not started, %d to do", row.criteria))
        end

        if chased[row.id] then
            value = value + 4
            table.insert(reasons, "you are chasing this")
        end

        -- The zone you are standing in costs nothing to reach.
        if currentZone and currentZone.id == row.id then
            value = value + 2
            table.insert(reasons, "you are already here")
        end

        -- A small remainder is a session; a large one is a project.
        local remaining = row.criteria - row.done

        if remaining <= 5 then
            value = value + 1
            table.insert(reasons, remaining .. " left")
        end

        table.insert(scored, {
            id        = row.id,
            name      = row.name,
            done      = row.done,
            criteria  = row.criteria,
            fraction  = row.fraction,
            remaining = remaining,
            value     = value,
            here      = currentZone and currentZone.id == row.id or false,
            reasons   = reasons,
        })
    end

    table.sort(scored, function(a, b)
        if a.value ~= b.value then
            return a.value > b.value
        end

        if a.fraction ~= b.fraction then
            return a.fraction > b.fraction
        end

        return tostring(a.name) < tostring(b.name)
    end)

    limit = limit or 5

    while #scored > limit do
        table.remove(scored)
    end

    return scored
end

CN:RegisterCommand{
    name    = "zones",
    aliases = { "nextzone", "wherenext" },
    order   = 15,
    help    = "Which zone to work on next, and why.",
    handler = function()
        local rows = Loremaster.NextZones(6)

        if #rows == 0 then
            Print("No unfinished zone achievements are recorded yet.")
            -- `/cn loremaster scan` is not a command. `loremaster` treats
            -- any argument that is not `all` or `zone` as a NAME FILTER, so
            -- that line sent the player to "Nothing matched."
            Print("|cff999999Run |cffffff00/cn scanlore|r"
                .. "|cff999999 to read them from the game.|r")
            return
        end

        Print("Zones worth doing next:")

        for index, row in ipairs(rows) do
            Print(string.format("  %d. %s%s|r  |cff999999%d/%d|r",
                index,
                row.here and "|cff5dd2fb" or "|cffffff00",
                tostring(row.name),
                row.done, row.criteria))

            Print("     |cff999999" .. table.concat(row.reasons, "; ") .. "|r")
        end

        Print("|cff999999Ordered by what is cheapest to finish, not by size. "
            .. "Zones you have not started are included -- an earlier version "
            .. "left them out entirely.|r")
    end,
}

------------------------------------------------------------
-- THE STORY, AS DISTINCT FROM EVERYTHING ELSE
------------------------------------------------------------

-- "Finish the story, then do the side quests" is how players actually talk,
-- and the client knows which quests are campaign quests. Splitting the zone's
-- work along that line costs one API call per quest and matches the plan the
-- player already has in their head.
function Loremaster.SplitZoneWork(mapID)
    local quests = CN:GetModule("Quests")

    if not quests then
        return { story = {}, side = {} }
    end

    local split = { story = {}, side = {} }

    for _, poi in ipairs(quests.AvailableOnMap(mapID)) do
        if Blizzard.IsQuestCampaign(poi.questID) then
            table.insert(split.story, poi)
        else
            table.insert(split.side, poi)
        end
    end

    return split
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A zone achievement you are most of the way through is a genuine next
-- action: three quests from Loremaster is worth knowing about while you are
-- standing in the zone, and worthless as a line in a list of four hundred.
CN.RegisterCandidateProvider("Loremaster", function()
    local candidates = {}

    local zone = Loremaster.ForZone()

    if not zone or zone.completed or (zone.criteria or 0) == 0 then
        return candidates
    end

    local remaining = zone.criteria - zone.done

    if remaining <= 0 or remaining > 10 then
        return candidates
    end

    local mapID = select(1, CN.GetPlayerPosition())

    table.insert(candidates, CN.NewObjective({
        id              = zone.id,
        type            = CN.objectiveTypes.ACHIEVEMENT,
        name            = zone.name,
        mapID           = mapID,
        accountWide     = false,
        completionValue = 4,
        reasons         = {
            remaining .. " of " .. zone.criteria .. " left in this zone",
        },
    }))

    return candidates
end, { events = { "ZONE_CHANGED_NEW_AREA", "CRITERIA_UPDATE" }, cooldown = 5 })

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function PrintAchievement(entry, indent)
    local bar = ""

    if (entry.criteria or 0) > 0 then
        local fraction = entry.done / entry.criteria

        bar = " |cff5dd2fb" .. CN.ProgressBar(fraction, 12) .. "|r "
            .. entry.done .. "/" .. entry.criteria
    end

    Print((indent or "  ")
        .. (entry.completed and "|cff73b873" or "|cffffff00")
        .. tostring(entry.name) .. "|r" .. bar)
end

CN:RegisterCommand{
    name    = "loremaster",
    -- "zones" REMOVED. It was registered as its own command 120 lines up --
    -- "Which zone to work on next, and why" -- and this alias, loading later,
    -- overwrote it. So `/cn zones` printed the quest-completion-by-zone
    -- report while `/cn help` and the store page both described the zone
    -- ranking, and the real command was reachable only as `/cn nextzone`.
    aliases = { "lore" },
    args    = "[all, zone, or a name to filter]",
    order   = 12,
    help    = "Quest completion by zone, continent and expansion.",
    handler = function(args)
        args = CN.Trim(args or "")

        if CN.CountKeys(Records()) == 0 then
            Print("No quest achievements scanned yet. Running a scan now.")
            Loremaster.Scan()
        end

        if string.lower(args) == "zone" or args == "" then
            local zone = Loremaster.ForZone()

            if zone then
                Print("This zone:")
                PrintAchievement(zone)
            end

            local split = Loremaster.SplitZoneWork()

            if #split.story > 0 or #split.side > 0 then
                Print("Available here: |cffffff00" .. #split.story
                    .. "|r story, |cffffff00" .. #split.side .. "|r side.")
            end

            if args ~= "" then
                return
            end

            Print("Closest to finished:")

            for _, entry in ipairs(Loremaster.Closest(8)) do
                PrintAchievement(entry)
            end

            Print("|cff999999/cn loremaster all|r lists everything by expansion.")

            return
        end

        local includeCompleted = string.lower(args) == "all"

        local filter = (not includeCompleted) and string.lower(args) or nil

        local groups, order = Loremaster.ByCategory(includeCompleted)

        local shown = 0

        for _, key in ipairs(order) do
            if not filter or string.find(string.lower(key), filter, 1, true) then
                Print("|cffffd100" .. key .. "|r")

                for _, entry in ipairs(groups[key]) do
                    PrintAchievement(entry, "    ")
                    shown = shown + 1
                end
            end
        end

        if shown == 0 then
            Print("Nothing matched. Try |cffffff00/cn loremaster all|r.")
        end
    end,
}

CN:RegisterCommand{
    name    = "scanlore",
    order   = 27,
    help    = "Rescan quest achievements by zone and expansion.",
    handler = function()
        Print("Quest achievements scanned: " .. Loremaster.Scan() .. ".")
    end,
}

CN:OnLogin(function()
    if CN.CountKeys(Records()) == 0 then
        Loremaster.Scan()
    end
end)

return Loremaster
'@

$Embedded['Modules\Follow.lua'] = @'
-- Modules/Follow.lua
-- Completion Navigator :: stop consulting the addon, start following it.
--
-- Everything this addon knows is currently something you have to ASK for.
-- You type a command, read a list, close it, and play from memory. The
-- routing engine computes stops, orders them, improves the order, and then
-- hands all of that to a player who has to carry it in their head.
--
-- Follow mode makes it present. One small frame showing the stop you are
-- walking to and what you do when you get there, ticking things off as the
-- game reports them, advancing to the next stop when this one is clear, with
-- the arrow already pointed the right way.
--
-- THE RULE THIS FILE IS BUILT AROUND: a co-pilot that fights you is worse
-- than no co-pilot.
--
--   * Off by default. It is started deliberately and stopped with one word.
--   * It never re-points the waypoint while you are walking to something.
--     Advancing happens when the current stop is DONE, not on a timer.
--   * If you wander off and do something it did not suggest, it re-plans
--     around where you actually are rather than herding you back.
--   * It says nothing in chat while it runs. A frame that updates silently
--     is a companion; one that narrates is a nuisance.

local ADDON_NAME, CN = ...

local Follow = CN:RegisterModule("Follow")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- STATE
------------------------------------------------------------

Follow.active = false

-- The stop currently being walked to, and what it held when we set out.
local current = {
    hub        = nil,
    objectives = nil,
    startedAt  = nil,
}

local frame

Follow.recheckSeconds = 3

------------------------------------------------------------
-- WHAT IS LEFT AT THIS STOP
------------------------------------------------------------

-- An objective is done when it is no longer a candidate.
--
-- Deliberately defined by absence rather than by watching for completion
-- events. Events are per-type and there are eleven types; absence is one
-- rule that covers all of them, including the ones added later, and it is
-- also correct when something is finished by means the addon never saw.
-- The live index, memoised against the candidate generation.
--
-- PERFORMANCE, AND A BUG I SHIPPED IN 0.27.0: a single redraw calls this
-- three times -- once to test whether the stop is finished, once for the
-- header, once for the body -- and each call walked the entire candidate list
-- and built a fresh set of several thousand keys. Three full scans, three
-- throwaway tables, every three seconds, for an answer that cannot have
-- changed between them.
--
-- The candidate list already publishes a generation number that increments
-- when anything is rebuilt. Keyed on that, this is built once per actual
-- change instead of once per question.
local liveIndex = { generation = -1, keys = nil }

local function LiveKeys()
    -- COLLECT FIRST, THEN MEMOISE ON WHAT COLLECTING PRODUCED.
    --
    -- This read the generation, compared it to the memo, and returned early
    -- before calling CollectCandidates -- while stamping the memo with the
    -- generation from BEFORE the collect that followed it. Two things then
    -- went wrong together.
    --
    -- Marking a provider dirty deliberately does not advance the generation:
    -- only an actual rebuild does, and only CollectCandidates rebuilds. So
    -- once the stamp converged, this function stopped calling
    -- CollectCandidates, which meant nothing here ever rebuilt, which meant
    -- the generation could never advance, which meant the memo stayed valid
    -- forever. Follow mode stopped noticing that a stop was finished and sat
    -- on it -- unstuck only if something unrelated happened to collect, such
    -- as the heads-up display's timer, which is off by default.
    --
    -- Collecting when nothing is stale costs about two microseconds. Guarding
    -- it was never worth this.
    local candidates = CN.CollectCandidates() or {}

    local generation = 0

    if CN.GetCandidateCacheState then
        local ok, state = pcall(CN.GetCandidateCacheState)

        if ok and state then
            generation = state.generation or 0
        end
    end

    if liveIndex.keys and liveIndex.generation == generation then
        return liveIndex.keys
    end

    local keys = {}

    for _, candidate in ipairs(candidates) do
        keys[tostring(candidate.type) .. ":" .. tostring(candidate.id)] = true
    end

    liveIndex.generation = generation
    liveIndex.keys       = keys

    return keys
end

Follow.LiveKeys = LiveKeys

function Follow.Remaining(objectives)
    local remaining = {}

    if type(objectives) ~= "table" then
        return remaining
    end

    local live = LiveKeys()

    for _, objective in ipairs(objectives) do
        local key = tostring(objective.type) .. ":" .. tostring(objective.id)

        if live[key] then
            table.insert(remaining, objective)
        end
    end

    return remaining
end

function Follow.IsStopComplete()
    if not current.objectives then
        return false
    end

    return #Follow.Remaining(current.objectives) == 0
end

------------------------------------------------------------
-- CHOOSING A STOP
------------------------------------------------------------

-- The next stop is the first stop of a route built from where you are
-- STANDING, recomputed rather than remembered.
--
-- Remembering the route and walking down it would be cheaper and wrong: the
-- player who took a detour, took a flight path, or died and released is no
-- longer on the route that was computed, and the honest answer is to look at
-- where they are now.
function Follow.NextStop()
    local mapID, x, y = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return nil
    end

    -- THE TOTAL MOVES, BECAUSE THE ROUTE DOES.
    --
    -- The route is rebuilt from live candidates on every call, so accepting
    -- five quests in three new places lengthens it. A denominator frozen at
    -- the start therefore produced "Stop 9 of 8 cleared", fired the "Route
    -- complete" flourish at stop 8 and then again at 9, 10 and 11 while
    -- stops remained, and left the heads-up display -- which clamps -- stuck
    -- on "stop 8 of 8" for the rest of the session.
    --
    -- What the player is being told is how far through the CURRENT route
    -- they are, so the total is what is currently there plus what has already
    -- been cleared. It can grow; that is honest, because the work grew.
    local total = #hubs + (Follow.completed or 0)

    if total > (Follow.startedWith or 0) then
        Follow.startedWith = total

        -- The route grew, so it is no longer a finished route: the
        -- completion moment is available again.
        if total > (Follow.completed or 0) then
            Follow.celebrated = false
        end
    end

    for _, hub in ipairs(hubs) do
        local remaining = Follow.Remaining(hub.objectives)

        if #remaining > 0 then
            return hub, remaining
        end
    end

    return nil
end

function Follow.SetStop(hub, objectives)
    current.hub        = hub
    current.objectives = objectives or (hub and hub.objectives)
    current.startedAt  = time()

    if hub and hub.mapID and hub.x and hub.y then
        local label = CN.DescribeHub and CN.DescribeHub(hub) or "Next stop"

        CN.SetWaypoint(hub.mapID, hub.x, hub.y, label)
    end
end

-- Advance only when there is a reason to.
--
-- `force` exists for the player asking out loud ("/cn follow next"), which is
-- a different thing from the addon deciding on its own.
-- PROGRESS THE PLAYER CAN SEE.
--
-- Follow mode has always advanced silently: the waypoint moved, and that was
-- the only evidence anything had happened. Somebody walking a route for
-- twenty minutes had no sense of getting anywhere, which is the difference
-- between a tool that feels like it is working with you and one that feels
-- like a timer.
--
-- Counted per run rather than persisted -- "how far through tonight's route
-- am I" is a question about tonight.
Follow.completed = 0
Follow.startedWith = 0

-- Whether this route has already had its completion moment. Reset when a
-- route starts, and when the total grows past what was already cleared --
-- because a route that has more stops in it than it did is not a route that
-- has been finished.
Follow.celebrated = false

-- How long to wait before searching again when the last search found nothing
-- routable here. A forced advance -- the player asking -- ignores it.
Follow.emptySearchSeconds = 15
Follow.lastEmptySearch    = 0

function Follow.NoteStopCleared()
    Follow.completed = Follow.completed + 1

    local total = Follow.startedWith

    -- Translated. This is the string 0.48.1 made a build failure over for
    -- having no translations at all -- and then it was printed as an English
    -- literal anyway, so the ten locale files that carry it were never
    -- consulted.
    local text = CN.L["Stop cleared"]

    if total > 0 then
        text = string.format(CN.L["Stop %d of %d cleared"],
            Follow.completed, total)
    end

    Print("|cff73b873" .. text .. "|r")

    Follow.Cue("stop")

    -- A COMPLETION MOMENT, when there is genuinely nothing left. The route
    -- finishing is the only thing this addon does that is worth a small
    -- flourish, and it happens rarely enough to stay one.
    -- ONCE PER ROUTE, NOT ONCE PER STOP PAST THE END.
    --
    -- `completed >= total` is true for every clear after the last one, so a
    -- route whose total shrank -- or a player who cleared something outside
    -- the counted set -- got the flourish again on every stop. 0.50.0 fixed
    -- the "Stop 9 of 8" half of this by letting the total grow; the
    -- celebration half was left firing repeatedly.
    if total > 0 and Follow.completed >= total and not Follow.celebrated then
        Follow.celebrated = true

        Print("|cff5dd2fb" .. CN.L["Route complete."] .. "|r " .. total .. " stops, "
            .. "everything on it done.")

        Follow.Celebrate()
    end

    return Follow.completed
end

-- Sound and a flash, both OFF by default, because unsolicited noise is the
-- most intrusive thing an addon can do and this addon's standing rule is that
-- nothing is taken over without being asked.
-- THREE MOMENTS, NOT ONE.
--
-- `/cn cues` was described as sound and a flash "when a route finishes", and
-- that is all it did -- while the two moments a player actually wants marking
-- are the smaller ones: arriving somewhere, and clearing a stop. A cue that
-- fires once an hour is a cue nobody has an opinion about.
--
-- Quieter for the small moments than for the big one. A route finishing is
-- worth a noise; arriving at the third of eight camps is worth a tap.
Follow.cueSounds = {
    route   = "UI_QUEST_ROLLING_FORWARD_01",
    stop    = "IG_QUEST_LIST_SELECT",
    arrival = "IG_QUEST_LIST_OPEN",
}

function Follow.Cue(moment)
    local settings = CN.Settings()

    if not settings or not settings.cues then
        return false
    end

    local sound = Follow.cueSounds[moment or "route"]

    if PlaySound and SOUNDKIT and sound and SOUNDKIT[sound] then
        pcall(PlaySound, SOUNDKIT[sound])
    end

    -- The flash belongs to the route, not to every arrival: a frame that
    -- blinks every time you reach a camp is a frame people turn off.
    if moment == "route" and UIFrameFlash and frame then
        pcall(UIFrameFlash, frame, 0.3, 0.3, 1.2, false, 0, 0)
    end

    return true
end

function Follow.Celebrate()
    return Follow.Cue("route")
end

function Follow.Advance(force)
    if not Follow.active then
        return false
    end

    -- NOT DURING A FIGHT.
    --
    -- Advancing mid-combat re-points the arrow and the waypoint at the next
    -- camp while the player is being hit by something at this one. It is the
    -- single most intrusive moment the addon could pick, and there is no
    -- version of "you finished that stop" that is urgent enough to deliver
    -- during a fight. The stop is still finished thirty seconds later.
    --
    -- A forced advance -- the player pressing the button -- is still obeyed.
    -- They can see their own screen.
    if not force and InCombatLockdown and InCombatLockdown() then
        Follow.deferred = true

        return false
    end

    if not force and current.hub and not Follow.IsStopComplete() then
        -- Still work here. Do not move the waypoint out from under someone
        -- who is walking toward it.
        return false
    end

    -- NOTHING TO ROUTE TO IS NOT A REASON TO KEEP ROUTING.
    --
    -- When no hub is found, `current.hub` is cleared -- and the guard above
    -- then lets every subsequent call fall straight through to NextStop,
    -- which builds a full zone route with a 2-opt pass and bumps the ranking
    -- generation. QUEST_LOG_UPDATE is not throttled on this path, so standing
    -- somewhere with nothing routable -- a capital city, a dungeon, a
    -- battleground, a flight -- rebuilt the route on every one of them.
    --
    -- Measured: with a live stop, twenty events cost zero route builds; with
    -- none, twenty events cost twenty.
    if not force and not current.hub then
        local now = time()

        if (now - (Follow.lastEmptySearch or 0)) < Follow.emptySearchSeconds then
            return false
        end

        Follow.lastEmptySearch = now
    end

    local hub, remaining = Follow.NextStop()

    if not hub then
        current.hub        = nil
        current.objectives = nil

        return false
    end

    -- Do not re-set the waypoint for the stop we are already on.
    if current.hub
        and current.hub.x == hub.x
        and current.hub.y == hub.y
        and not force then

        current.objectives = remaining

        return false
    end

    -- Something was actually finished if we are moving on from a stop we
    -- were already on and were not forced.
    if current.hub and not force then
        Follow.NoteStopCleared()
    end

    Follow.SetStop(hub, remaining)

    return true
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

Follow.maxLines = 6

-- What the frame should say, computed separately from the frame itself so it
-- can be asserted without a client.
function Follow.Lines()
    local lines = {}

    if not current.hub then
        table.insert(lines, { text = "Nothing left to route here.", state = "NOTE" })

        return lines
    end

    local remaining = Follow.Remaining(current.objectives)

    local quests = CN:GetModule("Quests")

    local shown = 0

    local open = {}

    for _, objective in ipairs(remaining) do
        open[tostring(objective.type) .. ":" .. tostring(objective.id)] = true
    end

    for _, objective in ipairs(current.objectives or {}) do
        local stillOpen =
            open[tostring(objective.type) .. ":" .. tostring(objective.id)] == true

        if shown >= Follow.maxLines then
            table.insert(lines, {
                text  = "and " .. (#current.objectives - shown) .. " more",
                state = "NOTE",
            })
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, {
            text  = verb .. ": " .. tostring(objective.name or objective.id),
            state = stillOpen and "OPEN" or "DONE",
        })

        shown = shown + 1
    end

    return lines
end

function Follow.HeaderText()
    if not current.hub then
        return "Completion Navigator"
    end

    local remaining = #Follow.Remaining(current.objectives)

    local total = #(current.objectives or {})

    return string.format("Stop: %d of %d left", remaining, total)
end

local function BuildFrame()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorFollow", UIParent)

    frame:SetSize(240, 120)
    frame:SetFrameStrata("MEDIUM")
    frame:SetMovable(true)
    frame:EnableMouse(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetClampedToScreen(true)

    local saved = Settings()

    saved.followPosition = saved.followPosition or {}

    frame:SetPoint(
        saved.followPosition.point or "TOPLEFT",
        UIParent,
        saved.followPosition.point or "TOPLEFT",
        saved.followPosition.x or 40,
        saved.followPosition.y or -200)

    frame.header = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    frame.header:SetPoint("TOPLEFT", 8, -8)
    frame.header:SetJustifyH("LEFT")

    frame.body = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    frame.body:SetPoint("TOPLEFT", frame.header, "BOTTOMLEFT", 0, -6)
    frame.body:SetJustifyH("LEFT")
    frame.body:SetJustifyV("TOP")

    frame:SetScript("OnDragStart", function(self) self:StartMoving() end)

    frame:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local point, _, _, x, y = self:GetPoint()

        Settings().followPosition = { point = point, x = x, y = y }
    end)

    frame:Hide()

    return frame
end

Follow.BuildFrame = BuildFrame

function Follow.Redraw()
    if not frame then
        return
    end

    frame.header:SetText(Follow.HeaderText())

    local rendered = {}

    for _, line in ipairs(Follow.Lines()) do
        local colour = "|cffcccccc"

        if line.state == "DONE" then
            colour = "|cff73b873"
        elseif line.state == "NOTE" then
            colour = "|cff999999"
        end

        table.insert(rendered, colour
            .. (line.state == "DONE" and "x " or "- ")
            .. line.text .. "|r")
    end

    frame.body:SetText(table.concat(rendered, "\n"))
end

------------------------------------------------------------
-- THE LOOP
------------------------------------------------------------

local ticker

-- Driven by events, with a slow clock as a backstop rather than as the
-- mechanism. Position changes with no event attached -- walking into range of
-- something -- are the only reason the clock exists at all.
local function Tick()
    if not Follow.active then
        return
    end

    Follow.Advance(false)
    Follow.Redraw()
end

function Follow.Start()
    if Follow.active then
        return false
    end

    Follow.active = true

    Follow.completed  = 0
    Follow.celebrated = false

    -- How many stops there were when the route started, so progress can be
    -- reported as a fraction rather than as a running count that means
    -- nothing on its own.
    local mapID, x, y = CN.GetPlayerPosition()

    local hubs

    if mapID and CN.BuildZoneRoute then
        local _, _, built = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

        hubs = built
    end

    -- COUNTED WHEN THE MAP WILL ANSWER, NOT BEFORE.
    --
    -- Start() also runs from the login hook when follow mode was left on, and
    -- at PLAYER_LOGIN the map API has nothing to say yet -- so the total was
    -- fixed at zero for the whole session. Every "Stop 3 of 8 cleared"
    -- degraded to a bare "Stop cleared", and the completion moment, which
    -- needs a total to compare against, was unreachable for any session that
    -- resumed follow rather than typing the command.
    --
    -- Zero means "not counted yet" rather than "no stops", so the first
    -- advance that finds a route sets it.
    Follow.startedWith = (type(hubs) == "table") and #hubs or 0

    Settings().follow = true

    BuildFrame()

    if frame then
        frame:Show()
    end

    Follow.Advance(true)
    Follow.Redraw()

    if C_Timer and C_Timer.NewTicker and not ticker then
        -- Guarded, for the reason spelled out on Session's ticker: a
        -- repeating callback that throws is a repeating error box.
        ticker = C_Timer.NewTicker(Follow.recheckSeconds, function()
            CN.Guard("Follow.Tick", Tick)
        end)
    end

    return true
end

function Follow.Stop()
    Follow.active = false

    Settings().follow = false

    current.hub        = nil
    current.objectives = nil

    if ticker then
        ticker:Cancel()
        ticker = nil
    end

    if frame then
        frame:Hide()
    end

    -- OFF MEANS OFF.
    --
    -- Setting a stop puts a waypoint on the map, draws the on-screen arrow
    -- and starts Navigation's own ticker. Stopping hid this module's frame
    -- and cancelled this module's ticker and left all three of those running
    -- -- so `/cn follow off` left an arrow pointing at a route that was no
    -- longer being followed, indefinitely.
    --
    -- The suite started follow mode and read its lines; it never asked what
    -- was still on screen after stopping it.
    if CN.ClearWaypoints then
        pcall(CN.ClearWaypoints)
    end

    -- And a deferral is about the route that was being walked. Left set, it
    -- fired into the next combat-free moment of a session that was no longer
    -- following anything, and survived into the next Start().
    Follow.deferred = false

    return true
end

function Follow.Toggle()
    if Follow.active then
        Follow.Stop()
        return false
    end

    Follow.Start()

    return true
end

function Follow.CurrentStop()
    return current.hub, current.objectives
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- Something finished. Check whether it emptied the stop; the check is cheap
-- and the alternative is a co-pilot that lags behind the player.
local function OnSomethingChanged()
    if Follow.active then
        Follow.Advance(false)
        Follow.Redraw()
    end
end

CN:RegisterEvent("QUEST_TURNED_IN", OnSomethingChanged)
CN:RegisterEvent("QUEST_ACCEPTED", OnSomethingChanged)
CN:RegisterEvent("QUEST_LOG_UPDATE", OnSomethingChanged)

-- A new zone invalidates the route entirely, so re-plan rather than advance.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if Follow.active then
        Follow.Advance(true)
        Follow.Redraw()
    end
end)

CN:OnLogin(function()
    if Settings().follow then
        Follow.Start()
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "follow",
    aliases = { "copilot", "run" },
    args    = "[on, off, next, or nothing to toggle]",
    order   = 10,
    help    = "Follow the route: current stop on screen, advancing as you finish.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "off" or args == "stop" then
            Follow.Stop()
            Print("Follow mode off.")
            return
        end

        if args == "next" or args == "skip" then
            if not Follow.active then
                Print("Follow mode is not running. |cffffff00/cn follow|r starts it.")
                return
            end

            Follow.Advance(true)
            Follow.Redraw()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Moved on: " .. (CN.DescribeHub(hub) or "next stop") .. ".")
            else
                Print("Nothing left to route here.")
            end

            return
        end

        if args == "on" or args == "" then
            if args == "" and Follow.active then
                Follow.Stop()
                Print("Follow mode off.")
                return
            end

            Follow.Start()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Following. First stop: "
                    .. (CN.DescribeHub(hub) or "ahead") .. ".")
                Print("|cff999999It advances when the stop is clear. "
                    .. "|cffffff00/cn follow off|r|cff999999 stops.|r")
            else
                Print("Following, but nothing here needs doing.")
            end

            return
        end

        Print("Usage: /cn follow [on | off | next]")
    end,
}

-- Whatever was held back during the fight happens the moment it ends.
CN:RegisterEvent("PLAYER_REGEN_ENABLED", function()
    if Follow.active and Follow.deferred then
        Follow.deferred = false

        Follow.Advance()
    end
end)

return Follow
'@

$Embedded['Modules\Session.lua'] = @'
-- Modules/Session.lua
-- Completion Navigator :: "I have forty minutes. What should I do?"
--
-- The single most common shape a play session actually has, and the addon
-- had nothing to say about it. It could rank everything and route between
-- stops, and it could not answer the one question a person with a job and a
-- bedtime asks before logging in.
--
-- WHY THIS IS HARD TO DO HONESTLY.
--
-- A plan that fits in forty minutes requires knowing how long things take,
-- and the client does not say. The tempting move is to make numbers up --
-- "quests take four minutes" -- and present them in a font that looks like
-- measurement. This addon has a standing rule against exactly that.
--
-- So the estimate is built from two halves, and only one of them is guessed:
--
--   TRAVEL is computed. The router already knows the real yard distance
--   between stops, and this module measures how fast you actually move by
--   watching your position. That is arithmetic on observations.
--
--   TASK TIME is learned. Every completion is timed against when the
--   objective was first offered as the current stop, and the median per type
--   is kept. Until a type has been seen enough times, it has NO estimate and
--   the plan says so rather than inventing one.
--
-- A plan therefore starts out honest and vague -- "these stops, distance
-- known, duration not yet" -- and sharpens as it watches you play. That is
-- slower to become useful than a table of invented constants, and it is the
-- only version that is ever true.

local ADDON_NAME, CN = ...

local Session = CN:RegisterModule("Session")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- MEASURED TRAVEL SPEED
------------------------------------------------------------

-- Yards per second. Seeded with a walking-speed figure that is immediately
-- replaced by measurement; it exists so the first plan is not divided by nil.
Session.defaultSpeed = 7

Session.minSamples = 5

-- THE CLOCK.
--
-- `time()` returns whole seconds. Sampling a ten-second interval with a
-- one-second ruler is up to ten per cent of error baked into every estimate
-- the planner produces, and it silently discarded every task that finished
-- within the same second it was offered -- which, in the offline suite, was
-- all of them. `GetTime()` is the client's fractional monotonic clock and is
-- the right instrument for measuring a duration.
--
-- Kept behind a function so the offline harness can drive it.
function Session.Now()
    if GetTime then
        return GetTime()
    end

    return os.clock()
end

-- Speed is kept in three buckets, not one.
--
-- A single median across mounted and unmounted travel is a number that is
-- wrong in both states: too slow to plan a mounted route, too fast to plan a
-- walk around a town.
--
-- 0.43.0 added the third, and it was the same mistake one level down: flying
-- yourself was landing in `mounted` beside a ground mount, so the median was
-- dragged upward by however much the player skyrides and every ground
-- estimate inherited it. Three medians are three honest answers.
local speed = {
    lastMapID  = nil,
    lastX      = nil,
    lastY      = nil,
    lastAt     = nil,
    lastMounted = nil,
    lastFlying = nil,
    samples    = { mounted = {}, onFoot = {}, flying = {} },
}

-- SAMPLES SURVIVE A RELOAD.
--
-- They did not. Speed was measured into a table that lived and died with the
-- session, so every `/reload` -- which a player does several times an hour --
-- threw away the measurements and put the planner back on a guessed constant.
-- The addon was permanently five samples from being useful and never got
-- there.
--
-- Stored per character, because a druid in travel form and a warrior on foot
-- are different measurements and averaging them helps nobody.
local function Persisted()
    local character = CN.character

    if not character then
        return nil
    end

    character.speedSamples = character.speedSamples or {}

    character.speedSamples.mounted = character.speedSamples.mounted or {}
    character.speedSamples.onFoot  = character.speedSamples.onFoot or {}
    character.speedSamples.flying  = character.speedSamples.flying or {}

    return character.speedSamples
end

Session.Persisted = Persisted

-- THE SANITY BAND, PER BUCKET.
--
-- It was a single range -- above half a yard a second, below sixty -- written
-- when there were two buckets and both were ground travel. Sixty is a
-- perfectly good ceiling for running and riding, and it is BELOW the speed a
-- player actually flies at.
--
-- So when 0.43.0 added the flying bucket, every genuine flying sample was
-- silently discarded as implausible, the bucket never filled, and the flying
-- estimate stayed permanently seeded. The feature would have looked like it
-- was working and never learned anything. Caught by a test that assumed a
-- realistic flying speed.
Session.speedBands = {
    onFoot  = { 0.5, 60 },
    mounted = { 0.5, 60 },

    -- Skyriding sustains well past sixty and bursts higher. The upper bound
    -- is the same one Travel uses for a taxi: fast enough to be a loading
    -- screen rather than a mount.
    flying  = { 0.5, 200 },
}

function Session.IsPlausibleSpeed(value, bucket)
    local band = Session.speedBands[bucket or "onFoot"]
        or Session.speedBands.onFoot

    return value > band[1] and value < band[2]
end

function Session.LoadSamples()
    local stored = Persisted()

    if not stored then
        return 0
    end

    local loaded = 0

    for _, bucket in ipairs({ "mounted", "onFoot", "flying" }) do
        speed.samples[bucket] = {}

        for _, value in ipairs(stored[bucket] or {}) do
            if type(value) == "number" and Session.IsPlausibleSpeed(value, bucket) then
                table.insert(speed.samples[bucket], value)
                loaded = loaded + 1
            end
        end
    end

    -- Write the cleaned set back.
    --
    -- SavedVariables are a file on disk that other things can touch and that
    -- survives every future version of this addon. Filtering junk on read and
    -- leaving it in place means filtering the same junk on every login
    -- forever; cleaning it means the corruption is dealt with once.
    Session.SaveSamples()

    return loaded
end

function Session.SaveSamples()
    local stored = Persisted()

    if not stored then
        return false
    end

    -- ALL THREE BUCKETS, INCLUDING THE ONE THAT WAS MISSING.
    --
    -- `flying` was left out of this list while Persisted() creates it and
    -- LoadSamples reads it, so measured flight speed survived until logout
    -- and then vanished. Travel.HasFlying needs five flying samples before it
    -- will consider a self-flown route at all, so after any reload the addon
    -- silently went back to costing every journey on the ground -- the
    -- feature 0.43.0 was built around, off, permanently, for everyone.
    --
    -- The suite tested disk-to-memory for all three and memory-to-disk for
    -- two. A round trip is not tested by testing each half against a
    -- different fixture.
    for _, bucket in ipairs({ "mounted", "onFoot", "flying" }) do
        stored[bucket] = {}

        for _, value in ipairs(speed.samples[bucket]) do
            table.insert(stored[bucket], value)
        end
    end

    return true
end

Session.speedSampleCap = 40

local function Mounted()
    if IsMounted and IsMounted() then
        return true
    end

    if UnitOnTaxi and UnitOnTaxi("player") then
        return true
    end

    return false
end

Session.IsMounted = Mounted

-- Flying yourself, which is not the same as being on a flight path and not
-- the same as a ground mount. On a taxi the client also reports the player as
-- flying, and that movement belongs to Travel's flight-speed measurement
-- rather than to this one -- so it is excluded here.
local function Flying()
    if UnitOnTaxi and UnitOnTaxi("player") then
        return false
    end

    return (IsFlying and IsFlying()) and true or false
end

Session.IsFlying = Flying

-- Which bucket the player's current movement belongs in.
function Session.Bucket()
    if Flying() then
        return "flying"
    end

    if Mounted() then
        return "mounted"
    end

    return "onFoot"
end

-- Called on a slow clock. Measures the distance covered since the last look.
--
-- Deliberately discards anything implausible: a teleport, a flight path, a
-- hearthstone or a zone change would otherwise register as a very fast
-- player and make every estimate useless.
function Session.Observe()
    local mapID, x, y = CN.GetPlayerPosition()

    local now     = Session.Now()
    local mounted = Mounted()
    local flying  = Flying()

    if not mapID or not x or not y then
        return nil
    end

    local previousMap, previousX, previousY, previousAt, previousMounted =
        speed.lastMapID, speed.lastX, speed.lastY, speed.lastAt, speed.lastMounted

    -- Read BEFORE it is overwritten. The first version of the flying check
    -- compared the new value against itself, which is always equal, so taking
    -- off mid-interval produced a sample that was half ground speed and half
    -- flight speed and was filed under whichever the player ended in.
    local previousFlying = speed.lastFlying

    speed.lastMapID, speed.lastX, speed.lastY = mapID, x, y
    speed.lastAt, speed.lastMounted = now, mounted
    speed.lastFlying = flying

    if previousMap ~= mapID or not previousAt then
        return nil
    end

    -- Mounting halfway through an interval makes the sample a blend of both
    -- speeds and belongs to neither bucket. The same is true of taking off.
    if previousMounted ~= mounted or previousFlying ~= flying then
        return nil
    end

    local elapsed = now - previousAt

    if elapsed <= 0 or elapsed > 30 then
        return nil
    end

    local nav = CN:GetModule("Navigation")

    if not nav or not nav.DistanceYards then
        return nil
    end

    local yards = nav.DistanceYards(mapID, previousX, previousY, x, y)

    if not yards or yards <= 0 then
        return nil
    end

    local observed = yards / elapsed

    -- A player on foot does about 7 yards a second; mounted, roughly 14 to
    -- 20; flying, a great deal more. The ceiling is per bucket for exactly
    -- that reason -- see Session.speedBands.
    local bucketName = flying and "flying"
        or (mounted and "mounted" or "onFoot")

    if not Session.IsPlausibleSpeed(observed, bucketName) then
        return nil
    end

    local bucket = speed.samples[bucketName]

    table.insert(bucket, observed)

    while #bucket > Session.speedSampleCap do
        table.remove(bucket, 1)
    end

    -- Written straight through. A measurement kept only in memory is a
    -- measurement thrown away at the next reload, which is what this used
    -- to do.
    Session.SaveSamples()

    return observed, mounted
end

-- The median, not the mean: standing still for a minute should not halve the
-- estimate, and one flight path should not double it.
local function Median(values)
    if #values == 0 then
        return nil
    end

    local sorted = {}

    for index = 1, #values do
        sorted[index] = values[index]
    end

    table.sort(sorted)

    local middle = math.floor(#sorted / 2) + 1

    if #sorted % 2 == 1 then
        return sorted[middle]
    end

    return (sorted[middle - 1] + sorted[middle]) / 2
end

Session.Median = Median

-- The speed to plan with.
--
-- Defaults to however the player is travelling right now, because that is
-- the best available guess at how they will travel next. Falls back to the
-- other bucket rather than to a constant: measured-but-wrong-state beats
-- unmeasured.
function Session.Speed(mounted)
    local bucket

    if mounted == nil then
        bucket = Session.Bucket()
    elseif mounted == true then
        bucket = "mounted"
    elseif mounted == false then
        bucket = "onFoot"
    else
        -- A caller that names a bucket outright: Travel asks for "flying"
        -- when it is costing a journey the player would fly themselves,
        -- which has nothing to do with how they happen to be moving now.
        bucket = mounted
    end

    local preferred = speed.samples[bucket] or {}

    if #preferred >= Session.minSamples then
        return Median(preferred), true
    end

    -- Fall back through the other buckets rather than to a constant:
    -- measured-but-wrong-state beats unmeasured. Ordered nearest-first, so a
    -- missing flying median falls to mounted before it falls to walking.
    local fallbacks = {
        flying  = { "mounted", "onFoot" },
        mounted = { "flying", "onFoot" },
        onFoot  = { "mounted", "flying" },
    }

    for _, name in ipairs(fallbacks[bucket] or {}) do
        local other = speed.samples[name] or {}

        if #other >= Session.minSamples then
            return Median(other), false
        end
    end

    return Session.defaultSpeed, false
end

function Session.SpeedSampleCount(mounted)
    if mounted == nil then
        return #speed.samples.mounted + #speed.samples.onFoot
            + #speed.samples.flying
    end

    if mounted == true then
        return #speed.samples.mounted
    end

    if mounted == false then
        return #speed.samples.onFoot
    end

    return #(speed.samples[mounted] or {})
end

-- The in-memory samples themselves. Exposed so that a round trip through
-- disk can be tested as a round trip -- testing each half against a fixture
-- the other half never produced is how a bucket that was loaded but never
-- saved stayed broken for four releases.
function Session.Samples()
    return speed.samples
end

function Session.SpeedBuckets()
    return {
        mounted = Median(speed.samples.mounted),
        onFoot  = Median(speed.samples.onFoot),
        flying  = Median(speed.samples.flying),
    }
end

------------------------------------------------------------
-- LEARNED TASK DURATION
------------------------------------------------------------

local function Durations()
    return CN.Account("taskDurations")
end

Session.Durations = Durations

Session.minDurationSamples = 4
Session.durationSampleCap  = 25

-- The shortest a thing can be said to have taken once its journey is removed.
--
-- A floor rather than a discard, and a very small one. Discarding every
-- sample where the journey estimate exceeded the whole elapsed span would
-- throw away precisely the fast objectives -- biasing the learned time
-- upward, which is the error this subtraction exists to remove. A floored
-- sample says "the work itself was negligible next to getting there", which
-- for a quest handed in on arrival is exactly true.
Session.minimumWorkSeconds = 0.05

-- When each objective was first put in front of the player. A completion
-- timed from here is "how long it took once it was the thing to do", which is
-- the number a plan needs.
-- BOUNDED, because it was not.
--
-- Every objective the addon decorated used to get an entry here and only a
-- completion removed one. Cross a dozen zones and it accumulates a timestamp
-- for everything that ever scrolled past -- a slow leak I shipped in 0.28.0.
--
-- Two bounds now: entries expire, and the table is capped. Neither costs
-- accuracy, because an entry older than the expiry window would have been
-- rejected as implausible at completion time anyway.
local offeredAt = {}
local offeredCount = 0

Session.offerMemoryCap     = 400
Session.offerMemorySeconds = 1800

-- HYSTERESIS, and why it is not optional.
--
-- Pruning the moment the table reaches its cap means every subsequent insert
-- triggers a full sweep of four hundred entries. Recommend(25) does twenty
-- five inserts, so a single call became ten thousand iterations -- measured
-- at 1.5ms, up from 0.02ms. A fix for a memory leak that costs seventy times
-- the CPU is not a fix.
--
-- So: let it overshoot by a quarter, then prune back to the cap. Sweeps
-- happen once per hundred inserts instead of once per insert, and the table
-- is still bounded, which was the entire point.
Session.offerMemorySlack = 0.25

local function Prune(force)
    local trigger = Session.offerMemoryCap
        * (1 + Session.offerMemorySlack)

    if not force and offeredCount <= trigger then
        return 0
    end

    local now = Session.Now()

    local removed = 0

    for key, record in pairs(offeredAt) do
        if now - record.at > Session.offerMemorySeconds then
            offeredAt[key] = nil
            removed = removed + 1
        end
    end

    offeredCount = offeredCount - removed

    -- Still over cap after expiring? Drop the oldest until it fits. A
    -- timestamp we cannot afford to keep is worth less than a bounded table.
    if offeredCount > Session.offerMemoryCap then
        local ordered = {}

        for key, record in pairs(offeredAt) do
            table.insert(ordered, { key = key, at = record.at })
        end

        table.sort(ordered, function(a, b) return a.at < b.at end)

        local excess = offeredCount - Session.offerMemoryCap

        for index = 1, excess do
            offeredAt[ordered[index].key] = nil
            removed = removed + 1
        end

        offeredCount = offeredCount - excess
    end

    return removed
end

Session.Prune = Prune

function Session.OfferedCount()
    return offeredCount
end

function Session.NoteOffered(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return
    end

    local key = tostring(objective.type) .. ":" .. tostring(objective.id)

    if offeredAt[key] then
        return
    end

    -- WHAT THE JOURNEY WAS EXPECTED TO COST, RECORDED WITH THE CLOCK.
    --
    -- The elapsed span between "this was recommended" and "this was finished"
    -- contains the walk to it. The planner then ADDS a separately computed
    -- travel leg to a sum of those spans, so the journey was counted twice --
    -- and once per objective at a stop, which is worst exactly where the
    -- router is trying to reward batching. Four quests six minutes away came
    -- out at thirty-six minutes against a true twelve, reported confident.
    --
    -- Subtracting the addon's own estimate makes the stored number a WORK
    -- time, which is what every consumer already assumes it is. Using the
    -- addon's own model rather than a measurement keeps the two consistent
    -- even where the model is imperfect: the same quantity is removed here
    -- and added back there.
    local travelSeconds = 0

    if objective.travelCost and CN.secondsPerCostPoint then
        travelSeconds = objective.travelCost * CN.secondsPerCostPoint
    end

    offeredAt[key] = { at = Session.Now(), travel = travelSeconds }
    offeredCount   = offeredCount + 1

    Prune()
end

function Session.NoteCompleted(objectiveType, id)
    if not objectiveType or not id then
        return nil
    end

    local key = tostring(objectiveType) .. ":" .. tostring(id)

    local started = offeredAt[key]

    if offeredAt[key] then
        offeredAt[key] = nil
        offeredCount   = offeredCount - 1
    end

    if not started then
        return nil
    end

    local elapsed = Session.Now() - started.at

    -- The journey out, which the caller will add back separately.
    elapsed = elapsed - (started.travel or 0)

    -- A floor rather than a discard: something finished faster than the model
    -- said the journey would take is a fast objective, not a corrupt sample.
    if elapsed < Session.minimumWorkSeconds then
        elapsed = Session.minimumWorkSeconds
    end

    -- Anything over twenty minutes was not "doing the thing", it was living
    -- your life with the thing still on the list.
    --
    -- The lower bound is now a fraction of a second rather than a whole one.
    -- With a one-second clock, anything finished in the same second it was
    -- offered read as zero elapsed and was thrown away -- which quietly
    -- discarded exactly the fast turn-ins a quest grinder produces most of.
    if elapsed <= 0.05 or elapsed > 1200 then
        return nil
    end

    local store = Durations()

    store[objectiveType] = store[objectiveType] or {}

    table.insert(store[objectiveType], elapsed)

    while #store[objectiveType] > Session.durationSampleCap do
        table.remove(store[objectiveType], 1)
    end

    DebugPrint(objectiveType .. " took " .. elapsed .. "s ("
        .. #store[objectiveType] .. " samples).")

    return elapsed
end

-- Seconds this type usually takes, or NIL when the addon has not watched it
-- often enough to have an opinion. Nil is a real answer here and every
-- caller must handle it rather than substituting a guess.
function Session.TypicalSeconds(objectiveType)
    local samples = Durations()[objectiveType]

    if not samples or #samples < Session.minDurationSamples then
        return nil
    end

    return Median(samples)
end

function Session.HasEnoughData()
    for _, samples in pairs(Durations()) do
        if #samples >= Session.minDurationSamples then
            return true
        end
    end

    return false
end

------------------------------------------------------------
-- THE PLAN
------------------------------------------------------------

-- Estimates a stop: travel to it, plus the work at it.
--
-- Returns seconds and a confidence flag. `false` means part of this was not
-- measured, and callers must say so out loud.
function Session.EstimateHub(hub, fromX, fromY)
    local confident = true

    local travelSeconds = 0

    -- ASK TRAVEL, WHICH KNOWS ABOUT FLIGHT PATHS.
    --
    -- This used to be a straight line at running speed between two points on
    -- the same map, and gave up entirely when the maps differed -- so a stop
    -- one zone away was either uncosted or costed as though you would run
    -- there in a straight line through the mountains.
    local travel = CN:GetModule("Travel")

    local playerMap = CN.GetPlayerPosition()

    if travel and hub.mapID and hub.x and hub.y and fromX and fromY and playerMap then
        local seconds, sure = travel.EstimateSeconds(
            playerMap, fromX, fromY, hub.mapID, hub.x, hub.y)

        if seconds then
            travelSeconds = seconds

            if not sure then
                confident = false
            end
        else
            confident = false
        end
    else
        confident = false
    end

    local workSeconds = 0

    for _, objective in ipairs(hub.objectives or {}) do
        local typical = Session.TypicalSeconds(objective.type)

        if typical then
            workSeconds = workSeconds + typical
        else
            confident = false
        end
    end

    return travelSeconds + workSeconds, confident, travelSeconds, workSeconds
end

-- Builds a route and takes stops from the front of it until the budget is
-- spent.
--
-- Takes from the FRONT rather than choosing the best-fitting subset. The
-- route is already ordered to minimise walking; cherry-picking stops out of
-- it produces a plan that fits the clock and makes you cross the zone twice.
-- HOW LONG YOU ACTUALLY PLAY.
--
-- `/cn plan` has always needed a number, and its example has always been
-- thirty minutes -- a figure chosen because it sounds reasonable, not because
-- anybody plays in thirty-minute units. The addon watches how long sessions
-- run anyway; asking it is cheaper than asking the player.
--
-- Stored per character, capped, and used only as the DEFAULT: an explicit
-- number always wins, because "I have twenty minutes" is a fact about tonight
-- that no amount of history overrides.
Session.lengthSampleCap = 20
Session.minLengthSamples = 3

local sessionStartedAt = nil

local function Lengths()
    local character = CN.character

    if not character then
        return nil
    end

    character.sessionLengths = character.sessionLengths or {}

    return character.sessionLengths
end

Session.Lengths = Lengths

function Session.BeginSession()
    sessionStartedAt = Session.Now()
end

-- Called at logout and on a reload. A reload is not the end of a session, but
-- there is no way to tell one from the other at the moment it happens -- so
-- very short sessions are discarded rather than counted, which handles the
-- reload case without needing to detect it.
Session.minCountableMinutes = 8

function Session.EndSession()
    local lengths = Lengths()

    if not lengths or not sessionStartedAt then
        return false
    end

    local minutes = (Session.Now() - sessionStartedAt) / 60

    sessionStartedAt = nil

    if minutes < Session.minCountableMinutes or minutes > 720 then
        return false
    end

    table.insert(lengths, math.floor(minutes + 0.5))

    while #lengths > Session.lengthSampleCap do
        table.remove(lengths, 1)
    end

    return true
end

-- Returns minutes and whether it was measured.
function Session.TypicalSessionMinutes()
    local lengths = Lengths()

    if not lengths or #lengths < Session.minLengthSamples then
        return 30, false
    end

    return math.floor(Median(lengths) + 0.5), true
end

CN:OnLogin(function()
    Session.BeginSession()
end)

CN:RegisterEvent("PLAYER_LOGOUT", function()
    Session.EndSession()
end)

function Session.Plan(minutes)
    local requested = tonumber(minutes)

    -- THE RANKING KNOWS WHERE YOU ARE; THE PLANNER DID NOT.
    --
    -- 0.43.0 taught the ranking about being dead and being in an instance,
    -- and the session planner carried on laying out a walking route through
    -- the open world regardless -- which is a plan the player cannot start.
    local group = CN:GetModule("Group")

    local situation = group and group.Situation()

    if situation == "dead" or situation == "instanced" then
        return {
            minutes   = (requested or Session.TypicalSessionMinutes()),
            stops     = {},
            seconds   = 0,
            confident = true,
            skipped   = 0,
            blocked   = situation,
            notice    = group and group.Notice(),
        }
    end

    -- No number given: use however long this character usually plays, rather
    -- than a round thirty that was only ever a placeholder.
    local budget = (requested or Session.TypicalSessionMinutes()) * 60

    local mapID, x, y = CN.GetPlayerPosition()

    local plan = {
        minutes   = budget / 60,
        stops     = {},
        seconds   = 0,
        confident = true,
        skipped   = 0,
    }

    if not mapID then
        return plan
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return plan
    end

    local currentX, currentY = x or 0.5, y or 0.5

    for _, hub in ipairs(hubs) do
        local seconds, confident, travel, work =
            Session.EstimateHub(hub, currentX, currentY)

        -- STOP AT THE FIRST STOP THAT DOES NOT FIT.
        --
        -- This used to `continue` past an overrunning hub and keep testing
        -- later ones, which is exactly the cherry-picking the comment above
        -- this function forbids -- and it forbids it for a good reason: the
        -- route is ordered to minimise walking, so skipping the middle of it
        -- and taking the far end makes you cross the zone twice to save a
        -- number on a screen.
        --
        -- It was also arithmetically wrong even on its own terms: the skipped
        -- hub's position was not advanced past, so every later hub's travel
        -- leg was costed from wherever the last ACCEPTED stop was, which is
        -- not where the player would be.
        -- THE FIRST STOP IS NOT EXEMPT FROM THE CLOCK.
        --
        -- `#plan.stops > 0` meant stop one was admitted whatever it cost, so
        -- `/cn plan 5` against a forty-five minute hub printed "1 stop, about
        -- 45m of the 5m you have" with nothing flagging that the budget had
        -- been blown ninefold. Taking it is still often the right call --
        -- there may be nothing smaller -- but the player has to be told, not
        -- shown a plan that silently is not a plan.
        if plan.seconds + seconds > budget and #plan.stops > 0 then
            plan.skipped = plan.skipped + 1

            break
        else
            table.insert(plan.stops, {
                hub       = hub,
                seconds   = seconds,
                travel    = travel,
                work      = work,
                summary   = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                confident = confident,
            })

            plan.seconds = plan.seconds + seconds

            if not confident then
                plan.confident = false
            end

            currentX, currentY = hub.x or currentX, hub.y or currentY
        end
    end

    -- `skipped` counts the stop that did not fit plus everything behind it,
    -- because that is what the player is not doing tonight. Counting only the
    -- one that overran would report "1 skipped" for a route with nine stops
    -- left in it.
    if plan.skipped > 0 then
        plan.skipped = #hubs - #plan.stops
    end

    -- Said out loud when the only thing available does not fit.
    plan.overran = plan.seconds > budget

    return plan
end

-- SHORT IS NOT FREE.
--
-- Rounded to whole minutes, a twenty-five second stop rendered as "0m" in
-- `/cn plan` and `/cn travel`, which reads as costing nothing rather than as
-- costing very little. Under a minute is reported in seconds.
function Session.FormatDuration(seconds)
    if not seconds or seconds <= 0 then
        return "0m"
    end

    if seconds < 60 then
        return math.max(1, math.floor(seconds + 0.5)) .. "s"
    end

    local minutes = math.floor(seconds / 60 + 0.5)

    if minutes < 60 then
        return minutes .. "m"
    end

    return string.format("%dh %dm", math.floor(minutes / 60), minutes % 60)
end

------------------------------------------------------------
-- WIRING
------------------------------------------------------------

-- The clock starts when something is RECOMMENDED, not when it is collected.
--
-- 0.28.0 hung this on a candidate decorator, which meant a timestamp was
-- taken for every objective the addon knew about on every rebuild -- two
-- hundred at retail scale, the overwhelming majority of which the player
-- never saw and no plan ever used. Wrong on cost and wrong on meaning: an
-- objective sitting at rank 180 has not been "offered" to anybody.
--
-- Recommend() is the moment something is actually put in front of a player.
function Session.NoteRecommended(list)
    for index = 1, math.min(#list, Session.timedRecommendations) do
        Session.NoteOffered(list[index])
    end

    return list
end

Session.timedRecommendations = 25

if CN.RegisterRecommendationHook then
    CN.RegisterRecommendationHook("SessionTiming", Session.NoteRecommended)
end

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Session.NoteCompleted(CN.objectiveTypes.QUEST, questID)
end)

CN:RegisterEvent("NEW_PET_ADDED", function()
    -- The client does not say which pet, so nothing can be timed here
    -- honestly. Left deliberately unhandled rather than attributing the
    -- elapsed time to a guess.
end)

local ticker

CN:OnLogin(function()
    Session.LoadSamples()

    Session.Observe()

    if C_Timer and C_Timer.NewTicker and not ticker then
        -- GUARDED. A C_Timer callback that throws goes to the client's own
        -- error handler, and a REPEATING ticker means a repeating error box:
        -- one bad observation and the player gets a popup every ten seconds
        -- for the rest of the session. Navigation's ticker has been guarded
        -- since 0.34.0; the four others were not.
        ticker = C_Timer.NewTicker(10, function()
            CN.Guard("Session.Observe", Session.Observe)
        end)
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "plan",
    aliases = { "time", "budget" },
    args    = "<minutes>",
    order   = 13,
    help    = "What fits in the time you actually have.",
    handler = function(args)
        local minutes = tonumber(CN.Trim(args or ""))

        if not minutes or minutes <= 0 then
            -- No number is no longer a usage error. The addon has watched how
            -- long this character plays; asking it beats asking the player,
            -- and a player who wanted a specific number can still say one.
            local typical, measured = Session.TypicalSessionMinutes()

            minutes = typical

            Print("Planning " .. minutes .. " minutes -- "
                .. (measured
                    and ("|cff999999your usual session on this character|r")
                    or ("|cff999999a default; play a few sessions and this "
                        .. "becomes your own figure|r")))
        end

        local plan = Session.Plan(minutes)

        if plan.blocked then
            -- Not "nothing to plan around": there is plenty, and the player
            -- cannot start any of it from where they are. Saying the first
            -- when the second is true is how an addon earns a reputation for
            -- not paying attention.
            Print(plan.notice or "Not while you are in the middle of that.")
            Print("|cff999999The plan is waiting; ask again when you are back "
                .. "in the world.|r")
            return
        end

        if #plan.stops == 0 then
            Print("Nothing here to plan around.")
            return
        end

        -- THE SUM OF NUMBERS TOO UNCERTAIN TO SHOW IS NOT A CERTAIN NUMBER.
        --
        -- Each individual stop below refuses to print a duration it is not
        -- confident in, and this headline printed their total as a plain
        -- figure regardless. One convention, both lines.
        Print(string.format("%d stop%s, about %s of the %dm you have:",
            #plan.stops,
            #plan.stops == 1 and "" or "s",
            CN.WithConfidence(Session.FormatDuration(plan.seconds),
                CN.ConfidenceFor(plan.confident)),
            plan.minutes))

        for index, stop in ipairs(plan.stops) do
            Print(string.format("  %d. |cffffff00%s|r |cff999999%s|r",
                index,
                tostring(stop.summary or "stop"),
                stop.confident and Session.FormatDuration(stop.seconds)
                    or (CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time")))
        end

        if plan.skipped > 0 then
            Print("|cff999999" .. plan.skipped
                .. " further stop(s) did not fit.|r")
        end

        if plan.overran then
            Print("|cffffff00The nearest stop is longer than the time you "
                .. "have.|r |cff999999Nothing smaller was available, so it "
                .. "is shown anyway -- but it will not fit.|r")
        end

        if not plan.confident then
            -- THE COUNT MUST BE THE COUNT BEHIND THE RATE.
            --
            -- `Speed()` answers from one bucket; `SpeedSampleCount()` with no
            -- argument summed all three. So the line justifying confidence in
            -- a 62 yd/s flying median cited forty-six samples, forty of which
            -- were on-foot readings at seven that had no part in it --
            -- overstating the evidence sevenfold in the one place whose whole
            -- job is to say how much evidence there is.
            local bucket = Session.Bucket()

            local rate, measured = Session.Speed(bucket)

            Print("|cffffff00Some of this is not measured yet.|r "
                .. "|cff999999Travel speed: "
                .. (measured and string.format("%.0f yd/s from %d %s samples",
                        rate, Session.SpeedSampleCount(bucket), bucket)
                    or "still learning")
                .. ". Task times are learned from your own play, so the "
                .. "estimate sharpens as you go rather than starting from "
                .. "numbers nobody measured.|r")
        end
    end,
}

------------------------------------------------------------
-- HOW LONG A THING TAKES, AS A SCORING TERM
------------------------------------------------------------

-- THE LEVER `/cn mode fastest` HAS ALWAYS ADVERTISED AND NEVER HAD.
--
-- `estimatedTime` is a declared scoring weight, summed on every objective,
-- printed by `/cn order`, and overridden by the `fastest` profile to -1.5 --
-- and nothing in the addon has ever set the field. So the mode's second lever
-- did nothing: `/cn mode fastest` was a travel-cost change wearing the name
-- of something broader.
--
-- The data to fill it has been collected since 0.41.0. This is the wiring.
--
-- SCALED, NOT RAW. A raw duration in seconds would swamp every other term --
-- a twenty-minute dungeon would arrive at 1200 against a completion value of
-- 5. The term is the duration in units of the typical objective, so 1 means
-- "about as long as things usually take", 3 means "three times as long", and
-- an objective the addon has never timed contributes nothing rather than a
-- guess. The addon does not invent a duration it has not watched.
Session.timeScaleSeconds = 300

function Session.TimeCost(objectiveType)
    local typical = Session.TypicalSeconds(objectiveType)

    if not typical or typical <= 0 then
        return nil
    end

    return typical / Session.timeScaleSeconds
end

-- A DECORATOR RECEIVES ONE OBJECTIVE, NOT A LIST.
--
-- This took `candidates` and iterated it, which yields nothing when handed a
-- single objective table -- so the field was never set on anything and
-- `/cn mode fastest` kept the inert second lever that 0.48.0 recorded as
-- fixed. Two mistakes in one edit: this, and the block landing INSIDE
-- Session.Speed because the anchor `return Session` also matched
-- `return Session.defaultSpeed`. Everything here was therefore defined only
-- as a side effect of calling Speed(), and re-registered on every call that
-- fell through all three buckets -- fifty-seven registrations of the same
-- decorator in one session.
--
-- The harness asserted that TimeCost exists and then hand-built objectives
-- with estimatedTime already set, testing the scorer against a fixture the
-- producer never made. That is precisely the trap this file's own comment
-- about the flying speed bucket warns about.
CN.RegisterCandidateDecorator("Session", function(objective)
    if type(objective) == "table" and objective.type then
        objective.estimatedTime = Session.TimeCost(objective.type)
    end
end)


return Session
'@

$Embedded['Modules\Alts.lua'] = @'
-- Modules/Alts.lua
-- Completion Navigator :: which character should be doing this.
--
-- The addon has known the answer for a while and had no way to volunteer it.
-- `Warband.WhoShould` answers one objective at a time, when asked, buried in
-- `/cn why`. The question a player actually has is the other way round:
--
--   "Is the character I am logged into the right one to be playing tonight?"
--
-- Nothing answered that. Every recommendation was implicitly "do this, here,
-- now, as you", even when the honest answer was "your Druid is two quests
-- from the same reward and this reputation does not carry across anyway".
--
-- WHAT THIS CAN AND CANNOT KNOW.
--
-- Everything here is built from what each character recorded the last time it
-- logged in. That is a real limitation and it is not a small one: a character
-- last seen three weeks ago is described as it was three weeks ago. The addon
-- says so rather than presenting stale data as current, and weights a
-- recommendation down as it ages -- a suggestion to switch to a character
-- whose data predates a patch is worth less than one about yesterday's.
--
-- It also refuses to recommend switching for anything account-wide. If the
-- progress carries across the Warband, the character doing it is irrelevant
-- and saying otherwise would be advice that costs a loading screen and buys
-- nothing.

local ADDON_NAME, CN = ...

local Alts = CN:RegisterModule("Alts")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- STALENESS
------------------------------------------------------------

-- How old a character's data is, in days.
function Alts.AgeDays(character)
    if not character or not character.lastSeen then
        return nil
    end

    return (time() - character.lastSeen) / 86400
end

-- Past this, the addon still reports what it knows but stops making
-- suggestions from it. A month-old snapshot of a character is a description
-- of a character that may not exist in that form any more.
Alts.staleDays = 30

function Alts.DescribeAge(character)
    local days = Alts.AgeDays(character)

    if not days then
        return "never seen"
    end

    if days < 1 then
        return "today"
    end

    if days < 2 then
        return "yesterday"
    end

    if days < 14 then
        return string.format("%d days ago", math.floor(days))
    end

    return string.format("%d weeks ago", math.floor(days / 7))
end

------------------------------------------------------------
-- WHAT IS WORTH SWITCHING FOR
------------------------------------------------------------

-- Only character-specific work can justify a switch. Account-wide progress
-- is, by definition, indifferent to who does it.
Alts.switchableTypes = {
    REPUTATION = true,
    RECIPE     = true,
    PROFESSION = true,
    TITLE      = true,
    QUEST      = true,
}

-- One assignment: a character, a reason, and what it is for.
local function NewAssignment(key, character, objective, reason)
    return {
        key       = key,
        name      = character and character.name or key,
        realm     = character and character.realm,
        class     = character and character.class,
        level     = character and character.level,
        ageDays   = Alts.AgeDays(character),
        objective = objective,
        reason    = reason,
    }
end

-- For each of the top recommendations, ask whether somebody else should be
-- doing it.
--
-- Bounded deliberately: this walks the roster per objective, and answering
-- for two hundred candidates would cost more than the answer is worth. The
-- things a player will actually do next are the things worth asking about.
Alts.considered = 20

function Alts.Assignments()
    local assignments = {}

    if not CN.Recommend then
        return assignments
    end

    local warband = CN:GetModule("Warband")

    if not warband or not warband.WhoShould then
        return assignments
    end

    local seen = {}

    for _, objective in ipairs(CN.Recommend(Alts.considered) or {}) do
        if Alts.switchableTypes[objective.type] then
            local ok, bestKey, detail, scope =
                pcall(warband.WhoShould, objective.type, objective.id)

            -- "account-wide" is a real answer meaning the question does not
            -- apply, and must never become a suggestion to switch.
            if ok and bestKey and scope ~= "account-wide"
                and bestKey ~= CN.characterKey then

                local character = CN.db and CN.db.characters
                    and CN.db.characters[bestKey]

                local age = Alts.AgeDays(character)

                if not age or age <= Alts.staleDays then
                    local key = bestKey .. "|" .. tostring(objective.type)
                        .. "|" .. tostring(objective.id)

                    if not seen[key] then
                        seen[key] = true

                        table.insert(assignments,
                            NewAssignment(bestKey, character, objective,
                                detail and (scope .. ": " .. detail) or scope))
                    end
                end
            end
        end
    end

    return assignments
end

-- Grouped by character, because "switch to this one" is the decision, and
-- three reasons to switch to the same character is a stronger case than one.
function Alts.ByCharacter()
    local grouped, order = {}, {}

    for _, assignment in ipairs(Alts.Assignments()) do
        if not grouped[assignment.key] then
            grouped[assignment.key] = {
                key     = assignment.key,
                name    = assignment.name,
                realm   = assignment.realm,
                class   = assignment.class,
                level   = assignment.level,
                ageDays = assignment.ageDays,
                items   = {},
            }

            table.insert(order, assignment.key)
        end

        table.insert(grouped[assignment.key].items, assignment)
    end

    local rows = {}

    for _, key in ipairs(order) do
        table.insert(rows, grouped[key])
    end

    -- The strongest case first: most reasons, then freshest data.
    table.sort(rows, function(a, b)
        if #a.items ~= #b.items then
            return #a.items > #b.items
        end

        return (a.ageDays or math.huge) < (b.ageDays or math.huge)
    end)

    return rows
end

------------------------------------------------------------
-- THE VERDICT
------------------------------------------------------------

-- Should you be playing somebody else?
--
-- Answers "no" far more often than "yes", and that is correct. A tool that
-- suggests a loading screen every time you log in is a tool people turn off.
Alts.minimumReasons = 2

function Alts.Verdict()
    local rows = Alts.ByCharacter()

    if #rows == 0 then
        return nil, "This character is the right one for everything on the list."
    end

    local best = rows[1]

    if #best.items < Alts.minimumReasons then
        return nil, string.format(
            "Nothing worth a loading screen. %s could do 1 of these, which is "
            .. "not enough to switch for.", tostring(best.name))
    end

    return best, string.format("%s could do %d of these.",
        tostring(best.name), #best.items)
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "alts",
    -- No aliases. `who` and `warband` were declared here and both are real
    -- commands registered by Modules/Warband.lua, which loads later and
    -- overwrote them -- so these two entries have never resolved to anything
    -- in this file, while the help listed all three side by side as if they
    -- were different answers.
    aliases = { "alt", "characters" },
    order   = 12,
    help    = "Which character should be doing what, and whether to switch.",
    handler = function()
        local warband = CN:GetModule("Warband")

        if not warband then
            Print("The Warband module is not loaded.")
            return
        end

        local roster = warband.Roster()

        if #roster <= 1 then
            Print("Only this character has been seen. Log in on another and "
                .. "it will be recorded.")
            return
        end

        local best, verdict = Alts.Verdict()

        Print(verdict)

        if best then
            Print("|cffffd100" .. tostring(best.name) .. "|r"
                .. (best.level and (" (" .. best.level .. ")") or "")
                .. " |cff999999last played "
                .. Alts.DescribeAge({ lastSeen = time() - ((best.ageDays or 0) * 86400) })
                .. "|r")

            for _, item in ipairs(best.items) do
                Print("  |cffffff00" .. tostring(item.objective.name)
                    .. "|r |cff999999" .. tostring(item.reason) .. "|r")
            end
        end

        Print(" ")
        Print("Your Warband:")

        for _, row in ipairs(roster) do
            local character = CN.db and CN.db.characters
                and CN.db.characters[row.key]

            Print(string.format("  %s%-18s|r %-4s %-10s |cff999999%s|r",
                row.isCurrent and "|cff00ff00" or "|cffffffff",
                tostring(row.name),
                tostring(row.level or "?"),
                tostring(row.class or ""),
                Alts.DescribeAge(character)))
        end

        Print("|cff999999Everything here is what each character recorded the "
            .. "last time it logged in.|r")
    end,
}

return Alts
'@

$Embedded['Modules\Vault.lua'] = @'
-- Modules/Vault.lua
-- Completion Navigator :: the Great Vault.
--
-- The weekly reward chest. Three rows -- raid, dungeons, world -- each with
-- three thresholds, and you choose ONE item from everything unlocked.
--
-- This module matters more than its size suggests, because the Great Vault is
-- the only system in the game that hands the addon all three things it
-- normally has to guess at:
--
--   * a hard deadline      -- the weekly reset, which the client reports
--   * a known denominator  -- the thresholds are fixed
--   * a known reward       -- the client reports the item level
--
-- Everywhere else this addon reports counts rather than percentages, because
-- a percentage needs a denominator the client will not supply. Here it will.
-- "3 of 4 dungeons" is a fact, and "one more Heroic before Tuesday unlocks a
-- second reward" is a genuine next action rather than an estimate.
--
-- The nearly-there row is the whole point. A row sitting one activity short of
-- a threshold is the highest-value, most time-boxed objective the addon can
-- offer; a row already at its cap is worth nothing this week.

local ADDON_NAME, CN = ...

local Vault = CN:RegisterModule("Vault")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- ROWS
------------------------------------------------------------

Vault.rowLabels = {
    RAID    = "Raid",
    DUNGEON = "Dungeons",
    WORLD   = "World",
    PVP     = "PvP",
    UNKNOWN = "Other",
}

-- What the player would actually go and do to advance each row. Naming the
-- action is the difference between a progress bar and a recommendation.
Vault.rowActions = {
    RAID    = "defeat another raid boss",
    DUNGEON = "run another Heroic or higher dungeon",
    WORLD   = "complete another Delve, weekly quest or zone event",
    PVP     = "complete another rated PvP match",
    UNKNOWN = "complete another qualifying activity",
}

local ROW_ORDER = { "RAID", "DUNGEON", "WORLD", "PVP", "UNKNOWN" }

------------------------------------------------------------
-- READING THE VAULT
------------------------------------------------------------

-- Collapses the flat activity list into one entry per row:
--
--   { row, label, progress, unlocked, tiers, next, remaining, capped }
--
-- `next` is the next unmet threshold; `remaining` is how many activities
-- away it is. Both nil when the row is capped.
function Vault.Rows()
    local activities = Blizzard.GetWeeklyRewardActivities()

    if #activities == 0 then
        return {}
    end

    local byRow = {}

    for _, activity in ipairs(activities) do
        local row = byRow[activity.row]

        if not row then
            row = {
                row      = activity.row,
                label    = Vault.rowLabels[activity.row] or activity.row,
                progress = 0,
                unlocked = 0,
                tiers    = {},
            }

            byRow[activity.row] = row
        end

        -- Every tier of a row reports the same progress figure; taking the
        -- maximum is defensive rather than necessary.
        row.progress = math.max(row.progress, activity.progress or 0)

        table.insert(row.tiers, {
            threshold = activity.threshold,
            progress  = activity.progress,
            level     = activity.level,
            unlocked  = activity.unlocked,
        })

        if activity.unlocked then
            row.unlocked = row.unlocked + 1
        end
    end

    local rows = {}

    for _, name in ipairs(ROW_ORDER) do
        local row = byRow[name]

        if row then
            table.sort(row.tiers, function(a, b)
                return (a.threshold or 0) < (b.threshold or 0)
            end)

            for _, tier in ipairs(row.tiers) do
                if not tier.unlocked and not row.next then
                    row.next      = tier.threshold
                    row.remaining = math.max(0, (tier.threshold or 0) - row.progress)
                end
            end

            row.capped = row.next == nil

            table.insert(rows, row)
        end
    end

    return rows
end

function Vault.IsAvailable()
    return Blizzard.HasWeeklyRewards()
end

-- Total reward choices unlocked across every row.
function Vault.Summary()
    local rows = Vault.Rows()

    local summary = {
        rows     = #rows,
        unlocked = 0,
        closest  = nil,
        resetsIn = Blizzard.GetSecondsUntilWeeklyReset(),
        claimable = Blizzard.HasAvailableWeeklyRewards(),
    }

    for _, row in ipairs(rows) do
        summary.unlocked = summary.unlocked + row.unlocked

        if not row.capped and row.remaining then
            if not summary.closest or row.remaining < summary.closest.remaining then
                summary.closest = row
            end
        end
    end

    return summary
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

local function FormatReset(seconds)
    if not seconds then
        return nil
    end

    local days  = math.floor(seconds / 86400)
    local hours = math.floor((seconds % 86400) / 3600)

    if days > 0 then
        return days .. "d " .. hours .. "h"
    end

    if hours > 0 then
        return hours .. "h"
    end

    return math.max(1, math.floor(seconds / 60)) .. "m"
end

Vault.FormatReset = FormatReset

function Vault.DescribeRow(row)
    local text = row.label .. ": " .. row.progress

    if row.capped then
        return text .. " |cff00ff00all " .. row.unlocked .. " unlocked|r"
    end

    return text .. " of " .. row.next
        .. " |cff999999(" .. row.unlocked .. " unlocked, "
        .. row.remaining .. " more for the next)|r"
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Urgency rises as the reset approaches AND as the row nears its threshold.
-- One activity away with a day left is the single most actionable thing the
-- addon can surface; three away with six days left is barely worth a mention.
local function Urgency(remaining, resetsIn)
    local value = 0

    if remaining then
        if remaining <= 1 then
            value = value + 3
        elseif remaining <= 2 then
            value = value + 2
        else
            value = value + 1
        end
    end

    if resetsIn then
        local days = resetsIn / 86400

        if days <= 1 then
            value = value + 3
        elseif days <= 2 then
            value = value + 2
        elseif days <= 4 then
            value = value + 1
        end
    end

    return value
end

Vault.Urgency = Urgency

-- How many activities away a row can be and still be worth recommending.
-- Beyond this it is a plan for the week, not a next action.
Vault.maxRemaining = 4

CN.RegisterCandidateProvider("Vault", function()
    local candidates = {}

    if not Vault.IsAvailable() then
        return candidates
    end

    local resetsIn = Blizzard.GetSecondsUntilWeeklyReset()

    -- An unclaimed vault from last week outranks everything: it is free, it
    -- takes thirty seconds, and it expires.
    if Blizzard.HasAvailableWeeklyRewards() then
        table.insert(candidates, CN.NewObjective({
            id               = 0,
            type             = CN.objectiveTypes.CURRENCY,
            name             = "Collect your Great Vault reward",
            accountWide      = false,
            completionValue  = 8,
            limitedTimeBonus = 3,
            travelCost       = 2,
            reasons          = {
                "a reward is waiting to be claimed",
                "it is replaced when the vault next fills",
            },
        }))
    end

    for _, row in ipairs(Vault.Rows()) do
        if not row.capped
            and row.remaining
            and row.remaining <= Vault.maxRemaining
            and not CN.IsIgnored(CN.objectiveTypes.CURRENCY, row.row)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, row.row) then

            local reasons = {
                row.remaining .. " more to unlock a "
                    .. (row.unlocked > 0 and "further" or "first")
                    .. " Great Vault reward",
                Vault.rowActions[row.row] or "complete another activity",
            }

            if resetsIn then
                table.insert(reasons, "resets in " .. FormatReset(resetsIn))
            end

            table.insert(candidates, CN.NewObjective({
                id               = row.row,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Great Vault: " .. row.label,
                accountWide      = false,
                completionValue  = 4,
                limitedTimeBonus = Urgency(row.remaining, resetsIn),
                -- Instanced content has no map coordinate, but it is not
                -- "location unknown" either: the group finder is one click.
                travelCost       = 3,
                expiresIn        = resetsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "WEEKLY_REWARDS_UPDATE", "CHALLENGE_MODE_COMPLETED",
                  "ENCOUNTER_END", "QUEST_TURNED_IN" }, volatile = true })

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vault",
    aliases = { "greatvault" },
    order   = 16,
    help    = "Great Vault progress and what unlocks the next reward.",
    handler = function()
        if not Vault.IsAvailable() then
            Print("The Great Vault is not available on this client.")
            return
        end

        local rows = Vault.Rows()

        if #rows == 0 then
            Print("No Great Vault progress recorded yet.")
            Print("|cff999999The client reports vault progress once you have "
                .. "completed at least one qualifying activity this week.|r")
            return
        end

        local summary = Vault.Summary()

        Print("Great Vault: " .. summary.unlocked .. " reward"
            .. (summary.unlocked == 1 and "" or "s") .. " unlocked"
            .. (summary.resetsIn
                and (" |cff999999resets in " .. FormatReset(summary.resetsIn) .. "|r")
                or ""))

        if summary.claimable then
            Print("|cff00ff00A reward is waiting to be collected.|r")
        end

        for _, row in ipairs(rows) do
            Print("  " .. Vault.DescribeRow(row))
        end

        if summary.closest then
            Print("|cffffff00Closest:|r " .. summary.closest.label
                .. " -- " .. summary.closest.remaining .. " more, "
                .. (Vault.rowActions[summary.closest.row] or "keep going") .. ".")
        else
            Print("|cff00ff00Every row is capped. Nothing more to earn this week.|r")
        end

        Print("|cff999999You choose one item from everything unlocked.|r")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Navigation.lua'] = @'
-- Modules/Navigation.lua
-- Completion Navigator :: native waypoints and the on-screen arrow.
--
-- Until now the addon decided WHERE to go and handed the job of pointing at it
-- to TomTom. That made TomTom effectively required: without it you got a
-- static map pin and no arrow, which is not navigation.
--
-- This file removes that dependency. It is not an attempt to reimplement
-- TomTom -- it is the minimum that makes the addon complete on its own:
--
--   * a waypoint store of our own
--   * an arrow that points at the current target and colours by whether you
--     are facing it
--   * real distance in yards, not map percentage
--   * arrival detection, which is what makes auto-advance work properly
--
-- TomTom stays supported. Someone who already runs it and likes its arrow can
-- keep using it -- /cn nav tomtom -- and everything else still works.
--
------------------------------------------------------------------------------
-- THE MATH, and an admission about it.
--
--   Map coordinates run x east, y SOUTH. North is therefore -y.
--   bearing clockwise from north = atan2(dx, -dy)
--   relative bearing             = bearing - (facing * facingSign)
--   rotation to apply            = -(relative bearing)
--
-- The one thing that cannot be derived from first principles is which way
-- GetPlayerFacing() counts. 0 is north on every build; whether the value grows
-- as you turn left or as you turn right is a client convention.
--
-- 0.19.0 assumed counter-clockwise and shipped a bearing that pointed people
-- away from their target. The harness "verified" it against seven cases -- and
-- every one of those cases computed its expected answer from the same
-- assumption, so the tests agreed with the bug. A test that encodes the
-- premise it is meant to check proves nothing.
--
-- So the sign is not asserted here. It defaults to the convention every
-- established navigation addon uses, and then CORRECTS ITSELF from evidence:
-- if you are lined up with the arrow, moving, and the distance is growing,
-- the sign is wrong, and the addon flips it and says so. The game is the only
-- thing that can settle this, so the game settles it.
--
-- 0.40.0 added a second, better source of that evidence, because the first
-- one only fires when the player happens to be lined up with a target and
-- walking. When you move at all, the direction you moved IS the direction you
-- were facing, and only one of the two conventions agrees with that. See
-- NoteMotion below. Strafing and walking backwards agree with neither, so
-- they are discarded rather than voted on.
--
-- 0.40.0 also fixed an error that was present in every zone: angles were
-- taken from raw map coordinates, which normalize to 0-1 regardless of the
-- shape of the ground, so every bearing was stretched by the zone's aspect
-- ratio. See MapScale.
------------------------------------------------------------------------------

local ADDON_NAME, CN = ...

local Navigation = CN:RegisterModule("Navigation")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STATE
------------------------------------------------------------

-- The single active target. One arrow, one destination: a list of waypoints is
-- TomTom's job, and duplicating it would be duplicating the wrong half.
local target = nil

local arrow, ticker

Navigation.arrivalYards = 12

function Navigation.GetTarget()
    return target
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Radians clockwise from straight ahead. nil when the bearing cannot be
-- computed, which is different from zero and must not be shown as zero.
-- +1 means GetPlayerFacing() grows clockwise; -1 means counter-clockwise.
-- Persisted once determined, so the correction happens at most once ever.
function Navigation.FacingSign()
    local settings = CN.Settings()

    if settings and settings.facingSign then
        return settings.facingSign
    end

    return 1
end

function Navigation.SetFacingSign(sign)
    local settings = CN.Settings()

    if settings then
        settings.facingSign = (sign < 0) and -1 or 1
    end
end

-- MAP COORDINATES ARE NOT SQUARE, AND ANGLES MEASURED IN THEM ARE WRONG.
--
-- Every map normalizes to 0-1 in both axes regardless of the shape of the
-- ground it covers. A zone 3,000 yards wide and 2,000 yards tall therefore
-- stretches its vertical axis by half again, and an angle computed from raw
-- map deltas is distorted by exactly that ratio: a target genuinely 45
-- degrees off reads as 56 degrees in that zone, and worse in a long one.
--
-- The arrow was doing that in every zone in the game. It is not enough to be
-- noticed as "the arrow is broken" -- it is enough to be noticed as "the
-- arrow is sloppy", and both complaints about the arrow so far have come with
-- "it doesn't point quite right" attached.
--
-- The client will tell us the real width and height in yards, so ask once per
-- map and scale the deltas into yards before taking the angle.
local mapScales = {}

function Navigation.MapScale(mapID)
    if not mapID then
        return 1, 1
    end

    local cached = mapScales[mapID]

    if cached then
        return cached[1], cached[2]
    end

    -- A tenth of the map, measured across the middle, where a map is least
    -- likely to be doing something strange at its edges.
    local span = 0.1

    local xYards = Navigation.DistanceYards(mapID, 0.45, 0.5, 0.45 + span, 0.5)
    local yYards = Navigation.DistanceYards(mapID, 0.5, 0.45, 0.5, 0.45 + span)

    if not xYards or not yYards or xYards <= 0 or yYards <= 0 then
        -- Do NOT cache a failure. A map the client would not convert during a
        -- loading screen will convert a second later, and caching 1,1 would
        -- keep the distortion for the rest of the session.
        return 1, 1
    end

    xYards = xYards / span
    yYards = yYards / span

    mapScales[mapID] = { xYards, yYards }

    return xYards, yYards
end

function Navigation.ForgetMapScales()
    mapScales = {}
end

function Navigation.RelativeBearing(playerX, playerY, targetX, targetY, facing, sign, mapID)
    if not (playerX and playerY and targetX and targetY and facing) then
        return nil
    end

    local scaleX, scaleY = Navigation.MapScale(mapID)

    local dx = (targetX - playerX) * scaleX
    local dy = (targetY - playerY) * scaleY

    if dx == 0 and dy == 0 then
        return 0
    end

    -- -dy because map y grows southward.
    local bearing = CN.Atan2(dx, -dy)

    local relative = bearing - (facing * (sign or Navigation.FacingSign()))

    -- Normalize to (-pi, pi] so "how far off am I" is a small number.
    --
    -- THROUGH THE SHIM, WHICH IS WHAT THE SHIM IS FOR.
    --
    -- Core.lua defines `CN.Mod` as the floored modulo -- "if a construct
    -- means two things, the addon uses neither directly; it uses one of
    -- these" -- and then the one place in the addon that wraps an angle did
    -- it with two unbounded `while` loops instead. So the rule was enforced
    -- nowhere and the shim had no call sites at all, which is how a
    -- compatibility guard quietly stops being one.
    --
    -- The loops were also unbounded: a non-finite bearing spins the client.
    -- This is O(1) and it cannot.
    local full = 2 * math.pi

    relative = CN.Mod(relative + math.pi, full) - math.pi

    -- CN.Mod's range is [0, full), so the line above lands in [-pi, pi).
    -- The addon's convention is (-pi, pi] -- exactly antipodal must read as
    -- "behind you", not "behind you, negative".
    if relative == -math.pi then
        relative = math.pi
    end

    return relative
end

-- Distance in yards, using the client's world positions. Map coordinates are
-- normalized per map, so a 0.1 difference is a different real distance in
-- every zone; converting is the only way to get a number worth printing.
--
-- Returns nil when the client cannot convert, rather than a made-up figure.
function Navigation.DistanceYards(mapID, playerX, playerY, targetX, targetY)
    if not (mapID and playerX and playerY and targetX and targetY) then
        return nil
    end

    if not C_Map or not C_Map.GetWorldPosFromMapPos then
        return nil
    end

    -- GetWorldPosFromMapPos takes a Vector2D, NOT a UiMapPoint.
    --
    -- These are two different types and 0.19.0 passed the wrong one, so the
    -- call returned nothing and the arrow reported "distance unknown" for
    -- every target. UiMapPoint carries a nested `position`; Vector2D carries
    -- x and y directly. SetUserWaypoint wants the former, this wants the
    -- latter, and they are easy to confuse because both describe a point.
    if not CreateVector2D then
        return nil
    end

    local function worldPosition(x, y)
        local ok, continentID, position =
            pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

        if not ok or not position then
            return nil, nil
        end

        -- Vector2D exposes GetXY(); some builds also expose x and y directly.
        local wx, wy

        if position.GetXY then
            local gotXY, gx, gy = pcall(position.GetXY, position)

            if gotXY then
                wx, wy = gx, gy
            end
        end

        wx = wx or position.x
        wy = wy or position.y

        if not wx or not wy then
            return nil, nil
        end

        return continentID, { x = wx, y = wy }
    end

    local fromContinent, fromPos = worldPosition(playerX, playerY)

    if not fromPos then
        return nil
    end

    local toContinent, toPos = worldPosition(targetX, targetY)

    if not toPos then
        return nil
    end

    -- Different continents means the straight-line number would be nonsense.
    if fromContinent and toContinent and fromContinent ~= toContinent then
        return nil
    end

    local dx = toPos.x - fromPos.x
    local dy = toPos.y - fromPos.y

    return math.sqrt((dx * dx) + (dy * dy))
end

function Navigation.FormatDistance(yards)
    if not yards then
        return CN.L["distance unknown"]
    end

    if yards >= 1000 then
        return string.format("%.1f km", yards * 0.0009144)
    end

    return string.format("%d yd", math.floor(yards + 0.5))
end

------------------------------------------------------------
-- THE ARROW
------------------------------------------------------------

local function Settings()
    return CN.Settings() or {}
end

function Navigation.IsArrowEnabled()
    local settings = Settings()

    return settings.arrow ~= false
end

local function BuildArrow()
    if arrow or not CreateFrame then
        return arrow
    end

    arrow = CreateFrame("Frame", "CompletionNavigatorArrow", UIParent)

    arrow:SetSize(56, 56)
    arrow:SetFrameStrata("MEDIUM")
    arrow:SetMovable(true)
    arrow:EnableMouse(true)
    arrow:RegisterForDrag("LeftButton")
    arrow:SetClampedToScreen(true)

    local settings = Settings()

    settings.arrowPosition = settings.arrowPosition or {}

    arrow:SetPoint(
        settings.arrowPosition.point or "CENTER",
        UIParent,
        settings.arrowPosition.point or "CENTER",
        settings.arrowPosition.x or 0,
        settings.arrowPosition.y or 160)

    arrow.texture = arrow:CreateTexture(nil, "ARTWORK")
    arrow.texture:SetAllPoints()
    arrow.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    -- SetTexture fails silently on a missing file, so verify rather than
    -- shipping an invisible arrow.
    if not arrow.texture:GetTexture() then
        arrow.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    arrow.label = arrow:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    arrow.label:SetPoint("TOP", arrow, "BOTTOM", 0, -2)
    arrow.label:SetJustifyH("CENTER")

    arrow.distance = arrow:CreateFontString(nil, "OVERLAY", "GameFontHighlightLarge")
    arrow.distance:SetPoint("TOP", arrow.label, "BOTTOM", 0, -2)
    arrow.distance:SetJustifyH("CENTER")

    arrow:SetScript("OnDragStart", function(self)
        self:StartMoving()
    end)

    arrow:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local point, _, _, x, y = self:GetPoint()

        local saved = Settings()

        saved.arrowPosition = { point = point, x = x, y = y }
    end)

    arrow:Hide()

    return arrow
end

Navigation.BuildArrow = BuildArrow

-- The arrow's palette.
--
-- ON_COURSE is the blue of the waypoint marker in the addon's own logo,
-- sampled from it rather than guessed: #5DD2FB. Because you are pointed at
-- your target most of the time, this is the colour the arrow actually wears,
-- which is what makes it read as part of the addon rather than as generic
-- navigation furniture.
--
-- The texture is greyscale for exactly this reason: tinting is a multiply, so
-- a pre-coloured blue arrow could never turn amber, and the bearing feedback
-- would be lost to make one screenshot prettier.
Navigation.colors = {
    ON_COURSE = { 0.365, 0.824, 0.984 },   -- #5DD2FB, the logo's marker blue
    DRIFTING  = { 1.000, 0.780, 0.310 },   -- the logo's gold, for "turn a bit"
    AWAY      = { 0.960, 0.420, 0.380 },   -- you are walking the wrong way
    UNKNOWN   = { 0.600, 0.640, 0.680 },   -- no bearing available
}

-- THE PALETTE ITSELF, NOT ONLY A LABEL BESIDE IT.
--
-- Colourblind mode has until now added a word next to the arrow, which
-- satisfies "no information carried by colour alone" and leaves the colours
-- themselves as bad as they were. Gold against red is the single worst pair
-- for the commonest form of colour blindness -- and it is the pair carrying
-- "drifting" against "walking away", which is the distinction the arrow
-- exists to make.
--
-- Blue and orange instead, which separate under every common form, with
-- white for on-course so the three differ in lightness as well as in hue.
-- Somebody who cannot tell the hues apart can still tell these apart.
-- Chosen so that the three differ by at least 0.27 in relative luminance --
-- checked by the suite, not by eye. Lightness is what survives when hue does
-- not.
Navigation.colorblindColors = {
    ON_COURSE = { 0.980, 0.980, 0.980 },   -- near-white, luminance 0.98
    DRIFTING  = { 0.400, 0.760, 1.000 },   -- light blue,  luminance 0.70
    AWAY      = { 0.780, 0.340, 0.020 },   -- dark orange, luminance 0.41
    UNKNOWN   = { 0.520, 0.540, 0.560 },
}

function Navigation.Palette()
    local hud = CN:GetModule("Hud")

    if hud and hud.IsColourblind and hud.IsColourblind() then
        return Navigation.colorblindColors
    end

    return Navigation.colors
end

-- Blue when you are walking toward it, gold when you are drifting, red when
-- you are walking away. The single most useful thing an arrow does, and it
-- costs one comparison.
function Navigation.BearingColor(relative)
    local palette = Navigation.Palette()

    if not relative then
        return palette.UNKNOWN[1], palette.UNKNOWN[2], palette.UNKNOWN[3]
    end

    local off = math.abs(relative)

    if off < 0.35 then
        return palette.ON_COURSE[1], palette.ON_COURSE[2], palette.ON_COURSE[3]
    end

    if off < 1.2 then
        return palette.DRIFTING[1], palette.DRIFTING[2], palette.DRIFTING[3]
    end

    return palette.AWAY[1], palette.AWAY[2], palette.AWAY[3]
end

-- Recomputes the arrow. Split out so the harness can drive it without a frame.
-- The player's position expressed on a specific map, or nil.
--
-- Works for any map that can describe where the player is standing -- a zone
-- while you are inside one of its buildings, for instance -- and returns nil
-- when it genuinely cannot, which is the honest answer for another continent.
function Navigation.PlayerPositionOnMap(mapID)
    if not mapID or not C_Map or not C_Map.GetPlayerMapPosition then
        return nil
    end

    local ok, position = pcall(C_Map.GetPlayerMapPosition, mapID, "player")

    if not ok or not position then
        return nil
    end

    local x, y

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            x, y = gx, gy
        end
    end

    x = x or position.x
    y = y or position.y

    if not x or not y then
        return nil
    end

    -- The client answers (0, 0) for a map that cannot place you, which is a
    -- real coordinate on every map and therefore indistinguishable from a
    -- corner. Treated as "cannot say", because a corner is a far less likely
    -- place to be standing than nowhere.
    if x == 0 and y == 0 then
        return nil
    end

    return { x = x, y = y }
end

function Navigation.Compute()
    if not target then
        return nil
    end

    local mapID, playerX, playerY = CN.GetPlayerPosition()

    if not mapID or not playerX or not playerY then
        return { state = "NO_POSITION" }
    end

    -- THE MAP UNDER YOUR FEET IS NOT THE MAP THE TARGET IS ON.
    --
    -- `GetBestMapForUnit` answers with the most SPECIFIC map containing you:
    -- step into a building, a cave, an inn or a city district and it changes,
    -- even though you have moved thirty yards. The arrow compared that to the
    -- target's map, found them different, and gave up -- announcing "another
    -- zone" while standing next to the destination.
    --
    -- This is the same defect that made available quests invisible in a city
    -- in 0.27.0, in a different file. The fix is the same shape: ask the
    -- client for the player's position expressed on the map that matters,
    -- rather than assuming the two maps are the same one.
    local onTargetMap = false

    if mapID ~= target.mapID then
        local translated = Navigation.PlayerPositionOnMap(target.mapID)

        if translated then
            mapID   = target.mapID
            playerX = translated.x
            playerY = translated.y

            onTargetMap = true
        else
            -- Genuinely somewhere the target's map cannot describe --
            -- another continent, or an instance.
            return {
                state = "WRONG_MAP",
                zone  = target.zone or Blizzard.GetMapName(target.mapID),
            }
        end
    end

    local facing = GetPlayerFacing and GetPlayerFacing() or nil

    local relative = Navigation.RelativeBearing(playerX, playerY,
        target.x, target.y, facing, nil, mapID)

    local yards = Navigation.DistanceYards(mapID, playerX, playerY,
        target.x, target.y)

    local within = yards and yards <= Navigation.arrivalYards

    -- ARRIVAL DOES NOT LATCH.
    --
    -- REPORTED FROM LIVE PLAY, TWICE: "I walked past it and the arrow did not
    -- turn around." `target.arrived` was set once and never cleared, so a
    -- player who walked through the destination and kept going was, as far as
    -- this code was concerned, still arrived -- forever.
    --
    -- Walking back out of the arrival radius is the player un-arriving. Say
    -- so, so that tracking resumes and the arrow turns round.
    if target.arrived and yards and yards > (Navigation.arrivalYards * 2) then
        target.arrived = false

        DebugPrint("Left the destination; tracking it again.")
    end

    return {
        state    = within and "ARRIVED" or "TRACKING",
        relative = relative,
        yards    = yards,
        facing   = facing,
        within   = within,
        mapID    = mapID,
        playerX  = playerX,
        playerY  = playerY,
        translated = onTargetMap,
    }
end

------------------------------------------------------------
-- SELF-CORRECTION
------------------------------------------------------------

-- Evidence that the facing convention is backwards.
--
-- If you are lined up with the arrow and moving, the distance must shrink. If
-- it grows instead, the arrow is pointing at the reciprocal. That is not a
-- guess -- it is the definition of the arrow being wrong, observed directly.
--
-- Several consecutive samples are required so that walking backwards, a
-- flight path, or a teleport cannot trigger it.
local calibration = {
    lastDistance = nil,
    growing      = 0,
    corrected    = false,
}

Navigation.calibrationSamples = 4

function Navigation.ResetCalibration()
    calibration.lastDistance = nil
    calibration.growing      = 0
end

-- WHICH WAY DOES GetPlayerFacing COUNT?
--
-- Everything the arrow does rests on one unverified assumption: that the
-- number the client gives for "facing" grows in the same rotational direction
-- as the bearing computed from map coordinates. If it does not, the arrow is
-- not backwards -- it is MIRRORED, wrong by twice your facing, which looks
-- right when you face north and badly wrong when you face east. That is a
-- much better description of what was reported twice than "backwards" was.
--
-- The old evidence for it was indirect: follow the arrow, and if the distance
-- grows, the arrow is wrong. That only fires when the player happens to be
-- lined up and walking, and cannot fire at all when nothing is targeted.
--
-- This is direct evidence instead, and it needs no target and no cooperation:
-- when you MOVE, the direction you moved is the direction you were facing.
-- Compute the bearing of your own movement, compare it against your facing
-- under both conventions, and only one of them can agree. Strafing and
-- walking backwards agree with neither, so they are discarded rather than
-- voted on -- which is what makes this safe to run continuously.
local motion = {
    mapID   = nil,
    x       = nil,
    y       = nil,
    agree   = 0,
    against = 0,
    samples = 0,
    verdict = nil,
}

-- Consecutive agreeing samples before the sign is changed. At ten samples a
-- second this is a fraction of a second of walking, but every one of them has
-- to agree, and one strafe resets the count.
Navigation.motionSamples   = 6

-- Below this the player is standing still; above it, a loading screen, a
-- flight path or a teleport.
Navigation.motionMinYards  = 1.5
Navigation.motionMaxYards  = 60

-- How close a hypothesis has to be to count as agreeing, and how far the
-- other one has to be to count as excluded.
Navigation.motionAgree     = math.rad(25)
Navigation.motionExclude   = math.rad(60)

local function Normalize(angle)
    while angle > math.pi do
        angle = angle - (2 * math.pi)
    end

    while angle <= -math.pi do
        angle = angle + (2 * math.pi)
    end

    return angle
end

Navigation.NormalizeAngle = Normalize

function Navigation.ResetMotion()
    motion.mapID   = nil
    motion.x       = nil
    motion.y       = nil
    motion.agree   = 0
    motion.against = 0
end

function Navigation.MotionState()
    return {
        samples = motion.samples,
        agree   = motion.agree,
        against = motion.against,
        verdict = motion.verdict,
        sign    = Navigation.FacingSign(),
    }
end

-- Returns the sign the evidence supports, or nil when this sample said
-- nothing. Separated from the sampling so it can be tested as arithmetic.
function Navigation.SignFromMotion(moved, facing)
    if not moved or not facing then
        return nil
    end

    local withPlus  = math.abs(Normalize(moved - facing))
    local withMinus = math.abs(Normalize(moved + facing))

    if withPlus <= Navigation.motionAgree and withMinus >= Navigation.motionExclude then
        return 1
    end

    if withMinus <= Navigation.motionAgree and withPlus >= Navigation.motionExclude then
        return -1
    end

    -- Facing north or south makes both conventions agree, so the sample
    -- cannot distinguish them and must not be counted as evidence for the one
    -- we happen to be using.
    return nil
end

function Navigation.NoteMotion()
    if not GetPlayerFacing then
        return nil
    end

    if UnitOnTaxi and UnitOnTaxi("player") then
        Navigation.ResetMotion()
        return nil
    end

    local mapID, x, y = CN.GetPlayerPosition()

    if not mapID or not x or not y then
        Navigation.ResetMotion()
        return nil
    end

    local previousMap, previousX, previousY = motion.mapID, motion.x, motion.y

    motion.mapID, motion.x, motion.y = mapID, x, y

    if previousMap ~= mapID or not previousX then
        return nil
    end

    local scaleX, scaleY = Navigation.MapScale(mapID)

    local dx = (x - previousX) * scaleX
    local dy = (y - previousY) * scaleY

    local yards = math.sqrt((dx * dx) + (dy * dy))

    if yards < Navigation.motionMinYards then
        -- Standing still is not evidence against anything; leave the tally.
        return nil
    end

    if yards > Navigation.motionMaxYards then
        Navigation.ResetMotion()
        return nil
    end

    local facing = GetPlayerFacing()

    if not facing then
        return nil
    end

    local moved = CN.Atan2(dx, -dy)

    local supported = Navigation.SignFromMotion(moved, facing)

    if not supported then
        return nil
    end

    motion.samples = motion.samples + 1

    if supported == Navigation.FacingSign() then
        motion.agree   = motion.agree + 1
        motion.against = 0

        -- "corrected" is sticky. Once the sign has been changed this session,
        -- every subsequent sample agrees with it by construction, and
        -- overwriting the verdict with "confirmed" would erase the only
        -- record that anything was ever wrong -- which is the single most
        -- useful line in a bug report about the arrow.
        if motion.verdict ~= "corrected" then
            motion.verdict = "confirmed"
        end

        return nil
    end

    motion.against = motion.against + 1
    motion.agree   = 0

    if motion.against < Navigation.motionSamples then
        return nil
    end

    motion.against = 0
    motion.verdict = "corrected"

    Navigation.SetFacingSign(supported)
    Navigation.ResetCalibration()

    Print("The arrow was reading your facing backwards. Corrected, and "
        .. "remembered.")
    DebugPrint("Facing sign is now " .. Navigation.FacingSign()
        .. ", from " .. motion.samples .. " movement samples.")

    return supported
end

function Navigation.NoteObservation(relative, yards)
    -- Only meaningful while genuinely lined up: if you are not following the
    -- arrow, the distance says nothing about whether the arrow is right.
    if not relative or not yards or math.abs(relative) > 0.3 then
        Navigation.ResetCalibration()
        return false
    end

    local previous = calibration.lastDistance

    calibration.lastDistance = yards

    if not previous then
        return false
    end

    local delta = yards - previous

    -- Ignore standing still and ignore jumps far too large to be walking,
    -- which are loading screens rather than movement.
    if math.abs(delta) < 0.5 or math.abs(delta) > 200 then
        return false
    end

    if delta > 0 then
        calibration.growing = calibration.growing + 1
    else
        calibration.growing = 0
    end

    if calibration.growing < Navigation.calibrationSamples then
        return false
    end

    calibration.growing = 0

    if calibration.corrected then
        -- Already flipped once this session and still wrong: flipping back and
        -- forth forever would be worse than leaving it alone.
        return false
    end

    calibration.corrected = true

    Navigation.SetFacingSign(-Navigation.FacingSign())

    Print("The arrow was pointing the wrong way. Corrected, and remembered.")
    DebugPrint("Facing sign is now " .. Navigation.FacingSign() .. ".")

    return true
end

-- Wipe what the arrow is showing.
--
-- Hiding a frame does not clear it. The rotation, the colour and the distance
-- stay exactly as they were, so an arrow hidden while pointing north-east at
-- "10 yd" is still pointing north-east at "10 yd" the moment anything shows
-- it again -- a stale claim about a destination that is no longer being
-- tracked. Costs nothing to reset; costs the player's trust not to.
local function Blank()
    Navigation.ResetSmoothing()
    Navigation.ResetDistanceSmoothing()

    if not arrow then
        return
    end

    if arrow.texture then
        arrow.texture:SetRotation(0)
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
    end

    if arrow.distance then
        arrow.distance:SetText("")
    end

    if arrow.label then
        arrow.label:SetText("")
    end
end

Navigation.Blank = Blank

-- SMOOTHING.
--
-- The arrow recomputes ten times a second and snapped straight to each new
-- bearing, so a player turning on the spot saw it step rather than sweep. The
-- underlying number is right either way -- this is only about whether it
-- reads as an instrument or as a slideshow.
--
-- Snaps rather than sweeps when the change is large: an arrow that eases
-- through 170 degrees is pointing at nothing at all for a quarter of a second,
-- which is worse than a jump. Passing a destination and turning around is
-- exactly that case, and it is the one complaint this addon has actually
-- received about the arrow.
Navigation.smoothingFactor  = 0.35
Navigation.smoothingSnapRad = math.rad(90)

local smoothed = nil

function Navigation.ResetSmoothing()
    smoothed = nil
end

function Navigation.Smooth(bearing)
    if not bearing then
        return bearing
    end

    if not smoothed then
        smoothed = bearing

        return smoothed
    end

    local delta = Normalize(bearing - smoothed)

    if math.abs(delta) >= Navigation.smoothingSnapRad then
        smoothed = bearing

        return smoothed
    end

    smoothed = Normalize(smoothed + (delta * Navigation.smoothingFactor))

    return smoothed
end

-- Distance, eased. Snaps on a large jump for the same reason the rotation
-- does: a teleport, a flight path or a loading screen is a real change and
-- easing through it would show a number that was never true.
Navigation.distanceSmoothing = 0.5
Navigation.distanceSnapYards = 80

local smoothedDistance = nil

function Navigation.ResetDistanceSmoothing()
    smoothedDistance = nil
end

function Navigation.SmoothDistance(yards)
    if not yards then
        smoothedDistance = nil

        return nil
    end

    if not smoothedDistance
        or math.abs(yards - smoothedDistance) >= Navigation.distanceSnapYards then

        smoothedDistance = yards

        return smoothedDistance
    end

    smoothedDistance = smoothedDistance
        + ((yards - smoothedDistance) * Navigation.distanceSmoothing)

    return smoothedDistance
end

local function Refresh()
    if not arrow then
        return
    end

    if not target or not Navigation.IsArrowEnabled() then
        Blank()
        arrow:Hide()
        return
    end

    local state = Navigation.Compute()

    if not state then
        arrow:Hide()
        return
    end

    arrow:Show()

    arrow.label:SetText(target.title or CN.L["Destination"])

    if state.state == "WRONG_MAP" then
        arrow.texture:SetRotation(0)
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff999999" .. (state.zone or CN.L["another zone"]) .. "|r")
        return
    end

    if state.state == "NO_POSITION" then
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff999999" .. CN.L["no position"] .. "|r")
        return
    end

    if state.relative then
        -- SetRotation turns counter-clockwise; the relative bearing is
        -- clockwise, hence the negation.
        arrow.texture:SetRotation(-Navigation.Smooth(state.relative))
    end

    arrow.texture:SetVertexColor(Navigation.BearingColor(state.relative))

    -- The distance figure jumped the way the rotation used to, because it is
    -- recomputed from a position the client rounds. Same treatment, and a
    -- much lower factor: distance should look steady, not sluggish.
    local distanceText = Navigation.FormatDistance(
        Navigation.SmoothDistance(state.yards))

    -- NO INFORMATION CARRIED BY COLOUR ALONE.
    --
    -- The arrow's whole language is colour -- blue on course, amber drifting,
    -- red walking away -- which is precisely the design that fails a
    -- colourblind player. In that mode the same fact is written next to the
    -- distance, where it survives the colours being indistinguishable.
    local hud = CN:GetModule("Hud")

    if hud and hud.IsColourblind() then
        distanceText = distanceText .. " |cffffffff"
            .. hud.BearingWord(state.relative) .. "|r"
    end

    arrow.distance:SetText(distanceText)

    -- Watch whether following the arrow actually works.
    Navigation.NoteObservation(state.relative, state.yards)

    if state.state == "ARRIVED" then
        Navigation.Arrive()
    end
end

Navigation.Refresh = Refresh

function Navigation.Arrive()
    if not target or target.arrived then
        return
    end

    target.arrived = true

    local reached = tostring(target.title or "destination")

    Print(string.format(CN.L["Arrived: %s"], reached))

    -- The other moment `/cn cues` was written for and never wired to.
    local follow = CN:GetModule("Follow")

    if follow and follow.Cue then
        pcall(follow.Cue, "arrival")
    end

    -- Arrival is exactly the moment auto-advance was designed for; before
    -- this, it could only re-point on a timer or an event.
    if CN.IsAutoWaypointEnabled and CN.IsAutoWaypointEnabled() then
        CN.AutoAdvance("arrival", true)

        -- SAY SO WHEN THE ARROW NOW MEANS SOMETHING ELSE.
        --
        -- Auto-advance re-points at the next thing, and the arrow looks
        -- absolutely identical doing it: same shape, same blue, still ahead
        -- of you. A player who walks through a destination and sees the arrow
        -- still pointing forward reasonably concludes it failed to turn
        -- round, when in fact it is now pointing at something else. That was
        -- reported as a bug twice, and it was a communication failure rather
        -- than a maths one.
        local now = target and tostring(target.title or "destination")

        if now and now ~= reached then
            Print(string.format(CN.L["Now heading to: %s"],
                "|cffffff00" .. now .. "|r"))
        end
    else
        Navigation.Clear()
    end
end

------------------------------------------------------------
-- TICKER
------------------------------------------------------------

-- Ten times a second. A rotating arrow needs to feel continuous; recomputing
-- world positions every frame does not.
Navigation.tickSeconds = 0.1

function Navigation.StartTicker()
    if ticker or not C_Timer or not C_Timer.NewTicker then
        return
    end

    ticker = C_Timer.NewTicker(Navigation.tickSeconds, function()
        -- Before drawing, and regardless of what is being tracked: the
        -- player's own movement is the only direct evidence of which way the
        -- client counts facing, and it is free to read.
        pcall(Navigation.NoteMotion)

        local ok, err = pcall(Refresh)

        if not ok then
            DebugPrint("Arrow refresh failed: " .. tostring(err))

            local errors = CN:GetModule("Errors")

            if errors then
                errors.Record("arrow refresh", err)
            end
        end
    end)
end

function Navigation.StopTicker()
    if ticker then
        ticker:Cancel()
        ticker = nil
    end
end

------------------------------------------------------------
-- DIAGNOSIS
------------------------------------------------------------

-- Everything the arrow is thinking, in one command.
--
-- Written because a player reported the arrow misbehaving twice, and both
-- times the only evidence available was a description in prose. I guessed
-- from it twice and was wrong twice. Prose is a bad instrument; this is a
-- better one.
--
-- Reports what is being tracked, where the client says you are, which way it
-- says you are facing, every intermediate value in the bearing, what was
-- actually applied to the texture, and which of the several things that can
-- silently change the destination is switched on.
function Navigation.Diagnose()
    local report = {}

    local function add(label, value)
        table.insert(report, { label = label, value = tostring(value) })
    end

    if not target then
        add("target", "none -- nothing is being tracked")

        return report
    end

    add("target", tostring(target.title or "untitled"))
    add("target map", string.format("%s (%s)",
        tostring(target.mapID), tostring(target.zone or "?")))
    add("target coords", string.format("%.1f, %.1f",
        (target.x or 0) * 100, (target.y or 0) * 100))
    add("marked arrived", target.arrived and "yes" or "no")

    local bestMap, px, py = CN.GetPlayerPosition()

    add("your map", tostring(bestMap))
    add("your coords", px and string.format("%.1f, %.1f", px * 100, py * 100)
        or "the client will not say")

    local state = Navigation.Compute() or {}

    add("state", tostring(state.state))

    if state.translated then
        add("translation", "your position was expressed on the target's map")
    end

    add("facing (raw)", state.facing
        and string.format("%.1f deg", math.deg(state.facing)) or "nil")
    local motionState = Navigation.MotionState()

    add("facing sign", tostring(Navigation.FacingSign())
        .. " (flips if the arrow ever pointed backwards)")
    add("facing evidence", motionState.samples == 0
        and "none yet -- walk a few yards with the arrow up"
        or string.format("%d movement samples, %s",
            motionState.samples, tostring(motionState.verdict)))

    local scaleX, scaleY = Navigation.MapScale(state.mapID or bestMap)

    add("map scale", string.format("%.0f x %.0f yards across", scaleX, scaleY))

    add("relative bearing", state.relative
        and string.format("%.1f deg", math.deg(state.relative))
        or "nil -- no bearing could be computed")

    if state.relative then
        add("rotation applied", string.format("%.1f deg", math.deg(-state.relative)))

        local off = math.abs(state.relative)

        add("colour", off < 0.35 and "BLUE (on course)"
            or off < 1.2 and "GOLD (drifting)"
            or "RED (walking away)")
    end

    add("distance", Navigation.FormatDistance(state.yards))
    add("arrival radius", Navigation.arrivalYards .. " yd")

    add("provider", tostring(select(2, CN.GetWaypointProvider())))

    -- The two settings that can change what the arrow means without the
    -- player doing anything.
    add("auto-advance", (CN.IsAutoWaypointEnabled and CN.IsAutoWaypointEnabled())
        and "ON -- arriving re-points the arrow at the next thing"
        or "off")

    local follow = CN:GetModule("Follow")

    add("follow mode", (follow and follow.active) and "ON" or "off")

    return report
end

CN:RegisterCommand{
    name    = "navdiag",
    aliases = { "arrowdiag" },
    order   = 30,
    help    = "Show exactly what the navigation arrow is doing and why.",
    handler = function()
        local report = Navigation.Diagnose()

        Print("Arrow diagnosis:")

        for _, row in ipairs(report) do
            Print(string.format("  |cff999999%-18s|r %s", row.label, row.value))
        end

        if not target then
            Print("|cff999999Set one with |cffffff00/cn go|r"
                .. "|cff999999 and run this again.|r")
        end
    end,
}

------------------------------------------------------------
-- WAYPOINT PROVIDER
------------------------------------------------------------

local provider = {}

function provider.IsAvailable()
    -- Native navigation needs nothing but the map API, which is why it is the
    -- default: it is the only provider that cannot be missing.
    return C_Map ~= nil and C_Map.GetBestMapForUnit ~= nil
end

function provider.SetWaypoint(mapID, x, y, title)
    -- THE MAP MAY REFUSE, AND THE ARROW IS NOT THE WHOLE ANSWER.
    --
    -- The native provider draws its own arrow, which works anywhere -- but it
    -- also drops the client's user waypoint, and the client will not place one
    -- on a dungeon, raid, cosmic or continent map. `CanSetUserWaypointOnMap`
    -- says which, and was called nowhere in this addon.
    --
    -- The arrow is still worth having on those maps, so this does not refuse
    -- outright; it simply does not claim a map pin it could not place.
    local allowed = true

    if C_Map and C_Map.CanSetUserWaypointOnMap then
        local asked, answer = pcall(C_Map.CanSetUserWaypointOnMap, mapID)

        if asked and not answer then
            allowed = false
        end
    end

    target = {
        mapID = mapID,
        x     = x,
        y     = y,
        title = title,
        zone  = Blizzard.GetMapName(mapID),
        setAt = time(),
    }

    Navigation.ResetCalibration()
    Navigation.ResetMotion()

    -- SMOOTHING BELONGS TO A DESTINATION, NOT TO THE ARROW.
    --
    -- `Blank` -- the only thing that resets the smoothed bearing and distance
    -- -- ran from `Navigation.Clear` and only when an arrow already existed.
    -- Changing target without clearing first, which is what `/cn go`, the
    -- route's auto-advance and a map-pin click all do, left the previous
    -- destination's smoothed values in place. The snap thresholds hid the
    -- large jumps, so what remained was the confusing case: a new target
    -- within 89 degrees and 79 yards was eased into over several ticks,
    -- showing a bearing and a distance belonging to neither destination.
    Navigation.ResetSmoothing()
    Navigation.ResetDistanceSmoothing()

    BuildArrow()
    Navigation.StartTicker()
    Refresh()

    -- Also drop a map pin, so the destination is visible on the world map and
    -- not only in front of the player.
    if allowed and C_Map.SetUserWaypoint and UiMapPoint
        and UiMapPoint.CreateFromCoordinates then

        local ok = pcall(function()
            C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(mapID, x, y))
        end)

        if ok then
            -- Remembered so Clear can tell this addon's pin from one the
            -- player placed by hand.
            Navigation.ownsUserWaypoint = true

            if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
                pcall(C_SuperTrack.SetSuperTrackedUserWaypoint, true)
            end
        end
    end

    if not allowed then
        return true, "the arrow is set; the game does not allow a map pin here"
    end

    return true
end

function provider.ClearAll()
    return Navigation.Clear()
end

function Navigation.Clear()
    local had = target ~= nil or Navigation.ownsUserWaypoint

    target = nil

    if arrow then
        arrow:Hide()
    end

    -- Unconditionally, not only when an arrow was built: the smoothed values
    -- are state about a destination and the destination is gone either way.
    Blank()

    Navigation.StopTicker()

    -- ONLY OUR OWN PIN. `ClearUserWaypoint` removes THE user waypoint, and
    -- there is one. Stopping follow mode used to delete a pin the player had
    -- placed by hand.
    if Navigation.ownsUserWaypoint and C_Map and C_Map.ClearUserWaypoint then
        pcall(C_Map.ClearUserWaypoint)
    end

    Navigation.ownsUserWaypoint = nil

    return had and true or false
end

-- Priority 5: ahead of TomTom's 10. The addon is self-contained now, and a
-- player who prefers TomTom's arrow can say so with /cn nav tomtom.
CN.RegisterWaypointProvider("Native", provider, 5)

Navigation.provider = provider

------------------------------------------------------------
-- PROVIDER PREFERENCE
------------------------------------------------------------

-- Overrides the priority order. Stored rather than inferred, because
-- "whichever addon happens to be loaded" is not a preference.
function Navigation.SetPreference(name)
    local settings = Settings()

    if name == "auto" or name == nil then
        settings.navigation = nil
        return true, "automatic"
    end

    local key = string.lower(name)

    local known = {
        native  = "Native",
        tomtom  = "TomTom",
        blizzard = "Blizzard",
    }

    if not known[key] then
        return false, nil
    end

    settings.navigation = known[key]

    return true, known[key]
end

function Navigation.Preference()
    return Settings().navigation
end

-- Consulted by Routing before the priority order.
function CN.GetPreferredWaypointProvider()
    local preferred = Navigation.Preference()

    if not preferred then
        return nil
    end

    local candidate = CN.waypointProviders[preferred]

    if candidate and candidate.IsAvailable and candidate.IsAvailable() then
        return candidate, preferred
    end

    return nil
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "arrow",
    args    = "[on or off]",
    order   = 40,
    help    = "Toggle the on-screen navigation arrow.",
    handler = function(args)
        local settings = Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.arrow = true
        elseif args == "off" then
            settings.arrow = false
        elseif args ~= "" then
            Print("Usage: /cn arrow [on or off]")
            return
        else
            settings.arrow = (settings.arrow == false)
        end

        Print("Navigation arrow: " .. CN.YesNo(Navigation.IsArrowEnabled()))

        if Navigation.IsArrowEnabled() then
            BuildArrow()
            Refresh()
        elseif arrow then
            arrow:Hide()
        end

        if not target then
            Print("|cff999999Nothing is being tracked. |cffffff00/cn go|r "
                .. "points it at something.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "calibrate",
    aliases = { "flip" },
    order   = 43,
    help    = "Flip the navigation arrow if it points the wrong way.",
    handler = function()
        Navigation.SetFacingSign(-Navigation.FacingSign())
        Navigation.ResetCalibration()

        Print("Arrow direction flipped and remembered.")
        Print("|cff999999Whether GetPlayerFacing counts clockwise or "
            .. "counter-clockwise is a client convention, so the addon "
            .. "normally works this out on its own by watching whether "
            .. "following the arrow shortens the distance.|r")

        Navigation.Refresh()
    end,
}

CN:RegisterCommand{
    name    = "nav",
    args    = "[auto, native, tomtom or blizzard]",
    order   = 41,
    help    = "Choose which navigation provider to use.",
    handler = function(args)
        args = CN.Trim(args or "")

        if args ~= "" then
            local ok, resolved = Navigation.SetPreference(args)

            if not ok then
                Print("Not a navigation provider: " .. args)
                Print("|cff999999Choose auto, native, tomtom or blizzard.|r")
                return
            end

            Print("Navigation provider: |cffffff00" .. tostring(resolved) .. "|r")
        end

        local preference = Navigation.Preference()

        Print("Preference: " .. (preference or "automatic"))

        local active, name = CN.GetWaypointProvider()

        Print("Currently using: " .. (active and name or "none available"))

        Print("Available:")

        for _, entry in ipairs(CN.waypointOrder) do
            local candidate = CN.waypointProviders[entry.name]

            local available = candidate and candidate.IsAvailable
                and candidate.IsAvailable()

            Print("  " .. entry.name .. " " .. CN.YesNo(available)
                .. " |cff999999priority " .. entry.priority .. "|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "where am i",
    aliases = { "here" },
    order   = 42,
    help    = "Report your position and what is being tracked.",
    handler = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            Print("Your position is not available right now.")
            return
        end

        Print("You are in " .. tostring(Blizzard.GetMapName(mapID))
            .. (x and y and string.format(" at %.1f, %.1f", x * 100, y * 100) or ""))

        if not target then
            Print("Nothing is being tracked.")
            return
        end

        local state = Navigation.Compute()

        Print("Tracking: |cffffff00" .. tostring(target.title) .. "|r in "
            .. tostring(target.zone))

        if state and state.state == "WRONG_MAP" then
            Print("  |cff999999It is in another zone.|r")
        elseif state then
            Print("  " .. Navigation.FormatDistance(state.yards)
                .. (state.relative and string.format(" |cff999999%d degrees off|r",
                    math.floor(math.abs(math.deg(state.relative)) + 0.5)) or ""))
        end
    end,
}

------------------------------------------------------------
-- LIFECYCLE
------------------------------------------------------------

CN:OnLogin(function()
    if Navigation.IsArrowEnabled() then
        BuildArrow()
    end
end)

-- Zone changes can move you onto the target's map, or off it.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if target then
        Refresh()
    end
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\MapPins.lua'] = @'
-- Modules/MapPins.lua
-- Completion Navigator :: the plan, drawn on the world map.
--
-- Everything else in this addon answers "what next?" one line at a time. That
-- is the right answer to the question, but it hides the thing that actually
-- makes the routing worth having: the SHAPE of the work. The router already
-- groups objectives into hubs, orders the hubs to minimise walking, and
-- improves that order with a 2-opt pass -- and until now a player saw none of
-- it. They saw a list and an arrow, and had no way to know that stops three
-- through six were all the same camp, or that the route doubles back for a
-- reason.
--
-- So: one numbered pin per HUB, in route order, on the map you are looking at.
-- The number is the order. The tooltip is what you do when you arrive, in the
-- order you would do it. Clicking navigates there.
--
-- One pin per hub, not per objective. Twelve overlapping pins on one camp
-- communicate less than a single pin reading "3 -- pick up 2, do 4, hand in
-- 1", and a map that becomes unreadable when you have a lot to do is a map
-- that fails exactly when it matters most.
--
-- Deliberately NOT a MapCanvasDataProvider. The data-provider API is the
-- blessed route, and it is also a moving target that has broken addons across
-- several expansions. A pooled frame parented to the canvas is boring, has no
-- version surface to speak of, and degrades to "no pins" rather than to a Lua
-- error inside Blizzard's map code.

local ADDON_NAME, CN = ...

local MapPins = CN:RegisterModule("MapPins")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- ENABLEMENT
------------------------------------------------------------

-- On by default. Pins are additive and read-only -- like tooltip lines, and
-- unlike the waypoint, they take nothing over and interrupt nothing. They
-- also appear only on a map you have deliberately opened.
function MapPins.IsEnabled()
    return Settings().mapPins ~= false
end

function MapPins.SetEnabled(value)
    Settings().mapPins = value and true or false

    if value then
        MapPins.Refresh(true)
    else
        MapPins.Clear()
    end

    return MapPins.IsEnabled()
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Normalised map coordinates to a canvas offset.
--
-- The canvas is anchored from its TOPLEFT and y grows DOWNWARD, while map
-- coordinates also grow downward -- so the offset is +x and -y. Getting the
-- sign wrong mirrors every pin vertically, which looks plausible on a
-- symmetrical map and is completely wrong on every other one.
--
-- Pure, and tested as such: this is the one piece of the file that can be
-- wrong in a way no amount of looking at the screen would reveal, because a
-- mirrored pin is still a pin in a believable place.
function MapPins.CanvasOffset(x, y, width, height)
    if not x or not y or not width or not height then
        return nil
    end

    return x * width, -(y * height)
end

MapPins.pinSize      = 26
MapPins.maxPins      = 40
MapPins.crowdedScale = 0.8

-- How big a pin should be. A hub holding six things is worth more of the
-- player's attention than one holding a single stray pet, and size is the
-- cheapest way to say so without adding another colour to read.
function MapPins.PinSize(hubSize, pinCount)
    local size = MapPins.pinSize

    if (hubSize or 1) > 1 then
        size = size + math.min(10, (hubSize - 1) * 2)
    end

    -- A busy zone gets smaller pins rather than fewer of them. Dropping stops
    -- silently would misrepresent the route; shrinking them does not.
    if (pinCount or 0) > 12 then
        size = size * MapPins.crowdedScale
    end

    return math.floor(size + 0.5)
end

------------------------------------------------------------
-- LAYOUT
------------------------------------------------------------

-- Turns ordered hubs into pin descriptors. Pure: no frames, no client, no
-- side effects. Everything that decides what a pin SAYS happens here, so it
-- can be asserted offline.
function MapPins.Layout(hubs)
    local pins = {}

    if type(hubs) ~= "table" then
        return pins
    end

    local total = 0

    for _, hub in ipairs(hubs) do
        if hub.x and hub.y then
            total = total + 1
        end
    end

    for index, hub in ipairs(hubs) do
        if #pins >= MapPins.maxPins then
            break
        end

        -- A hub with no coordinates cannot be drawn. It is not dropped from
        -- the route -- the list still reports it -- it simply has nowhere to
        -- go on a map.
        if hub.x and hub.y then
            local objectives = hub.objectives or {}

            table.insert(pins, {
                order      = index,
                mapID      = hub.mapID,
                x          = hub.x,
                y          = hub.y,
                size       = MapPins.PinSize(#objectives, total),
                hubSize    = #objectives,
                summary    = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                objectives = objectives,
            })
        end
    end

    return pins
end

-- The tooltip body for one pin: what you do when you get there, in the order
-- you would do it. The hub's objectives are already sorted pick up -> do ->
-- hand in by the router, so this only has to not re-sort them.
function MapPins.DescribeLines(pin)
    local lines = {}

    if not pin then
        return lines
    end

    local quests = CN:GetModule("Quests")

    local shown = 0

    for _, objective in ipairs(pin.objectives or {}) do
        if shown >= 8 then
            table.insert(lines, string.format(
                "and %d more", #pin.objectives - shown))
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, string.format("%s: %s",
            verb, tostring(objective.name or objective.id)))

        shown = shown + 1
    end

    return lines
end

------------------------------------------------------------
-- THE CANVAS
------------------------------------------------------------

-- Resolves the world map's canvas, or nil. Every layer here is optional
-- because every layer is Blizzard's: if any of it moves, pins stop appearing
-- and nothing else in the addon notices.
function MapPins.Canvas()
    local map = _G and _G.WorldMapFrame

    if not map or not map.ScrollContainer then
        return nil
    end

    return map.ScrollContainer.Child
end

-- Which map the player is LOOKING AT, which is not necessarily where they
-- are standing.
function MapPins.DisplayedMapID()
    local map = _G and _G.WorldMapFrame

    if not map or not map.GetMapID then
        return nil
    end

    local ok, mapID = pcall(map.GetMapID, map)

    if ok then
        return mapID
    end

    return nil
end

function MapPins.IsMapShown()
    local map = _G and _G.WorldMapFrame

    if not map or not map.IsShown then
        return false
    end

    local ok, shown = pcall(map.IsShown, map)

    return ok and shown == true
end

------------------------------------------------------------
-- THE ROUTE FOR A DISPLAYED MAP
------------------------------------------------------------

-- Where a route across THIS map should start.
--
-- If you are looking at the zone you are standing in, the route starts at
-- your feet -- that is the whole point of routing. If you are looking at
-- somewhere else, your position is meaningless there: using it would order
-- the stops by their distance from a point on another continent, producing a
-- route that is not merely suboptimal but arbitrary. Start from the middle
-- instead, which orders the stops by their relationship to each other.
function MapPins.RouteStart(displayedMapID)
    local playerMap, x, y = nil, nil, nil

    if CN.GetPlayerPosition then
        local ok, a, b, c = pcall(CN.GetPlayerPosition)

        if ok then
            playerMap, x, y = a, b, c
        end
    end

    if displayedMapID and playerMap == displayedMapID and x and y then
        return x, y, true
    end

    return 0.5, 0.5, false
end

local cache = { mapID = nil, generation = nil, hubs = nil }

function MapPins.InvalidateCache()
    cache.mapID      = nil
    cache.generation = nil
    cache.hubs       = nil
end

-- EVERYTHING THE ROUTE DEPENDS ON, NOT JUST THE CANDIDATES.
--
-- `BuildZoneRoute` applies the objective-type filter when it picks the stops,
-- so the hub set is a function of that filter as well as of the candidate
-- list. `SetTypeEnabled` deliberately does not rebuild providers -- it bumps
-- `CN.typeFilterGeneration` instead -- so the candidate generation did not
-- move and this cache did not notice.
--
-- The result was two views of one route disagreeing on screen: `/cn zone`
-- honoured `/cn show only quests` and the map, reopened a second later, still
-- drew the pet and appearance stops the player had just hidden.
local function RouteGeneration()
    local generation = 0

    if CN.GetCandidateCacheState then
        local ok, state = pcall(CN.GetCandidateCacheState)

        if ok and state then
            generation = state.generation or 0
        end
    end

    -- The ranking generation is deliberately NOT part of this key:
    -- `BuildZoneRoute` bumps it itself, so including it would mean the cache
    -- never matched and the route was rebuilt on every map pan -- which is
    -- the cost this cache exists to avoid.
    return generation .. ":" .. tostring(CN.typeFilterGeneration or 0)
end

-- Building a zone route means collecting and scoring every candidate, so it
-- must not happen on every map pan. It happens when the map you are looking
-- at changes, or when the underlying candidates do.
function MapPins.HubsForMap(mapID, force)
    if not mapID or not CN.BuildZoneRoute then
        return nil
    end

    local generation = RouteGeneration()

    if not force
        and cache.mapID == mapID
        and cache.generation == generation
        and cache.hubs then

        return cache.hubs
    end

    local startX, startY = MapPins.RouteStart(mapID)

    local ok, _, _, hubs = pcall(CN.BuildZoneRoute, mapID, startX, startY)

    if not ok then
        return nil
    end

    cache.mapID      = mapID
    cache.generation = generation
    cache.hubs       = hubs

    return hubs
end

------------------------------------------------------------
-- THE PINS THEMSELVES
------------------------------------------------------------

local pool = {}

local function PinColor(order)
    local nav = CN:GetModule("Navigation")

    local palette = nav and nav.colors

    if not palette then
        return 0.365, 0.824, 0.984
    end

    -- The next stop wears the addon's blue. Everything after it is dimmed,
    -- so "where do I go now" is answerable at a glance rather than by
    -- reading numbers.
    if order == 1 then
        local c = palette.ON_COURSE
        return c[1], c[2], c[3]
    end

    local c = palette.UNKNOWN

    return c[1], c[2], c[3]
end

local function ShowPinTooltip(frame)
    if not GameTooltip or not frame.pin then
        return
    end

    GameTooltip:SetOwner(frame, "ANCHOR_RIGHT")

    GameTooltip:AddLine(string.format("Stop %d", frame.pin.order), 1, 1, 1)

    if frame.pin.summary then
        GameTooltip:AddLine(frame.pin.summary, 0.365, 0.824, 0.984)
    end

    for _, line in ipairs(MapPins.DescribeLines(frame.pin)) do
        GameTooltip:AddLine(line, 0.8, 0.8, 0.8)
    end

    GameTooltip:AddLine("Click to navigate here", 0.6, 0.6, 0.6)

    GameTooltip:Show()
end

local function HidePinTooltip()
    if GameTooltip then
        GameTooltip:Hide()
    end
end

-- Clicking navigates to the STOP, not to whichever objective happens to be
-- listed first there.
--
-- Those are different things. An objective's own coordinates may be missing
-- -- plenty of collectibles are known to be in a zone and nowhere more
-- precise -- while the stop's are the centre of everything at it and always
-- exist, because that is how the stop was formed. Routing to the member and
-- finding it has no location would answer a click with "no coordinates are
-- known", which from the player's side is the addon refusing to go to a place
-- it just drew a pin on.
local function ClickPin(frame)
    local pin = frame.pin

    if not pin then
        return
    end

    for _, objective in ipairs(pin.objectives or {}) do
        if objective.x and objective.y and CN.NavigateToObjective then
            CN.NavigateToObjective(objective)
            return
        end
    end

    if pin.x and pin.y and pin.mapID and CN.SetWaypoint then
        local first = (pin.objectives or {})[1]

        CN.SetWaypoint(pin.mapID, pin.x, pin.y,
            first and tostring(first.name or first.id) or
                ("Stop " .. tostring(pin.order)))
    end
end

local function AcquirePin(index, canvas)
    if pool[index] then
        return pool[index]
    end

    if not CreateFrame or not canvas then
        return nil
    end

    local frame = CreateFrame("Button", "CompletionNavigatorMapPin" .. index, canvas)

    frame:SetSize(MapPins.pinSize, MapPins.pinSize)

    frame.texture = frame:CreateTexture(nil, "OVERLAY")
    frame.texture:SetAllPoints()
    frame.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    if not frame.texture:GetTexture() then
        frame.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    frame.label = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    frame.label:SetPoint("CENTER")

    frame:SetScript("OnEnter", ShowPinTooltip)
    frame:SetScript("OnLeave", HidePinTooltip)
    frame:SetScript("OnClick", ClickPin)

    pool[index] = frame

    return frame
end

MapPins.AcquirePin = AcquirePin

function MapPins.Clear()
    for _, frame in ipairs(pool) do
        frame:Hide()
    end
end

-- Positions the pins. Separated from Refresh so the arithmetic can be driven
-- offline against a stubbed canvas.
function MapPins.Place(pins, canvas)
    if not canvas then
        return 0
    end

    local width  = canvas:GetWidth()
    local height = canvas:GetHeight()

    if not width or not height or width <= 0 or height <= 0 then
        return 0
    end

    local placed = 0

    for index, pin in ipairs(pins) do
        local frame = AcquirePin(index, canvas)

        if frame then
            local offsetX, offsetY = MapPins.CanvasOffset(pin.x, pin.y, width, height)

            if offsetX then
                frame.pin = pin

                frame:SetSize(pin.size, pin.size)
                frame:ClearAllPoints()
                frame:SetPoint("CENTER", canvas, "TOPLEFT", offsetX, offsetY)

                frame.label:SetText(tostring(pin.order))
                frame.texture:SetVertexColor(PinColor(pin.order))

                frame:Show()

                placed = placed + 1
            end
        end
    end

    -- Surplus frames from a busier map are hidden, never destroyed. Pin
    -- frames are cheap to keep and expensive to churn.
    for index = #pins + 1, #pool do
        pool[index]:Hide()
        pool[index].pin = nil
    end

    return placed
end

function MapPins.Refresh(force)
    if not MapPins.IsEnabled() then
        MapPins.Clear()
        return 0
    end

    if not MapPins.IsMapShown() then
        return 0
    end

    local canvas = MapPins.Canvas()

    if not canvas then
        return 0
    end

    local mapID = MapPins.DisplayedMapID()

    if not mapID then
        MapPins.Clear()
        return 0
    end

    local hubs = MapPins.HubsForMap(mapID, force)

    if not hubs then
        MapPins.Clear()
        return 0
    end

    local pins = MapPins.Layout(hubs)

    local placed = MapPins.Place(pins, canvas)

    DebugPrint(string.format("Map pins: %d stop(s) on map %s.",
        placed, tostring(mapID)))

    return placed
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

local hooked = false

-- Hooked, not overwritten. The world map is shared with every other addon
-- the player runs, and replacing a script on it would break them.
function MapPins.Install()
    if hooked then
        return true
    end

    local map = _G and _G.WorldMapFrame

    if not map or not map.HookScript then
        return false
    end

    -- GUARDED, because these are hooks on a frame the player opens
    -- constantly and shares with every other addon they run. An unguarded
    -- throw here is an error box every time the world map opens.
    map:HookScript("OnShow", function()
        CN.Guard("MapPins.Refresh", MapPins.Refresh)
    end)

    map:HookScript("OnHide", function()
        CN.Guard("MapPins.Clear", MapPins.Clear)
    end)

    -- Panning to a different zone is a map change, not a redraw, so the
    -- route must be rebuilt for the map now on screen.
    if map.RegisterCallback and map.OnMapChanged then
        pcall(map.RegisterCallback, map, "WorldMapOnMapChanged", function()
            CN.Guard("MapPins.Refresh", MapPins.Refresh)
        end)
    end

    hooked = true

    return true
end

CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    MapPins.Install()
end)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    MapPins.InvalidateCache()
    MapPins.Refresh()
end)

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    MapPins.InvalidateCache()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "pins",
    aliases = { "map" },
    args    = "[on, off, or refresh]",
    order   = 18,
    help    = "Show the route as numbered pins on the world map.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            MapPins.SetEnabled(true)
            Print("Map pins are on.")
            return
        end

        if args == "off" then
            MapPins.SetEnabled(false)
            Print("Map pins are off.")
            return
        end

        if args == "refresh" then
            MapPins.InvalidateCache()

            local placed = MapPins.Refresh(true)

            Print(string.format("Redrew %d stop(s).", placed))
            return
        end

        if not MapPins.IsEnabled() then
            Print("Map pins are off. Turn them on with /cn pins on")
            return
        end

        local mapID = MapPins.DisplayedMapID()

        if not mapID then
            Print("Map pins are on. Open the world map to see the route.")
            return
        end

        local hubs = MapPins.HubsForMap(mapID)
        local pins = MapPins.Layout(hubs or {})

        if #pins == 0 then
            Print("Nothing to route on this map.")
            return
        end

        Print(string.format("%d stop(s) on this map:", #pins))

        for _, pin in ipairs(pins) do
            Print(string.format("  %d. %s (%d)",
                pin.order,
                tostring(pin.summary or "do " .. pin.hubSize),
                pin.hubSize))
        end
    end,
}

return MapPins
'@

$Embedded['Modules\Broker.lua'] = @'
-- Modules/Broker.lua
-- Completion Navigator :: LibDataBroker feed, and rare-spawn alerts.
--
-- Two small things that share a theme: telling you something without you
-- having to ask.
--
-- The broker is the addon's answer to "what next?" displayed permanently in
-- whatever bar you already run -- Titan Panel, ElvUI, ChocolateBar. This is
-- the only place the addon touches an external library, and it does so the
-- same way it touches TomTom and AllTheThings: probed, wrapped, optional. If
-- LibDataBroker is not installed nothing happens and nothing is said, because
-- an addon complaining about a library you never asked for is noise.
--
-- Alerts are OFF by default. Unsolicited sound is worse than a waypoint you
-- did not ask for, and this addon has already decided how it feels about that.

local ADDON_NAME, CN = ...

local Broker = CN:RegisterModule("Broker")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- LIBDATABROKER
------------------------------------------------------------

Broker.available = false

local dataObject

-- `results` may be supplied by a caller that already has them. The
-- recommendation hook does, and re-asking from inside it is re-entering the
-- function that fired the hook -- which recursed until pcall stopped it and
-- cost seventy times the budget for one refresh. A performance budget caught
-- it before it shipped.
local function CurrentText(results)
    if not results then
        local ok, fetched = pcall(CN.Recommend, 1)

        results = ok and fetched or nil
    end

    if not results or not results[1] then
        return "Completion Navigator", CN.L["nothing actionable"]
    end

    local objective = results[1]

    return tostring(objective.name or objective.id), CN.TypeLabel(objective.type)
end

Broker.CurrentText = CurrentText

function Broker.Refresh(results)
    if not dataObject then
        return
    end

    local name, kind = CurrentText(results)

    dataObject.text  = name
    dataObject.value = name
    dataObject.label = kind
end

function Broker.Install()
    if Broker.available or not LibStub then
        return Broker.available
    end

    -- LibStub's silent form: it returns nil rather than throwing when the
    -- library is absent, which is exactly what optional means.
    local ok, ldb = pcall(LibStub, "LibDataBroker-1.1", true)

    if not ok or not ldb then
        return false
    end

    local created, object = pcall(ldb.NewDataObject, ldb, "CompletionNavigator", {
        type  = "data source",
        text  = "Completion Navigator",
        icon  = CN.MEDIA_PATH .. "Logo",

        -- GUARDED, both of them. `Broker.CurrentText` forty lines up already
        -- wraps `CN.Recommend`; the click and tooltip handlers did not -- and
        -- these run inside the host bar addon, so a throw here breaks Titan
        -- Panel's or ElvUI's tooltip rather than this addon's.
        OnClick = function(_, button)
            if button == "RightButton" then
                local asked, results = pcall(CN.Recommend, 1)

                if not asked then
                    results = nil
                end

                if results and results[1] then
                    CN.NavigateToObjective(results[1])
                end

                return
            end

            if CN.UI and CN.UI.Toggle then
                CN.UI.Toggle()
            end
        end,

        OnTooltipShow = function(tooltip)
            if not tooltip or not tooltip.AddLine then
                return
            end

            tooltip:AddLine("Completion Navigator")

            local asked, results = pcall(CN.Recommend, 3)

            if not asked then
                tooltip:AddLine("Something went wrong; /cn errors has it.",
                    0.96, 0.42, 0.38)
                return
            end

            if not results or #results == 0 then
                tooltip:AddLine("Nothing actionable yet.", 0.6, 0.6, 0.6)

                for index, line in ipairs(CN.ExplainEmptyList()) do
                    if index > 2 then
                        break
                    end

                    tooltip:AddLine(line, 0.6, 0.6, 0.6)
                end

                return
            end

            for index, objective in ipairs(results) do
                tooltip:AddLine(
                    (index == 1 and "Next: " or "     ")
                        .. tostring(objective.name or objective.id),
                    index == 1 and 0.365 or 0.7,
                    index == 1 and 0.824 or 0.7,
                    index == 1 and 0.984 or 0.7)
            end

            tooltip:AddLine(" ")
            tooltip:AddLine("Left-click to open, right-click to navigate.", 1, 1, 1)
        end,
    })

    if not created or not object then
        return false
    end

    dataObject      = object
    Broker.available = true

    Broker.Refresh()

    DebugPrint("LibDataBroker feed registered.")

    return true
end

------------------------------------------------------------
-- RARE ALERTS
------------------------------------------------------------

-- Which vignettes have already been announced this session. A rare drifting
-- in and out of vignette range must not announce itself repeatedly.
local announced = {}

function Broker.AlertsEnabled()
    local settings = CN.Settings()

    -- Off by default, deliberately. See the file header.
    return settings and settings.rareAlerts == true
end

function Broker.ResetAnnounced()
    announced = {}
end

-- Returns the vignettes worth announcing: up right now, not already announced,
-- not already cleared by this character, and not something you have ignored.
function Broker.PendingAlerts()
    local rares = CN:GetModule("Rares")

    if not rares then
        return {}
    end

    local pending = {}

    for _, vignette in ipairs(rares.GetActive()) do
        local id = vignette.vignetteID

        if id
            and not announced[id]
            and vignette.kind == "RARE"
            and not rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(CN.objectiveTypes.RARE, id) then

            table.insert(pending, vignette)
        end
    end

    return pending
end

function Broker.Announce(vignette)
    announced[vignette.vignetteID] = time()

    Print("|cff5DD2FBRare up:|r " .. tostring(vignette.name or "unknown")
        .. (vignette.x and vignette.y
            and string.format(" |cff999999%.1f, %.1f|r",
                vignette.x * 100, vignette.y * 100)
            or ""))

    if PlaySound then
        -- A quiet, non-alarming stock sound. Raid warnings are for raids.
        pcall(PlaySound, 8959, "Master")
    end

    return true
end

function Broker.CheckAlerts()
    if not Broker.AlertsEnabled() then
        return 0
    end

    local sent = 0

    for _, vignette in ipairs(Broker.PendingAlerts()) do
        Broker.Announce(vignette)

        sent = sent + 1
    end

    return sent
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

for _, event in ipairs({ "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED" }) do
    CN:RegisterEvent(event, function()
        local ok, err = pcall(Broker.CheckAlerts)

        if not ok then
            DebugPrint("Rare alert check failed: " .. tostring(err))
        end
    end)
end

-- A new zone is a new set of rares; nothing carries over.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    Broker.ResetAnnounced()
end)

CN:OnLogin(function()
    Broker.Install()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "alerts",
    args    = "[on or off]",
    order   = 44,
    help    = "Announce rares that appear near you.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.rareAlerts = true
        elseif args == "off" then
            settings.rareAlerts = false
        elseif args ~= "" then
            Print("Usage: /cn alerts [on or off]")
            return
        else
            settings.rareAlerts = not Broker.AlertsEnabled()
        end

        Print("Rare alerts: " .. CN.YesNo(Broker.AlertsEnabled()))

        if Broker.AlertsEnabled() then
            Print("|cff999999Announced once each, only for rares you have not "
                .. "already cleared, and reset when you change zone.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "broker",
    order   = 45,
    help    = "Show LibDataBroker status.",
    handler = function()
        if Broker.available then
            local name = CurrentText()

            Print("LibDataBroker feed: " .. CN.YesNo(true))
            Print("Currently showing: |cffffff00" .. tostring(name) .. "|r")
            Print("|cff999999Add it from your display addon: Titan Panel, "
                .. "ElvUI datatexts, ChocolateBar.|r")
            return
        end

        Print("LibDataBroker feed: " .. CN.YesNo(false))
        Print("|cff999999LibDataBroker is not installed, which is fine -- it is "
            .. "optional. Display addons like Titan Panel and ElvUI ship it, "
            .. "and the feed appears automatically when one of them is present.|r")
    end,
}

------------------------------------------------------------
-- KEEPING IT CURRENT
------------------------------------------------------------

-- REFRESHED WHEN THE ANSWER CHANGES, WHICH IT NEVER WAS.
--
-- `Broker.Refresh` had exactly one caller: `Install`, from a login hook that
-- runs before the collection scans in their own login hooks have populated
-- anything. So the feed was built from an empty database, almost always
-- settled on "nothing actionable", and then never changed again for the whole
-- session -- in a module whose header calls it "the addon's answer to 'what
-- next?' displayed permanently".
--
-- A recommendation hook is the right place: it fires exactly when the list is
-- recomputed, which is the only time this text can be stale.
if CN.RegisterRecommendationHook then
    CN.RegisterRecommendationHook("Broker", function(results)
        if Broker.available then
            pcall(Broker.Refresh, results)
        end
    end)
end

-- And once shortly after login, because a player who opens no window and
-- asks for nothing should still see a real answer rather than the placeholder
-- the feed was created with.
CN:OnLogin(function()
    if C_Timer and C_Timer.After then
        C_Timer.After(10, function()
            if Broker.available then
                pcall(Broker.Refresh)
            end
        end)
    end
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Group.lua'] = @'
-- Modules/Group.lua
-- Completion Navigator :: the state the player is actually in.
--
-- Two facts the addon has never read, both of which change what a sensible
-- next action is, and both of which the client reports for free.
--
-- BEING DEAD.
--
-- A dead player's next action is not "collect a battle pet". It is "get back
-- to your body". Until 0.43.0 the addon carried on recommending as though
-- nothing had happened, which is not merely unhelpful -- it is the clearest
-- possible signal that the addon is not paying attention.
--
-- BEING IN A GROUP.
--
-- The addon behaved identically whether you were alone or standing in a
-- dungeon with four other people. Somebody in an instance with a group is not
-- about to go and pick a herb in Durotar, and a recommendation that says so
-- is noise at best and a reason to close the window at worst.
--
-- WHAT THIS DELIBERATELY IS NOT.
--
-- It is not addon-to-addon communication. No messages are sent, no protocol
-- is defined, and nothing depends on anybody else running this addon. That
-- design needs versioned messages and matching builds on both machines, and
-- it becomes a support burden the moment either side is stale. Everything
-- here is read from the client, about this player, on this machine.

local ADDON_NAME, CN = ...

local Group = CN:RegisterModule("Group")

local Print = CN.Print

------------------------------------------------------------
-- STATE
------------------------------------------------------------

function Group.IsDead()
    if UnitIsDeadOrGhost then
        local ok, dead = pcall(UnitIsDeadOrGhost, "player")

        if ok then
            return dead and true or false
        end
    end

    return false
end

function Group.IsGhost()
    if UnitIsGhost then
        local ok, ghost = pcall(UnitIsGhost, "player")

        if ok then
            return ghost and true or false
        end
    end

    return false
end

function Group.Size()
    if GetNumGroupMembers then
        local ok, count = pcall(GetNumGroupMembers)

        if ok and type(count) == "number" then
            return count
        end
    end

    return 0
end

function Group.InGroup()
    return Group.Size() > 1
end

function Group.InRaid()
    if IsInRaid then
        local ok, raid = pcall(IsInRaid)

        if ok then
            return raid and true or false
        end
    end

    return false
end

-- Returns inInstance, kind ("party", "raid", "scenario", "pvp", "none").
function Group.Instance()
    if not IsInInstance then
        return false, "none"
    end

    local ok, inside, kind = pcall(IsInInstance)

    if not ok then
        return false, "none"
    end

    return inside and true or false, kind or "none"
end

-- One word for what the player is doing, which is all the ranking needs.
function Group.Situation()
    if Group.IsDead() then
        return "dead"
    end

    local inside, kind = Group.Instance()

    if inside and (kind == "party" or kind == "raid" or kind == "scenario") then
        return "instanced"
    end

    if Group.InGroup() then
        return "grouped"
    end

    return "solo"
end

------------------------------------------------------------
-- WHAT IT CHANGES
------------------------------------------------------------

-- Types that make no sense to walk off and do while four other people are
-- waiting at a boss. NOT hidden -- the player asked to see them at some point
-- and the addon does not un-ask that -- just pushed down.
Group.instancedPenalty = 0.35

Group.instancedTypes = {
    [CN.objectiveTypes.PET]         = true,
    [CN.objectiveTypes.TOY]         = true,
    [CN.objectiveTypes.MOUNT]       = true,
    [CN.objectiveTypes.APPEARANCE]  = true,
    [CN.objectiveTypes.EXPLORATION] = true,
    [CN.objectiveTypes.RARE]        = true,
    [CN.objectiveTypes.TREASURE]    = true,
    [CN.objectiveTypes.VENDOR]      = true,
    [CN.objectiveTypes.PROFESSION]  = true,
    [CN.objectiveTypes.RECIPE]      = true,
}

-- While dead, everything is worth less than getting up. The multiplier is
-- deliberately not zero: the list still answers "what next", it just stops
-- pretending the player can act on it this second.
Group.deadPenalty = 0.2

CN.RegisterScoreAdjuster("Group", function(objective, score)
    local situation = Group.Situation()

    -- WHAT IS NO LONGER TRUE IS WITHDRAWN FIRST.
    --
    -- Both sentences below describe the player's situation at the moment of
    -- scoring, and both used to be one-way: once stamped onto a cached
    -- objective they stayed there through every later pass. Every pass now
    -- starts by taking back the ones that do not apply, so the explanation
    -- and the multiplier always agree.
    if situation ~= "dead" then
        CN.ClearAdjusterReason(objective, "groupDead")
    end

    if situation ~= "instanced" then
        CN.ClearAdjusterReason(objective, "groupInstanced")
    end

    if situation == "dead" then
        -- EXCEPT THE BODY.
        --
        -- The corpse is the one thing that IS actionable while dead;
        -- demoting it with everything else would bury the answer under the
        -- list it is supposed to replace.
        if objective and objective.corpse then
            return score
        end

        -- Unguarded on `objective.reasons`, deliberately. The guard used to
        -- be here and not on the instanced branch below, and most providers
        -- build objectives with no `reasons` field -- so for those the
        -- fivefold penalty was applied with nothing on screen saying why.
        -- `AddAdjusterReason` creates the table itself.
        CN.AddAdjusterReason(objective, "groupDead",
            "you are dead -- this is for after")

        return score * Group.deadPenalty
    end

    if situation == "instanced"
        and objective
        and Group.instancedTypes[objective.type] then

        CN.AddAdjusterReason(objective, "groupInstanced",
            "outside work, and you are in an instance with a group")

        return score * Group.instancedPenalty
    end

    return score
end)

------------------------------------------------------------
-- SAYING SO
------------------------------------------------------------

-- The line the recommendation prints above everything else when the situation
-- makes the list beside the point. Nil when there is nothing to say, which is
-- most of the time -- an addon that comments on your circumstances constantly
-- is an addon people turn off.
-- WHERE YOUR BODY IS.
--
-- The addon has recognised death since 0.43.0 and ranked everything else down
-- for it -- which is right, and is only half an answer. A dead player's next
-- action is a corpse run, and the addon knew that, said so in a sentence, and
-- then could not point at the one place that mattered.
--
-- `C_DeathInfo.GetCorpseMapPosition` answers with the map position of your
-- own corpse. Guarded like every other client call: a client that will not
-- say returns nothing and the sentence stays a sentence.
function Group.CorpseTarget()
    if not Group.IsGhost() then
        return nil
    end

    if not C_DeathInfo or not C_DeathInfo.GetCorpseMapPosition then
        return nil
    end

    local mapID = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local ok, position = pcall(C_DeathInfo.GetCorpseMapPosition, mapID)

    if not ok or not position then
        return nil
    end

    local x, y

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            x, y = gx, gy
        end
    end

    x = x or position.x
    y = y or position.y

    if not x or not y or (x == 0 and y == 0) then
        return nil
    end

    return { mapID = mapID, x = x, y = y, title = "Your corpse" }
end

------------------------------------------------------------
-- THE ONE THING WORTH DOING WHILE YOU ARE DEAD
------------------------------------------------------------

-- A dead player's next action is not the recommendation list -- it is their
-- body. The addon has said so in a sentence since 0.43.0 while ranking
-- everything else down, and never once pointed at the place.
--
-- Offered as an ordinary candidate, so the arrow, the map pin, `/cn go` and
-- the heads-up display all pick it up without any of them needing to know
-- what a corpse is. Weighted far above anything else, because while you are a
-- ghost nothing else is actionable at all.
CN.RegisterCandidateProvider("Corpse", function()
    local corpse = Group.CorpseTarget()

    if not corpse then
        return {}
    end

    return {
        CN.NewObjective({
            id              = 1,
            type            = CN.objectiveTypes.QUEST,
            name            = "Run to your body",
            completionValue = 40,
            travelCost      = 0,
            mapID           = corpse.mapID,
            x               = corpse.x,
            y               = corpse.y,
            corpse          = true,
            reasons         = { "you are a ghost; everything else keeps" },
        }),
    }
end, { volatile = true, events = { "PLAYER_DEAD", "PLAYER_ALIVE",
                                   "PLAYER_UNGHOST" } })

function Group.Notice()
    local situation = Group.Situation()

    if situation == "dead" then
        if Group.IsGhost() then
            local corpse = Group.CorpseTarget()

            if corpse then
                return "You are a ghost. Your body is marked -- the rest of "
                    .. "this keeps."
            end

            return "You are a ghost. Your body first -- the rest of this "
                .. "keeps."
        end

        return "You are dead. Release or accept a resurrection first."
    end

    if situation == "instanced" then
        local _, kind = Group.Instance()

        return "You are in a " .. (kind == "raid" and "raid" or "instance")
            .. " with " .. Group.Size() .. " people; outside work is ranked "
            .. "down until you leave."
    end

    return nil
end

-- The situation changes what is worth doing, so the order has to be rebuilt.
-- Cheap: this bumps the ranking generation rather than rebuilding providers,
-- because no candidate's data changed -- only its weighting.
for _, event in ipairs({
    "PLAYER_DEAD", "PLAYER_ALIVE", "PLAYER_UNGHOST",
    "GROUP_ROSTER_UPDATE", "PLAYER_ENTERING_WORLD",
}) do
    CN:RegisterEvent(event, function()
        CN.InvalidateRanking()
    end)
end

CN:RegisterCommand{
    name    = "situation",
    aliases = { "state" },
    order   = 36,
    help    = "What the addon thinks you are in the middle of.",
    handler = function()
        local situation = Group.Situation()

        -- TRANSLATED WHERE IT IS SHOWN, NOT WHERE IT IS DECIDED.
        --
        -- `Situation()` returns an identifier that four call sites compare
        -- against; translating the return value would break every one of
        -- them. The four words are translated in all ten locale files and
        -- were never looked up, because the only place a player reads them is
        -- here.
        Print("Situation: |cffffff00" .. CN.L[situation] .. "|r")

        local inside, kind = Group.Instance()

        Print("  group: " .. (Group.InGroup()
            and (Group.Size() .. (Group.InRaid() and " (raid)" or " (party)"))
            or CN.L["solo"]))
        Print("  instance: " .. (inside and kind or "no"))
        Print("  alive: " .. CN.YesNo(not Group.IsDead()))

        local notice = Group.Notice()

        if notice then
            Print("|cffffd100" .. notice .. "|r")
        else
            Print("|cff999999Nothing about your situation is changing the "
                .. "ranking right now.|r")
        end
    end,
}

return Group

'@

$Embedded['Modules\Inventory.lua'] = @'
-- Modules/Inventory.lua
-- Completion Navigator :: what you are already carrying.
--
-- WHAT WAS MISSING.
--
-- `C_Container` appeared nowhere in this addon. Twenty-nine releases of
-- answering "what should I do next?" without ever looking in the player's
-- bags, which is where a surprising amount of the answer already is:
--
--   * The item that STARTS a quest, sitting in a bag since a boss dropped it.
--   * Forty of the fifty things a quest wants, so the answer is "ten more",
--     not "go and do that quest".
--   * A recipe you already own and have not learned.
--   * A mount, a pet or a toy in item form, uncollected and in a bag.
--
-- Every one of those is a next action the addon could not see, and three of
-- them are the cheapest actions available: the walk is zero yards.
--
-- WHAT IT DOES NOT DO.
--
-- It does not use anything, learn anything, sell anything or move anything. It
-- reads. The standing rule in this addon is that it prompts and never acts,
-- and an addon that starts using items out of your bags is an addon that will
-- eventually use the wrong one.

local ADDON_NAME, CN = ...

local Inventory = CN:RegisterModule("Inventory")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- READING THE BAGS
------------------------------------------------------------

-- Backpack plus four bags, and the reagent bag where the client has one.
-- Numbers rather than a constant because the constants have been renamed
-- twice and the numbers have not changed since 2004.
Inventory.bagIDs = { 0, 1, 2, 3, 4, 5 }

-- Bank containers. Read only while the bank is open -- the client refuses
-- otherwise, and a cached answer about a bank you are not standing at is a
-- claim the addon cannot support.
Inventory.bankIDs = { -1, 6, 7, 8, 9, 10, 11, 12 }

function Inventory.IsAvailable()
    return C_Container ~= nil
        and C_Container.GetContainerNumSlots ~= nil
        and C_Container.GetContainerItemInfo ~= nil
end

-- Whether the client considers this slot a quest item. Guarded separately
-- from the rest: GetContainerItemQuestInfo is a different call with its own
-- availability, and a client that lacks it should report "not a quest item"
-- rather than erroring on every slot in the bag.
local function QuestItem(bag, slot)
    if not C_Container or not C_Container.GetContainerItemQuestInfo then
        return false
    end

    local ok, info = pcall(C_Container.GetContainerItemQuestInfo, bag, slot)

    if not ok or type(info) ~= "table" then
        return false
    end

    return (info.isQuestItem or info.questID) and true or false
end

-- Every item in a set of containers, as { itemID, count, link, quality, bag,
-- slot, questItem }.
--
-- The shape above used to claim `questID` and `isUsable` as well. Neither was
-- ever set on these rows. A comment that describes a richer row than the code
-- builds is worse than no comment: the next reader writes `row.questID` and
-- gets nil forever, with nothing anywhere to say why.
-- CACHED FOR THE BAGS, WHICH IS WHERE IT IS ASKED FOR REPEATEDLY.
--
-- The candidate provider calls QuestStarters, NearlyDone and
-- UncollectedItems, and every one of them rescanned all five bags -- three
-- full walks of a hundred and eighty slots per rebuild, each slot costing two
-- client calls.
--
-- Bags announce their own changes, so the cache lives until they do. Only the
-- default container set is cached: a bank scan is a deliberate one-off and
-- caching it would risk answering about a bank the player has walked away
-- from.
local bagCache = nil

function Inventory.Forget()
    bagCache = nil
end

function Inventory.Scan(containers)
    if not containers and bagCache then
        return bagCache
    end

    local items = {}

    if not Inventory.IsAvailable() then
        return items
    end

    for _, bag in ipairs(containers or Inventory.bagIDs) do
        local gotSlots, slots = pcall(C_Container.GetContainerNumSlots, bag)

        if gotSlots and type(slots) == "number" and slots > 0 then
            for slot = 1, slots do
                local gotInfo, info =
                    pcall(C_Container.GetContainerItemInfo, bag, slot)

                if gotInfo and type(info) == "table" and info.itemID then
                    table.insert(items, {
                        itemID   = info.itemID,
                        count    = info.stackCount or 1,
                        link     = info.hyperlink,
                        quality  = info.quality,
                        bag      = bag,
                        slot     = slot,
                        -- `hasNoValue` means the vendor will not buy it. It
                        -- has nothing to do with quest items, and reading it
                        -- as one made `questItem` true for every grey and
                        -- every soulbound token in the bag. The real question
                        -- has its own API, which this same file already asks
                        -- correctly forty lines below.
                        questItem = QuestItem(bag, slot),
                    })
                end
            end
        end
    end

    if not containers then
        bagCache = items
    end

    return items
end

-- How many of an item the player is carrying, across every bag.
function Inventory.Count(itemID)
    if not itemID then
        return 0
    end

    if C_Item and C_Item.GetItemCount then
        local ok, count = pcall(C_Item.GetItemCount, itemID)

        if ok and count then
            return count
        end
    end

    if GetItemCount then
        local ok, count = pcall(GetItemCount, itemID)

        if ok and count then
            return count
        end
    end

    return 0
end

------------------------------------------------------------
-- WHAT IS ACTIONABLE IN THERE
------------------------------------------------------------

-- Items that start a quest. The client will say so directly, which makes this
-- the single most reliable thing in the file -- and the addon has been
-- ignoring it since the first build.
function Inventory.QuestStarters()
    local starters = {}

    if not Inventory.IsAvailable() or not C_Container.GetContainerItemQuestInfo then
        return starters
    end

    for _, item in ipairs(Inventory.Scan()) do
        local ok, info = pcall(C_Container.GetContainerItemQuestInfo,
            item.bag, item.slot)

        if ok and type(info) == "table" and info.questID and not info.isActive then
            item.questID = info.questID

            table.insert(starters, item)
        end
    end

    return starters
end

-- Collectible items sitting in a bag: a mount, a pet, a toy or a recipe the
-- player owns and has not used. Zero yards from where they are standing.
function Inventory.UncollectedItems()
    local found = {}

    for _, item in ipairs(Inventory.Scan()) do
        -- Collection state comes from the journals, which are the authority.
        -- Asking "is this item a mount" and "do I own that mount" are two
        -- different questions and only the second one keeps the addon from
        -- telling somebody to learn what they already have.
        local mountID = Blizzard.GetMountFromItem(item.itemID)

        local mount = mountID and Blizzard.GetMountByID(mountID)

        if mount and not mount.collected then
            item.kind = CN.objectiveTypes.MOUNT
            item.collectibleID = mountID

            table.insert(found, item)
        else
            local speciesID = Blizzard.GetPetSpeciesFromItem(item.itemID)

            local pets = CN:GetModule("Pets")

            if speciesID and pets and pets.Store()[speciesID]
                and not pets.Store()[speciesID].collected then

                item.kind = CN.objectiveTypes.PET
                item.collectibleID = speciesID

                table.insert(found, item)
            elseif PlayerHasToy and C_ToyBox and C_ToyBox.GetToyInfo then
                local isToy = select(2, pcall(C_ToyBox.GetToyInfo, item.itemID))

                local owned = select(2, pcall(PlayerHasToy, item.itemID))

                if isToy and not owned then
                    item.kind = CN.objectiveTypes.TOY
                    item.collectibleID = item.itemID

                    table.insert(found, item)
                end
            end
        end
    end

    return found
end

-- HOW CLOSE AN ACCEPTED QUEST IS, IN THINGS RATHER THAN IN PERCENT.
--
-- This file's own header has promised since 0.44.0 that the addon would say
-- "ten more" rather than "go and do that quest". It did not: the header
-- described an intention and the code collected quest STARTERS and nothing
-- else. Writing down what a thing is going to do and then not doing it is
-- worse than not writing it down, because the next reader believes it.
--
-- The client counts these itself, which is the whole reason this is cheap:
-- an objective that requires more than one of something reports how many are
-- done. Returns the objectives that are counting and unfinished, nearest to
-- completion first -- because "one more" is a completely different suggestion
-- from "nineteen more".
function Inventory.QuestProgress(questID)
    local rows = {}

    for _, objective in ipairs(Blizzard.GetCountingObjectives(questID)) do
        if not objective.finished then
            table.insert(rows, objective)
        end
    end

    table.sort(rows, function(a, b)
        return a.remaining < b.remaining
    end)

    return rows
end

-- The same question across every quest in the log: what is nearly done?
Inventory.nearlyDoneRemaining = 3

function Inventory.NearlyDone()
    local rows = {}

    for _, entry in ipairs(Blizzard.GetQuestLogEntries()) do
        for _, objective in ipairs(Inventory.QuestProgress(entry.questID)) do
            if objective.remaining <= Inventory.nearlyDoneRemaining then
                table.insert(rows, {
                    questID   = entry.questID,
                    title     = entry.title,
                    text      = objective.text,
                    done      = objective.done,
                    required  = objective.required,
                    remaining = objective.remaining,
                })
            end
        end
    end

    table.sort(rows, function(a, b)
        if a.remaining ~= b.remaining then
            return a.remaining < b.remaining
        end

        return (a.questID or 0) < (b.questID or 0)
    end)

    return rows
end

-- RECIPES YOU OWN AND HAVE NOT LEARNED.
--
-- The other promise this header made and did not keep. An unlearned recipe in
-- a bag is a profession skill-up sitting in your inventory, and the addon has
-- been recommending vendors that sell recipes while ignoring the ones you
-- already bought.
--
-- Item class 9 is Recipe. The client will say whether the character already
-- knows it -- an already-known recipe is greyed in the tooltip -- but there
-- is no clean API for that state, so this reports what is CARRIED and leaves
-- the "already known" question to the tooltip, which answers it visually.
function Inventory.Recipes()
    local recipes = {}

    if not C_Item or not C_Item.GetItemInfoInstant then
        return recipes
    end

    for _, item in ipairs(Inventory.Scan()) do
        local ok, _, _, _, _, classID = pcall(C_Item.GetItemInfoInstant, item.itemID)

        if ok and classID == 9 then
            item.kind = CN.objectiveTypes.RECIPE

            table.insert(recipes, item)
        end
    end

    return recipes
end

------------------------------------------------------------
-- THE BANK
------------------------------------------------------------

-- `bankIDs` has been declared since 0.44.0 and read by nothing -- a list of
-- container numbers sitting there looking like a feature.
--
-- The client refuses to describe bank containers unless the bank frame is
-- open, so this is only answerable while the player is standing at one. The
-- honest shape is therefore: scan when it is open, remember what was seen,
-- and report the remembered set with the date it was taken -- never
-- presenting a week-old snapshot as current.
function Inventory.BankStore()
    return CN.Account("bank")
end

function Inventory.ScanBank()
    local items = Inventory.Scan(Inventory.bankIDs)

    local store = Inventory.BankStore()

    for key in pairs(store) do
        store[key] = nil
    end

    -- Item ids and counts only. The bag and slot of something in a bank is
    -- not worth a byte on disk: it moves, and the player is looking at it.
    for _, item in ipairs(items) do
        store[item.itemID] = (store[item.itemID] or 0) + (item.count or 1)
    end

    store.scannedAt = time()

    return #items
end

CN:RegisterEvent("BAG_UPDATE_DELAYED", function()
    Inventory.Forget()
end)

CN:RegisterEvent("BANKFRAME_OPENED", function()
    local counted = Inventory.ScanBank()

    DebugPrint("Bank scanned: " .. counted .. " stacks.")
end)

function Inventory.Summary()
    local items = Inventory.Scan()

    return {
        items    = #items,
        starters = #Inventory.QuestStarters(),
        uncollected = #Inventory.UncollectedItems(),
    }
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- The cheapest actions the addon can offer: the walk is zero.
CN.RegisterCandidateProvider("Inventory", function()
    local candidates = {}

    if not Inventory.IsAvailable() then
        return candidates
    end

    for _, item in ipairs(Inventory.QuestStarters()) do
        if not CN.IsIgnored(CN.objectiveTypes.QUEST, item.questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, item.questID) then

            table.insert(candidates, CN.NewObjective({
                id               = item.questID,
                type             = CN.objectiveTypes.QUEST,
                name             = "Start: " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID)),
                state            = CN.objectiveStates.AVAILABLE,
                completionValue  = 3,
                unlockValue      = 1,

                -- Zero, and it is the honest number: the item is in your bag.
                travelCost       = 0,
                reasons          = {
                    "a quest starter in your bags -- right-click it",
                },
            }))
        end
    end

    -- NEARLY-FINISHED OBJECTIVES.
    --
    -- "One more Sunscale Feather" is the cheapest quest advice there is, and
    -- the ranking could not distinguish it from a quest not yet started.
    for _, row in ipairs(Inventory.NearlyDone()) do
        if not CN.IsIgnored(CN.objectiveTypes.QUEST, row.questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, row.questID) then

            table.insert(candidates, CN.NewObjective({
                id               = row.questID,
                type             = CN.objectiveTypes.QUEST,
                name             = tostring(row.title or ("Quest " .. row.questID))
                    .. ": " .. row.remaining .. " more",
                state            = CN.objectiveStates.AVAILABLE,

                -- Worth more the closer it is, which is the entire point.
                completionValue  = 2 + (Inventory.nearlyDoneRemaining - row.remaining),
                travelCost       = CN.unknownLocationCost,
                reasons          = {
                    string.format("%s -- %d of %d done",
                        tostring(row.text or "objective"), row.done, row.required),
                },
            }))
        end
    end

    for _, item in ipairs(Inventory.UncollectedItems()) do
        if not CN.IsIgnored(item.kind, item.collectibleID)
            and not CN.IsDeferred(item.kind, item.collectibleID) then

            table.insert(candidates, CN.NewObjective({
                id               = item.collectibleID,
                type             = item.kind,
                name             = Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID),
                completionValue  = 4,
                travelCost       = 0,
                reasons          = {
                    "already in your bags, uncollected",
                },
            }))
        end
    end

    return candidates
end, {
    events   = { "BAG_UPDATE_DELAYED", "PLAYER_ENTERING_WORLD" },
    cooldown = 5,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "bags",
    aliases = { "inventory" },
    order   = 28,
    help    = "What is in your bags that you could act on right now.",
    handler = function()
        if not Inventory.IsAvailable() then
            Print("This client does not expose container contents.")
            return
        end

        local summary = Inventory.Summary()

        Print(summary.items .. " items carried.")

        local starters = Inventory.QuestStarters()

        if #starters > 0 then
            Print(#starters .. " of them start a quest:")

            for _, item in ipairs(starters) do
                Print("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID))
                    .. " |cff999999bag " .. item.bag .. ", slot " .. item.slot .. "|r")
            end
        end

        local uncollected = Inventory.UncollectedItems()

        if #uncollected > 0 then
            Print(#uncollected .. " are collectibles you have not learned:")

            for _, item in ipairs(uncollected) do
                Print("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID))
                    .. " |cff999999" .. tostring(item.kind) .. "|r")
            end
        end

        local recipes = Inventory.Recipes()

        if #recipes > 0 then
            Print(#recipes .. " recipe(s) carried:")

            for _, item in ipairs(recipes) do
                Print("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID)))
            end
        end

        local nearly = Inventory.NearlyDone()

        if #nearly > 0 then
            Print("Nearly finished:")

            for index, row in ipairs(nearly) do
                if index > 8 then
                    -- Translated, like the identical phrase nine lines below.
                    -- Hardcoded English two lines from a CN.L lookup of the
                    -- same words is how a locale file ends up complete and
                    -- the addon still English.
                    Print("  |cff999999"
                        .. string.format(CN.L["%d more"], #nearly - 8) .. "|r")
                    break
                end

                Print(string.format("  |cffffff00" .. CN.L["%d more"]
                    .. "|r %s |cff999999(%d/%d)|r",
                    row.remaining, tostring(row.text or row.title),
                    row.done, row.required))
            end
        end

        local bank = Inventory.BankStore()

        if bank.scannedAt then
            local age = math.max(0, time() - bank.scannedAt)

            Print("|cff999999Bank: " .. (CN.CountKeys(bank) - 1)
                .. " kinds of item, seen "
                .. math.floor(age / 3600) .. "h ago -- the client only "
                .. "describes it while you are standing at one.|r")
        end

        if #starters == 0 and #uncollected == 0 and #recipes == 0
            and #nearly == 0 then

            Print("|cff999999Nothing in there needs doing.|r")
        end

        Print("|cff999999Nothing is used, learned or moved on your behalf.|r")
    end,
}

return Inventory
'@

$Embedded['Modules\Waiting.lua'] = @'
-- Modules/Waiting.lua
-- Completion Navigator :: things with a clock on them that the addon could
-- not see.
--
-- Four systems, one file, because each is thirty lines and none of them
-- deserves a module. What they share is the only thing that matters to the
-- ranking: a deadline, and something lost when it passes.
--
--   MAIL          -- expires and is destroyed. Thirty days, and the client
--                    tells you how many are left.
--   KEYSTONE      -- the one in your bag is gone at the weekly reset.
--   KNOWLEDGE     -- profession knowledge is weekly, capped, and permanently
--                    missable: the week you skip does not come back.
--   HEIRLOOMS     -- no deadline, but a collection with its own journal that
--                    nothing in this addon had ever read.
--
-- ON MAIL, SPECIFICALLY.
--
-- This reads the mailbox the client has already told the addon about. It does
-- not open mail, take attachments, or send anything. An addon that empties
-- your mailbox unprompted is one bad edge case away from destroying something
-- irreplaceable, and the standing rule here is that the addon prompts and
-- never acts.

local ADDON_NAME, CN = ...

local Waiting = CN:RegisterModule("Waiting")

local Print      = CN.Print
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- MAIL
------------------------------------------------------------

-- Below this, it is worth interrupting whatever the player is doing. Three
-- days: enough warning to be actionable, short enough that it is not shouting
-- about mail that arrived this morning.
Waiting.mailWarningDays = 3

function Waiting.Mail()
    local items = {}

    if not GetInboxNumItems or not GetInboxHeaderInfo then
        return items, false
    end

    local ok, count = pcall(GetInboxNumItems)

    if not ok or not count or count == 0 then
        return items, true
    end

    for index = 1, count do
        local gotInfo, _, _, sender, subject, money, _, daysLeft, itemCount =
            pcall(GetInboxHeaderInfo, index)

        if gotInfo and daysLeft then
            table.insert(items, {
                sender    = sender,
                subject   = subject,
                money     = money or 0,
                items     = itemCount or 0,
                daysLeft  = daysLeft,
                expiring  = daysLeft <= Waiting.mailWarningDays,
            })
        end
    end

    table.sort(items, function(a, b)
        return (a.daysLeft or 0) < (b.daysLeft or 0)
    end)

    return items, true
end

function Waiting.ExpiringMail()
    local expiring = {}

    for _, mail in ipairs((Waiting.Mail())) do
        if mail.expiring and (mail.items > 0 or mail.money > 0) then
            table.insert(expiring, mail)
        end
    end

    return expiring
end

------------------------------------------------------------
-- KEYSTONE
------------------------------------------------------------

function Waiting.Keystone()
    if not C_MythicPlus then
        return nil
    end

    local level, mapID

    if C_MythicPlus.GetOwnedKeystoneLevel then
        local ok, owned = pcall(C_MythicPlus.GetOwnedKeystoneLevel)

        if ok then
            level = owned
        end
    end

    if not level or level == 0 then
        return nil
    end

    if C_MythicPlus.GetOwnedKeystoneChallengeMapID then
        local ok, owned = pcall(C_MythicPlus.GetOwnedKeystoneChallengeMapID)

        if ok then
            mapID = owned
        end
    end

    local name

    if mapID and C_ChallengeMode and C_ChallengeMode.GetMapUIInfo then
        local ok, mapName = pcall(C_ChallengeMode.GetMapUIInfo, mapID)

        if ok then
            name = mapName
        end
    end

    return {
        level = level,
        mapID = mapID,
        name  = name,
        -- A keystone is replaced at the reset whether or not it is used, so
        -- the reset IS its expiry.
        expiresIn = Blizzard.GetSecondsUntilWeeklyReset(),
    }
end

------------------------------------------------------------
-- PROFESSION KNOWLEDGE
------------------------------------------------------------

-- Weekly knowledge is the most permanently missable thing in modern
-- professions: the cap resets, and a week not collected is gone. The client
-- exposes it as a currency, which is why this reads currencies rather than
-- the profession API -- fewer moving parts, and it works for every expansion
-- that has used the pattern.
Waiting.knowledgePattern = "[Kk]nowledge"

function Waiting.Knowledge()
    local rows = {}

    local currencies = CN:GetModule("Currencies")

    -- `CharacterStore`, not `Store`. There has never been a Currencies.Store,
    -- so this guard was false on every client and the whole KNOWLEDGE section
    -- of `/cn clock` -- plus its candidates -- has never once produced a row,
    -- in a file whose header calls weekly profession knowledge "the most
    -- permanently missable thing in modern professions".
    --
    -- Nothing caught it because an empty knowledge list and a knowledge list
    -- that cannot be built look identical from outside, and the suite only
    -- asserted that `/cn clock` did not error.
    if not currencies or not currencies.CharacterStore then
        return rows
    end

    for currencyID, record in pairs(currencies.CharacterStore() or {}) do
        if record.maxWeeklyQuantity and record.maxWeeklyQuantity > 0
            and (record.weeklyRemaining or 0) > 0 then

            local name = Blizzard.GetCurrency(currencyID)

            name = name and name.name

            if name and name:find(Waiting.knowledgePattern) then
                table.insert(rows, {
                    currencyID = currencyID,
                    name       = name,
                    remaining  = record.weeklyRemaining,
                    cap        = record.maxWeeklyQuantity,
                })
            end
        end
    end

    table.sort(rows, function(a, b) return a.currencyID < b.currencyID end)

    return rows
end

------------------------------------------------------------
-- HEIRLOOMS
------------------------------------------------------------

function Waiting.Heirlooms()
    if not C_Heirloom or not C_Heirloom.GetNumHeirlooms then
        return nil
    end

    local ok, total = pcall(C_Heirloom.GetNumHeirlooms)

    if not ok or not total then
        return nil
    end

    local collected = 0

    for index = 1, total do
        local gotID, itemID = pcall(C_Heirloom.GetHeirloomItemIDFromIndex, index)

        if gotID and itemID then
            local gotOwned, owned = pcall(C_Heirloom.PlayerHasHeirloom, itemID)

            if gotOwned and owned then
                collected = collected + 1
            end
        end
    end

    return { total = total, collected = collected }
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Waiting", function()
    local candidates = {}

    -- MAIL. Ranked by what is actually at stake: mail with something in it,
    -- about to be destroyed.
    local expiring = Waiting.ExpiringMail()

    if #expiring > 0 then
        local soonest = expiring[1]

        table.insert(candidates, CN.NewObjective({
            id               = "mail",
            type             = CN.objectiveTypes.CURRENCY,
            name             = #expiring .. " mail expiring",
            completionValue  = 6,
            limitedTimeBonus = 3,
            travelCost       = 3,
            expiresIn        = math.max(0, (soonest.daysLeft or 0) * 86400),
            reasons          = {
                string.format("%d message(s) with attachments, the first in "
                    .. "%.1f days", #expiring, soonest.daysLeft or 0),
                "expired mail is destroyed, not returned",
            },
        }))
    end

    -- KEYSTONE. Not gearing: a thing in your bag that is replaced on Tuesday
    -- whether you use it or not.
    local keystone = Waiting.Keystone()

    if keystone and not CN.IsIgnored(CN.objectiveTypes.INSTANCE, "keystone")
        and not CN.IsDeferred(CN.objectiveTypes.INSTANCE, "keystone") then

        table.insert(candidates, CN.NewObjective({
            id               = "keystone",
            type             = CN.objectiveTypes.INSTANCE,
            name             = "Keystone: " .. (keystone.name or "unknown")
                .. " +" .. keystone.level,
            completionValue  = 4,
            limitedTimeBonus = 2,
            travelCost       = 3,
            expiresIn        = keystone.expiresIn,
            reasons          = {
                "your keystone is replaced at the weekly reset whether you "
                    .. "use it or not",
            },
        }))
    end

    -- KNOWLEDGE. The most permanently missable thing in the game that the
    -- addon can see.
    for _, row in ipairs(Waiting.Knowledge()) do
        if not CN.IsIgnored(CN.objectiveTypes.PROFESSION, row.currencyID)
            and not CN.IsDeferred(CN.objectiveTypes.PROFESSION, row.currencyID) then

            table.insert(candidates, CN.NewObjective({
                id               = row.currencyID,
                type             = CN.objectiveTypes.PROFESSION,
                name             = row.name .. ": " .. row.remaining .. " left this week",
                completionValue  = 5,
                limitedTimeBonus = 2,
                travelCost       = CN.unknownLocationCost,
                expiresIn        = Blizzard.GetSecondsUntilWeeklyReset(),
                reasons          = {
                    row.remaining .. " of " .. row.cap .. " still collectable this week",
                    "a week not collected does not come back",
                },
            }))
        end
    end

    return candidates
end, {
    events   = { "MAIL_INBOX_UPDATE", "BAG_UPDATE_DELAYED", "CURRENCY_DISPLAY_UPDATE" },
    volatile = true,
    cooldown = 30,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "clock",
    aliases = { "expiring" },
    order   = 29,
    help    = "Everything with a deadline that is not a quest.",
    handler = function()
        local said = false

        local mail, readable = Waiting.Mail()

        if not readable then
            Print("|cff999999Mail cannot be read in this client.|r")
        elseif #mail == 0 then
            Print("|cff999999No mail, or the mailbox has not been opened this "
                .. "session -- the client only hands the addon the inbox once "
                .. "you have looked at it.|r")
        else
            Print(#mail .. " message(s) in your mailbox:")

            for index, entry in ipairs(mail) do
                if index > 5 then
                    Print("  |cff999999... and " .. (#mail - 5) .. " more|r")
                    break
                end

                local colour = entry.expiring and "|cfff56b61" or "|cff999999"

                Print(string.format("  %s%.1f days|r %s |cff999999from %s|r",
                    colour, entry.daysLeft or 0,
                    tostring(entry.subject or "(no subject)"),
                    tostring(entry.sender or "?")))
            end

            said = true
        end

        local keystone = Waiting.Keystone()

        if keystone then
            Print("Keystone: " .. (keystone.name or "unknown")
                .. " |cffffff00+" .. keystone.level .. "|r")

            said = true
        end

        local knowledge = Waiting.Knowledge()

        for _, row in ipairs(knowledge) do
            Print(row.name .. ": |cffffff00" .. row.remaining
                .. "|r of " .. row.cap .. " still collectable this week")

            said = true
        end

        local heirlooms = Waiting.Heirlooms()

        if heirlooms then
            Print("Heirlooms: " .. heirlooms.collected .. " of " .. heirlooms.total)

            said = true
        end

        if not said then
            Print(CN.L["Nothing is on a clock right now."])
        end
    end,
}

return Waiting
'@

$Embedded['Modules\Sets.lua'] = @'
-- Modules/Sets.lua
-- Completion Navigator :: appearance SETS, the guild, and what you could
-- queue for.
--
-- Three readers, one file, for the same reason Waiting holds four: each is a
-- thin wrapper over a client API the addon had never opened, and none of them
-- carries enough behaviour to justify a module of its own.
--
-- SETS.
--
-- The addon has tracked individual appearances since 0.13.0 and has never
-- known that the game groups them. That matters because collecting is
-- overwhelmingly done by SET -- nobody wants "one more shoulder", they want
-- the tier set finished -- and "3 of 5 pieces" is a genuine denominator the
-- client supplies, which this addon is otherwise very short of.
--
-- GUILD.
--
-- Guild achievements and guild reputation are a whole progression track that
-- was structurally invisible. Modest scope deliberately: what the guild is,
-- and whether the character is close to anything in it.
--
-- QUEUES.
--
-- "You could run this right now" is a different and more useful sentence than
-- "this dungeon exists". The client knows what the character is eligible for;
-- the addon never asked.

local ADDON_NAME, CN = ...

local Sets = CN:RegisterModule("Sets")

local Print = CN.Print

------------------------------------------------------------
-- APPEARANCE SETS
------------------------------------------------------------

function Sets.IsAvailable()
    return C_TransmogSets ~= nil and C_TransmogSets.GetAllSets ~= nil
end

-- Every set the client will describe, with how much of it is collected.
--
-- Bounded: there are several thousand sets across the game's history and each
-- one costs a call to enumerate its pieces. The cap is a real limit on what
-- this answers, so it is stated rather than hidden -- the command says how
-- many were examined.
Sets.scanCap = 400

-- CACHED, BECAUSE THIS IS THE MOST EXPENSIVE THING IN THE ADDON WITHOUT IT.
--
-- Measured at realistic scale -- three thousand sets, which is roughly what
-- the game holds -- the uncached scan cost 4.4 milliseconds per candidate
-- rebuild: more than every other provider in the addon added together, and
-- nearly half of a 16ms frame.
--
-- It was invisible in the first measurement because the fixture had three
-- sets in it. That is the same trap as the map that was always square and the
-- flying speed that was always rejected: a fixture small enough to read is a
-- fixture too small to measure.
--
-- Collections change rarely and announce themselves, so the cache is held
-- until the client says a transmog was collected.
local cache = nil

function Sets.Forget()
    cache = nil
end

function Sets.All(limit)
    limit = limit or Sets.scanCap

    if cache and cache.limit == limit then
        return cache.rows, cache.readable, cache.examined
    end

    local rows = {}

    if not Sets.IsAvailable() then
        return rows, false
    end

    local ok, all = pcall(C_TransmogSets.GetAllSets)

    if not ok or type(all) ~= "table" then
        return rows, false
    end

    local examined = 0

    for _, set in ipairs(all) do
        if examined >= limit then
            break
        end

        if set.setID and set.collected ~= nil then
            examined = examined + 1

            local total, collected = 0, 0

            if C_TransmogSets.GetSetPrimaryAppearances then
                local gotPieces, pieces =
                    pcall(C_TransmogSets.GetSetPrimaryAppearances, set.setID)

                if gotPieces and type(pieces) == "table" then
                    for _, piece in ipairs(pieces) do
                        total = total + 1

                        if piece.collected then
                            collected = collected + 1
                        end
                    end
                end
            end

            table.insert(rows, {
                setID     = set.setID,
                name      = set.name,
                label     = set.label,
                collected = collected,
                total     = total,
                complete  = set.collected and true or false,
            })
        end
    end

    cache = {
        rows     = rows,
        readable = true,
        examined = examined,
        limit    = limit,
    }

    return rows, true, examined
end

-- The sets closest to finished, which is the only ordering anybody wants.
-- A set with nothing collected is not "nearly done"; it is a decision.
function Sets.NearlyComplete(maxMissing)
    maxMissing = maxMissing or 2

    local rows = {}

    for _, set in ipairs((Sets.All())) do
        local missing = set.total - set.collected

        if set.total > 0 and missing > 0 and missing <= maxMissing then
            set.missing = missing

            table.insert(rows, set)
        end
    end

    table.sort(rows, function(a, b)
        if a.missing ~= b.missing then
            return a.missing < b.missing
        end

        return (a.setID or 0) < (b.setID or 0)
    end)

    return rows
end

------------------------------------------------------------
-- THE GUILD
------------------------------------------------------------

function Sets.Guild()
    if not IsInGuild then
        return nil
    end

    local ok, inGuild = pcall(IsInGuild)

    if not ok or not inGuild then
        return nil
    end

    local name, rank, rankIndex

    if GetGuildInfo then
        local gotInfo, guildName, guildRank, guildRankIndex =
            pcall(GetGuildInfo, "player")

        if gotInfo then
            name, rank, rankIndex = guildName, guildRank, guildRankIndex
        end
    end

    return {
        name      = name,
        rank      = rank,
        rankIndex = rankIndex,
    }
end

------------------------------------------------------------
-- WHAT YOU COULD QUEUE FOR
------------------------------------------------------------

-- Deliberately read-only, and deliberately not a queueing button. An addon
-- that puts you in a group finder queue is an addon that will one day do it
-- while you are in a raid.
function Sets.Queues()
    local rows = {}

    if not C_LFGList or not C_LFGList.GetAvailableActivities then
        return rows, false
    end

    local ok, activities = pcall(C_LFGList.GetAvailableActivities)

    if not ok or type(activities) ~= "table" then
        return rows, false
    end

    for _, activityID in ipairs(activities) do
        local gotInfo, info = pcall(C_LFGList.GetActivityInfoTable, activityID)

        if gotInfo and type(info) == "table" and info.fullName then
            table.insert(rows, {
                activityID = activityID,
                name       = info.fullName,
                maxPlayers = info.maxNumPlayers,
            })
        end
    end

    return rows, true
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN:RegisterEvent("TRANSMOG_COLLECTION_UPDATED", function()
    Sets.Forget()
end)

CN.RegisterCandidateProvider("Sets", function()
    local candidates = {}

    for _, set in ipairs(Sets.NearlyComplete()) do
        if not CN.IsIgnored(CN.objectiveTypes.APPEARANCE, set.setID)
            and not CN.IsDeferred(CN.objectiveTypes.APPEARANCE, set.setID) then

            table.insert(candidates, CN.NewObjective({
                id               = set.setID,
                type             = CN.objectiveTypes.APPEARANCE,
                name             = tostring(set.name or ("Set " .. set.setID))
                    .. ": " .. set.missing .. " piece(s) left",

                -- A REAL denominator, which this addon is normally short of.
                completionValue  = 3 + (3 - math.min(3, set.missing)),
                travelCost       = CN.unknownLocationCost,
                reasons          = {
                    set.collected .. " of " .. set.total .. " pieces collected",
                },
            }))
        end
    end

    return candidates
end, {
    events   = { "TRANSMOG_COLLECTION_UPDATED" },
    cooldown = 60,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "sets",
    aliases = { "guild", "queues" },
    order   = 31,
    help    = "Appearance sets nearly finished, your guild, and what you "
        .. "could queue for.",
    handler = function()
        local rows, readable, examined = Sets.All()

        if not readable then
            Print("|cff999999This client does not expose appearance sets.|r")
        else
            local nearly = Sets.NearlyComplete()

            Print(#rows .. " sets read"
                .. (examined and examined >= Sets.scanCap
                    and (" |cff999999(capped at " .. Sets.scanCap
                        .. "; there are more)|r") or "") .. ".")

            if #nearly == 0 then
                Print("|cff999999None of them is within two pieces.|r")
            else
                Print("Nearly finished:")

                for index, set in ipairs(nearly) do
                    if index > 10 then
                        Print("  |cff999999... and " .. (#nearly - 10) .. " more|r")
                        break
                    end

                    Print(string.format("  |cffffff00%d left|r %s |cff999999(%d/%d)|r",
                        set.missing, tostring(set.name or set.setID),
                        set.collected, set.total))
                end
            end
        end

        local guild = Sets.Guild()

        if guild then
            Print("Guild: |cffffff00" .. tostring(guild.name or "?") .. "|r"
                .. (guild.rank and (" |cff999999" .. guild.rank .. "|r") or ""))
        end

        local queues, queueReadable = Sets.Queues()

        if queueReadable and #queues > 0 then
            Print(#queues .. " activities you are eligible to queue for.")
            Print("|cff999999The addon reads that list. It does not queue you "
                .. "for anything.|r")
        end
    end,
}

return Sets
'@

$Embedded['Modules\Travel.lua'] = @'
-- Modules/Travel.lua
-- Completion Navigator :: how long it actually takes to get there.
--
-- WHAT WAS WRONG.
--
-- Every travel figure in this addon was a straight line. Within a zone that is
-- very nearly right -- you run in roughly the direction you are going. Between
-- zones it is not even approximately right, and the addon papered over that
-- with a flat penalty: anything outside your current zone cost the same
-- whether it was over the next ridge or on the far side of the continent.
--
-- That flat number is why `/cn plan 30` could put something in your half hour
-- that is a flight and a ride away, and why `/cn zones` ranked a zone with a
-- flight master in it the same as one without.
--
-- WHAT THIS DOES.
--
-- Costs a journey the way you would actually make it: run to the nearest
-- flight point you know, fly, run from the arrival point to the target -- and
-- compares that against simply running the whole way, taking whichever is
-- quicker. Flight points you have not discovered do not exist as far as this
-- is concerned, because they do not exist for you either.
--
-- WHAT IT REFUSES TO DO.
--
-- Guess. Flight speed is MEASURED, from your own flights, exactly the way
-- running speed already is -- the client will not tell us and the number
-- differs between expansions. Until it has been measured, estimates are
-- returned with confidence false and every caller says so out loud rather
-- than printing a number that looks like a fact.
--
-- Two continents with no flight between them return nil, not a large number.
-- "I do not know" is an answer; a fabricated four hours is not.

local ADDON_NAME, CN = ...

local Travel = CN:RegisterModule("Travel")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- POINTS IN THE WORLD
------------------------------------------------------------

-- Map coordinates are normalized per map, so two points on different maps
-- cannot be compared at all in map space. World coordinates can: they are
-- yards, they are continuous across a continent, and the client will convert
-- into them. This is what makes a cross-zone distance possible where the old
-- code simply gave up and charged a flat penalty.
-- MEMOISED, and safely so: a map coordinate's world position is a property of
-- the world, not of the player, so it cannot go stale. The conversion is a
-- client call with a table allocation on either side of it, and costing a
-- journey needs four of them -- which the quest provider then does once per
-- candidate.
--
-- Bounded rather than unbounded: a long session touches a lot of points, and a
-- cache with no ceiling is a memory leak with good intentions.
local worldPoints = {}
local worldPointCount = 0

Travel.worldPointCap = 2048

function Travel.ForgetWorldPoints()
    worldPoints = {}
    worldPointCount = 0
end

function Travel.WorldPoint(mapID, x, y)
    if not (mapID and x and y) then
        return nil
    end

    -- Rounded to about a yard on any map. Finer than that is precision the
    -- callers do not use and cache entries nothing will ever hit again.
    local key = mapID .. ":" .. math.floor(x * 10000) .. ":" .. math.floor(y * 10000)

    local cached = worldPoints[key]

    if cached ~= nil then
        if cached == false then
            return nil
        end

        return cached
    end

    if not C_Map or not C_Map.GetWorldPosFromMapPos or not CreateVector2D then
        return nil
    end

    local ok, continentID, position =
        pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

    if not ok or not position then
        -- NOT cached as a miss: during a loading screen the client refuses
        -- every conversion, and remembering that would poison the cache for
        -- the rest of the session.
        return nil
    end

    local wx, wy

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            wx, wy = gx, gy
        end
    end

    wx = wx or position.x
    wy = wy or position.y

    if not wx or not wy then
        return nil
    end

    local point = { continent = continentID, x = wx, y = wy }

    if worldPointCount >= Travel.worldPointCap then
        Travel.ForgetWorldPoints()
    end

    worldPoints[key] = point
    worldPointCount  = worldPointCount + 1

    return point
end

-- Yards between two world points, or nil when they are not on the same
-- continent -- in which case the straight-line number would be meaningless
-- rather than merely imprecise.
function Travel.YardsBetweenPoints(from, to)
    if not from or not to then
        return nil
    end

    if from.continent and to.continent and from.continent ~= to.continent then
        return nil
    end

    local dx = to.x - from.x
    local dy = to.y - from.y

    return math.sqrt((dx * dx) + (dy * dy))
end

-- The headline: distance between two points that may be on different maps.
function Travel.YardsBetween(fromMapID, fromX, fromY, toMapID, toX, toY)
    return Travel.YardsBetweenPoints(
        Travel.WorldPoint(fromMapID, fromX, fromY),
        Travel.WorldPoint(toMapID, toX, toY))
end

------------------------------------------------------------
-- FLIGHT POINTS
------------------------------------------------------------

-- The continent a map belongs to. Taxi nodes are listed per continent, and a
-- zone map will not answer for them.
function Travel.ContinentFor(mapID)
    local guard = 0

    while mapID and guard < 12 do
        local info = Blizzard.GetMapInfo(mapID)

        if not info then
            return nil
        end

        -- Enum.UIMapType.Continent == 2.
        if info.mapType == 2 then
            return mapID
        end

        mapID = info.parentMapID

        guard = guard + 1
    end

    return nil
end

-- Cached per continent. The set of flight points you know changes only when
-- you discover one, which is rare and which the client announces.
local nodeCache = {}

-- THE DISTANCE BETWEEN TWO FLIGHT POINTS DOES NOT CHANGE.
--
-- The pair search below tries every origin against every arrival, which is
-- the right search -- nearest-to-you and nearest-to-target are frequently not
-- the best route together. What was wrong was recomputing the flight leg of
-- every pair on every journey estimate.
--
-- It was invisible for the same reason the appearance-set scan was: the
-- fixture had three flight points in it. A levelled character has sixty on a
-- continent, and sixty squared is three and a half thousand distance
-- computations for one objective's travel cost. Measured with a realistic
-- fixture, a single estimate cost 1.5 ms and a cold rebuild 11.4.
--
-- Two nodes do not move relative to each other, so this is computed once per
-- continent and thrown away with the node list.
local spanCache = {}

-- The flight network, and the shortest way through it. See THE NETWORK below.
local neighbourCache = {}
local pathCache      = {}

function Travel.ForgetNodes()
    nodeCache      = {}
    spanCache      = {}
    neighbourCache = {}
    pathCache      = {}
end

-- Only nodes you can actually use. An undiscovered flight master is not a
-- shortcut, and costing a journey through one would produce a plan you cannot
-- follow -- which is worse than a pessimistic plan you can.
local function IsUsable(node)
    if not node then
        return false
    end

    if not Enum or not Enum.FlightPathState then
        -- Unknown enum: trust the client's list rather than dropping
        -- everything, and let the distance maths decide.
        return true
    end

    return node.state == Enum.FlightPathState.Current
        or node.state == Enum.FlightPathState.Reachable
end

function Travel.KnownNodes(mapID)
    local continent = Travel.ContinentFor(mapID)

    if not continent then
        return {}, nil
    end

    if nodeCache[continent] then
        return nodeCache[continent], continent
    end

    if not C_TaxiMap or not C_TaxiMap.GetAllTaxiNodes then
        return {}, continent
    end

    local ok, nodes = pcall(C_TaxiMap.GetAllTaxiNodes, continent)

    if not ok or type(nodes) ~= "table" then
        return {}, continent
    end

    local usable = {}

    for _, node in ipairs(nodes) do
        if IsUsable(node) and node.position then
            local nx, ny

            if node.position.GetXY then
                local gotXY, gx, gy = pcall(node.position.GetXY, node.position)

                if gotXY then
                    nx, ny = gx, gy
                end
            end

            nx = nx or node.position.x
            ny = ny or node.position.y

            local point = nx and Travel.WorldPoint(continent, nx, ny)

            if point then
                table.insert(usable, {
                    name  = node.name,
                    id    = node.nodeID,
                    point = point,
                })
            end
        end
    end

    -- AN EMPTY LIST IS NOT AN ANSWER, SO IT IS NOT REMEMBERED.
    --
    -- `C_TaxiMap.GetAllTaxiNodes` answers usefully only while the client has
    -- the taxi map's data to hand, and every node here needs
    -- `Travel.WorldPoint`, which refuses during a loading screen. The one
    -- event that clears this cache -- PLAYER_ENTERING_WORLD -- is a loading
    -- screen, so the very next query was the one most likely to get nothing.
    --
    -- Caching that nothing meant every flight-based estimate on the continent
    -- degraded to "run there" for the rest of the session. `Travel.WorldPoint`
    -- and `Navigation.MapScale` both already refuse to remember a miss, with
    -- comments saying why; this derived list did it anyway.
    if #usable > 0 then
        nodeCache[continent] = usable
    end

    return usable, continent
end

-- The flight leg of every pair, computed once. Indexed by position in the
-- node list rather than by node id, because the list is what the search
-- walks and an integer index costs nothing to look up.
local function Spans(continent, nodes)
    if spanCache[continent] then
        return spanCache[continent]
    end

    local spans = {}

    for i = 1, #nodes do
        spans[i] = {}

        for j = 1, #nodes do
            if i ~= j then
                spans[i][j] =
                    Travel.YardsBetweenPoints(nodes[i].point, nodes[j].point)
            end
        end
    end

    spanCache[continent] = spans

    return spans
end

------------------------------------------------------------
-- THE NETWORK
------------------------------------------------------------

-- A FLIGHT IS NOT A STRAIGHT LINE, AND SOME JOURNEYS NEED TWO HOPS.
--
-- Until now the flight leg of a route was the straight-line distance between
-- the two flight points, which is the one distance a taxi never travels. The
-- network is a graph: the bird hops from master to master, and a pair at
-- opposite ends of a continent is reached by going through the ones in
-- between. Measuring the hypotenuse understated every long flight -- always
-- in the same direction, so the addon systematically recommended distant
-- objectives over near ones.
--
-- It also let the addon cost a pairing that does not connect at all. An
-- island node with no route to the mainland was quoted as a short flight
-- because the two points happen to be close together on the map.
--
-- The client does not publish the edge list -- `GetAllTaxiNodes` gives
-- positions and reachability, not who connects to whom -- so the edges are
-- inferred: a flight master connects to the ones near it, plus its nearest
-- few regardless of distance so that a sparse region is not cut off from the
-- rest of the continent. That is a model, and it is marked as one: a
-- multi-hop estimate is never reported as confident.
--
-- What it is not is a guess in the direction of optimism. Every path length
-- this produces is at least the straight line it replaces, so the estimate
-- moved from "certainly too short" to "approximately right".
Travel.hopYards = 4000

-- Plus the nearest few whatever the distance, so that a lone outpost still
-- joins the graph rather than becoming unreachable and silently dropping out
-- of every route.
Travel.minimumNeighbours = 4

-- No real continent has a flight chain anywhere near this long. It exists so
-- that a malformed graph cannot spin a loop.
Travel.maximumHops = 32

local function Neighbours(continent, nodes)
    if neighbourCache[continent] then
        return neighbourCache[continent]
    end

    local spans = Spans(continent, nodes)
    local out   = {}

    for i = 1, #nodes do
        local ranked = {}

        for j = 1, #nodes do
            local yards = (i ~= j) and spans[i] and spans[i][j]

            if yards then
                table.insert(ranked, { index = j, yards = yards })
            end
        end

        -- Ties broken on index so the graph is the same graph every time it
        -- is built. A route that changes between two identical calls is not
        -- a route the player can be told about.
        table.sort(ranked, function(a, b)
            if a.yards == b.yards then
                return a.index < b.index
            end

            return a.yards < b.yards
        end)

        local list = {}

        for rank, entry in ipairs(ranked) do
            if entry.yards <= Travel.hopYards
                or rank <= Travel.minimumNeighbours then

                table.insert(list, entry)
            else
                -- Ascending, so nothing further can qualify on either test.
                break
            end
        end

        out[i] = list
    end

    -- AND THE GRAPH IS UNDIRECTED, BECAUSE FLIGHT PATHS ARE.
    --
    -- Built one node at a time, `minimumNeighbours` is a rule about who each
    -- node reaches OUT to, and that is not the same as who reaches it. A lone
    -- outpost picks its four nearest and every one of them is close enough to
    -- fill its own four from the crowd nearby -- so the outpost had a way out
    -- and no way in, and Dijkstra from anywhere on the mainland simply never
    -- reached it. It vanished from every route, silently, which is the exact
    -- failure `minimumNeighbours` was written to prevent.
    for i = 1, #nodes do
        for _, edge in ipairs(out[i]) do
            local back    = out[edge.index]
            local present = false

            for _, other in ipairs(back) do
                if other.index == i then
                    present = true
                    break
                end
            end

            if not present then
                table.insert(back, { index = i, yards = edge.yards })
            end
        end
    end

    neighbourCache[continent] = out

    return out
end

-- Dijkstra from one flight point to every other, cached per origin.
--
-- Per origin rather than all-pairs: the search below prunes most origins
-- before it ever asks, and paying for a full Floyd-Warshall on sixty nodes at
-- the first estimate of a session would be a visible hitch for answers that
-- are mostly never needed. What is computed is kept, and thrown away with the
-- node list it was derived from.
local function ShortestFrom(continent, nodes, source)
    local cache = pathCache[continent]

    if not cache then
        cache = {}
        pathCache[continent] = cache
    end

    if cache[source] then
        return cache[source]
    end

    local neighbours = Neighbours(continent, nodes)
    local count      = #nodes
    local dist, prev, settled = {}, {}, {}

    dist[source] = 0

    for _ = 1, count do
        local pick, pickDist

        for index = 1, count do
            if not settled[index] and dist[index]
                and (not pickDist or dist[index] < pickDist) then

                pick, pickDist = index, dist[index]
            end
        end

        if not pick then
            -- Everything reachable has been settled. What is left is a
            -- separate component, and stays unreachable -- which is the
            -- honest answer for it.
            break
        end

        settled[pick] = true

        for _, edge in ipairs(neighbours[pick] or {}) do
            local through = pickDist + edge.yards

            if not dist[edge.index] or through < dist[edge.index] then
                dist[edge.index] = through
                prev[edge.index] = pick
            end
        end
    end

    local result = { dist = dist, prev = prev }

    cache[source] = result

    return result
end

-- The hops themselves, so `/cn travel` can print the chain rather than a
-- single number the player cannot check.
function Travel.LegsBetween(nodes, path, source, target)
    if not path or not path.dist or not path.dist[target] then
        return nil
    end

    local chain, at, guard = {}, target, 0

    while at and guard <= Travel.maximumHops do
        table.insert(chain, 1, at)

        if at == source then
            break
        end

        at    = path.prev[at]
        guard = guard + 1
    end

    if chain[1] ~= source then
        return nil
    end

    local legs = {}

    for step = 1, #chain - 1 do
        local a, b = chain[step], chain[step + 1]

        table.insert(legs, {
            from  = nodes[a] and nodes[a].name,
            to    = nodes[b] and nodes[b].name,
            yards = (path.dist[b] or 0) - (path.dist[a] or 0),
        })
    end

    return legs
end

-- Nearest known flight point to a world point, and how far it is.
function Travel.NearestNode(point, nodes)
    if not point then
        return nil, nil
    end

    local best, bestYards

    for _, node in ipairs(nodes or {}) do
        local yards = Travel.YardsBetweenPoints(point, node.point)

        if yards and (not bestYards or yards < bestYards) then
            best, bestYards = node, yards
        end
    end

    return best, bestYards
end

------------------------------------------------------------
-- HOW FAST YOU FLY
------------------------------------------------------------

-- MEASURED, not assumed. Flight-path speed differs by expansion and by
-- whether the route is a modern one, the client does not expose it, and
-- Session already discards taxi movement when learning running speed -- so
-- nothing in the addon knew this number at all.
--
-- Seeded with a figure that is in the right area so the feature does
-- something on day one, and flagged as unmeasured until the player has
-- actually flown, exactly as running speed is.
Travel.seededFlightSpeed = 25

-- The part of a flight that is not flying: talking to the flight master,
-- taking off, and landing. A constant rather than a measurement because it is
-- dominated by a fixed animation, and because the alternative -- timing the
-- gossip window -- would be measuring the player's reading speed.
Travel.flightOverheadSeconds = 20

-- Casting a teleport and loading the destination. A constant for the same
-- reason as the others: it is an animation and a loading screen, not
-- something worth instrumenting.
Travel.castSeconds = 15

Travel.speedSampleCap = 20

local function Samples()
    local account = CN.Account("flight")

    account.samples = account.samples or {}

    return account.samples
end

local flight = {
    point = nil,
    at    = nil,
    yards = 0,
    seconds = 0,
}

local function Median(values)
    if not values or #values == 0 then
        return nil
    end

    local sorted = {}

    for _, value in ipairs(values) do
        table.insert(sorted, value)
    end

    table.sort(sorted)

    local middle = math.floor(#sorted / 2)

    if #sorted % 2 == 1 then
        return sorted[middle + 1]
    end

    return (sorted[middle] + sorted[middle + 1]) / 2
end

-- Returns yards per second and whether it was measured.
function Travel.FlightSpeed()
    local measured = Median(Samples())

    if measured and measured > 0 then
        return measured, true
    end

    return Travel.seededFlightSpeed, false
end

function Travel.FlightSampleCount()
    return #Samples()
end

-- Called on a timer while the player is on a taxi. Accumulates distance and
-- time for the whole flight and records ONE sample when it ends, rather than
-- one per tick: a flight is a single observation of a constant speed, and
-- treating each tick as independent would let a long flight drown out every
-- other measurement.
function Travel.ObserveFlight()
    local onTaxi = UnitOnTaxi and UnitOnTaxi("player")

    local now = (GetTime and GetTime()) or 0

    if not onTaxi then
        if flight.at and flight.seconds > 10 and flight.yards > 100 then
            local speed = flight.yards / flight.seconds

            -- Sanity bounds. A loading screen or a zone change mid-flight can
            -- produce a figure no aircraft in this game achieves, and one bad
            -- sample in a median of twenty is survivable but pointless.
            if speed > 5 and speed < 200 then
                local samples = Samples()

                table.insert(samples, speed)

                while #samples > Travel.speedSampleCap do
                    table.remove(samples, 1)
                end

                DebugPrint(string.format(
                    "Flight speed sampled: %.1f yards/second over %.0f yards.",
                    speed, flight.yards))
            end
        end

        flight.point, flight.at = nil, nil
        flight.yards, flight.seconds = 0, 0

        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    if point and flight.point and flight.at then
        local yards = Travel.YardsBetweenPoints(flight.point, point)

        local elapsed = now - flight.at

        -- Crossing a continent boundary mid-flight yields nil, which is not a
        -- reason to throw the flight away -- just this interval.
        if yards and elapsed > 0 and elapsed < 10 then
            flight.yards   = flight.yards + yards
            flight.seconds = flight.seconds + elapsed
        end
    end

    flight.point, flight.at = point, now

    return true
end

------------------------------------------------------------
-- WHICH FLIGHTS ACTUALLY CONNECT
------------------------------------------------------------

-- THE ASSUMPTION THIS REPLACES.
--
-- The costing has assumed since 0.42.0 that any flight point on a continent
-- can reach any other. Mostly true, and wrong often enough to matter: routes
-- go through hubs, some connect only one way, and a few zones are served by a
-- single node that reaches almost nothing.
--
-- There is no API that answers "does A connect to B". There is, however, the
-- player, who takes flights -- and a flight taken is proof that its two ends
-- connect. So: watch, remember, and prefer a pair that is known to work over
-- one that is merely plausible.
--
-- Nothing is ever ruled OUT by this. A pair never observed is not a pair that
-- does not connect; it is a pair nobody has flown yet, and treating those as
-- impossible would make the model worse than the assumption it replaces.
local function Routes()
    return CN.Account("flightRoutes")
end

Travel.Routes = Routes

local function RouteKey(fromID, toID)
    if not fromID or not toID then
        return nil
    end

    -- Undirected: a flight path that carries you one way is evidence the two
    -- points are on the same network, which is what the costing needs.
    if fromID > toID then
        fromID, toID = toID, fromID
    end

    return fromID .. ":" .. toID
end

Travel.RouteKey = RouteKey

function Travel.NoteRoute(fromID, toID)
    local key = RouteKey(fromID, toID)

    if not key then
        return false
    end

    local routes = Routes()

    routes[key] = (routes[key] or 0) + 1

    return true
end

function Travel.IsKnownRoute(fromID, toID)
    local key = RouteKey(fromID, toID)

    return key ~= nil and (Routes()[key] or 0) > 0
end

-- How much a known pair is preferred. A multiplier on the estimate rather
-- than a hard filter, because an unobserved pair is unproven, not impossible
-- -- and a small preference is enough to break a tie between two routes of
-- similar length.
Travel.knownRouteBonus = 0.9

-- The flight the player is currently on, so its endpoints can be recorded
-- when it ends. Which node they left from is known at the moment they board:
-- it is the nearest one to where they were standing.
local boarding = nil

function Travel.NoteBoarding()
    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    local node = point and Travel.NearestNode(point, Travel.KnownNodes(mapID))

    boarding = node and node.id or nil

    return boarding
end

function Travel.NoteLanding()
    if not boarding then
        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    local node = point and Travel.NearestNode(point, Travel.KnownNodes(mapID))

    local landed = node and node.id

    local recorded = false

    if landed and landed ~= boarding then
        recorded = Travel.NoteRoute(boarding, landed)

        DebugPrint("Flight recorded: " .. boarding .. " to " .. landed .. ".")
    end

    boarding = nil

    return recorded
end

------------------------------------------------------------
-- FLYING YOURSELF
------------------------------------------------------------

-- Seconds spent mounting up and gaining height before any distance is
-- covered. A constant, like the flight master's overhead, and for the same
-- reason: it is an animation, not a measurement.
Travel.takeoffSeconds = 6

-- Whether the player can fly to the destination.
--
-- Two separate questions, and both have to be yes: does this character fly at
-- all, and does the game allow it where they are going. `IsFlyableArea`
-- answers for where the player IS, which is the honest approximation
-- available -- the client will not answer for a zone the player is not in, so
-- a cross-zone claim is checked at the near end and re-checked when they get
-- there.
-- Which zones the player has actually been able to fly in.
--
-- `IsFlyableArea` answers for where the player IS STANDING, and there is no
-- API that answers for anywhere else -- so a cross-zone claim was being made
-- from the near end and could be wrong at the far end. Remembering the answer
-- per zone, as it is observed, turns that guess into evidence: a zone the
-- player has flown in is flyable, and one they have been in and could not fly
-- in is not.
local function FlightMemory()
    return CN.Account("flyableZones")
end

Travel.FlightMemory = FlightMemory

function Travel.NoteFlyable(mapID)
    if not mapID or not IsFlyableArea then
        return nil
    end

    local ok, flyable = pcall(IsFlyableArea)

    if not ok then
        return nil
    end

    FlightMemory()[mapID] = flyable and true or false

    return flyable
end

function Travel.CanFly(mapID)
    if not Travel.HasFlying() then
        return false
    end

    -- What is REMEMBERED about the destination beats what is true where the
    -- player happens to be standing.
    local remembered = mapID and FlightMemory()[mapID]

    if remembered == false then
        return false
    end

    if remembered ~= true and IsFlyableArea and not IsFlyableArea() then
        -- Nothing remembered, and flight is disabled here. The conservative
        -- answer is the one the player can definitely follow.
        return false
    end

    -- Same continent only; crossing one is handled above.
    local continent = Travel.ContinentFor(mapID)

    return continent ~= nil
end

-- Has this character ever actually flown? Measured, not assumed: the client
-- exposes no reliable "can you fly here" for an arbitrary map, and skyriding
-- availability changes with expansion, level and campaign progress. A
-- character with flying samples has flown; one without has not, and the
-- addon does not offer them a route they may not be able to take.
function Travel.HasFlying()
    local session = CN:GetModule("Session")

    if not session or not session.SpeedSampleCount then
        return false
    end

    return session.SpeedSampleCount("flying") >= (session.minSamples or 3)
end

-- Yards per second flying yourself, from the player's own measurements.
function Travel.SelfFlightSpeed()
    local session = CN:GetModule("Session")

    if not session or not session.Speed then
        return Travel.seededFlightSpeed, false
    end

    return session.Speed("flying")
end

------------------------------------------------------------
-- HEARTHSTONES, PORTALS AND TELEPORTS
------------------------------------------------------------

-- WHAT THIS IS AND IS NOT.
--
-- It is a list of ways off this continent that the player DEMONSTRABLY has:
-- an item in their bags, or a spell they know. Each one is reported with the
-- cooldown the client gives, so "your hearthstone is ready" and "your
-- hearthstone is on a 40 minute cooldown" are different answers.
--
-- It is NOT a routing model. The addon does not know where a hearthstone is
-- bound in map terms -- `GetBindLocation` returns a name, and names do not
-- convert to map ids -- so no duration is claimed and none is folded into any
-- score. Naming the option is useful; costing it would be fiction.
-- WHERE A TELEPORT ACTUALLY GOES.
--
-- The client will not convert a hearthstone's bind location into a map, and
-- it will not tell you where a mage portal leads either. Both are knowable
-- facts about the game rather than about the player, so they are curated
-- here -- which is the same argument that put quest locations in Data.
--
-- `mapID` is the ZONE the teleport lands in. Where it is nil, the option is
-- still listed and simply cannot be costed; naming a shortcut you have is
-- useful even when the addon cannot price it.
-- WHERE EACH ONE PUTS YOU DOWN.
--
-- A cross-continent journey can only be costed through a teleport whose
-- destination is known, and eight of these fourteen carried no destination at
-- all -- including the hearthstone, which is the one every player has. So a
-- non-mage asking about another continent got a list of what they own and no
-- duration whatsoever, which is the state this whole branch was built to
-- replace.
--
-- Three of them genuinely cannot be pinned, and are marked rather than given
-- a plausible-looking false landing:
--
--   * The hearthstone and Astral Recall go wherever the player set them. The
--     client reports that as a zone NAME, and this addon has no name-to-map
--     index -- building one means walking the whole map tree, which is a
--     client call per zone for a fact that is worth less than its cost. They
--     are still listed as available; they are not costed.
--   * The Flight Master's Whistle lands at the nearest flight point in the
--     zone you are already standing in. It is not a cross-continent option at
--     all.
--
-- The other eleven are fixed locations and are simply written down. Five of
-- them had no destination for no better reason than that nobody had filled
-- it in, which is why a non-mage got no cross-continent number at all.
Travel.teleports = {
    { kind = "item",  id = 6948,   label = "Hearthstone", bindPoint = true },

    { kind = "item",  id = 110560, label = "Garrison Hearthstone",
      -- Two garrisons, one per faction, and the client will not say which
      -- without reading the player's own garrison data. Draenor is the
      -- continent either way, which is what a cross-continent estimate needs.
      mapID = 590 },

    { kind = "item",  id = 140192, label = "Dalaran Hearthstone", mapID = 627 },

    -- Not a destination: it lands you at the nearest flight point in the zone
    -- you are already in.
    { kind = "item",  id = 141605, label = "Flight Master's Whistle",
      local_ = true },

    { kind = "spell", id = 556,    label = "Astral Recall", bindPoint = true },
    { kind = "spell", id = 3565,   label = "Teleport: Darnassus",     mapID = 89 },
    { kind = "spell", id = 3562,   label = "Teleport: Ironforge",     mapID = 87 },
    { kind = "spell", id = 3561,   label = "Teleport: Stormwind",     mapID = 84 },
    { kind = "spell", id = 3567,   label = "Teleport: Orgrimmar",     mapID = 85 },
    { kind = "spell", id = 3563,   label = "Teleport: Undercity",     mapID = 90 },
    { kind = "spell", id = 3566,   label = "Teleport: Thunder Bluff", mapID = 88 },
    { kind = "spell", id = 18960,  label = "Teleport: Moonglade",     mapID = 80 },
    { kind = "spell", id = 50977,  label = "Death Gate",              mapID = 118 },
    { kind = "spell", id = 126892, label = "Zen Pilgrimage",          mapID = 809 },
}


local function ItemCooldown(itemID)
    local count = 0

    if C_Item and C_Item.GetItemCount then
        count = C_Item.GetItemCount(itemID) or 0
    elseif GetItemCount then
        count = GetItemCount(itemID) or 0
    end

    if count <= 0 then
        return nil
    end

    local start, duration

    if C_Item and C_Item.GetItemCooldown then
        start, duration = C_Item.GetItemCooldown(itemID)
    elseif GetItemCooldown then
        start, duration = GetItemCooldown(itemID)
    end

    if not start or not duration or duration == 0 then
        return 0
    end

    local remaining = (start + duration) - ((GetTime and GetTime()) or 0)

    return math.max(0, remaining)
end

local function SpellCooldown(spellID)
    local known = false

    if IsSpellKnown then
        local ok, result = pcall(IsSpellKnown, spellID)

        known = ok and result
    end

    if not known and IsPlayerSpell then
        local ok, result = pcall(IsPlayerSpell, spellID)

        known = ok and result
    end

    if not known then
        return nil
    end

    local start, duration

    if C_Spell and C_Spell.GetSpellCooldown then
        local info = C_Spell.GetSpellCooldown(spellID)

        if type(info) == "table" then
            start, duration = info.startTime, info.duration
        end
    elseif GetSpellCooldown then
        start, duration = GetSpellCooldown(spellID)
    end

    if not start or not duration or duration == 0 then
        return 0
    end

    local remaining = (start + duration) - ((GetTime and GetTime()) or 0)

    return math.max(0, remaining)
end

-- Every teleport this character has, with seconds of cooldown remaining.
-- Ready ones first, because that is the order they are useful in.
function Travel.ReadyTeleports()
    local available = {}

    for _, entry in ipairs(Travel.teleports) do
        local remaining

        if entry.kind == "item" then
            remaining = ItemCooldown(entry.id)
        else
            remaining = SpellCooldown(entry.id)
        end

        if remaining then
            table.insert(available, {
                label     = entry.label,
                kind      = entry.kind,
                id        = entry.id,
                mapID     = entry.mapID,
                remaining = remaining,
                ready     = remaining <= 0,
                -- Where a hearthstone actually goes. A name, because that is
                -- all the client offers; deliberately not turned into a map.
                bound     = (entry.id == 6948 and GetBindLocation)
                    and GetBindLocation() or nil,
            })
        end
    end

    table.sort(available, function(a, b)
        if a.ready ~= b.ready then
            return a.ready
        end

        return a.remaining < b.remaining
    end)

    return available
end

------------------------------------------------------------
-- THE ESTIMATE
------------------------------------------------------------

-- Returns seconds, confident, detail.
--
-- detail = { mode = "run"|"fly", yards, runToNode, flightYards, runFromNode,
--            node, arrival }
function Travel.EstimateSeconds(fromMapID, fromX, fromY, toMapID, toX, toY)
    local from = Travel.WorldPoint(fromMapID, fromX, fromY)
    local to   = Travel.WorldPoint(toMapID, toX, toY)

    if not from or not to then
        return nil, false, nil
    end

    if from.continent and to.continent and from.continent ~= to.continent then
        -- ANOTHER CONTINENT.
        --
        -- Still no duration: portal networks and boat schedules are not
        -- modelled and a fabricated number would be worse than an admission.
        -- But "I cannot cost this" and "there is no way to do it" are
        -- different statements, and until 0.43.0 the addon made the first and
        -- the player heard the second. So: say what is actually available.
        local teleports = Travel.ReadyTeleports()

        -- COSTED THROUGH A TELEPORT, WHERE ONE LANDS SOMEWHERE USEFUL.
        --
        -- Until 0.44.0 a cross-continent journey returned nothing at all,
        -- which is honest and unhelpful: the real answer is usually "hearth,
        -- then fly for ten seconds". Where a teleport has a known destination
        -- ON THE TARGET'S CONTINENT, the journey becomes castable: the
        -- teleport, plus the ordinary journey from where it drops you.
        --
        -- A teleport on cooldown is still offered, with the wait added --
        -- because "twenty minutes, then four" is a real answer and often the
        -- right one.
        local best

        for _, teleport in ipairs(teleports) do
            local landing = teleport.mapID and Travel.WorldPoint(teleport.mapID, 0.5, 0.5)

            if landing and landing.continent == to.continent then
                local onward, _, onwardDetail = Travel.EstimateSeconds(
                    teleport.mapID, 0.5, 0.5, toMapID, toX, toY)

                if onward then
                    local seconds = onward + Travel.castSeconds
                        + (teleport.ready and 0 or teleport.remaining)

                    if not best or seconds < best.seconds then
                        best = {
                            seconds   = seconds,
                            mode      = "teleport",
                            via       = teleport.label,
                            waited    = teleport.ready and 0 or teleport.remaining,
                            onward    = onward,
                            onwardMode = onwardDetail and onwardDetail.mode,
                        }
                    end
                end
            end
        end

        if best then
            -- Never confident: the onward leg is measured from the middle of
            -- the landing zone, because the addon does not know precisely
            -- where a teleport puts you down.
            best.teleports = teleports

            return best.seconds, false, best
        end

        return nil, false, {
            mode      = "elsewhere",
            teleports = teleports,
        }
    end

    local session = CN:GetModule("Session")

    -- THE SPEED OF RUNNING, NOT THE SPEED YOU HAPPEN TO BE MOVING.
    --
    -- `Speed()` with no argument answers for the bucket the player is in
    -- RIGHT NOW -- so asking it while airborne returned the skyriding median
    -- and used it to divide the "run the whole way" option and both walking
    -- legs of every flight-path route. A twenty-one thousand yard journey was
    -- quoted at six minutes, labelled `run`, and marked confident. The true
    -- figure on foot is fifty.
    --
    -- It also made the self-flown option unreachable while flying: dividing
    -- the same distance by the same number and then adding six seconds of
    -- takeoff can never win, so the mode this addon built a whole travel
    -- model around never appeared in the situation it was written for.
    --
    -- The ground speed is asked for by name. Which bucket the player is
    -- standing in is not a fact about how long it takes to walk somewhere.
    local runSpeed, runMeasured = 7, false

    if session and session.Speed then
        runSpeed, runMeasured = session.Speed(false)
    end

    runSpeed = math.max(0.5, runSpeed)

    local direct = Travel.YardsBetweenPoints(from, to)

    if not direct then
        return nil, false, nil
    end

    local best = {
        seconds = direct / runSpeed,
        mode    = "run",
        yards   = direct,
    }

    -- What the comparison uses, which is the duration for everything except a
    -- flight pair the player has flown before -- see the tie-break below.
    local bestRanking = best.seconds

    local confident = runMeasured

    -- SELF-FLYING (0.43.0).
    --
    -- In current content, flying yourself point to point usually beats both
    -- running and the flight network: no walk to a flight master, no
    -- overhead, and a straight line. Leaving it out meant the addon sent
    -- people to a flight master for journeys they would simply fly.
    --
    -- Only offered where the player can actually fly: a zone with flying
    -- disabled, or a character who has never flown, gets the ground answer.
    if Travel.CanFly(toMapID) then
        local flySpeed, flyMeasured = Travel.SelfFlightSpeed()

        local seconds = (direct / flySpeed) + Travel.takeoffSeconds

        if seconds < bestRanking then
            bestRanking = seconds

            best = {
                seconds = seconds,
                mode    = "self",
                yards   = direct,
            }

            confident = flyMeasured
        end
    end

    local nodes, continent = Travel.KnownNodes(toMapID)

    nodes = nodes or {}

    if #nodes >= 2 then
        -- THE BEST PAIR, NOT THE NEAREST AT EACH END.
        --
        -- Nearest-to-you and nearest-to-target are two independently sensible
        -- choices that together are often not the best route: a flight point
        -- slightly further from you can sit much closer to where you are
        -- going. The node count per continent is small enough to simply try
        -- every pairing, and that is still true -- what was not true was
        -- doing three distance computations inside each pairing.
        --
        -- REWRITTEN IN 0.46.0 with the same answers and a twentieth of the
        -- work. The two ends are each measured once per node instead of once
        -- per pair, the flight leg comes from a table computed once per
        -- continent, and the inner loop is arithmetic on numbers already in
        -- hand.
        local flightSpeed, flightMeasured = Travel.FlightSpeed()

        local originSeconds, arrivalSeconds = {}, {}

        -- The cheapest either end can possibly be. Used to abandon an origin
        -- whose walk alone already costs more than the best route found so
        -- far.
        local cheapestArrival

        -- AND THE MOST THE REST OF THE SUM CAN BE DISCOUNTED.
        --
        -- 0.46.0 wrote this bound and called it exact "because every remaining
        -- term of the sum is positive". Every term is -- but the sum is then
        -- MULTIPLIED by knownRouteBonus when the pair is a route the player
        -- has actually flown, and a discount is not a term. A bound that
        -- ignores it prunes origins whose true cost is up to a tenth below
        -- what the bound predicted, and the addon silently reports the
        -- second-best route.
        --
        -- The test that was supposed to catch this brute-forced the answer
        -- honestly and still missed it: no routes had been noted at that point
        -- in the run, so the discount branch was never live while the
        -- comparison ran. It would have bitten only players who had flown
        -- somewhere -- which is all of them, and none of the fixtures.
        local bestPossibleDiscount = math.min(1, Travel.knownRouteBonus or 1)

        for index, node in ipairs(nodes) do
            local originYards = Travel.YardsBetweenPoints(from, node.point)
            local arrivalYards = Travel.YardsBetweenPoints(to, node.point)

            originSeconds[index]  = originYards and (originYards / runSpeed)
            arrivalSeconds[index] = arrivalYards and (arrivalYards / runSpeed)

            if arrivalSeconds[index]
                and (not cheapestArrival or arrivalSeconds[index] < cheapestArrival) then

                cheapestArrival = arrivalSeconds[index]
            end
        end

        for i = 1, #nodes do
            local walkOut = originSeconds[i]

            -- Nothing beyond this point can be free, and nothing can be
            -- discounted further than a known route discounts it, so an
            -- origin whose best conceivable total already loses cannot win.
            if walkOut and cheapestArrival
                and (bestPossibleDiscount
                    * (walkOut + Travel.flightOverheadSeconds + cheapestArrival))
                    < bestRanking then

                local origin = nodes[i]

                -- THE WAY THE BIRD ACTUALLY GOES.
                --
                -- `spans` is still what the graph is built from, but the
                -- flight leg is now the shortest path through that graph
                -- rather than the straight line across it. A pair with no
                -- path between them has no entry and is not offered.
                local path = ShortestFrom(continent, nodes, i)

                for j = 1, #nodes do
                    local flightYards = (i ~= j) and path.dist[j] or nil
                    local walkIn      = arrivalSeconds[j]

                    if flightYards and walkIn then
                        local seconds = walkOut
                            + Travel.flightOverheadSeconds
                            + (flightYards / flightSpeed)
                            + walkIn

                        -- A pair the player has actually flown beats an
                        -- equivalent pair nobody has: same distance, one
                        -- of them proven to connect.
                        --
                        -- A TIE-BREAK, NOT A DISCOUNT. This used to multiply
                        -- `seconds` itself, so the duration reported to the
                        -- player was ten percent below the model's own
                        -- arithmetic -- `/cn travel` printed legs that summed
                        -- to fifty seconds more than its own headline -- and
                        -- that shortened number flowed into scoring and into
                        -- `/cn plan`'s budget. Every player has flown
                        -- somewhere, so this was the common case, not an
                        -- edge one.
                        --
                        -- The preference belongs in the comparison. The
                        -- seconds are the seconds.
                        local ranking = seconds

                        if Travel.IsKnownRoute(origin.id, nodes[j].id) then
                            ranking = ranking * Travel.knownRouteBonus
                        end

                        if ranking < bestRanking then
                            bestRanking = ranking

                            best = {
                                seconds     = seconds,
                                mode        = "fly",
                                yards       = direct,
                                runToNode   = walkOut * runSpeed,
                                flightYards = flightYards,
                                runFromNode = walkIn * runSpeed,
                                node        = origin.name,
                                arrival     = nodes[j].name,

                                -- The ids as well as the names, added in
                                -- 0.46.0: a name is what a player reads, and
                                -- an id is what anything downstream needs to
                                -- ask a further question about the route.
                                nodeID      = origin.id,
                                arrivalID   = nodes[j].id,

                                -- The chain itself. One entry means the
                                -- ordinary direct hop; more means the route
                                -- goes through flight masters in between,
                                -- and the player is told which.
                                legs        = Travel.LegsBetween(
                                                  nodes, path, i, j),
                            }

                            best.hops = best.legs and #best.legs or 1

                            -- A flight estimate is only as good as the
                            -- flight speed behind it -- and a multi-hop
                            -- route rests on an inferred edge list as well,
                            -- which is a model and not a measurement.
                            confident = runMeasured and flightMeasured
                                and best.hops <= 1
                        end
                    end
                end
            end
        end
    end

    return best.seconds, confident, best
end

-- The same answer on the scale the scorer uses, where roughly ten is "across
-- a zone". Kept as a separate function so the scoring scale and the human
-- number never drift apart: one is derived from the other.
Travel.secondsPerCostPoint = 30

-- Published, because Session has to remove from a measured duration exactly
-- what the planner will add back to it. One constant, one conversion.
CN.secondsPerCostPoint = Travel.secondsPerCostPoint
Travel.maximumCost         = 40

function Travel.CostFor(mapID, x, y)
    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    if not playerMap or not mapID or not x or not y then
        return nil
    end

    local seconds = Travel.EstimateSeconds(playerMap, playerX, playerY, mapID, x, y)

    if not seconds then
        return nil
    end

    return math.min(Travel.maximumCost, seconds / Travel.secondsPerCostPoint)
end

-- Published so providers do not each have to decide what to do when the
-- estimate is unavailable.
--
-- IT MUST NOT BE CHEAPER THAN A JOURNEY WE CAN ACTUALLY COST.
--
-- This was 25 while a costed journey saturates at `maximumCost = 40`, so
-- "I cannot work out how to get there" scored fifteen points BELOW the far
-- side of the zone the player is standing in -- and fifteen is nearly twice
-- the entire range of what finishing something is worth. Another continent,
-- unreachable and unmodelled, outranked a quest two minutes away.
--
-- An uncostable journey is the one we know least about; it has to be the
-- pessimistic answer, not the optimistic one.
CN.fallbackZoneCost = 40

function CN.TravelCost(mapID, x, y)
    local travel = CN:GetModule("Travel")

    local cost = travel and travel.CostFor(mapID, x, y)

    if cost then
        return cost, true
    end

    local playerMap = CN.GetPlayerPosition()

    if mapID and playerMap and mapID == playerMap then
        return CN.unknownLocationCost, false
    end

    if not mapID then
        return CN.unknownLocationCost, false
    end

    return CN.fallbackZoneCost, false
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

-- Short "how long until it is usable" text. Minutes and seconds, because a
-- cooldown the player is waiting on is measured in the units they are
-- counting in.
function Travel.FormatReset(seconds)
    if not seconds or seconds <= 0 then
        return "ready"
    end

    if seconds < 60 then
        return math.floor(seconds) .. "s"
    end

    if seconds < 3600 then
        return math.floor(seconds / 60) .. "m"
    end

    return string.format("%.1fh", seconds / 3600)
end

function Travel.Describe(detail, seconds, confident)
    if not seconds then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " travel time"
    end

    local session = CN:GetModule("Session")

    local text = session and session.FormatDuration
        and session.FormatDuration(seconds)
        or (math.floor(seconds / 60) .. " min")

    if detail and detail.mode == "self" then
        text = text .. " |cff999999flying yourself|r"
    end

    if detail and detail.mode == "teleport" then
        text = text .. " |cff999999via " .. tostring(detail.via)

        if (detail.waited or 0) > 0 then
            text = text .. ", after a " .. Travel.FormatReset(detail.waited)
                .. " cooldown"
        end

        text = text .. "|r"
    end

    if detail and detail.mode == "fly" and detail.node then
        text = text .. " |cff999999via " .. tostring(detail.node)
        if detail.arrival then
            text = text .. " to " .. tostring(detail.arrival)
        end
        text = text .. "|r"
    end

    -- One convention, defined in Core, used by everything that prints a
    -- number it is not certain of.
    return CN.WithConfidence(text, CN.ConfidenceFor(confident))
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- Discovering a flight point changes every cross-zone answer this module
-- gives, so the cache goes when it happens.
--
-- `NEW_TAXI_NODE` was in this list and is not an event. The client refuses to
-- register an unknown name -- it throws -- so every login since this line was
-- written produced a Lua error, and the two events either side of it were
-- registered anyway only because they come before and after in the loop. It
-- was invented, plausibly, and nothing ever checked.
--
-- There is no discovery event. TAXIMAP_OPENED is the honest substitute: you
-- discover a flight point by talking to the flight master, which opens the
-- map.
for _, event in ipairs({ "TAXIMAP_OPENED", "PLAYER_ENTERING_WORLD" }) do
    CN:RegisterEvent(event, function()
        Travel.ForgetNodes()

        CN.InvalidateCandidates()
    end)
end

-- WHERE THE FLYABILITY MEMORY IS ACTUALLY WRITTEN.
--
-- `Travel.NoteFlyable` was written in 0.43.0 with a block comment explaining
-- that remembering the answer per zone "turns that guess into evidence", and
-- then nothing ever called it. The store stayed empty for four releases, so
-- `Travel.CanFly` always fell through to `IsFlyableArea()` -- which answers
-- for where the player is STANDING -- and that is precisely the guess the
-- comment claims was replaced. Every self-flown route estimate to another
-- zone rested on it.
--
-- The test suite could not see it because the harness wrote the store
-- directly, bypassing the producer: populated in test, permanently empty in
-- game.
--
-- Observed on arrival, which is the only moment the client will answer
-- honestly about a zone.
local function NoteWhereWeAre()
    local mapID = CN.GetPlayerPosition()

    if mapID then
        pcall(Travel.NoteFlyable, mapID)
    end
end

for _, event in ipairs({ "ZONE_CHANGED_NEW_AREA", "PLAYER_ENTERING_WORLD" }) do
    CN:RegisterEvent(event, NoteWhereWeAre)
end

-- And whenever the player is demonstrably flying, which is evidence that
-- outranks anything the client says about the area: you cannot be flying
-- somewhere flight is disabled.
CN:RegisterEvent("PLAYER_CONTROL_GAINED", function()
    if IsFlying and select(1, pcall(IsFlying)) then
        local flying = select(2, pcall(IsFlying))

        if flying then
            local mapID = CN.GetPlayerPosition()

            if mapID then
                FlightMemory()[mapID] = true
            end
        end
    end
end)

-- Sampling the flight only while there is a flight to sample.
local ticker

Travel.tickSeconds = 1

CN:RegisterEvent("PLAYER_CONTROL_LOST", function()
    -- Losing control is the moment a flight starts. Record where from.
    pcall(Travel.NoteBoarding)

    if ticker or not C_Timer or not C_Timer.NewTicker then
        return
    end

    ticker = C_Timer.NewTicker(Travel.tickSeconds, function()
        local flying = Travel.ObserveFlight()

        if not flying and ticker then
            -- The flight has ended: record which two points it joined.
            pcall(Travel.NoteLanding)

            ticker:Cancel()
            ticker = nil
        end
    end)
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "travel",
    order   = 26,
    help    = "How long it takes to reach the top recommendation, and how.",
    handler = function()
        local nodes, continent = Travel.KnownNodes(CN.GetPlayerPosition())

        local speed, measured = Travel.FlightSpeed()

        Print(string.format("Flight points known on this continent: %d", #nodes))
        Print(string.format("Flight speed: %.1f yards/second %s",
            speed, measured
                and ("|cff999999from " .. Travel.FlightSampleCount()
                    .. " of your own flights|r")
                or (CN.WithConfidence("", CN.confidence.ESTIMATED)
                    .. " |cff999999-- take a flight path and it will be "
                    .. "measured|r")))

        if not continent then
            Print("|cff999999The client will not say which continent this is.|r")
        end

        local results = CN.Recommend(1)

        local target = results and results[1]

        if not target or not target.mapID or not target.x then
            Print("|cff999999Nothing with a location is being recommended, so "
                .. "there is nothing to cost.|r")
            return
        end

        local playerMap, playerX, playerY = CN.GetPlayerPosition()

        local seconds, confident, detail = Travel.EstimateSeconds(
            playerMap, playerX, playerY, target.mapID, target.x, target.y)

        Print("To " .. tostring(target.name) .. ": "
            .. Travel.Describe(detail, seconds, confident))

        if detail and detail.mode == "fly" then
            local session = CN:GetModule("Session")

            local runSpeed = session and session.Speed() or 7

            Print(string.format(
                "  |cff999999%.0f yd to %s, %.0f yd in the air, %.0f yd at the "
                .. "far end -- against %.0f yd on foot|r",
                detail.runToNode, tostring(detail.node), detail.flightYards,
                detail.runFromNode, detail.yards))

            -- THE CHAIN, NOT JUST ITS ENDS.
            --
            -- A two-hop route printed as a single "in the air" figure looks
            -- like a straight line the player can check against the map and
            -- find wrong. Printed as its legs it is checkable, which is the
            -- point of the whole breakdown.
            local legs = detail.legs or {}

            if #legs > 1 then
                Print(string.format("  |cff999999%d legs:|r", #legs))

                for index, leg in ipairs(legs) do
                    Print(string.format("    |cff999999%d. %s to %s, %.0f yd|r",
                        index, tostring(leg.from), tostring(leg.to),
                        leg.yards or 0))
                end
            end

            Print(string.format("  |cff999999running the whole way: %s|r",
                session and session.FormatDuration
                    and session.FormatDuration(detail.yards / math.max(0.5, runSpeed))
                    or "unknown"))
        elseif detail and detail.mode == "self" then
            local flySpeed, flyMeasured = Travel.SelfFlightSpeed()

            Print(string.format(
                "  |cff999999%.0f yd direct at %.0f yd/s%s|r",
                detail.yards, flySpeed,
                flyMeasured and ""
                    or (" " .. CN.WithConfidence("",
                        CN.confidence.ESTIMATED))))
        elseif detail and detail.mode == "elsewhere" then
            Print("|cff999999That is on another continent. Portals and boats "
                .. "are not modelled, so no time is claimed -- but here is "
                .. "what you have:|r")

            local teleports = detail.teleports or {}

            if #teleports == 0 then
                Print("  |cff999999no hearthstone or teleport available|r")
            end

            for index, teleport in ipairs(teleports) do
                if index > 5 then
                    break
                end

                local line = "  " .. teleport.label

                if teleport.bound then
                    line = line .. " |cff999999to " .. teleport.bound .. "|r"
                end

                if teleport.ready then
                    line = line .. " |cff73b873ready|r"
                else
                    line = line .. " |cfff56b61"
                        .. Travel.FormatReset(teleport.remaining) .. "|r"
                end

                Print(line)
            end
        end
    end,
}

return Travel
'@

$Embedded['Modules\Instances.lua'] = @'
-- Modules/Instances.lua
-- Completion Navigator :: dungeons and raids, which the addon could not see.
--
-- WHAT WAS MISSING.
--
-- Until now this addon knew everything about the open world and nothing about
-- the inside of a dungeon. A mount that drops from a raid boss was a line of
-- free text out of the mount journal: no boss, no instance, no difficulty, no
-- idea whether you had already killed the thing this week. `/cn chase` on such
-- a mount produced a goal with no path to it, which is the one thing this
-- addon is supposed to never do.
--
-- Worse, lockouts are the strongest deadline in the game -- stronger than a
-- daily, because a missed raid week is gone for a week rather than a day --
-- and the ranking could not see them at all, so a world quest expiring in an
-- hour outranked a raid you were six bosses into with two days left on it.
--
-- WHAT THIS DOES NOT DO.
--
-- It does not queue for anything, invite anyone, or set foot in an instance.
-- It reads three things and reports them: what you are locked to, which
-- bosses in that lockout are still alive, and where a given drop comes from.
--
-- AND WHAT IT REFUSES TO STORE.
--
-- Nothing. A lockout expires, the client always knows it, and a stale copy is
-- worse than none: "6 of 8 down in there" is actively wrong advice the moment
-- the reset it never heard about happens. The same goes for loot tables,
-- which change with patches. Everything here is read live and cached in
-- memory for the session at most.

local ADDON_NAME, CN = ...

local Instances = CN:RegisterModule("Instances")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- LOCKOUTS
------------------------------------------------------------

-- An unfinished lockout is the cheapest progress in the game: the bosses you
-- already killed stay dead, so the remaining ones cost a fraction of a fresh
-- clear. A finished one is worth nothing until it resets. That difference is
-- the entire reason this module scores anything.
function Instances.Lockouts()
    local raw = Blizzard.GetSavedInstances()

    local lockouts = {}

    for _, saved in ipairs(raw) do
        -- An expired lockout is still listed for a while. Anything with no
        -- time left on it is not a lockout, it is a memory.
        if not saved.reset or saved.reset > 0 then
            local encounters = saved.encounters or 0
            local defeated   = saved.defeated or 0

            table.insert(lockouts, {
                name         = saved.name,

                -- Two ids, deliberately both carried and deliberately named
                -- differently: `id` is the lockout save, `instanceID` is the
                -- Encounter Journal's. Handing the first to the journal is
                -- the defect this pair exists to make impossible.
                id           = saved.id,
                instanceID   = saved.instanceID,
                difficulty   = saved.difficulty,
                difficultyID = saved.difficultyID,
                raid         = saved.raid,
                defeated     = defeated,
                encounters   = encounters,
                remaining    = math.max(0, encounters - defeated),
                resetsIn     = saved.reset,
                extended     = saved.extended,
                complete     = encounters > 0 and defeated >= encounters,
            })
        end
    end

    table.sort(lockouts, function(a, b)
        -- Most nearly finished first: that is the order they are worth doing.
        if a.complete ~= b.complete then
            return b.complete
        end

        if a.remaining ~= b.remaining then
            return a.remaining < b.remaining
        end

        return (a.resetsIn or math.huge) < (b.resetsIn or math.huge)
    end)

    return lockouts
end

function Instances.Summary()
    local lockouts = Instances.Lockouts()

    local summary = {
        total      = #lockouts,
        unfinished = 0,
        soonest    = nil,
        bosses     = 0,
    }

    for _, lockout in ipairs(lockouts) do
        if not lockout.complete then
            summary.unfinished = summary.unfinished + 1
            summary.bosses     = summary.bosses + lockout.remaining

            if not summary.soonest
                or (lockout.resetsIn or math.huge) < (summary.soonest.resetsIn or math.huge) then
                summary.soonest = lockout
            end
        end
    end

    return summary
end

-- WHICH bosses are still alive in a lockout the player is part-way through.
--
-- The client reports a count, not a list, so the names come from the
-- Adventure Guide and the state comes from the count. Where the two cannot be
-- reconciled -- a boss killed out of order, which is normal -- this says how
-- many are left rather than inventing which ones. An invented name is worse
-- than a number.
function Instances.RemainingBosses(lockout)
    if not lockout or lockout.remaining <= 0 then
        return {}, nil
    end

    if not lockout.id then
        return {}, "the client did not name this instance"
    end

    -- The JOURNAL's id, not the lockout id. See GetSavedInstances.
    if not lockout.instanceID then
        return {}, "the client did not give an Adventure Guide id for this "
            .. "instance"
    end

    local encounters = Blizzard.GetInstanceEncounters(lockout.instanceID)

    if #encounters == 0 then
        return {}, "the Adventure Guide has no boss list for this instance"
    end

    -- Only when nothing has been killed can each boss be named with
    -- confidence. Past that, the client tells us how many, not which.
    if lockout.defeated == 0 then
        return encounters, nil
    end

    return {}, lockout.remaining .. " of " .. lockout.encounters
        .. " still up (the client does not say which)"
end

------------------------------------------------------------
-- WHERE DOES IT DROP
------------------------------------------------------------

-- Answers for a name rather than an ID, because that is what the collection
-- journals hand us, and because the Adventure Guide's own search works that
-- way. Cached for the session: the answer does not change until a patch does,
-- and the search is not free.
local dropCache = {}

function Instances.ForgetDrops()
    dropCache = {}
end

function Instances.WhereDoesItDrop(name)
    if type(name) ~= "string" or name == "" then
        return {}
    end

    local cached = dropCache[name]

    if cached then
        return cached
    end

    local results = Blizzard.SearchEncounterJournal(name, 6)

    -- A ZERO IS "NOT YET", NOT "NOTHING".
    --
    -- The journal's search is asynchronous, so the first query for a name
    -- reliably returns nothing. Caching that made the emptiness permanent for
    -- the session: every later ask returned the memoised zero and the search
    -- that had by then completed was never read.
    --
    -- Only an answer is remembered. The cost of asking again is one search
    -- the player triggered themselves.
    if #results > 0 then
        dropCache[name] = results
    end

    return results
end

-- The one-line version, for a tooltip or a chase step.
function Instances.DescribeSource(name)
    local results = Instances.WhereDoesItDrop(name)

    if #results == 0 then
        return nil
    end

    local first = results[1]

    local text = tostring(first.encounter or "a boss")

    if first.instance then
        text = text .. " in " .. first.instance
    end

    -- THE DIFFICULTY THIS REPORTED WAS NOT THE DROP'S.
    --
    -- It came from `EJ_GetDifficulty()`, which answers with the difficulty
    -- the Encounter Journal happens to be SET to -- a window the player may
    -- have opened once and left on Normal. So a Mythic-only mount was
    -- confidently labelled "Normal", and the sentence below explaining why
    -- that distinction matters made the wrong label worse: it told the reader
    -- to trust it.
    --
    -- A mount that only drops on Mythic is indeed a different plan from one
    -- that drops on Normal -- which is exactly why a guess is not good enough
    -- here. The client offers no per-item difficulty, so the label is now
    -- shown only when the journal's setting is genuinely what was queried,
    -- and is named as such rather than presented as a property of the drop.
    if first.difficulty then
        text = text .. " |cff999999(searched on " .. first.difficulty .. ")|r"
    end

    if #results > 1 then
        text = text .. " (and " .. (#results - 1) .. " other "
            .. (#results == 2 and "encounter" or "encounters") .. ")"
    end

    return text, first
end

-- Is the player locked to the instance a drop comes from? This is the
-- difference between "go and kill it" and "not until Tuesday".
function Instances.LockoutFor(instanceName)
    if not instanceName then
        return nil
    end

    for _, lockout in ipairs(Instances.Lockouts()) do
        if lockout.name == instanceName then
            return lockout
        end
    end

    return nil
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

function Instances.FormatReset(seconds)
    local vault = CN:GetModule("Vault")

    if vault and vault.FormatReset then
        return vault.FormatReset(seconds)
    end

    if not seconds then
        return "unknown"
    end

    return math.max(1, math.floor(seconds / 3600)) .. "h"
end

function Instances.Describe(lockout)
    local text = lockout.name

    if lockout.difficulty then
        text = text .. " |cff999999(" .. lockout.difficulty .. ")|r"
    end

    if lockout.encounters > 0 then
        text = text .. ": " .. lockout.defeated .. " of " .. lockout.encounters
    end

    if lockout.complete then
        return text .. " |cff00ff00cleared|r"
    end

    return text .. " |cffffff00" .. lockout.remaining .. " left|r"
        .. " |cff999999resets in " .. Instances.FormatReset(lockout.resetsIn) .. "|r"
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- How near the reset the lockout has to be, and how few bosses have to be
-- left, before an unfinished lockout is a next action rather than a plan for
-- the week. Same shape as the Vault's rule, and for the same reason.
Instances.maxRemaining = 6

local function Urgency(remaining, resetsIn, defeated)
    local value = 0

    -- Already started is the whole point: those kills are spent effort that
    -- expires. Nothing started is just "a dungeon exists".
    if defeated and defeated > 0 then
        value = value + 2
    end

    if remaining then
        if remaining <= 1 then
            value = value + 3
        elseif remaining <= 3 then
            value = value + 2
        else
            value = value + 1
        end
    end

    if resetsIn then
        local days = resetsIn / 86400

        if days <= 1 then
            value = value + 3
        elseif days <= 2 then
            value = value + 2
        elseif days <= 4 then
            value = value + 1
        end
    end

    return value
end

Instances.Urgency = Urgency

CN.RegisterCandidateProvider("Instances", function()
    local candidates = {}

    for _, lockout in ipairs(Instances.Lockouts()) do
        -- A cleared lockout is not an objective, and a lockout nobody has
        -- started is a decision about the evening rather than a next action.
        if not lockout.complete
            and lockout.defeated > 0
            and lockout.remaining > 0
            and lockout.remaining <= Instances.maxRemaining
            and not CN.IsIgnored(CN.objectiveTypes.INSTANCE, lockout.name)
            and not CN.IsDeferred(CN.objectiveTypes.INSTANCE, lockout.name) then

            local reasons = {
                lockout.defeated .. " of " .. lockout.encounters
                    .. " already defeated -- those kills expire at the reset",
                lockout.remaining .. " "
                    .. (lockout.remaining == 1 and "boss" or "bosses") .. " left",
            }

            if lockout.resetsIn then
                table.insert(reasons, "resets in " .. Instances.FormatReset(lockout.resetsIn))
            end

            if lockout.extended then
                table.insert(reasons, "you extended this lockout deliberately")
            end

            table.insert(candidates, CN.NewObjective({
                id               = lockout.name,
                type             = CN.objectiveTypes.INSTANCE,
                name             = lockout.name
                    .. (lockout.difficulty and (" (" .. lockout.difficulty .. ")") or ""),
                accountWide      = false,
                completionValue  = lockout.raid and 6 or 4,
                limitedTimeBonus = Urgency(lockout.remaining, lockout.resetsIn, lockout.defeated),
                -- No map coordinate, but not "location unknown" either: the
                -- group finder is one click. Same figure the Vault uses.
                travelCost       = 3,
                expiresIn        = lockout.resetsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, {
    -- A lockout changes when a boss dies or when the reset happens, and
    -- nothing else. UPDATE_INSTANCE_INFO is the client saying so.
    events   = { "UPDATE_INSTANCE_INFO", "BOSS_KILL", "ENCOUNTER_END" },
    volatile = true,
    cooldown = 30,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "instances",
    aliases = { "lockouts", "saved" },
    order   = 24,
    help    = "What you are saved to, and how much of it is left.",
    handler = function()
        local lockouts = Instances.Lockouts()

        if #lockouts == 0 then
            Print("You are not saved to anything.")
            Print("|cff999999Lockouts appear here as soon as you kill a boss "
                .. "in a dungeon or raid that saves you.|r")
            return
        end

        Print("Saved to " .. #lockouts
            .. (#lockouts == 1 and " instance:" or " instances:"))

        for _, lockout in ipairs(lockouts) do
            Print("  " .. Instances.Describe(lockout))

            local bosses, note = Instances.RemainingBosses(lockout)

            for _, boss in ipairs(bosses) do
                Print("      |cff999999" .. boss.name .. "|r")
            end

            if note then
                Print("      |cff999999" .. note .. "|r")
            end
        end

        local summary = Instances.Summary()

        if summary.unfinished > 0 then
            Print(summary.bosses .. " "
                .. (summary.bosses == 1 and "boss" or "bosses")
                .. " still available across "
                .. summary.unfinished
                .. (summary.unfinished == 1 and " lockout." or " lockouts."))
        else
            Print("|cff999999Everything you are saved to is cleared.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "drops",
    args    = "<name>",
    order   = 25,
    help    = "Which boss drops something, and whether you are locked to it.",
    handler = function(args)
        args = CN.Trim(args or "")

        if args == "" then
            Print("Usage: /cn drops <name of a mount, pet or item>")
            return
        end

        if not Blizzard.HasEncounterJournal() then
            Print("The Adventure Guide is not available in this client.")
            return
        end

        if Blizzard.IsEncounterJournalOpen() then
            -- Reading the journal moves its selection, which is what the
            -- player is looking at. Refuse rather than reach into it.
            Print("Close the Adventure Guide first -- reading it would change "
                .. "what you are looking at.")
            return
        end

        local results = Instances.WhereDoesItDrop(args)

        if #results == 0 then
            Print("Nothing in the Adventure Guide matches \"" .. args .. "\".")
            Print("|cff999999Not everything drops from a boss; try the exact "
                .. "name the journal uses.|r")
            return
        end

        Print("\"" .. args .. "\" -- " .. #results
            .. (#results == 1 and " encounter:" or " encounters:"))

        for _, result in ipairs(results) do
            local line = "  " .. tostring(result.encounter or "?")

            if result.instance then
                line = line .. " |cff999999in " .. result.instance .. "|r"
            end

            local lockout = result.instance and Instances.LockoutFor(result.instance)

            if lockout then
                if lockout.complete then
                    line = line .. " |cfff56b61locked until "
                        .. Instances.FormatReset(lockout.resetsIn) .. "|r"
                else
                    line = line .. " |cffffff00" .. lockout.remaining
                        .. " left on your lockout|r"
                end
            end

            Print(line)
        end
    end,
}

return Instances
'@

$Embedded['Modules\Preference.lua'] = @'
-- Modules/Preference.lua
-- Completion Navigator :: learning what you actually do.
--
-- THE PROBLEM.
--
-- The ranking has always been the addon's opinion. It is a good opinion --
-- deadlines first, batching second, travel cost third -- but it is the same
-- opinion for everybody, and people do not play the same way. Somebody who
-- has never once gone out of their way for a battle pet gets pets in their
-- list forever, and the addon never notices.
--
-- Hiding the type is the blunt fix and it already exists. This is the fine
-- one: notice what you take up, notice what you scroll past, and lean.
--
-- WHAT IS MEASURED.
--
--   shown   -- the objective was actually put in front of you, via the
--              recommendation hook, which fires on the handful that were
--              displayed rather than the two hundred that were considered.
--   acted   -- it was completed, or its type was, within the window below.
--
-- A ratio of those two, per objective TYPE, on this character.
--
-- WHY TYPE AND NOT THE OBJECTIVE ITSELF.
--
-- Because an individual objective is shown a handful of times before it is
-- either done or gone, which is far too little to learn anything from. A type
-- accumulates hundreds of observations in a week of play. Learning per
-- objective would be learning noise, and dressing it up as personalisation.
--
-- THE GUARDRAILS, WHICH MATTER MORE THAN THE LEARNING.
--
--   * Nothing happens below `minimumObservations`. Until then the multiplier
--     is exactly 1 and the addon behaves as it always did.
--   * The adjustment is CLAMPED, hard. A type you ignore is quieter, never
--     silent -- silencing a type is a decision for you to make in /cn show,
--     not one for a counter to make on your behalf.
--   * It is EXPLAINED. Every adjusted line carries a reason saying so. A
--     ranking that changed for reasons the player cannot see is a ranking
--     they cannot trust.
--   * It DECAYS. Somebody who spent a month on transmog and has now moved on
--     should not be arguing with a month-old opinion forever.
--   * `/cn learned` shows the whole table, and `/cn learned reset` throws it
--     away. Nothing here is permanent and nothing here is hidden.

local ADDON_NAME, CN = ...

local Preference = CN:RegisterModule("Preference")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- TUNING
------------------------------------------------------------

-- How many times a type has to have been shown before its ratio is allowed
-- to move anything at all. Deliberately high: the cost of learning too early
-- is a ranking that lurches around in the player's first evening, which reads
-- as the addon being unreliable rather than adaptive.
Preference.minimumObservations = 25

-- The window in which finishing something counts as having acted on it.
--
-- Twenty minutes suits a quest. It does not suit a raid lockout, which takes
-- an evening, or a reputation, which takes a week -- and crediting those at
-- twenty minutes meant the addon concluded the player ignores exactly the
-- things that take longest to do.
--
-- Per type, therefore, with the old figure as the default. These are not
-- measured -- they are how long the ACTIVITY takes, which the addon cannot
-- observe before the fact -- so they are stated plainly as judgements rather
-- than dressed up as data.
Preference.actionWindowSeconds = 1200

Preference.actionWindows = {
    [CN.objectiveTypes.INSTANCE]   = 5400,   -- an evening's raid
    [CN.objectiveTypes.REPUTATION] = 5400,
    [CN.objectiveTypes.RENOWN]     = 5400,
    [CN.objectiveTypes.ACHIEVEMENT] = 3600,
    [CN.objectiveTypes.PROFESSION] = 3600,
    [CN.objectiveTypes.APPEARANCE] = 2400,
}

function Preference.WindowFor(objectiveType)
    return Preference.actionWindows[objectiveType]
        or Preference.actionWindowSeconds
end

-- The full range of the multiplier. A type you always act on gets a modest
-- push; one you never touch gets a modest shove. Both are small on purpose --
-- this is a thumb on the scale, not a second scoring system.
Preference.minMultiplier = 0.80
Preference.maxMultiplier = 1.25

-- Above this ratio the type is "one you act on", below it "one you skip".
-- Not 0.5: most recommendations are not acted on immediately by anybody,
-- because the list is longer than the evening.
Preference.actedThreshold = 0.25

-- Counters are halved when either passes this, so the table reflects how you
-- play now rather than how you played in June.
Preference.decayAt = 400

------------------------------------------------------------
-- THE STORE
------------------------------------------------------------

-- Per character, because how you play a levelling alt is not how you play the
-- character you raid on. Two integers per type: about as cheap as a store in
-- this addon gets, and nothing here cannot be thrown away.
local function Store()
    local character = CN.character

    if not character then
        return nil
    end

    character.preference = character.preference or {}

    return character.preference
end

Preference.Store = Store

local function Row(objectiveType)
    local store = Store()

    if not store or not objectiveType then
        return nil
    end

    store[objectiveType] = store[objectiveType] or { shown = 0, acted = 0 }

    return store[objectiveType]
end

function Preference.IsEnabled()
    local settings = CN.Settings()

    -- On by default, but a real setting: someone who wants the addon's
    -- opinion and only the addon's opinion is entitled to have it.
    return not settings or settings.learnPreferences ~= false
end

function Preference.SetEnabled(enabled)
    local settings = CN.Settings()

    if settings then
        -- Store false to turn it OFF and nil to turn it back on: the default
        -- is on, so "nil" and "off" must not be the same stored value.
        --
        -- Written as an if rather than as `x and false or nil`, which is how
        -- it was written first: in Lua that expression can never produce
        -- false, because `and false` is falsy and falls straight through to
        -- the `or`. It read correctly and did nothing.
        if enabled then
            settings.learnPreferences = nil
        else
            settings.learnPreferences = false
        end
    end

    CN.InvalidateRanking()
end

------------------------------------------------------------
-- MEMOISATION
------------------------------------------------------------

-- MEMOISED, because this runs on every candidate in the list.
--
-- Ranking scores a few thousand objectives, and without this each one of them
-- resolved the settings proxy, found the character table and did the
-- arithmetic again for an answer that changes a few times an hour. Measured,
-- the uncached version doubled the cost of Recommend(25).
--
-- The key is both generations: the ranking one, bumped when something the
-- player did changes the order, and the observation one, bumped whenever a
-- counter moves. Between them nothing can go stale.
local multiplierCache   = {}
local multiplierKey     = nil

Preference.observationGeneration = 0

local function Observed()
    Preference.observationGeneration = Preference.observationGeneration + 1
end

local function CacheKey()
    return tostring(CN.rankingGeneration or 0) .. ":"
        .. tostring(Preference.observationGeneration)
end

------------------------------------------------------------
-- OBSERVING
------------------------------------------------------------

-- What was shown, and when. In memory only: this is a question about the last
-- twenty minutes, and twenty minutes does not survive a logout in any useful
-- form.
local shownAt = {}

-- Which sub-bucket each sighting was filed under, so the completion side can
-- credit the same bucket the showing side incremented.
local shownRefinement = {}

-- BOUNDED, THE SAME WAY SESSION'S OFFER MEMORY IS.
--
-- `shownAt` gained an entry per distinct objective ever put in front of the
-- player and lost one only on a successful action or on the expired branch,
-- so anything shown and never acted on stayed forever. `shownRefinement` was
-- worse: the success path cleared `shownAt[key]` and left the refinement
-- entry behind unconditionally -- and that is the table the fallback match
-- loop runs a `string.sub` over on every NEW_PET_ADDED, NEW_MOUNT_ADDED and
-- NEW_TOY_ADDED.
--
-- Session next door carries the identical structure with an expiry and a cap
-- and a comment calling the unbounded version "a slow leak I shipped in
-- 0.28.0". The same shape was reintroduced here. Same two bounds, same
-- hysteresis, same reason.
local shownCount = 0

Preference.sightingCap     = 400
Preference.sightingSeconds = 1800
Preference.sightingSlack   = 0.25

-- Removing a sighting means removing it from both tables. Every path that
-- used to touch only one of them is why this is a function.
local function Forget(key)
    if shownAt[key] ~= nil then
        shownCount = shownCount - 1
    end

    shownAt[key]         = nil
    shownRefinement[key] = nil
end

Preference.Forget = Forget

local function Now()
    return (GetTime and GetTime()) or (time and time()) or 0
end

Preference.Now = Now

-- Overshoot by a quarter, then sweep back to the cap -- pruning on every
-- insert would walk four hundred entries per recommendation, which is the
-- trade Session already refused to make.
function Preference.Prune(force)
    local trigger = Preference.sightingCap * (1 + Preference.sightingSlack)

    if not force and shownCount <= trigger then
        return 0
    end

    local now     = Now()
    local removed = 0

    for key, at in pairs(shownAt) do
        if (now - at) > Preference.sightingSeconds then
            Forget(key)
            removed = removed + 1
        end
    end

    if shownCount > Preference.sightingCap then
        local ordered = {}

        for key, at in pairs(shownAt) do
            table.insert(ordered, { key = key, at = at })
        end

        table.sort(ordered, function(a, b)
            if a.at == b.at then
                return a.key < b.key
            end

            return a.at < b.at
        end)

        for index = 1, shownCount - Preference.sightingCap do
            if ordered[index] then
                Forget(ordered[index].key)
                removed = removed + 1
            end
        end
    end

    -- A refinement entry with no sighting behind it is unreachable, and this
    -- is the table the fallback loop walks.
    for key in pairs(shownRefinement) do
        if shownAt[key] == nil then
            shownRefinement[key] = nil
        end
    end

    return removed
end

function Preference.SightingCount()
    return shownCount
end

-- Hung on the recommendation hook rather than a decorator, deliberately.
-- Duration learning made exactly this mistake in 0.28.0 and timed all two
-- hundred candidates on every rebuild, including the hundred and seventy
-- nobody ever saw.
CN.RegisterRecommendationHook("Preference", function(results)
    if not Preference.IsEnabled() then
        return
    end

    local now = Now()

    local store = Store()

    if not store then
        return
    end

    for _, objective in ipairs(results or {}) do
        local objectiveType = objective and objective.type

        if objectiveType then
            local row = store[objectiveType]

            if not row then
                row = { shown = 0, acted = 0 }

                store[objectiveType] = row
            end

            if row then
                -- ONE OBSERVATION PER APPEARANCE, NOT PER REDRAW.
                --
                -- The window redraws on a great many events, and the same
                -- three lines are "shown" on every one of them. Counting
                -- those would mean an open window taught the addon that you
                -- ignore everything, at a rate of several observations a
                -- second, purely for leaving it open.
                -- Built once and kept on the objective. This runs on
                -- every redraw of an open window, and the concatenation was
                -- the most expensive thing in it -- for a string that cannot
                -- change while the objective exists.
                local key = objective.preferenceKey

                if not key then
                    key = objectiveType .. ":" .. tostring(objective.id)

                    objective.preferenceKey = key
                end

                local last = shownAt[key]

                -- FINER THAN A TYPE, WHERE THE TYPE IS TOO COARSE.
                --
                -- "Quests" is one bucket containing two quite different
                -- habits: people who follow the story, and people who clear
                -- everything. Somebody who always does the campaign and never
                -- touches side quests looks, at type resolution, like
                -- somebody with no opinion at all -- the rate averages to the
                -- middle and nothing moves.
                --
                -- Only quests get this. Every other type is one habit, and
                -- six buckets that each learn nothing beat none at all.
                local refined = Preference.Refine(objective)

                -- Keyed on `key`, which is what `shownAt` is keyed on and
                -- what the completion side matches against. It used to
                -- rebuild the string from the type and id, which is the same
                -- thing only while `objective.preferenceKey` has not been set
                -- to something else -- and a refinement filed under a key
                -- nothing looks up is a refinement that never credits.
                shownRefinement[key] = refined

                if refined ~= objectiveType then
                    local refinedRow = store[refined]

                    if not refinedRow then
                        refinedRow = { shown = 0, acted = 0 }

                        store[refined] = refinedRow
                    end

                    -- The SAME window as the counter twelve lines below, and
                    -- for the same reason. This one kept the flat default
                    -- that 0.46.0 replaced with per-type windows, so the
                    -- moment a quest window is added to Preference.
                    -- actionWindows the two counters silently disagree and
                    -- the refined buckets over-count what was shown.
                    if not last
                        or (now - last) > Preference.WindowFor(objectiveType) then

                        refinedRow.shown = refinedRow.shown + 1
                    end
                end

                if not last
                    or (now - last) > Preference.WindowFor(objectiveType) then

                    row.shown = row.shown + 1

                    Observed()

                    -- Only when a counter actually moved. Decaying on every
                    -- call meant walking the whole table on every redraw of
                    -- the window to discover, almost always, that nothing had
                    -- reached the threshold -- the same shape of waste the
                    -- 0.28.0 duration bug was.
                    Preference.Decay()
                end

                if shownAt[key] == nil then
                    shownCount = shownCount + 1
                end

                shownAt[key] = now

                Preference.Prune()
            end
        end
    end
end)

-- Types whose completion event carries the same id the recommendation did.
-- For these an inexact match is not evidence of anything.
Preference.exactIdEvents = {
    [CN.objectiveTypes.QUEST]       = true,
    [CN.objectiveTypes.ACHIEVEMENT] = true,
}

-- Called when something is genuinely finished. Credited only if the addon had
-- recommended it recently -- otherwise every quest anybody turns in would
-- count as the addon's advice being taken, which would teach it that its
-- opinion is always right.
-- The sub-bucket an objective belongs in, or its plain type when it has none.
function Preference.Refine(objective)
    if not objective or objective.type ~= CN.objectiveTypes.QUEST then
        return objective and objective.type
    end

    -- The game's own campaign data, which is what Loremaster already uses to
    -- keep "the story" and "everything else" apart.
    if CN.Blizzard and CN.Blizzard.IsQuestCampaign
        and CN.Blizzard.IsQuestCampaign(objective.id) then

        return "QUEST_CAMPAIGN"
    end

    return "QUEST_SIDE"
end

-- Which sub-bucket a recorded sighting belonged to.
--
-- The showing side files an objective under both its plain type and its
-- refinement; the completion side sees only a type and an id, and the id is
-- not always the one that was recommended. So the refinement is remembered
-- when the sighting is recorded, keyed the same way.
function Preference.RefinedKeyFor(key, objectiveType)
    local remembered = shownRefinement[key]

    if remembered then
        return remembered
    end

    return objectiveType
end

function Preference.NoteCompleted(objectiveType, objectiveID)
    if not Preference.IsEnabled() or not objectiveType then
        return false
    end

    local now = Now()

    local key = objectiveType .. ":" .. tostring(objectiveID)

    local last = shownAt[key]

    -- THE ID THE EVENT CARRIES IS NOT ALWAYS THE ID THAT WAS RECOMMENDED.
    --
    -- NEW_PET_ADDED reports the unique pet you now own; the recommendation was
    -- about the species. NEW_MOUNT_ADDED and the transmog events have the same
    -- shape of mismatch. For those, fall back to "was anything of this type
    -- recommended in the window", since what is being learned is per type
    -- anyway.
    --
    -- NOT for quests and achievements. Those events carry exactly the id that
    -- was recommended, so a fallback there would credit the addon for every
    -- quest anybody turns in merely because it had mentioned some other quest
    -- in the last twenty minutes -- and on a levelling character it has always
    -- mentioned some other quest in the last twenty minutes. That is not
    -- learning, it is a counter that only goes up.
    if not last and not Preference.exactIdEvents[objectiveType] then
        local fallbackKey

        for candidateKey, when in pairs(shownAt) do
            if (now - when) <= Preference.WindowFor(objectiveType)
                and string.sub(candidateKey, 1, #objectiveType + 1)
                    == (objectiveType .. ":") then

                -- The most recently shown one, so a stale sighting from
                -- nineteen minutes ago does not get the credit.
                if not fallbackKey or when > shownAt[fallbackKey] then
                    fallbackKey = candidateKey
                end
            end
        end

        if not fallbackKey then
            return false
        end

        key  = fallbackKey
        last = shownAt[fallbackKey]
    end

    -- Still nothing: this was never recommended, so it teaches us nothing.
    -- Reaching the arithmetic below with a nil here threw inside a
    -- QUEST_TURNED_IN handler -- a learning feature breaking quest turn-ins
    -- would be a spectacularly bad trade.
    if not last then
        return false
    end

    if (now - last) > Preference.WindowFor(objectiveType) then
        Forget(key)

        return false
    end

    local row = Row(objectiveType)

    if not row then
        return false
    end

    row.acted = row.acted + 1

    -- AND THE REFINED BUCKET, WHICH WAS NEVER CREDITED AT ALL.
    --
    -- The showing side increments both the plain type and the campaign/side
    -- sub-bucket; this side incremented only the plain type. So the refined
    -- rows accumulated sightings and no actions, drifted to the floor
    -- multiplier, and the score adjuster PREFERS the refined row whenever its
    -- multiplier is not 1 -- meaning the plain row that held the true answer
    -- was correct and unreachable.
    --
    -- Measured: a player who turned in all 120 quests they were shown was
    -- told, after an hour or two, that they "rarely act on these", and every
    -- quest was multiplied by 0.80 permanently.
    --
    -- The id is not always available here (some events carry a different one
    -- than was recommended), so the bucket is recovered from the key that was
    -- actually matched.
    local refined = Preference.RefinedKeyFor(key, objectiveType)

    if refined and refined ~= objectiveType then
        local store = Store()

        local refinedRow = store and store[refined]

        if refinedRow then
            refinedRow.acted = (refinedRow.acted or 0) + 1
        end
    end

    Observed()

    -- BOTH TABLES. Clearing only `shownAt` here is what left an entry in
    -- `shownRefinement` for every objective the player ever acted on.
    Forget(key)

    CN.InvalidateRanking()

    DebugPrint("Acted on a " .. objectiveType .. " that was recommended.")

    return true
end

-- Halve everything once the counts get large, so the table tracks how you
-- play now. Halving keeps the RATIO and forgets the certainty, which is
-- exactly the right thing to forget.
function Preference.Decay()
    local store = Store()

    if not store then
        return false
    end

    local decayed = false

    for _, row in pairs(store) do
        if row.shown >= Preference.decayAt then
            row.shown = math.floor(row.shown / 2)
            row.acted = math.floor(row.acted / 2)

            Observed()

            decayed = true
        end
    end

    return decayed
end

------------------------------------------------------------
-- THE ADJUSTMENT
------------------------------------------------------------

-- Returns the multiplier and, when it is not 1, a sentence saying why.
function Preference.Multiplier(objectiveType)
    if not objectiveType then
        return 1, nil
    end

    local key = CacheKey()

    if key ~= multiplierKey then
        multiplierCache = {}
        multiplierKey   = key
    end

    local cached = multiplierCache[objectiveType]

    if cached then
        return cached[1], cached[2]
    end

    local multiplier, reason = Preference.Compute(objectiveType)

    multiplierCache[objectiveType] = { multiplier, reason }

    return multiplier, reason
end

function Preference.Compute(objectiveType)
    if not Preference.IsEnabled() then
        return 1, nil
    end

    local store = Store()

    local row = store and store[objectiveType]

    if not row or row.shown < Preference.minimumObservations then
        return 1, nil
    end

    local ratio = row.acted / row.shown

    if ratio >= Preference.actedThreshold then
        -- Scale across the range above the threshold rather than jumping to
        -- the cap the moment it is crossed.
        local above = math.min(1, (ratio - Preference.actedThreshold)
            / (1 - Preference.actedThreshold))

        local multiplier = 1 + (Preference.maxMultiplier - 1) * above

        return multiplier, "you usually act on these"
    end

    local below = 1 - (ratio / Preference.actedThreshold)

    local multiplier = 1 - (1 - Preference.minMultiplier) * below

    return multiplier, "you rarely act on these"
end

-- Applied in scoring, after the profile's own type weighting, so a focus you
-- chose deliberately always outranks a habit the addon inferred.
CN.RegisterScoreAdjuster("Preference", function(objective, score)
    -- The finer bucket first, and only if it has earned an opinion of its
    -- own. Falling back to the type means a player whose quest habits are
    -- undifferentiated is treated exactly as before.
    local refined = Preference.Refine(objective)

    local multiplier, reason = 1, nil

    if refined and refined ~= (objective and objective.type) then
        multiplier, reason = Preference.Multiplier(refined)
    end

    if multiplier == 1 then
        multiplier, reason = Preference.Multiplier(objective and objective.type)
    end

    if multiplier == 1 then
        return score
    end

    -- SAY SO. A list that quietly reordered itself is a list nobody can
    -- argue with, and this addon's whole contract is that every line has a
    -- stated reason.
    if reason then
        CN.AddAdjusterReason(objective, "preference", reason)
    end

    return score * multiplier
end)

------------------------------------------------------------
-- WHAT COUNTS AS HAVING ACTED
------------------------------------------------------------

-- Only completions the game announces. Nothing here infers that you did
-- something because you walked near it.
local completionEvents = {
    { event = "QUEST_TURNED_IN",   type = CN.objectiveTypes.QUEST },
    { event = "ACHIEVEMENT_EARNED", type = CN.objectiveTypes.ACHIEVEMENT },
    { event = "NEW_PET_ADDED",     type = CN.objectiveTypes.PET },
    { event = "NEW_MOUNT_ADDED",   type = CN.objectiveTypes.MOUNT },
    { event = "NEW_TOY_ADDED",     type = CN.objectiveTypes.TOY },
}

for _, entry in ipairs(completionEvents) do
    CN:RegisterEvent(entry.event, function(_, id)
        Preference.NoteCompleted(entry.type, id)
    end)
end

Preference.completionEvents = completionEvents

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "learned",
    args    = "[reset or off or on]",
    order   = 34,
    help    = "What the addon has worked out about how you play.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "reset" then
            local character = CN.character

            if character then
                character.preference = nil
            end

            CN.InvalidateRanking()

            Print("Forgotten. The ranking is back to its defaults.")
            return
        end

        if args == "off" or args == "on" then
            Preference.SetEnabled(args == "on")

            Print("Learning from what you do: "
                .. CN.YesNo(Preference.IsEnabled()))
            return
        end

        local store = Store()

        if not store or next(store) == nil then
            Print("Nothing learned yet.")
            Print("|cff999999The addon watches which kinds of thing you "
                .. "actually go and do, and needs "
                .. Preference.minimumObservations
                .. " sightings of a kind before it acts on anything.|r")
            return
        end

        if not Preference.IsEnabled() then
            Print("|cff999999Learning is switched off; the figures below are "
                .. "not affecting your ranking. |cffffff00/cn learned on|r "
                .. "re-enables it.|r")
        end

        local filters = CN:GetModule("Filters")

        local rows = {}

        for objectiveType, row in pairs(store) do
            table.insert(rows, { type = objectiveType, row = row })
        end

        table.sort(rows, function(a, b)
            return (a.row.shown or 0) > (b.row.shown or 0)
        end)

        Print("What this character actually does:")

        for _, entry in ipairs(rows) do
            local labels = {
                QUEST_CAMPAIGN = "Story quests",
                QUEST_SIDE     = "Side quests",
            }

            local label = labels[entry.type]
                or (filters and filters.TypeLabel(entry.type))
                or entry.type

            local multiplier, reason = Preference.Multiplier(entry.type)

            local line = string.format("  %-16s %d of %d acted on",
                label, entry.row.acted, entry.row.shown)

            if multiplier == 1 then
                local short = Preference.minimumObservations - entry.row.shown

                line = line .. " |cff999999(no effect"
                    .. (short > 0 and (" -- " .. short .. " more sightings needed")
                        or "")
                    .. ")|r"
            else
                line = line .. string.format(" |cffffff00x%.2f|r |cff999999%s|r",
                    multiplier, reason or "")
            end

            Print(line)
        end

        Print("|cff999999" .. "/cn learned reset" .. " forgets all of it. "
            .. "Hiding a type outright is |cffffff00/cn show|r.|r")
    end,
}

return Preference
'@

$Embedded['Modules\Capture.lua'] = @'
-- Modules/Capture.lua
-- Completion Navigator :: recording what the client actually returns.
--
-- THE PROBLEM THIS EXISTS TO END.
--
-- Nine defects in this addon's history came from the same place: the offline
-- test harness modelled the world more simply than the world is, the tests
-- agreed with the model, and the bug shipped. A map point modelled as a flat
-- table when the client wants a vector. A quest list containing no quest
-- starts. An achievement criterion with no counter. Every map modelled as a
-- perfect square, for eight releases, which hid an angle error in every zone
-- in the game.
--
-- `/cn selftest` catches these in play, which is a great deal better than a
-- player catching them, but it is still after the fact. It cannot stop the
-- NEXT optimistic stub from being written, because the author of a stub does
-- not know which part of reality he is simplifying -- that is what makes it a
-- simplification rather than a decision.
--
-- The only thing that ends it is testing against real data. So: record what
-- the client actually returned, on a real character, and let the offline
-- suite check its own stubs against that recording. A stub that is missing a
-- field reality had becomes a test failure instead of a future bug report.
--
-- WHAT IS RECORDED.
--
-- Shapes and small samples, never the player's collections wholesale. The
-- suite needs to know that GetSavedInstanceInfo returns thirteen values in a
-- particular order and that map spans are not square; it does not need
-- eighteen hundred pets.
--
-- WHAT IS NOT RECORDED.
--
-- Character names, realm, guild, anything that identifies the player, and
-- nothing at all unless the command is run deliberately. The file is written
-- into your own SavedVariables and goes nowhere on its own -- this addon has
-- no network access of any kind and never will.

local ADDON_NAME, CN = ...

local Capture = CN:RegisterModule("Capture")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

CN.captures = CN.captures or {}

-- definition = {
--     name = "GetSavedInstanceInfo",
--     run  = function() return <plain data>, note end,
-- }
function CN.RegisterCapture(definition)
    if type(definition) ~= "table" or type(definition.run) ~= "function" then
        return false
    end

    table.insert(CN.captures, definition)

    return true
end

------------------------------------------------------------
-- SHAPE, NOT CONTENT
------------------------------------------------------------

-- Reduces a value to what a test needs to know about it: its type, and for a
-- table, the shape of its keys. Numbers survive because a range matters --
-- a map span of 4,000 by 2,700 is the whole point of one of these captures --
-- but a list of three thousand achievement IDs collapses to "3000 numbers".
--
-- Bounded by depth and by width, because this is written to disk and read
-- back on every login until it is cleared.
function Capture.Shape(value, depth, width)
    depth = depth or 3
    width = width or 12

    local kind = type(value)

    if kind ~= "table" then
        if kind == "string" and #value > 64 then
            return { type = "string", length = #value }
        end

        return { type = kind, value = (kind == "function" and "function" or value) }
    end

    if depth <= 0 then
        return { type = "table", truncated = true }
    end

    local shape = { type = "table", fields = {}, count = 0, array = 0 }

    -- Methods matter as much as fields: the 0.19.0 bug was a Vector2D whose
    -- GetXY the stub did not have.
    for key, entry in pairs(value) do
        shape.count = shape.count + 1

        if type(key) == "number" then
            shape.array = shape.array + 1
        elseif type(key) == "string" and shape.count <= width then
            shape.fields[key] = Capture.Shape(entry, depth - 1, width)
        end
    end

    if getmetatable(value) then
        shape.metatable = true
    end

    return shape
end

------------------------------------------------------------
-- WHAT GETS CAPTURED
------------------------------------------------------------

CN.RegisterCapture{
    name = "position",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        return { mapID = mapID, x = x, y = y }
    end,
}

-- THE ONE THAT WOULD HAVE CAUGHT 0.40.0's ANGLE BUG EIGHT RELEASES EARLIER.
CN.RegisterCapture{
    name = "mapSpanYards",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        local nav = CN:GetModule("Navigation")

        if not mapID or not nav then
            return nil, "no map"
        end

        local scaleX, scaleY = nav.MapScale(mapID)

        return {
            mapID  = mapID,
            xYards = scaleX,
            yYards = scaleY,
            square = math.abs(scaleX - scaleY) < 1,
        }
    end,
}

CN.RegisterCapture{
    name = "worldPosition",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID or not C_Map or not C_Map.GetWorldPosFromMapPos then
            return nil, "no map"
        end

        local ok, continentID, position =
            pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

        if not ok or not position then
            return nil, "the client would not convert"
        end

        return {
            continentID = continentID,
            shape       = Capture.Shape(position),
            hasGetXY    = position.GetXY ~= nil,
        }
    end,
}

CN.RegisterCapture{
    name = "mapInfo",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        return Capture.Shape(Blizzard.GetMapInfo(mapID))
    end,
}

CN.RegisterCapture{
    name = "questPOI",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        local pois = Blizzard.GetQuestPOIsOnMap(mapID)

        if #pois == 0 then
            return nil, "no quest pins here"
        end

        local starts = 0

        for _, poi in ipairs(pois) do
            if poi.isQuestStart then
                starts = starts + 1
            end
        end

        return {
            count       = #pois,
            questStarts = starts,
            shape       = Capture.Shape(pois[1]),
        }
    end,
}

CN.RegisterCapture{
    name = "achievementCriteria",
    run  = function()
        local achievements = CN:GetModule("Achievements")

        if not achievements then
            return nil, "achievements module not loaded"
        end

        for achievementID in pairs(achievements.Store()) do
            local criteria = Blizzard.GetAchievementCriteriaList(achievementID, 4)

            if criteria and criteria[1] then
                return {
                    shape    = Capture.Shape(criteria[1]),
                    counted  = criteria[1].required ~= nil,
                }
            end
        end

        return nil, "nothing scanned yet"
    end,
}

CN.RegisterCapture{
    name = "savedInstances",
    run  = function()
        local saved = Blizzard.GetSavedInstances()

        if #saved == 0 then
            return nil, "not saved to anything"
        end

        return { count = #saved, shape = Capture.Shape(saved[1]) }
    end,
}

CN.RegisterCapture{
    name = "encounterJournal",
    run  = function()
        if not Blizzard.HasEncounterJournal() then
            return nil, "no Adventure Guide in this client"
        end

        if Blizzard.IsEncounterJournalOpen() then
            return nil, "the Adventure Guide is open"
        end

        return { available = true }
    end,
}

CN.RegisterCapture{
    name = "completedQuests",
    run  = function()
        local progress = CN:GetModule("Progress")

        local total = progress and progress.LifetimeCompleted()

        if not total then
            return nil, "the client will not report a lifetime total"
        end

        -- The COUNT is the interesting number: a stub that returns eight
        -- entries where the client returns twelve thousand is a stub that
        -- makes an expensive call look free.
        return { count = total }
    end,
}

CN.RegisterCapture{
    name = "weeklyReset",
    run  = function()
        local seconds = Blizzard.GetSecondsUntilWeeklyReset()

        if not seconds then
            return nil, "the client will not say"
        end

        return { seconds = seconds }
    end,
}

-- WHICH OF THE EVENTS THIS ADDON REGISTERS ARE REAL.
--
-- Added in 0.46.0, after `NEW_TAXI_NODE` -- a name that does not exist and
-- never has -- threw a Lua error at every login. The test suite could not see
-- it because the stub frame accepted any string, and the fix for that is a
-- list of real event names maintained by hand in the harness. A list
-- maintained by hand is precisely the kind of thing this project keeps being
-- caught by, so it needs checking against a client rather than against
-- memory.
--
-- This asks the live client to register every event the addon uses, on a
-- throwaway frame with no handler attached, and records the ones it refused.
-- The harness fails on any refusal.
CN.RegisterCapture{
    name = "events",
    run  = function()
        if not CreateFrame then
            return nil, "no frame factory"
        end

        local ok, probe = pcall(CreateFrame, "Frame")

        if not ok or not probe then
            return nil, "the client would not make a frame"
        end

        local refused, accepted = {}, 0

        for event in pairs(CN.eventTable or {}) do
            local registered = pcall(probe.RegisterEvent, probe, event)

            if registered then
                accepted = accepted + 1

                pcall(probe.UnregisterEvent, probe, event)
            else
                table.insert(refused, event)
            end
        end

        table.sort(refused)

        return { accepted = accepted, refused = refused }
    end,
}

-- WHICH OF THE CLIENT FUNCTIONS THIS ADDON CALLS STILL EXIST.
--
-- The sibling of the `events` capture, and the more insidious half. An
-- unknown EVENT name throws, so it announces itself. An unknown FUNCTION name
-- announces nothing: every call site in this addon is guarded with
-- `if C_Thing and C_Thing.Method`, which is correct, and which makes a
-- misspelled or renamed name indistinguishable from a client that does not
-- support the feature. The guard is false, the branch never runs, and the
-- feature is quietly dead for as long as nobody notices.
--
-- Data/ApiSurface.lua is generated from the source at build time -- a
-- hand-written list of what the code calls is a second copy of the code, and
-- would drift within a release.
CN.RegisterCapture{
    name = "apiSurface",
    run  = function()
        if type(CN.apiSurface) ~= "table" or #CN.apiSurface == 0 then
            return nil, "no generated surface in this build"
        end

        local missing, present = {}, 0

        for _, path in ipairs(CN.apiSurface) do
            local namespace, method = string.match(path, "^([^.]+)%.(.+)$")

            local value

            if namespace then
                local container = _G and _G[namespace]

                value = type(container) == "table" and container[method] or nil
            else
                value = _G and _G[path]
            end

            if value ~= nil then
                present = present + 1
            else
                table.insert(missing, path)
            end
        end

        return { examined = #CN.apiSurface, present = present, missing = missing }
    end,
}

------------------------------------------------------------
-- RUNNING IT
------------------------------------------------------------

function Capture.Run()
    local records = {}

    local captured, skipped = 0, 0

    for _, definition in ipairs(CN.captures) do
        local ok, value, note = pcall(definition.run)

        if not ok then
            records[definition.name] = { skipped = "errored: " .. tostring(value) }
            skipped = skipped + 1
        elseif value == nil then
            records[definition.name] = { skipped = note or "nothing to record" }
            skipped = skipped + 1
        else
            records[definition.name] = value
            captured = captured + 1
        end
    end

    records.build   = CN.version
    records.locale  = CN.ClientLocale and CN.ClientLocale() or nil
    records.recorded = time()

    -- WHICH CLIENT THIS IS EVIDENCE ABOUT.
    --
    -- Added in 0.46.0, because a recording with no interface number cannot be
    -- checked for staleness, and stale evidence is worse than none: it makes
    -- the audit report success about a game that has since been patched. The
    -- .toc's Interface line is the addon's claim about which client it
    -- supports; this is the client that was actually running.
    if GetBuildInfo then
        local ok, _, _, _, interface = pcall(GetBuildInfo)

        if ok then
            records.interface = tonumber(interface)
        end
    end

    -- Written under the account table so it survives to the next logout and
    -- lands in SavedVariables, which is the only way it can reach the
    -- repository. Explicitly NOT merged into anything the addon reads: this
    -- is evidence, not data.
    local account = CN.Account()

    account.capture = records

    return records, captured, skipped
end

function Capture.Clear()
    local account = CN.Account()

    local had = account.capture ~= nil

    account.capture = nil

    return had
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "capture",
    args    = "[clear]",
    order   = 35,
    help    = "Record what your client returns, so the tests can check "
        .. "themselves against reality.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "clear" then
            Print(Capture.Clear()
                and "Capture cleared. It will be gone from your saved data "
                    .. "at the next logout."
                or "There was nothing recorded.")
            return
        end

        local records, captured, skipped = Capture.Run()

        Print("Recorded " .. captured .. " of " .. (captured + skipped)
            .. " observations.")

        for name, value in pairs(records) do
            if type(value) == "table" and value.skipped then
                Print("  |cff999999" .. name .. " -- " .. value.skipped .. "|r")
            end
        end

        Print("|cff999999Nothing identifying you is recorded, and nothing "
            .. "leaves your machine -- this addon has no network access. "
            .. "It is written to your SavedVariables at logout.|r")
        Print("To send it: log out, then find "
            .. "|cffffff00WTF\\Account\\<account>\\SavedVariables\\"
            .. "CompletionNavigatorDB.lua|r.")
        Print("|cffffff00/cn capture clear|r removes it again.")
    end,
}

return Capture
'@

$Embedded['Modules\SelfTest.lua'] = @'
-- Modules/SelfTest.lua
-- Completion Navigator :: assertions that run where reality is.
--
-- WHY THIS EXISTS.
--
-- Seven times in this project's history, the offline test harness has modelled
-- the world more simply than the world, and hidden a real defect by doing it:
--
--   * a map point modelled as a flat table when the client wants a vector
--   * a quest list that contained no quest starts
--   * an achievement criterion with no counter
--   * a completed-quest list that cost nothing to read
--   * a player who could not move
--   * an arrow whose direction nothing could read
--   * a map that would place the player anywhere it was asked about
--
-- Every one was found by somebody playing the game. None was found by the
-- suite. And no amount of improving the harness fixes that, because the
-- harness is the thing that is wrong: you cannot write a stub for the part of
-- reality you did not know you were simplifying.
--
-- So these assertions do not run against a stub. They run against the live
-- client, on the player's own character, and report what they actually got.
-- When something is wrong, the answer is one command rather than a
-- conversation.
--
-- RULES FOR A CHECK IN HERE.
--
--   * It must be read-only. A diagnostic that changes the game is a liability.
--   * It must be fast. This runs on demand, but nobody waits.
--   * It must report the VALUE it saw, not just pass or fail. "Failed" starts
--     a conversation; "expected a number, got nil" ends one.
--   * A client that cannot answer is a SKIP, not a failure. Being in a raid
--     with the map API restricted is not a bug in this addon.

local ADDON_NAME, CN = ...

local SelfTest = CN:RegisterModule("SelfTest")

local Print = CN.Print

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

SelfTest.results = { PASS = "PASS", FAIL = "FAIL", SKIP = "SKIP" }

-- The registry itself is in Core.lua, so that a module registering a check
-- does not have to load after this file:
--
--     CN.RegisterSelfTest{ name = ..., area = ..., run = function() end }
--
-- definition.run returns status, detail.

function SelfTest.Run()
    local rows = { passed = 0, failed = 0, skipped = 0, checks = {} }

    local ordered = {}

    for _, definition in ipairs(CN.selfTests) do
        table.insert(ordered, definition)
    end

    table.sort(ordered, function(a, b)
        if (a.area or "") ~= (b.area or "") then
            return (a.area or "") < (b.area or "")
        end

        return (a.order or 0) < (b.order or 0)
    end)

    for _, definition in ipairs(ordered) do
        -- A check that throws is a failed check, not a broken command. The
        -- whole point is to survive a client that surprises us.
        local ok, status, detail = pcall(definition.run)

        if not ok then
            -- `status` is the error message here, so read it BEFORE
            -- overwriting it. Getting that order wrong produced a check that
            -- reported "the check itself errored: FAIL", which is the least
            -- useful sentence this module could possibly print.
            detail = "the check itself errored: " .. tostring(status)
            status = SelfTest.results.FAIL
        end

        status = status or SelfTest.results.SKIP

        if status == SelfTest.results.PASS then
            rows.passed = rows.passed + 1
        elseif status == SelfTest.results.FAIL then
            rows.failed = rows.failed + 1
        else
            rows.skipped = rows.skipped + 1
        end

        table.insert(rows.checks, {
            name   = definition.name,
            area   = definition.area or "general",
            status = status,
            detail = detail,
        })
    end

    return rows
end

------------------------------------------------------------
-- THE CHECKS
------------------------------------------------------------

local PASS = SelfTest.results.PASS
local FAIL = SelfTest.results.FAIL
local SKIP = SelfTest.results.SKIP

-- 1. Can the client say where we are at all? Everything else depends on it.
-- WHAT THE GAME PATCHED OUT FROM UNDER US.
--
-- Added in 0.47.0. Every expansion renames or removes client functions, and
-- this addon names nearly two hundred of them. Each call site guards on the
-- name existing -- which is right, and which is also why a removed function
-- produces silence rather than an error: the guard goes false and the feature
-- is dead with nothing to say so.
--
-- Data/ApiSurface.lua is generated from the source at build time, so this
-- cannot fall out of step with what the addon actually calls. Reported here
-- because the player is the one holding a client the author has not seen.
CN.RegisterSelfTest{
    area  = "client",
    order = 0,
    name  = "every client function this addon calls still exists",
    run   = function()
        if type(CN.apiSurface) ~= "table" or #CN.apiSurface == 0 then
            return SKIP, "this build carries no generated API list"
        end

        local missing = {}

        for _, path in ipairs(CN.apiSurface) do
            local namespace, method = string.match(path, "^([^.]+)%.(.+)$")

            local value

            if namespace then
                local container = _G and _G[namespace]

                value = type(container) == "table" and container[method] or nil
            else
                value = _G and _G[path]
            end

            if value == nil then
                table.insert(missing, path)
            end
        end

        if #missing == 0 then
            return PASS, #CN.apiSurface .. " client functions, all present"
        end

        -- Named, and bounded: a patch that removes a whole namespace would
        -- otherwise print forty lines into the chat frame.
        local named = {}

        for index = 1, math.min(6, #missing) do
            table.insert(named, missing[index])
        end

        return FAIL, #missing .. " of " .. #CN.apiSurface
            .. " are gone from this client: " .. table.concat(named, ", ")
            .. (#missing > 6 and (" and " .. (#missing - 6) .. " more") or "")
    end,
}

CN.RegisterSelfTest{
    area = "position",
    name = "the client reports your position",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map -- are you in an instance or a loading screen?"
        end

        if not x or not y then
            return FAIL, "map " .. mapID .. " but no coordinates"
        end

        return PASS, string.format("map %d at %.1f, %.1f", mapID, x * 100, y * 100)
    end,
}

-- 2. THE 0.19.0 BUG. GetWorldPosFromMapPos wants a Vector2D, not a UiMapPoint.
--    Passing the wrong one returns nothing and every distance reads "unknown".
--    The stub modelled both as the same shape, so the suite agreed with it.
CN.RegisterSelfTest{
    area = "position",
    name = "map coordinates convert to world positions",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID or not x then
            return SKIP, "no position to convert"
        end

        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        -- Distance from where we are to slightly north of it. Any real
        -- number proves the conversion works.
        local yards = nav.DistanceYards(mapID, x, y, x, math.max(0, y - 0.01))

        if not yards then
            return FAIL, "the client would not convert -- every distance in "
                .. "the addon will read 'unknown'"
        end

        return PASS, string.format("%.0f yards per 1%% of this map", yards)
    end,
}

-- 3. THE 0.34.0 BUG. Standing in a building changes which map you are "on",
--    and the arrow gave up when that map differed from the destination's.
CN.RegisterSelfTest{
    area = "position",
    name = "your position is expressible on the surrounding zone",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map"
        end

        local info = Blizzard.GetMapInfo(mapID)

        local parentID = info and info.parentMapID

        if not parentID or parentID == 0 then
            return SKIP, "this map has no parent -- you are not indoors"
        end

        local nav = CN:GetModule("Navigation")

        local translated = nav and nav.PlayerPositionOnMap(parentID)

        if not translated then
            return SKIP, "the parent map cannot place you, which is normal "
                .. "for a continent"
        end

        return PASS, string.format("also %.1f, %.1f on map %d",
            translated.x * 100, translated.y * 100, parentID)
    end,
}

-- 4. THE BEARING MATHS, against cases whose answers are known independently
--    of the code being checked.
--
--    NOT written the obvious way. The obvious way is to project a point in
--    front of the player using the addon's own facing convention and then ask
--    the addon which way that point is -- which is a tautology: it derives the
--    expected answer from the thing under test, so it passes whether the
--    convention is right or wrong. That is precisely the failure this module
--    exists to stop, and it was in this file before it shipped.
--
--    Instead: fix the facing at zero, put a target somewhere whose bearing is
--    known from the definition of the map (north is up, east is right), and
--    require the stated answer.
CN.RegisterSelfTest{
    area = "navigation",
    name = "the bearing maths gives known answers",
    run  = function()
        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        local cases = {
            { name = "north",  x = 0.5, y = 0.4, expected =   0 },
            { name = "east",   x = 0.6, y = 0.5, expected =  90 },
            { name = "south",  x = 0.5, y = 0.6, expected = 180 },
            { name = "west",   x = 0.4, y = 0.5, expected = -90 },
        }

        for _, case in ipairs(cases) do
            -- No mapID: unscaled, so the four cardinals stay cardinal.
            local relative = nav.RelativeBearing(0.5, 0.5, case.x, case.y, 0, 1)

            if not relative then
                return FAIL, "no bearing could be computed at all"
            end

            local degrees = math.deg(relative)

            -- Signed difference, wrapped, so that east reading as west is a
            -- failure rather than the same distance from zero.
            local off = math.abs(math.deg(
                nav.NormalizeAngle(math.rad(degrees - case.expected))))

            if off > 1 then
                return FAIL, string.format(
                    "a target due %s read as %.0f degrees, not %d",
                    case.name, degrees, case.expected)
            end
        end

        return PASS, "north, east, south and west all read correctly"
    end,
}

-- 5. WHICH WAY THE CLIENT COUNTS FACING, from the player's own movement.
--
--    This is the one that would have ended two bug reports. It cannot be
--    answered by arithmetic, because it is a fact about the client, so it is
--    answered by evidence: when you walk, the direction you moved is the
--    direction you were facing, and only one of the two conventions agrees
--    with that.
--
--    No evidence yet is a SKIP with an instruction, not a pass. An
--    unverified assumption reported as PASS is worse than no check.
CN.RegisterSelfTest{
    area = "navigation",
    name = "your facing is being read the right way round",
    run  = function()
        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        local state = nav.MotionState()

        if state.samples == 0 then
            return SKIP, "no movement seen yet -- point the arrow at "
                .. "something with /cn go, walk forward a few seconds, and "
                .. "run this again"
        end

        if state.verdict == "corrected" then
            return PASS, "was backwards; corrected from your movement and "
                .. "remembered (sign " .. tostring(state.sign) .. ")"
        end

        return PASS, string.format(
            "confirmed against %d movement samples (sign %s)",
            state.samples, tostring(state.sign))
    end,
}

-- 6. MAP ASPECT RATIO. Angles taken from raw map coordinates are distorted by
--    however far from square the zone is, which was wrong in every zone in
--    the game until 0.40.0.
CN.RegisterSelfTest{
    area = "navigation",
    name = "angles are corrected for the shape of the zone",
    run  = function()
        local nav = CN:GetModule("Navigation")

        local mapID = CN.GetPlayerPosition()

        if not nav or not mapID then
            return SKIP, "no map"
        end

        local scaleX, scaleY = nav.MapScale(mapID)

        if scaleX == 1 and scaleY == 1 then
            return SKIP, "the client would not size this map"
        end

        local ratio = scaleX / scaleY

        return PASS, string.format(
            "%.0f x %.0f yards, ratio %.2f -- angles adjusted by it",
            scaleX, scaleY, ratio)
    end,
}

-- 7. THE 0.23.0 BUG. Every quest source read the quest log, so quests
--    offered in front of the player were structurally invisible.
CN.RegisterSelfTest{
    area = "quests",
    name = "the map reports quests you have NOT accepted",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map"
        end

        local pois = Blizzard.GetQuestPOIsOnMap(mapID)

        if #pois == 0 then
            return SKIP, "no quest pins on this map at all"
        end

        local starts = 0

        for _, poi in ipairs(pois) do
            if poi.isQuestStart then
                starts = starts + 1
            end
        end

        return PASS, string.format("%d pins, %d of them quest starts",
            #pois, starts)
    end,
}

-- 8. THE 0.32.0 BUG. This returns a table of every quest ever completed, not
--    a count, and reading it on every refresh was expensive.
CN.RegisterSelfTest{
    area = "quests",
    name = "your completed-quest history is readable",
    run  = function()
        local progress = CN:GetModule("Progress")

        if not progress then
            return SKIP, "progress module not loaded"
        end

        local total = progress.LifetimeCompleted()

        if not total then
            return SKIP, "the client will not report a lifetime total"
        end

        return PASS, CN.Comma(total) .. " quests completed on this character"
    end,
}

-- 9. THE 0.26.0 BUG. A criterion can carry its own counter, and a stub that
--    returned only three values hid that.
CN.RegisterSelfTest{
    area = "achievements",
    name = "achievement criteria report their counters",
    run  = function()
        local achievements = CN:GetModule("Achievements")

        if not achievements then
            return SKIP, "achievements module not loaded"
        end

        local sampled, counted = 0, 0

        for achievementID in pairs(achievements.Store()) do
            local criteria = Blizzard.GetAchievementCriteriaList(achievementID, 6)

            for _, criterion in ipairs(criteria) do
                sampled = sampled + 1

                if criterion.required and criterion.required > 1 then
                    counted = counted + 1
                end
            end

            if sampled >= 30 then
                break
            end
        end

        if sampled == 0 then
            return SKIP, "nothing scanned yet -- run /cn setup"
        end

        return PASS, string.format("%d criteria read, %d carry a counter",
            sampled, counted)
    end,
}

-- 10. Names the addon deliberately stopped storing must come back live. If
--    they do not, everything in the interface reads "Pet 12345".
CN.RegisterSelfTest{
    area = "names",
    name = "names resolve from the client rather than from disk",
    run  = function()
        local checked, resolved = 0, 0

        local pets = CN:GetModule("Pets")

        if pets then
            for speciesID in pairs(pets.Store()) do
                checked = checked + 1

                if Blizzard.GetPetName(speciesID) then
                    resolved = resolved + 1
                end

                if checked >= 10 then
                    break
                end
            end
        end

        if checked == 0 then
            return SKIP, "no pets scanned yet"
        end

        if resolved == 0 then
            return FAIL, "the pet journal named none of "
                .. checked .. " -- the interface will show numbers"
        end

        return PASS, resolved .. " of " .. checked .. " named by the client"
    end,
}

-- 11. The database is at the version this build expects. A migration that
--    silently failed leaves a shape nothing else understands.
CN.RegisterSelfTest{
    area = "database",
    name = "the database is at the expected version",
    run  = function()
        if not CN.db then
            return FAIL, "no database loaded at all"
        end

        local version = CN.db.version

        if version ~= CN.dbVersion then
            return FAIL, "database is version " .. tostring(version)
                .. ", this build expects " .. tostring(CN.dbVersion)
        end

        return PASS, "version " .. tostring(version)
    end,
}

-- 12. Size, because it is rewritten on every logout and nobody notices it
--     growing until logging out becomes slow.
CN.RegisterSelfTest{
    area = "database",
    name = "saved data is a reasonable size",
    run  = function()
        if not CN.MeasureDatabase or not CN.db then
            return SKIP, "cannot measure"
        end

        local bytes = CN.MeasureDatabase(CN.db)

        local kb = bytes / 1024

        if kb > 4096 then
            return FAIL, string.format(
                "%.0f KB -- unusually large; run /cn dbsize to see where", kb)
        end

        return PASS, string.format("%.0f KB", kb)
    end,
}

-- 13. The recommendation engine produces something. An addon whose entire
--     purpose is answering a question should be asked it.
CN.RegisterSelfTest{
    area = "engine",
    name = "the engine can answer 'what next'",
    run  = function()
        local results = CN.Recommend(1)

        if not results or #results == 0 then
            return SKIP, "nothing actionable right now -- try /cn setup, or "
                .. "check /cn show in case everything is filtered out"
        end

        local first = results[1]

        return PASS, tostring(first.name or first.id)
            .. " (" .. tostring(first.type) .. ")"
    end,
}

-- 14. LOCKOUTS. The client reports these directly, and a lockout the addon
--     cannot read is a deadline it cannot rank.
CN.RegisterSelfTest{
    area = "instances",
    name = "your dungeon and raid lockouts are readable",
    run  = function()
        local instances = CN:GetModule("Instances")

        if not instances then
            return SKIP, "instances module not loaded"
        end

        local lockouts = instances.Lockouts()

        if #lockouts == 0 then
            return SKIP, "you are not saved to anything right now"
        end

        local summary = instances.Summary()

        return PASS, string.format("%d saved, %d unfinished, %d bosses left",
            summary.total, summary.unfinished, summary.bosses)
    end,
}

-- 15. THE ADVENTURE GUIDE, which is how a drop gets a boss's name attached to
--     it. Open, it must refuse -- reading it moves what the player is looking
--     at, and that refusal is the behaviour worth checking.
CN.RegisterSelfTest{
    area = "instances",
    name = "the Adventure Guide can be read without disturbing you",
    run  = function()
        if not Blizzard.HasEncounterJournal() then
            return SKIP, "this client has no Adventure Guide"
        end

        if Blizzard.IsEncounterJournalOpen() then
            return SKIP, "the Adventure Guide is open, so nothing was read -- "
                .. "which is the intended behaviour, not a fault"
        end

        local encounters = Blizzard.GetInstanceEncounters(1273)

        if #encounters == 0 then
            return SKIP, "the journal returned no bosses for the sample "
                .. "instance; loot lookups may be unavailable"
        end

        return PASS, #encounters .. " bosses read, and the journal's own "
            .. "selection restored"
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "selftest",
    aliases = { "diagnose", "check" },
    order   = 32,
    help    = "Check the addon against the live game and report what it finds.",
    handler = function()
        local rows = SelfTest.Run()

        Print("Self-test: " .. #rows.checks .. " checks against the live client.")

        local area

        for _, check in ipairs(rows.checks) do
            if check.area ~= area then
                area = check.area

                Print("|cffffd100" .. area .. "|r")
            end

            local colour = "|cff73b873"

            if check.status == FAIL then
                colour = "|cfff56b61"
            elseif check.status == SKIP then
                colour = "|cff999999"
            end

            Print(string.format("  %s%-4s|r %s", colour, check.status, check.name))

            if check.detail then
                Print("        |cff999999" .. check.detail .. "|r")
            end
        end

        Print(string.format("%d passed, %d failed, %d skipped.",
            rows.passed, rows.failed, rows.skipped))

        if rows.failed > 0 then
            Print("|cffffff00A failure above is a real defect. Copy this "
                .. "output into a bug report -- it says more than any "
                .. "description could.|r")
        end
    end,
}

return SelfTest
'@

$Embedded['Modules\Orders.lua'] = @'
-- Modules/Orders.lua
-- Completion Navigator :: crafting orders, and a standing question about
-- Delves.
--
-- CRAFTING ORDERS.
--
-- The addon has tracked recipes since 0.14.0 and never noticed that other
-- people can pay you to use them, or that an order you placed yourself
-- finishes and then sits there. Both are time-limited -- an order expires --
-- and both are knowable from the client.
--
-- What it does NOT do is browse the order board. That requires standing at a
-- crafting table with the frame open, and an addon that pokes at that UI to
-- read it is an addon that fights the player for control of their own window.
-- This reports what the client will answer without being asked to open
-- anything: your own orders, and whether any of them are ready to collect.
--
-- DELVES.
--
-- Assessed twice and deliberately not built, for a reason that is written
-- down rather than remembered: `C_DelvesUI` exposes interface plumbing --
-- minimum level, which button to show -- and not progress. Delve credit
-- toward the Great Vault already flows through the World row, so a Delves
-- module would duplicate working behaviour with guesswork.
--
-- The decision has a trigger rather than a date: if a build ever exposes a
-- progress API, the probe below starts answering and the self-test says so.
-- That is the difference between a decision and a thing everyone forgot.

local ADDON_NAME, CN = ...

local Orders = CN:RegisterModule("Orders")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- CRAFTING ORDERS
------------------------------------------------------------

function Orders.IsAvailable()
    return C_CraftingOrders ~= nil
end

-- Orders this character placed, as the client last reported them. The list is
-- populated by the game when the order frame is opened, so this can be empty
-- and empty is not an error -- it means "nothing known yet", and the command
-- says so rather than claiming you have no orders.
function Orders.Mine()
    if not Orders.IsAvailable() or not C_CraftingOrders.GetMyOrders then
        return nil
    end

    local ok, orders = pcall(C_CraftingOrders.GetMyOrders)

    if not ok or type(orders) ~= "table" then
        return nil
    end

    local rows = {}

    for _, order in ipairs(orders) do
        if type(order) == "table" then
            table.insert(rows, {
                orderID    = order.orderID,
                itemID     = order.itemID,
                itemName   = order.itemName,
                expiresIn  = order.expirationTime
                    and math.max(0, order.expirationTime - time()) or nil,
                state      = order.orderState,
                crafter    = order.crafterName,
            })
        end
    end

    return rows
end

-- Whether the client says something is waiting to be collected.
function Orders.HasClaimable()
    if not Orders.IsAvailable() then
        return false
    end

    if C_CraftingOrders.GetClaimedOrder then
        local ok, claimed = pcall(C_CraftingOrders.GetClaimedOrder)

        if ok and claimed then
            return true
        end
    end

    return false
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Deliberately narrow. An order that is finished, or one about to expire, is
-- a real next action with a real deadline. "Someone somewhere might want a
-- flask" is not, and the addon does not have the data to say it anyway.
Orders.expiryHorizonSeconds = 86400

CN.RegisterCandidateProvider("Orders", function()
    local candidates = {}

    local mine = Orders.Mine()

    if not mine then
        return candidates
    end

    for _, order in ipairs(mine) do
        if order.expiresIn and order.expiresIn <= Orders.expiryHorizonSeconds
            and not CN.IsIgnored(CN.objectiveTypes.RECIPE, order.orderID)
            and not CN.IsDeferred(CN.objectiveTypes.RECIPE, order.orderID) then

            local session = CN:GetModule("Session")

            table.insert(candidates, CN.NewObjective({
                id               = order.orderID,
                type             = CN.objectiveTypes.RECIPE,
                name             = "Crafting order: "
                    .. tostring(order.itemName or order.itemID or "?"),
                completionValue  = 3,
                limitedTimeBonus = 2,
                travelCost       = CN.unknownLocationCost,
                expiresIn        = order.expiresIn,
                reasons          = {
                    "a crafting order you placed expires in "
                        .. ((session and session.FormatDuration
                            and session.FormatDuration(order.expiresIn))
                            or "less than a day"),
                },
            }))
        end
    end

    if Orders.HasClaimable() then
        table.insert(candidates, CN.NewObjective({
            id               = "claim",
            type             = CN.objectiveTypes.RECIPE,
            name             = "Collect your finished crafting order",
            completionValue  = 5,
            limitedTimeBonus = 2,
            travelCost       = CN.unknownLocationCost,
            reasons          = { "it is done and waiting at a crafting table" },
        }))
    end

    return candidates
end, {
    events   = { "CRAFTINGORDERS_UPDATE_ORDER_COUNT", "CRAFTINGORDERS_CLAIM_ORDER_RESPONSE" },
    cooldown = 30,
})

------------------------------------------------------------
-- THE DELVES PROBE
------------------------------------------------------------

-- Names the exact API that would change the decision, so that "we looked and
-- there was nothing" does not decay into "nobody ever checked".
Orders.delveProgressAPIs = {
    "GetDelvesProgress",
    "GetDelveProgressInfo",
    "GetSeasonProgress",
}

-- Returns available, detail.
function Orders.DelveProgressAvailable()
    if not C_DelvesUI then
        return false, "C_DelvesUI is not present in this client"
    end

    for _, name in ipairs(Orders.delveProgressAPIs) do
        if type(C_DelvesUI[name]) == "function" then
            return true, "C_DelvesUI." .. name .. " exists -- Delve progress "
                .. "is now readable, and this addon should be tracking it"
        end
    end

    return false, "C_DelvesUI exists but exposes no progress function; Delve "
        .. "credit still reaches the addon through the Great Vault's World row"
end

CN.RegisterSelfTest{
    area = "instances",
    name = "Delve progress is still unavailable",
    run  = function()
        local available, detail = Orders.DelveProgressAvailable()

        if available then
            -- A PASS would be wrong here. This check exists to notice a
            -- decision going stale, and the answer that needs acting on is
            -- the one that must stand out.
            return "FAIL", detail
        end

        return "SKIP", detail
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "orders",
    order   = 27,
    help    = "Crafting orders you have placed, and anything ready to collect.",
    handler = function()
        if not Orders.IsAvailable() then
            Print("This client has no crafting order system.")
            return
        end

        local mine = Orders.Mine()

        if not mine then
            Print("Nothing known yet.")
            Print("|cff999999The game only hands the addon your order list "
                .. "once you have opened the order frame this session. It is "
                .. "not asked to open on your behalf.|r")
            return
        end

        if #mine == 0 then
            Print("No orders outstanding.")
        else
            Print(#mine .. " order" .. (#mine == 1 and "" or "s") .. ":")

            local session = CN:GetModule("Session")

            for _, order in ipairs(mine) do
                local line = "  " .. tostring(order.itemName or order.itemID)

                if order.crafter then
                    line = line .. " |cff999999claimed by "
                        .. order.crafter .. "|r"
                end

                if order.expiresIn then
                    line = line .. " |cffffff00expires in "
                        .. ((session and session.FormatDuration
                            and session.FormatDuration(order.expiresIn))
                            or "soon") .. "|r"
                end

                Print(line)
            end
        end

        if Orders.HasClaimable() then
            Print("|cff73b873Something is finished and waiting to be "
                .. "collected.|r")
        end
    end,
}

return Orders
'@

$Embedded['Modules\Contribute.lua'] = @'
-- Modules/Contribute.lua
-- Completion Navigator :: sharing what you learned, without a server.
--
-- THE PROBLEM.
--
-- The addon learns quest orderings from play, and that knowledge dies on the
-- machine that learned it. One player's evening becomes better advice for
-- that player and for nobody else. The obvious fix is a central database that
-- collects everyone's observations -- and the obvious fix is wrong here, for
-- reasons worth writing down rather than re-deriving:
--
--   * A World of Warcraft addon has NO network access. None. So "upload"
--     necessarily means a second product -- a desktop application, an
--     installer, an update channel -- and that is a larger undertaking than
--     this addon.
--   * Character name, realm and play times are personal data. Collecting them
--     makes the publisher a data controller, with a privacy policy, deletion
--     requests and breach obligations attached.
--   * The project page promises, twice, that nothing leaves your machine.
--
-- So: a one-way, opt-in, de-identified export the player chooses to attach to
-- a bug report. No server, no account, no personal data, and the promise on
-- the store page stays true, because nothing leaves the machine unless the
-- player themselves moves it.
--
-- WHAT IS IN AN EXPORT.
--
-- Quest IDs and orderings. That is all. No names, no realm, no character, no
-- timestamps, no coordinates, no play history. The receiving end can verify
-- what it is by reading it, which is a property worth more than any assurance
-- in a privacy policy.

local ADDON_NAME, CN = ...

local Contribute = CN:RegisterModule("Contribute")

local Print = CN.Print

------------------------------------------------------------
-- THE FORMAT
------------------------------------------------------------

-- Version first, so a future format change is detectable rather than
-- misparsed. Deliberately plain text: a player can read it before deciding to
-- send it, and anybody who has ever been asked to paste an opaque blob into a
-- form knows why that matters.
--
--   CN1 <questID>:<prerequisiteID>,<prerequisiteID> ...
Contribute.formatVersion = "CN1"

function Contribute.Build()
    local harvest = CN:GetModule("Harvest")

    if not harvest or not harvest.AllConfident then
        return nil, "the harvest module is not loaded"
    end

    local edges = harvest.AllConfident()

    local ids = {}

    for questID in pairs(edges) do
        table.insert(ids, questID)
    end

    table.sort(ids)

    if #ids == 0 then
        return nil, "nothing is confident yet -- a chain has to hold on "
            .. (harvest.confidenceThreshold or 3)
            .. " characters before it is worth sending"
    end

    local parts = { Contribute.formatVersion }

    for _, questID in ipairs(ids) do
        local prerequisites = edges[questID]

        table.sort(prerequisites)

        table.insert(parts, questID .. ":" .. table.concat(prerequisites, ","))
    end

    return table.concat(parts, " "), nil, #ids
end

-- Reads an export back. Returns a table of questID -> { prerequisiteIDs }.
--
-- Strict: anything malformed is rejected outright rather than partially
-- accepted. A half-parsed contribution is worse than a refused one, because
-- it silently teaches the addon a chain nobody wrote.
function Contribute.Parse(text)
    if type(text) ~= "string" then
        return nil, "not text"
    end

    text = CN.Trim(text)

    local version, body = text:match("^(%u%u%d)%s+(.+)$")

    if version ~= Contribute.formatVersion then
        return nil, "not a Completion Navigator export "
            .. "(expected " .. Contribute.formatVersion .. ")"
    end

    local edges = {}

    local count = 0

    for entry in body:gmatch("%S+") do
        local questID, list = entry:match("^(%d+):([%d,]+)$")

        if not questID then
            return nil, "malformed entry: " .. entry
        end

        local prerequisites = {}

        for id in list:gmatch("%d+") do
            table.insert(prerequisites, tonumber(id))
        end

        if #prerequisites == 0 then
            return nil, "entry with no prerequisites: " .. entry
        end

        edges[tonumber(questID)] = prerequisites

        count = count + 1
    end

    if count == 0 then
        return nil, "no entries"
    end

    return edges, nil, count
end

------------------------------------------------------------
-- IMPORTING
------------------------------------------------------------

-- Imported chains land in their OWN store and are published as
-- observedRequires, never as requires.
--
-- The distinction is the whole safety model: curated data is something a
-- human checked, an observation is something the addon watched, and a
-- contribution is something a stranger's addon watched. The third must never
-- be able to present itself as the first, and /cn why has to be able to tell
-- the player which it is looking at.
function Contribute.Import(text)
    local edges, err, count = Contribute.Parse(text)

    if not edges then
        return false, err
    end

    local store = CN.Account("contributed")

    local added = 0

    for questID, prerequisites in pairs(edges) do
        if not store[questID] then
            added = added + 1
        end

        store[questID] = prerequisites

        -- TAGGED WITH WHERE IT CAME FROM.
        --
        -- The command promises that `/cn why` "will say the chain came from a
        -- contribution rather than from curated data", and it did not: an
        -- imported edge was indistinguishable from a locally observed one, so
        -- the eligibility checker formatted it as "seen first on N
        -- characters" -- with N read from the harvest store, which has no
        -- record of an imported quest and therefore answered zero. The player
        -- was told the addon had watched the ordering hold on ZERO
        -- characters, which is both a false provenance claim and nonsense as
        -- evidence.
        CN.AddDependency(CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID), {
            observedRequires = prerequisites,
            origin           = "contributed",
        })
    end

    CN.InvalidateCandidates()

    return true, nil, count, added
end

function Contribute.Forget()
    local store = CN.Account("contributed")

    local count = CN.CountKeys(store)

    for questID in pairs(store) do
        store[questID] = nil
    end

    return count
end

CN:OnLogin(function()
    -- Re-publish on login, because the dependency graph is rebuilt from
    -- scratch each session and imported edges would otherwise silently stop
    -- applying the next time the player logged in.
    local store = CN.Account("contributed")

    for questID, prerequisites in pairs(store) do
        CN.AddDependency(CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID), {
            observedRequires = prerequisites,
            origin           = "contributed",
        })
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "contribute",
    args    = "[import <text>, or forget]",
    order   = 37,
    help    = "Share the quest chains you have learned, or take somebody "
        .. "else's.",
    handler = function(args)
        args = CN.Trim(args or "")

        local verb, rest = args:match("^(%S+)%s*(.*)$")

        verb = verb and string.lower(verb) or ""

        if verb == "forget" then
            Print("Forgot " .. Contribute.Forget() .. " imported chain(s).")
            return
        end

        if verb == "import" then
            local ok, err, count, added = Contribute.Import(rest)

            if not ok then
                Print("|cfff56b61Not imported:|r " .. tostring(err))
                return
            end

            Print("Imported " .. count .. " chain(s), " .. added .. " new.")
            Print("|cff999999They are recorded as observations, not as facts: "
                .. "|cffffff00/cn why|r will say the chain came from a "
                .. "contribution rather than from curated data.|r")
            return
        end

        local export, err, count = Contribute.Build()

        if not export then
            Print("Nothing to contribute yet.")
            Print("|cff999999" .. tostring(err) .. "|r")
            return
        end

        Print(count .. " chain(s) ready to share. This text and nothing else:")
        Print("|cffffff00" .. export .. "|r")
        Print("|cff999999It contains quest IDs and orderings. No character "
            .. "name, no realm, no timestamps, no coordinates -- read it "
            .. "before you send it, which is rather the point of a format you "
            .. "can read.|r")
        Print("Paste it into an issue on the tracker and it ships to everyone "
            .. "in a later release.")
    end,
}

return Contribute
'@

$Embedded['Modules\Welcome.lua'] = @'
-- Modules/Welcome.lua
-- Completion Navigator :: the first sixty seconds.
--
-- An addon is judged before it is understood. This one opened with a slash
-- command and a list of things the player had not asked about, which is a
-- perfectly honest way to present a tool and a poor way to introduce one.
--
-- WHAT THIS IS.
--
-- One question, asked once: what are you playing for right now? The answer
-- sets the focus mode, which the addon already supports and which almost
-- nobody discovers, because `/cn mode collecting` is a sentence you have to
-- already know to type.
--
-- WHAT IT IS NOT.
--
--   * It is not a wizard. One screen, four buttons, and a way out.
--   * It does not run again. Ever. An addon that re-introduces itself is an
--     addon that has not noticed you already met.
--   * It does not block anything. Close it and every command still works
--     exactly as before -- nothing here is a gate.
--   * It changes only the focus, which `/cn mode off` reverses completely.
--     A first-run screen that quietly reconfigures things is a first-run
--     screen people learn to distrust.

local ADDON_NAME, CN = ...

local Welcome = CN:RegisterModule("Welcome")

local Print = CN.Print

------------------------------------------------------------
-- STATE
------------------------------------------------------------

local function Account()
    return CN.Account()
end

function Welcome.HasSeen()
    local account = Account()

    return account and account.welcomed and true or false
end

function Welcome.MarkSeen()
    local account = Account()

    if account then
        account.welcomed = true
    end
end

------------------------------------------------------------
-- THE CHOICES
------------------------------------------------------------

-- Four, because five is a menu and three leaves out collecting or levelling,
-- which are the two most common answers. Each maps onto a focus that already
-- exists rather than inventing new behaviour for the occasion.
Welcome.choices = {
    {
        mode  = "leveling",
        label = "Levelling",
        note  = "Quests first, collections quiet.",
    },
    {
        mode  = "collecting",
        label = "Collecting",
        note  = "Mounts, pets, toys and appearances.",
    },
    {
        mode  = "reputation",
        label = "Reputation & renown",
        note  = "Factions, paragon and renown tracks.",
    },
    {
        mode  = "everything",
        label = "A bit of everything",
        note  = "Balanced. The default.",
    },
}

function Welcome.Choose(mode)
    Welcome.MarkSeen()

    -- "A BIT OF EVERYTHING" SET NOTHING, AND SAID IT HAD.
    --
    -- This short-circuited before `ApplyMode`, so the click handler printed
    -- "Focus set to everything" while `/cn mode` reported no focus and `/cn
    -- mode off` answered "No focus was set, so nothing changed." Worse: with
    -- a focus already active -- from an earlier `/cn mode collecting`, say --
    -- picking "a bit of everything" left thirteen types hidden and told the
    -- player the focus was now everything.
    --
    -- `CN.modes.everything` exists and does exactly the right thing.
    if not mode then
        mode = "everything"
    end

    local filters = CN:GetModule("Filters")

    if filters and filters.ApplyMode then
        filters.ApplyMode(mode)
    end

    CN.InvalidateCandidates()

    return true, mode
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

local frame

function Welcome.Build()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorWelcome", UIParent,
        BackdropTemplateMixin and "BackdropTemplate" or nil)

    frame:SetSize(420, 260)
    frame:SetPoint("CENTER")
    frame:SetFrameStrata("DIALOG")
    frame:EnableMouse(true)
    frame:SetMovable(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetScript("OnDragStart", frame.StartMoving)
    frame:SetScript("OnDragStop", frame.StopMovingOrSizing)

    if frame.SetBackdrop then
        frame:SetBackdrop({
            bgFile   = "Interface\\DialogFrame\\UI-DialogBox-Background",
            edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Border",
            tile = true, tileSize = 32, edgeSize = 32,
            insets = { left = 8, right = 8, top = 8, bottom = 8 },
        })
    end

    local title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
    title:SetPoint("TOP", 0, -18)
    title:SetText("Completion Navigator")

    local body = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
    body:SetPoint("TOPLEFT", 24, -48)
    body:SetPoint("TOPRIGHT", -24, -48)
    body:SetJustifyH("LEFT")
    body:SetText("What are you playing for at the moment? This only sets a "
        .. "starting focus -- everything is still tracked, and |cffffff00/cn "
        .. "mode off|r puts it back.")

    local previous

    for index, choice in ipairs(Welcome.choices) do
        local button = CreateFrame("Button", nil, frame,
            "UIPanelButtonTemplate")

        button:SetSize(180, 24)
        button:SetText(choice.label)

        if index == 1 then
            button:SetPoint("TOPLEFT", 24, -104)
        elseif index == 2 then
            button:SetPoint("TOPLEFT", previous, "TOPRIGHT", 12, 0)
        elseif index == 3 then
            button:SetPoint("TOPLEFT", 24, -136)
        else
            button:SetPoint("TOPLEFT", previous, "TOPRIGHT", 12, 0)
        end

        button:SetScript("OnClick", function()
            local _, mode = Welcome.Choose(choice.mode)

            Print("Focus set to |cffffff00" .. mode .. "|r. "
                .. "|cff999999/cn mode off|r undoes it.")
            Print("Ask it anything with |cffffff00/cn|r, or open the window "
                .. "with |cffffff00/cn ui|r.")

            -- OFFER THE SCAN HERE, where the player is already answering
            -- questions -- rather than leaving it to a reminder that arrives
            -- later, out of context, and reads like nagging. Offered, not
            -- run: a first-run screen that starts work uninvited is the
            -- opposite of what this addon does everywhere else.
            local setup = CN:GetModule("Setup")

            if setup and setup.HasRun and not setup.HasRun() then
                Print("It has not looked at your collections yet. "
                    .. "|cffffff00/cn setup|r does that once, and takes a "
                    .. "few seconds.")
            end

            frame:Hide()
        end)

        previous = button
    end

    local note = frame:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    note:SetPoint("BOTTOMLEFT", 24, 46)
    note:SetPoint("BOTTOMRIGHT", -24, 46)
    note:SetJustifyH("LEFT")
    note:SetText("Nothing is scanned, sent or changed until you ask. "
        .. "This appears once.")

    local dismiss = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
    dismiss:SetSize(120, 22)
    dismiss:SetPoint("BOTTOM", 0, 16)
    dismiss:SetText("Not now")
    dismiss:SetScript("OnClick", function()
        Welcome.MarkSeen()

        Print("Right. |cffffff00/cn|r whenever you want it.")

        frame:Hide()
    end)

    frame:Hide()

    return frame
end

function Welcome.Show()
    local built = Welcome.Build()

    if built then
        built:Show()

        -- SHOWN COUNTS AS SEEN.
        --
        -- This marked the window seen only on the button handlers, so a
        -- player who read it and closed it -- or ignored it -- got it again
        -- on every login, against this file's own promise that "it does not
        -- run again. Ever." Answering the question is a choice; being asked
        -- twice is not.
        Welcome.MarkSeen()

        return true
    end

    -- No frame available -- a headless test, or a client that refuses to
    -- create one. Say the same thing in chat rather than silently doing
    -- nothing.
    Print("Completion Navigator is installed. |cffffff00/cn mode leveling|r, "
        .. "|cffffff00collecting|r, |cffffff00reputation|r or just "
        .. "|cffffff00/cn|r to begin.")

    Welcome.MarkSeen()

    return false
end

CN:OnLogin(function()
    if Welcome.HasSeen() then
        return
    end

    -- After the login chatter, and after the setup reminder has had its turn.
    -- Two things talking at once on a first login is worse than either alone.
    --
    -- FOURTEEN SECONDS, NOT EIGHT. The setup reminder is also scheduled at
    -- eight, and because this module loads first its timer fired FIRST -- the
    -- exact opposite of what the sentence above promised, and the player got
    -- the modal with two lines of setup reminder appearing underneath it.
    -- A comment describing an ordering that the code leaves to load order is
    -- not an ordering.
    if C_Timer and C_Timer.After then
        C_Timer.After(14, function()
            if not Welcome.HasSeen() then
                Welcome.Show()
            end
        end)
    end
end)

CN:RegisterCommand{
    name    = "welcome",
    order   = 38,
    help    = "Show the first-run question again.",
    handler = function()
        Welcome.Show()
    end,
}

return Welcome
'@

$Embedded['Modules\Hud.lua'] = @'
-- Modules/Hud.lua
-- Completion Navigator :: a small always-on frame, and the settings that make
-- the whole addon legible.
--
-- THE HUD.
--
-- Off by default, like everything in this addon that puts pixels on the
-- screen uninvited. It shows one line -- what to do next -- and nothing else,
-- because a heads-up display that needs reading is not a heads-up display.
--
-- Distinct from Follow's frame, which appears only while a route is being
-- walked and shows the current stop. This is for the player who is not
-- following anything and wants the answer visible while they get on with
-- something else.
--
-- ACCESSIBILITY.
--
-- Two settings that cost almost nothing and matter a great deal to the people
-- who need them:
--
--   * A scale, because the default font is small and not everybody's monitor
--     is two feet away.
--   * A colourblind mode for the navigation arrow. The arrow's whole language
--     is colour -- blue on course, amber drifting, red walking away -- which
--     is exactly the design that fails eight percent of men. In this mode the
--     arrow carries a short text label as well, so the information survives
--     the colour being indistinguishable.
--
-- The rule behind both: no information carried by colour alone.

local ADDON_NAME, CN = ...

local Hud = CN:RegisterModule("Hud")

local Print = CN.Print

------------------------------------------------------------
-- SETTINGS
------------------------------------------------------------

-- Named `Preferences`, not `Settings`.
--
-- `Settings` is also the name of the client's global options API since 10.0,
-- and this file's options-panel registration reads `Settings.RegisterCanvas-
-- LayoutCategory` -- which resolved to this local FUNCTION and threw
-- "attempt to index a function value" on every login on every retail client.
-- The error was caught and printed, and because it aborted the function the
-- pre-10.0 fallback below never ran either: the addon has never appeared in
-- the game's own options list, which is the entire purpose of that block.
--
-- The harness never defined SettingsPanel, so the `and` chain short-circuited
-- before the bad index and the suite saw nothing. Same shape as the invented
-- event name: a stub more forgiving than the client.
local function Preferences()
    return CN.Settings() or {}
end

function Hud.IsEnabled()
    return Preferences().hud == true
end

function Hud.Scale()
    local scale = tonumber(Preferences().uiScale)

    if not scale or scale < 0.7 or scale > 2.0 then
        return 1
    end

    return scale
end

function Hud.IsColourblind()
    return Preferences().colourblind == true
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

local frame, ticker

local function Build()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorHud", UIParent)

    frame:SetSize(260, 34)
    frame:SetFrameStrata("BACKGROUND")
    frame:SetMovable(true)
    frame:EnableMouse(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetClampedToScreen(true)

    local placement = Preferences().hudPosition or {}

    frame:SetPoint(placement.point or "TOP", UIParent,
        placement.point or "TOP", placement.x or 0, placement.y or -220)

    frame.label = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    frame.label:SetPoint("TOPLEFT")
    frame.label:SetPoint("TOPRIGHT")
    frame.label:SetJustifyH("LEFT")

    frame.detail = frame:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    frame.detail:SetPoint("TOPLEFT", frame.label, "BOTTOMLEFT", 0, -2)
    frame.detail:SetPoint("TOPRIGHT", frame.label, "BOTTOMRIGHT", 0, -2)
    frame.detail:SetJustifyH("LEFT")

    frame:SetScript("OnDragStart", frame.StartMoving)
    frame:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local point, _, _, x, y = self:GetPoint()

        Preferences().hudPosition = { point = point, x = x, y = y }
    end)

    frame:SetScale(Hud.Scale())

    frame:Hide()

    return frame
end

Hud.Build = Build

function Hud.Refresh()
    if not frame or not Hud.IsEnabled() then
        return false
    end

    local results = CN.Recommend(1)

    local objective = results and results[1]

    if not objective then
        frame.label:SetText("|cff999999nothing actionable|r")
        frame.detail:SetText("")

        return true
    end

    frame.label:SetText(tostring(objective.name or objective.id))

    local detail = objective.reasons and objective.reasons[1]

    -- WHILE A ROUTE IS BEING WALKED, SAY HOW FAR THROUGH IT YOU ARE.
    --
    -- The reason line is the right thing to show when nothing else is
    -- happening. It is the wrong thing when the player is nine stops into a
    -- twelve-stop route, which is exactly when a glanceable frame earns its
    -- place on the screen.
    local follow = CN:GetModule("Follow")

    if follow and follow.active and (follow.startedWith or 0) > 0 then
        detail = string.format("stop %d of %d",
            math.min((follow.completed or 0) + 1, follow.startedWith),
            follow.startedWith)
    end

    frame.detail:SetText(detail and ("|cff999999" .. detail .. "|r") or "")

    return true
end

function Hud.SetEnabled(enabled)
    Preferences().hud = enabled and true or nil

    if enabled then
        Build()

        if frame then
            frame:SetScale(Hud.Scale())
            frame:Show()
        end

        -- Slow on purpose. The answer to "what next" changes when the player
        -- does something, not several times a second, and a HUD that
        -- recomputes constantly is a HUD that costs frames for nothing.
        if C_Timer and C_Timer.NewTicker and not ticker then
            ticker = C_Timer.NewTicker(5, function()
                pcall(Hud.Refresh)
            end)
        end

        Hud.Refresh()
    else
        if frame then
            frame:Hide()
        end

        if ticker then
            ticker:Cancel()
            ticker = nil
        end
    end

    return Hud.IsEnabled()
end

CN:OnLogin(function()
    if Hud.IsEnabled() then
        Hud.SetEnabled(true)
    end
end)

------------------------------------------------------------
-- ACCESSIBILITY APPLIED
------------------------------------------------------------

-- Everything the addon draws, at the player's scale.
function Hud.ApplyScale()
    local scale = Hud.Scale()

    for _, name in ipairs({
        "CompletionNavigatorFrame",
        "CompletionNavigatorHud",
        "CompletionNavigatorArrow",
        "CompletionNavigatorFollow",
        "CompletionNavigatorWelcome",
    }) do
        local target = _G and _G[name]

        if target and target.SetScale then
            pcall(target.SetScale, target, scale)
        end
    end

    return scale
end

-- The word for a bearing, for players who cannot rely on the colour. Kept
-- very short: it sits under an arrow, not in a paragraph.
function Hud.BearingWord(relative)
    if not relative then
        return "?"
    end

    local off = math.abs(relative)

    -- THROUGH CN.L, LIKE EVERY OTHER STRING A PLAYER READS.
    --
    -- These four are translated into all ten shipped locales and were
    -- returned as English literals, so the one accessibility feature that
    -- exists for players who cannot use the arrow's colours spoke only
    -- English to nine of them.
    if off < 0.35 then
        return CN.L["ahead"]
    end

    if off < 1.2 then
        return CN.L["veer"]
    end

    if off < 2.4 then
        return CN.L["turn"]
    end

    return CN.L["back"]
end

------------------------------------------------------------
-- THE GAME'S OWN OPTIONS LIST
------------------------------------------------------------

-- The addon has had a settings tab since 0.15.0 and it lives inside a window
-- you have to know how to open. Somebody who installs an addon and goes
-- looking for its options goes to the game's options list, finds nothing, and
-- reasonably concludes it has none.
--
-- Registered defensively: the API was replaced wholesale in 10.0 and the old
-- one still exists on older clients, so both paths are here and neither is
-- assumed.
local registered = false

function Hud.RegisterOptionsPanel()
    if registered or not CreateFrame then
        return registered
    end

    local panel = CreateFrame("Frame")

    panel.name = "Completion Navigator"

    local title = panel:CreateFontString(nil, "ARTWORK", "GameFontNormalLarge")
    title:SetPoint("TOPLEFT", 16, -16)
    title:SetText("Completion Navigator")

    local body = panel:CreateFontString(nil, "ARTWORK", "GameFontHighlight")
    body:SetPoint("TOPLEFT", 16, -48)
    body:SetPoint("TOPRIGHT", -16, -48)
    body:SetJustifyH("LEFT")
    body:SetText("Everything this addon can do is in its own window, which "
        .. "has a Settings tab of its own.\n\n"
        .. "/cn ui        open the window\n"
        .. "/cn           what to do next\n"
        .. "/cn scale     size of everything it draws\n"
        .. "/cn colourblind   label the arrow in words\n"
        .. "/cn hud       a small always-on line\n"
        .. "/cn selftest  check the addon against your client")

    local open = CreateFrame("Button", nil, panel, "UIPanelButtonTemplate")
    open:SetSize(160, 24)
    open:SetPoint("TOPLEFT", 16, -190)
    open:SetText("Open the window")
    open:SetScript("OnClick", function()
        if CompletionNavigator_ToggleUI then
            CompletionNavigator_ToggleUI()
        end
    end)

    -- Modern path first.
    if SettingsPanel and Settings and Settings.RegisterCanvasLayoutCategory
        and Settings.RegisterAddOnCategory then

        local ok, category = pcall(Settings.RegisterCanvasLayoutCategory,
            panel, panel.name)

        if ok and category then
            category.ID = panel.name

            pcall(Settings.RegisterAddOnCategory, category)

            registered = true
        end
    end

    -- The pre-10.0 API, still present on Classic clients.
    if not registered and InterfaceOptions_AddCategory then
        local ok = pcall(InterfaceOptions_AddCategory, panel)

        registered = ok and true or false
    end

    return registered
end

CN:OnLogin(function()
    Hud.RegisterOptionsPanel()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "hud",
    args    = "[on or off]",
    order   = 39,
    help    = "A small always-on line showing what to do next.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Hud.SetEnabled(true)
        elseif args == "off" then
            Hud.SetEnabled(false)
        else
            Hud.SetEnabled(not Hud.IsEnabled())
        end

        Print("Heads-up display: " .. CN.YesNo(Hud.IsEnabled()))

        if Hud.IsEnabled() then
            Print("|cff999999Drag it where you want it.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "scale",
    args    = "<0.7 to 2.0>",
    order   = 40,
    help    = "Size of everything this addon draws.",
    handler = function(args)
        local scale = tonumber(CN.Trim(args or ""))

        if not scale then
            Print("Scale: " .. Hud.Scale())
            Print("|cff999999Usage: /cn scale 1.25|r")
            return
        end

        if scale < 0.7 or scale > 2.0 then
            Print("Scale must be between 0.7 and 2.0.")
            return
        end

        Preferences().uiScale = scale

        Hud.ApplyScale()

        Print("Scale set to " .. scale .. ".")
    end,
}

CN:RegisterCommand{
    name    = "colourblind",
    aliases = { "colorblind" },
    args    = "[on or off]",
    order   = 41,
    help    = "Label the arrow in words as well as colour.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Preferences().colourblind = true
        elseif args == "off" then
            Preferences().colourblind = nil
        else
            Preferences().colourblind = (not Hud.IsColourblind()) or nil
        end

        Print("Arrow labelled in words: " .. CN.YesNo(Hud.IsColourblind()))

        local navigation = CN:GetModule("Navigation")

        if navigation and navigation.Refresh then
            navigation.Refresh()
        end
    end,
}

CN:RegisterCommand{
    name    = "keepfilter",
    args    = "[on or off]",
    order   = 44,
    help    = "Whether the window's filter box follows you between tabs.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        local settings = Preferences()

        if args == "on" then
            settings.keepFilter = true
        elseif args == "off" then
            settings.keepFilter = nil
        else
            settings.keepFilter = (not settings.keepFilter) or nil
        end

        Print("Filter follows you between tabs: "
            .. CN.YesNo(settings.keepFilter))

        if not settings.keepFilter then
            -- Turning it off forgets what it was holding. Leaving the term
            -- behind means turning the setting back on later silently applies
            -- a filter the player typed in another session.
            local ui = CN:GetModule("UI")

            if ui then
                ui.persistedFilter = nil
            end

            Print("|cff999999Off is the safer default: a filter that persists "
                .. "invisibly is how a list looks empty when it is not.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "cues",
    args    = "[on or off]",
    order   = 42,
    help    = "Sound when you arrive, clear a stop, or finish a route.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Preferences().cues = true
        elseif args == "off" then
            Preferences().cues = nil
        else
            Preferences().cues = (not Preferences().cues) or nil
        end

        Print("Completion cues: " .. CN.YesNo(Preferences().cues))
    end,
}

return Hud
'@

$Embedded['Modules\Errors.lua'] = @'
-- Modules/Errors.lua
-- Completion Navigator :: what went wrong, kept where the player can find it.
--
-- WHY.
--
-- Every bug report this project has received has been prose. "The arrow does
-- not turn around." I guessed from that description twice and was wrong twice,
-- and the fix both times was to build an instrument -- /cn navdiag, then
-- /cn selftest -- so that the next report could carry evidence instead of
-- adjectives.
--
-- This is the same move applied to errors themselves. The addon already wraps
-- its risky work in pcall, which is why a failure inside a candidate provider
-- does not break the player's session. The cost of that is that the failure is
-- invisible: it happened, something was quietly missing from a list, and
-- nobody will ever know.
--
-- So: keep them. A short ring buffer, in memory, that /cn errors prints.
--
-- WHAT THIS IS NOT.
--
-- It is not telemetry. Nothing is sent anywhere -- an addon cannot send
-- anything anywhere -- and nothing is written to disk, because an error from
-- three weeks ago is noise and a growing error log is a leak.

local ADDON_NAME, CN = ...

local Errors = CN:RegisterModule("Errors")

local Print = CN.Print

-- Twenty is enough to see a pattern and short enough that the memory cost is
-- irrelevant. When it fills, the oldest goes: the recent ones are the ones
-- somebody is trying to explain.
Errors.capacity = 20

local ring = {}

local seen = {}

function Errors.Record(context, message)
    if not message then
        return false
    end

    message = tostring(message)

    -- REPEATS ARE COUNTED, NOT LISTED.
    --
    -- A failure inside a ticker fires ten times a second. Twenty identical
    -- lines is not twenty pieces of evidence, and it pushes out the one
    -- different error that would have explained the whole thing.
    local key = tostring(context) .. "|" .. message

    if seen[key] then
        seen[key].count = seen[key].count + 1
        seen[key].last  = time()

        return true
    end

    local entry = {
        context = tostring(context or "?"),
        message = message,
        first   = time(),
        last    = time(),
        count   = 1,
    }

    seen[key] = entry

    table.insert(ring, entry)

    while #ring > Errors.capacity do
        local dropped = table.remove(ring, 1)

        seen[tostring(dropped.context) .. "|" .. dropped.message] = nil
    end

    return true
end

function Errors.All()
    return ring
end

function Errors.Count()
    return #ring
end

function Errors.Clear()
    local count = #ring

    ring = {}
    seen = {}

    return count
end

-- Wraps a call so a failure is recorded rather than swallowed. Returns the
-- same thing pcall does, so it is a drop-in replacement at every site that
-- currently discards the error.
local function Pack(...)
    return select("#", ...), { ... }
end

function Errors.Guard(context, fn, ...)
    -- COUNTED, NOT MEASURED WITH `#`.
    --
    -- This was `local results = { pcall(fn, ...) }` followed by
    -- `CN.Unpack(results)`, which truncates at the first nil: a wrapped
    -- function returning `value, nil` came back as one value, so a "drop-in
    -- replacement" silently changed the arity of whatever it wrapped. `#` on
    -- a table with holes is undefined in both interpreters -- 5.1 and 5.4
    -- happen to agree on the cases here, which is precisely the kind of
    -- agreement this project has learned not to rest on.
    --
    -- `table.pack` does not exist in 5.1, so the count is taken with
    -- `select("#", ...)` inside a varargs helper, which does.
    local count, results = Pack(pcall(fn, ...))

    if not results[1] then
        Errors.Record(context, results[2])
    end

    -- CN.Unpack, not a second copy of it. Core.lua states the rule -- "if a
    -- construct means two things, the addon uses neither directly; it uses
    -- one of these" -- and this file quietly kept its own identical shim
    -- outside the one file that gets audited for exactly this class of
    -- mistake. Equivalent today; the point is that there is one place to fix
    -- it when it is not.
    return CN.Unpack(results, 1, count)
end

CN.Guard = Errors.Guard

------------------------------------------------------------
-- THE PREVIOUS SESSION
------------------------------------------------------------

-- ONE SUMMARY LINE PER ERROR, KEPT ACROSS A LOGOUT.
--
-- The ring buffer is in memory, deliberately: a growing error log is a leak,
-- and an error from three weeks ago is noise. But the case that matters most
-- -- something went wrong, and the player relogged before thinking to look --
-- was exactly the case where the evidence was gone.
--
-- So the counts survive, and nothing else: context, message, and how many
-- times. Cleared whenever the player reads them, and capped at the same size
-- as the live ring.
local function Stored()
    return CN.Account("lastErrors")
end

function Errors.Persist()
    -- A CLEAN SESSION MUST NOT ERASE THE RECORD OF A BAD ONE.
    --
    -- This ran unconditionally on logout, including when nothing had gone
    -- wrong -- so the sequence the feature exists for destroyed its own
    -- evidence: something breaks, the player reloads before thinking to look,
    -- and the reload's empty ring overwrites the record. `/cn errors` then
    -- says nothing has gone wrong, which is true of the last four seconds and
    -- false of the thing the player wanted to report.
    --
    -- Players reload several times an hour. An empty ring is not news, so it
    -- is not written.
    if #ring == 0 then
        return 0
    end

    local stored = Stored()

    for key in pairs(stored) do
        stored[key] = nil
    end

    for index, entry in ipairs(ring) do
        stored[index] = {
            context = entry.context,
            message = entry.message,
            count   = entry.count,
        }
    end

    return #ring
end

function Errors.Previous()
    local rows = {}

    for _, entry in ipairs(Stored()) do
        table.insert(rows, entry)
    end

    return rows
end

function Errors.ForgetPrevious()
    local stored = Stored()

    local count = #stored

    for key in pairs(stored) do
        stored[key] = nil
    end

    return count
end

CN:RegisterEvent("PLAYER_LOGOUT", function()
    Errors.Persist()
end)

CN:RegisterCommand{
    name    = "errors",
    aliases = { "log" },
    args    = "[clear]",
    order   = 43,
    help    = "Anything that went wrong inside the addon this session.",
    handler = function(args)
        if string.lower(CN.Trim(args or "")) == "clear" then
            Print("Cleared " .. Errors.Clear() .. " recorded error(s).")
            return
        end

        -- EVENT NAMES THE CLIENT REFUSED.
        --
        -- `CN.RegisterWithClient` has recorded these since 0.49.0, with a
        -- comment saying they are kept "so /cn errors can name it". Nothing
        -- read the table. The secondary path -- recording into this module's
        -- ring -- cannot fire for the sixty-odd files that load before this
        -- one, which includes Travel, the very file whose invented
        -- `NEW_TAXI_NODE` the whole mechanism was written for. A bad event
        -- name today would reproduce the original symptom exactly: silent,
        -- and findable only by reading the source.
        --
        -- Printed first and unconditionally, because a handler that never
        -- runs is the failure most likely to be mistaken for "there is just
        -- nothing to do".
        local rejected = 0

        for event, why in pairs(CN.rejectedEvents or {}) do
            if rejected == 0 then
                Print("|cfff56b61The client refused to register these "
                    .. "events, so nothing listening for them ever runs:|r")
            end

            rejected = rejected + 1

            Print("  |cfff56b61" .. tostring(event) .. "|r")
            Print("    |cff999999" .. tostring(why) .. "|r")
        end

        if #ring == 0 then
            local previous = Errors.Previous()

            if #previous > 0 then
                Print("Nothing this session. From the previous one:")

                for _, entry in ipairs(previous) do
                    Print("  |cfff56b61" .. tostring(entry.context) .. "|r"
                        .. ((entry.count or 1) > 1
                            and (" |cffffff00x" .. entry.count .. "|r") or ""))
                    Print("    |cff999999" .. tostring(entry.message) .. "|r")
                end

                Errors.ForgetPrevious()

                Print("|cff999999Shown once, then forgotten.|r")
                return
            end

            if rejected > 0 then
                Print("Nothing else has gone wrong this session.")
                return
            end

            Print("Nothing has gone wrong this session.")
            Print("|cff999999Errors inside the addon are caught so they "
                .. "cannot break your session -- which is also why they would "
                .. "otherwise be invisible. They are recorded here instead.|r")
            return
        end

        Print(#ring .. " error(s) recorded this session:")

        for _, entry in ipairs(ring) do
            Print("  |cfff56b61" .. entry.context .. "|r"
                .. (entry.count > 1 and (" |cffffff00x" .. entry.count .. "|r") or ""))
            Print("    |cff999999" .. entry.message .. "|r")
        end

        Print("|cff999999Paste this into a bug report along with "
            .. "|cffffff00/cn selftest|r output.|r")
    end,
}

return Errors
'@

