local function Store()
    return CN.Account("__STORE__")
end

__NAME__.Store = Store

------------------------------------------------------------
-- API
------------------------------------------------------------

function __NAME__.Scan()
    -- TODO: read live state, persist it, return counts.
    return 0
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

